def init_mapping(self):
    import math
    import random
    import heapq
    from collections import defaultdict, deque
    from time import time as _time

    num_q = self.num_qubits
    physical_qubits = sorted(self.backend.keys())
    dist = self.distance_matrix

    # ---------------------------------------------------------------
    # Step 1: Build DAG and topological layers
    # ---------------------------------------------------------------
    all_gates = sorted(self.access.keys())
    two_qubit_gates = [g for g in all_gates if len(self.access[g]) == 2]

    last_gate_on_qubit = {}
    successors_dag = defaultdict(set)
    predecessors_dag = defaultdict(set)
    for g in all_gates:
        for q in self.access[g]:
            if q in last_gate_on_qubit:
                pred = last_gate_on_qubit[q]
                successors_dag[pred].add(g)
                predecessors_dag[g].add(pred)
            last_gate_on_qubit[q] = g

    in_degree = {g: len(predecessors_dag[g]) for g in all_gates}
    gate_layer = {g: 0 for g in all_gates}
    temp_in = dict(in_degree)
    queue = deque(g for g in all_gates if in_degree[g] == 0)
    topo_order = []
    while queue:
        g = queue.popleft()
        topo_order.append(g)
        for s in successors_dag[g]:
            gate_layer[s] = max(gate_layer[s], gate_layer[g] + 1)
            temp_in[s] -= 1
            if temp_in[s] == 0:
                queue.append(s)

    critical_path = {g: 0 for g in all_gates}
    for g in reversed(topo_order):
        for s in successors_dag[g]:
            if critical_path[s] + 1 > critical_path[g]:
                critical_path[g] = critical_path[s] + 1

    # 2q DAG for routing simulation
    gates_2q = {}
    dag2q_succ = defaultdict(set)
    dag2q_pred = defaultdict(set)
    last_2q_on_qubit = {}
    logical_qubits_set = set()

    for gate in all_gates:
        qubits = self.access[gate]
        if len(qubits) == 2:
            q1, q2 = qubits
            gates_2q[gate] = (q1, q2)
            logical_qubits_set.add(q1)
            logical_qubits_set.add(q2)
            for q in [q1, q2]:
                if q in last_2q_on_qubit:
                    prev = last_2q_on_qubit[q]
                    if prev != gate:
                        dag2q_succ[prev].add(gate)
                        dag2q_pred[gate].add(prev)
                last_2q_on_qubit[q] = gate
        elif len(qubits) == 1:
            logical_qubits_set.add(qubits[0])

    logical_qubits = sorted(logical_qubits_set)

    if not gates_2q:
        self.mapping_dict = list(range(num_q))
        self.reverse_mapping_dict = list(range(num_q))
        if self.use_isl:
            self.isl_mapping = dict_to_isl_map(self.mapping_dict)
        return

    # Topological order for 2q DAG
    topo_2q = []
    in_deg_2q = {g: len(dag2q_pred[g]) for g in gates_2q}
    q2 = deque(sorted(g for g in gates_2q if in_deg_2q[g] == 0))
    while q2:
        g = q2.popleft()
        topo_2q.append(g)
        for s in dag2q_succ[g]:
            in_deg_2q[s] -= 1
            if in_deg_2q[s] == 0:
                q2.append(s)

    dep_count = defaultdict(int)
    for g in reversed(topo_2q):
        for s in dag2q_succ[g]:
            dep_count[g] = max(dep_count[g], dep_count[s] + 1)

    # ---------------------------------------------------------------
    # Step 2: Interaction weights — critical-path weighting
    # ---------------------------------------------------------------
    max_layer = max((gate_layer[g] for g in two_qubit_gates), default=1)

    static_weight = defaultdict(float)
    logical_degree = defaultdict(float)

    for g in two_qubit_gates:
        q1, q2 = self.access[g]
        cp = critical_path[g] + 1
        layer = gate_layer[g]
        w = cp * (max_layer - layer + 1)
        key = (min(q1, q2), max(q1, q2))
        static_weight[key] += w
        logical_degree[q1] += w
        logical_degree[q2] += w

    interacting_logical = [q for q in logical_qubits if logical_degree.get(q, 0) > 0]

    # ---------------------------------------------------------------
    # Step 3: Physical graph properties
    # ---------------------------------------------------------------
    hw_adj = defaultdict(set)
    for pq in physical_qubits:
        for pq2 in self.backend.get(pq, []):
            hw_adj[pq].add(pq2)

    phys_degree = {pq: len(hw_adj[pq]) for pq in physical_qubits}
    phys_centrality = {}
    for pq in physical_qubits:
        phys_centrality[pq] = sum(dist[pq][pq2] for pq2 in physical_qubits)

    # ---------------------------------------------------------------
    # Step 4: Helper functions
    # ---------------------------------------------------------------
    def build_neighbors(weights):
        nbrs = defaultdict(dict)
        deg = defaultdict(float)
        for (q1, q2), w in weights.items():
            nbrs[q1][q2] = w
            nbrs[q2][q1] = w
            deg[q1] += w
            deg[q2] += w
        return nbrs, deg

    def compute_cost_nonlinear(m, weights, alpha_exp):
        cost = 0.0
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                d = dist[m[q1]][m[q2]]
                cost += w * (d ** alpha_exp)
        return cost

    def compute_cost(m, weights):
        cost = 0.0
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                cost += w * dist[m[q1]][m[q2]]
        return cost

    def delta_swap_cost_nonlinear(m, rm, pq_a, pq_b, nbrs, alpha_exp):
        lq_a, lq_b = rm[pq_a], rm[pq_b]
        delta = 0.0
        affected = set()
        if lq_a in nbrs:
            affected.update(nbrs[lq_a].keys())
        if lq_b in nbrs:
            affected.update(nbrs[lq_b].keys())
        for q in affected:
            if q == lq_a or q == lq_b:
                continue
            pq_q = m[q]
            w_a = nbrs.get(lq_a, {}).get(q, 0.0)
            if w_a > 0:
                old_d = dist[pq_a][pq_q] ** alpha_exp
                new_d = dist[pq_b][pq_q] ** alpha_exp
                delta += w_a * (new_d - old_d)
            w_b = nbrs.get(lq_b, {}).get(q, 0.0)
            if w_b > 0:
                old_d = dist[pq_b][pq_q] ** alpha_exp
                new_d = dist[pq_a][pq_q] ** alpha_exp
                delta += w_b * (new_d - old_d)
        return delta

    def do_swap(m, rm, pq_a, pq_b):
        lq_a, lq_b = rm[pq_a], rm[pq_b]
        m[lq_a], m[lq_b] = pq_b, pq_a
        rm[pq_a], rm[pq_b] = lq_b, lq_a

    # ---------------------------------------------------------------
    # Step 5: Identify early layers (first L=5 DAG layers) for A*
    # ---------------------------------------------------------------
    ASTAR_LAYERS = 5
    ASTAR_NODE_LIMIT = 5000

    # Partition 2q gates into layers
    gate_2q_layer = {}
    pred_rem_layer = {g: len(dag2q_pred[g]) for g in gates_2q}
    front_layer_calc = set(g for g in gates_2q if pred_rem_layer[g] == 0)
    current_layer = 0
    early_layer_gates = set()
    late_layer_gates = set()

    temp_front = set(front_layer_calc)
    while temp_front:
        # All gates in temp_front belong to current_layer
        for g in temp_front:
            gate_2q_layer[g] = current_layer
            if current_layer < ASTAR_LAYERS:
                early_layer_gates.add(g)
            else:
                late_layer_gates.add(g)
        next_front = set()
        for g in temp_front:
            for s in dag2q_succ[g]:
                pred_rem_layer[s] -= 1
                if pred_rem_layer[s] == 0:
                    next_front.add(s)
        current_layer += 1
        temp_front = next_front

    # ---------------------------------------------------------------
    # Step 6: A*-guided routing for early layers
    # ---------------------------------------------------------------
    def astar_routing_early(m, rm):
        """
        A* optimal SWAP search for first L=5 layers of the 2q DAG.
        State = (mapping_tuple, executed_gates_frozenset)
        Returns per-pair swap counts with exact costs.
        """
        if not early_layer_gates:
            return defaultdict(float), 0

        # Build predecessor counts restricted to early gates
        early_pred = {}
        for g in early_layer_gates:
            early_pred[g] = len(dag2q_pred[g] & early_layer_gates)

        initial_front = frozenset(g for g in early_layer_gates if early_pred[g] == 0)

        # Check which front gates are already executable
        init_executed = set()
        cur_front = set(initial_front)
        changed = True
        while changed:
            changed = False
            newly_exec = set()
            for g in cur_front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = m[gq1], m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    newly_exec.add(g)
            if newly_exec:
                changed = True
                init_executed |= newly_exec
                cur_front -= newly_exec
                for g in newly_exec:
                    for s in dag2q_succ[g]:
                        if s in early_layer_gates and s not in init_executed:
                            # Check all early predecessors executed
                            all_pred_done = True
                            for p in dag2q_pred[s]:
                                if p in early_layer_gates and p not in init_executed:
                                    all_pred_done = False
                                    break
                            if all_pred_done:
                                cur_front.add(s)

        remaining_early = early_layer_gates - init_executed
        if not remaining_early:
            return defaultdict(float), 0

        # Compute front for A* initial state
        def compute_front(executed):
            front = set()
            for g in early_layer_gates:
                if g in executed:
                    continue
                all_pred = True
                for p in dag2q_pred[g]:
                    if p in early_layer_gates and p not in executed:
                        all_pred = False
                        break
                if all_pred:
                    front.add(g)
            return frozenset(front)

        init_exec_frozen = frozenset(init_executed)
        init_front_astar = compute_front(init_executed)

        # Active qubits: only those involved in remaining early gates
        active_logical = set()
        for g in remaining_early:
            gq1, gq2 = gates_2q[g]
            active_logical.add(gq1)
            active_logical.add(gq2)

        # Heuristic: sum of distances for front gates (admissible)
        def h_func(mapping, front_gates):
            h = 0
            for g in front_gates:
                gq1, gq2 = gates_2q[g]
                h += dist[mapping[gq1]][mapping[gq2]]
            return h

        # Generate candidate SWAPs: only involving physical qubits of
        # front + extended layer logical qubits
        def get_candidate_swaps(mapping, front_gates, executed):
            active_phys = set()
            # Front layer qubits
            for g in front_gates:
                gq1, gq2 = gates_2q[g]
                active_phys.add(mapping[gq1])
                active_phys.add(mapping[gq2])
            # Extended: next layer after front
            ext_gates = set()
            for g in front_gates:
                for s in dag2q_succ[g]:
                    if s in early_layer_gates and s not in executed:
                        ext_gates.add(s)
            for g in ext_gates:
                gq1, gq2 = gates_2q[g]
                active_phys.add(mapping[gq1])
                active_phys.add(mapping[gq2])

            swaps = set()
            for pq in active_phys:
                for nb in hw_adj.get(pq, set()):
                    swaps.add((min(pq, nb), max(pq, nb)))
            return swaps

        # A* search
        # State: (mapping_tuple_for_active_qubits, executed_frozenset)
        # We use full mapping as tuple for state hashing
        active_logical_list = sorted(active_logical)
        n_active = len(active_logical_list)

        # Compact mapping: only track active logical qubits
        def mapping_key(mapping):
            return tuple(mapping[lq] for lq in active_logical_list)

        init_m = list(m)
        init_h = h_func(init_m, init_front_astar)

        # Priority queue: (f, tie_break, g_cost, mapping_list, executed_frozen, front_frozen, swap_count)
        counter = [0]
        start_state = (init_h, 0, 0, init_m, init_exec_frozen, init_front_astar)
        open_heap = [start_state]
        visited = {}  # mapping_key + executed -> best g
        best_known_total = float('inf')
        best_result = None

        # Track swap history per pair for best solution
        # We store (swap_count, pair_swaps_dict) in a side dict keyed by state
        swap_history = {}  # (mk, exec_frozen) -> pair_swap_counts
        init_key = (mapping_key(init_m), init_exec_frozen)
        swap_history[init_key] = defaultdict(float)

        expansions = 0

        while open_heap and expansions < ASTAR_NODE_LIMIT:
            f, _, g_cost, cur_m_list, executed, front = heapq.heappop(open_heap)

            mk = mapping_key(cur_m_list)
            state_key = (mk, executed)

            if state_key in visited and visited[state_key] <= g_cost:
                continue
            visited[state_key] = g_cost

            # Pruning: if f > best_known * 1.2, skip
            if best_known_total < float('inf') and f > best_known_total * 1.2:
                continue

            # Try executing all currently executable gates
            new_executed = set(executed)
            new_front = set(front)
            progress = True
            while progress:
                progress = False
                newly_exec = set()
                for g in list(new_front):
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = cur_m_list[gq1], cur_m_list[gq2]
                    if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                        newly_exec.add(g)
                if newly_exec:
                    progress = True
                    new_executed |= newly_exec
                    new_front -= newly_exec
                    for g in newly_exec:
                        for s in dag2q_succ[g]:
                            if s in early_layer_gates and s not in new_executed:
                                all_pred = True
                                for p in dag2q_pred[s]:
                                    if p in early_layer_gates and p not in new_executed:
                                        all_pred = False
                                        break
                                if all_pred:
                                    new_front.add(s)

            new_exec_frozen = frozenset(new_executed)
            new_front_frozen = frozenset(new_front)

            # Check if all early gates executed
            if not (early_layer_gates - new_executed):
                if g_cost < best_known_total:
                    best_known_total = g_cost
                    parent_key = (mk, executed)
                    pair_swaps = dict(swap_history.get(parent_key, {}))
                    best_result = (g_cost, pair_swaps)
                continue

            # No more gates to execute and front is empty means stuck - shouldn't happen
            if not new_front_frozen:
                continue

            # Expand: try each candidate SWAP
            candidate_swaps = get_candidate_swaps(cur_m_list, new_front_frozen, new_executed)
            expansions += 1

            parent_pair_swaps = swap_history.get((mk, executed), defaultdict(float))

            for (s1, s2) in candidate_swaps:
                new_m = list(cur_m_list)
                l1, l2 = new_m[0], new_m[0]  # placeholder
                # Find logical qubits at s1, s2
                # We need reverse mapping too
                # Build reverse from new_m
                # Actually we need to track reverse mapping too
                # Let's use a simpler approach: just swap in mapping
                # Find which logical qubits are at s1 and s2
                lq_at_s1 = -1
                lq_at_s2 = -1
                for lq in range(num_q):
                    if new_m[lq] == s1:
                        lq_at_s1 = lq
                    if new_m[lq] == s2:
                        lq_at_s2 = lq

                if lq_at_s1 >= 0:
                    new_m[lq_at_s1] = s2
                if lq_at_s2 >= 0:
                    new_m[lq_at_s2] = s1

                new_g = g_cost + 1
                new_mk = mapping_key(new_m)
                child_key = (new_mk, new_exec_frozen)

                if child_key in visited and visited[child_key] <= new_g:
                    continue

                new_h = h_func(new_m, new_front_frozen)
                new_f = new_g + new_h

                if best_known_total < float('inf') and new_f > best_known_total * 1.2:
                    continue

                counter[0] += 1

                # Track pair swap counts
                child_pair_swaps = defaultdict(float, parent_pair_swaps)
                for g in new_front_frozen:
                    gq1, gq2 = gates_2q[g]
                    pair_key = (min(gq1, gq2), max(gq1, gq2))
                    child_pair_swaps[pair_key] += 1.0

                swap_history[child_key] = child_pair_swaps

                heapq.heappush(open_heap, (new_f, counter[0], new_g, new_m, new_exec_frozen, new_front_frozen))

        if best_result is not None:
            return defaultdict(float, best_result[1]), best_result[0]
        else:
            # Fallback: return empty (will use greedy for all)
            return defaultdict(float), 0

    # ---------------------------------------------------------------
    # Step 7: Greedy routing simulation (for layers beyond A* or fallback)
    # ---------------------------------------------------------------
    def simulate_routing_greedy(m, rm, max_layers=20):
        sim_m = list(m)
        sim_rm = list(rm)
        swap_counts = defaultdict(float)
        total_swaps = 0

        if not gates_2q:
            return swap_counts, total_swaps

        pred_remaining = {g: len(dag2q_pred[g]) for g in gates_2q}
        front = set(g for g in gates_2q if pred_remaining[g] == 0)
        layers_done = 0

        while front and layers_done < max_layers:
            executable = []
            for g in front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = sim_m[gq1], sim_m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    executable.append(g)

            if executable:
                for g in executable:
                    front.discard(g)
                    for s in dag2q_succ[g]:
                        pred_remaining[s] -= 1
                        if pred_remaining[s] == 0:
                            front.add(s)
                layers_done += 1
                continue

            active_phys = set()
            for g in front:
                gq1, gq2 = gates_2q[g]
                active_phys.add(sim_m[gq1])
                active_phys.add(sim_m[gq2])

            candidates_sw = set()
            for pq in active_phys:
                for nb in self.backend.get(pq, []):
                    candidates_sw.add((min(pq, nb), max(pq, nb)))

            best_swap, best_score = None, float('inf')
            for (s1, s2) in candidates_sw:
                l1, l2 = sim_rm[s1], sim_rm[s2]
                score = 0.0
                for g in front:
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = sim_m[gq1], sim_m[gq2]
                    if gq1 == l1: p1 = s2
                    elif gq1 == l2: p1 = s1
                    if gq2 == l1: p2 = s2
                    elif gq2 == l2: p2 = s1
                    deps = dep_count.get(g, 0) + 1
                    score += deps * dist[p1][p2]
                if score < best_score:
                    best_score = score
                    best_swap = (s1, s2)

            if best_swap is None:
                break

            s1, s2 = best_swap
            l1, l2 = sim_rm[s1], sim_rm[s2]
            sim_m[l1], sim_m[l2] = s2, s1
            sim_rm[s1], sim_rm[s2] = l2, l1
            total_swaps += 1

            for g in front:
                gq1, gq2 = gates_2q[g]
                pair_key = (min(gq1, gq2), max(gq1, gq2))
                swap_counts[pair_key] += 1.0

        return swap_counts, total_swaps

    def simulate_routing_hybrid(m, rm, max_layers=20):
        """
        Hybrid routing: A* for early layers, greedy for the rest.
        Combines per-pair swap counts from both phases.
        """
        # Phase 1: A* for early layers
        astar_swaps, astar_total = astar_routing_early(m, rm)

        # Phase 2: Simulate A* swaps on mapping, then continue with greedy
        sim_m = list(m)
        sim_rm = [-1] * num_q
        for lq in range(num_q):
            if sim_m[lq] >= 0:
                sim_rm[sim_m[lq]] = lq

        # We need to advance the DAG state past early layers
        # and apply the swaps that A* found implicitly
        # Since A* gives us cost but not the actual swap sequence,
        # just run greedy for all layers but boost early-layer weights
        # Actually, let's run greedy simulation for the full depth
        # but use A* feedback to boost weights for early pairs
        greedy_swaps, greedy_total = simulate_routing_greedy(m, rm, max_layers=max_layers)

        # Merge: A* exact feedback for early pairs, greedy for late
        combined_swaps = defaultdict(float)

        # Early layer pairs get A* feedback (exact cost)
        early_pairs = set()
        for g in early_layer_gates:
            gq1, gq2 = gates_2q[g]
            early_pairs.add((min(gq1, gq2), max(gq1, gq2)))

        for pair_key in early_pairs:
            if pair_key in astar_swaps:
                combined_swaps[pair_key] = astar_swaps[pair_key]
            # If A* says 0 swaps for this pair, we keep it at 0 (dampened)

        # Late layer pairs get greedy feedback
        for pair_key, count in greedy_swaps.items():
            if pair_key not in early_pairs:
                combined_swaps[pair_key] = count

        return combined_swaps, astar_total + greedy_total

    # ---------------------------------------------------------------
    # Step 8: Seed generation setup
    # ---------------------------------------------------------------
    sorted_by_degree = sorted(interacting_logical, key=lambda q: logical_degree[q], reverse=True)
    seed_lqs = sorted_by_degree[:min(3, len(sorted_by_degree))]
    phys_by_centrality = sorted(physical_qubits, key=lambda pq: phys_centrality[pq])
    seed_pqs = phys_by_centrality[:min(3, len(phys_by_centrality))]

    logical_degree_ranked = sorted(interacting_logical, key=lambda q: logical_degree[q], reverse=True)
    logical_degree_rank = {q: i for i, q in enumerate(logical_degree_ranked)}
    max_logical_rank = max(len(logical_degree_ranked) - 1, 1)
    phys_degree_ranked = sorted(physical_qubits, key=lambda pq: phys_degree[pq], reverse=True)
    phys_degree_rank = {pq: i for i, pq in enumerate(phys_degree_ranked)}
    max_phys_rank = max(len(phys_degree_ranked) - 1, 1)

    static_nbrs, static_deg = build_neighbors(static_weight)
    max_iw = max(static_weight.values()) if static_weight else 1.0

    # ---------------------------------------------------------------
    # Step 9: Conflict-Graph MIS Seed
    # ---------------------------------------------------------------
    def conflict_graph_seed(start_pq, nbrs, deg, weights):
        if len(interacting_logical) < 2:
            return None, None

        cur_max_iw = max(weights.values()) if weights else 1.0

        top_partners = {}
        for lq in interacting_logical:
            nbr_list = sorted(nbrs.get(lq, {}).items(), key=lambda x: x[1], reverse=True)
            top_partners[lq] = set(p for p, _ in nbr_list[:3])

        conflict_adj = defaultdict(set)
        il = interacting_logical
        for i in range(len(il)):
            for j in range(i + 1, len(il)):
                l1, l2 = il[i], il[j]
                s1 = top_partners.get(l1, set())
                s2 = top_partners.get(l2, set())
                if not s1 and not s2:
                    continue
                intersection = len(s1 & s2)
                union = len(s1 | s2)
                if union > 0 and intersection / union > 0.5:
                    conflict_adj[l1].add(l2)
                    conflict_adj[l2].add(l1)

        sorted_by_deg_local = sorted(interacting_logical, key=lambda q: deg.get(q, 0), reverse=True)
        mis = set()
        excluded = set()
        for lq in sorted_by_deg_local:
            if lq not in excluded:
                mis.add(lq)
                for neighbor in conflict_adj.get(lq, set()):
                    excluded.add(neighbor)

        non_mis = [lq for lq in sorted_by_deg_local if lq not in mis]
        mis_ordered = sorted(mis, key=lambda q: deg.get(q, 0), reverse=True)

        m = [-1] * num_q
        rm = [-1] * num_q
        used_phys = set()

        if mis_ordered:
            first_lq = mis_ordered[0]
            m[first_lq] = start_pq
            rm[start_pq] = first_lq
            used_phys.add(start_pq)

            for lq in mis_ordered[1:]:
                nbrs_placed = {}
                for plq in mis:
                    if m[plq] >= 0 and plq in nbrs.get(lq, {}):
                        nbrs_placed[plq] = nbrs[lq][plq]

                if nbrs_placed:
                    best_pq = None
                    best_score = float('inf')
                    for pq in physical_qubits:
                        if pq in used_phys:
                            continue
                        score = 0.0
                        for plq, iw in nbrs_placed.items():
                            d = dist[pq][m[plq]]
                            cost = iw * d
                            if m[plq] in hw_adj[pq]:
                                cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                            score += cost
                        if score < best_score:
                            best_score = score
                            best_pq = pq
                else:
                    best_pq = None
                    best_score = float('inf')
                    for pq in physical_qubits:
                        if pq not in used_phys:
                            if phys_centrality[pq] < best_score:
                                best_score = phys_centrality[pq]
                                best_pq = pq

                if best_pq is not None:
                    m[lq] = best_pq
                    rm[best_pq] = lq
                    used_phys.add(best_pq)

        placed_set = set(lq for lq in interacting_logical if m[lq] >= 0)

        for lq in non_mis:
            nbrs_placed = {}
            for plq in placed_set:
                w = nbrs.get(lq, {}).get(plq, 0.0)
                if w > 0:
                    nbrs_placed[plq] = w

            if nbrs_placed:
                near_ties = []
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq in used_phys:
                        continue
                    score = 0.0
                    for plq, iw in nbrs_placed.items():
                        d = dist[pq][m[plq]]
                        cost = iw * d
                        if m[plq] in hw_adj[pq]:
                            cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                        score += cost
                    near_ties.append((score, pq))
                    if score < best_score:
                        best_score = score

                if near_ties and best_score > 0:
                    threshold = best_score * 1.05
                    candidates_list = [(s, pq) for s, pq in near_ties if s <= threshold]
                    if len(candidates_list) > 1 and lq in logical_degree_rank:
                        lq_rn = logical_degree_rank[lq] / max_logical_rank
                        best_pq = min(candidates_list, key=lambda x: (
                            abs(phys_degree_rank[x[1]] / max_phys_rank - lq_rn), x[0]))[1]
                    else:
                        best_pq = min(candidates_list, key=lambda x: x[0])[1]
                elif near_ties:
                    best_pq = min(near_ties, key=lambda x: x[0])[1]
                else:
                    best_pq = None
            else:
                best_pq = None
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq not in used_phys:
                        if phys_centrality[pq] < best_score:
                            best_score = phys_centrality[pq]
                            best_pq = pq

            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                used_phys.add(best_pq)
                placed_set.add(lq)

        remaining_lqs = [lq for lq in logical_qubits if m[lq] == -1]
        for lq in remaining_lqs:
            best_pq = None
            best_score = float('inf')
            for pq in physical_qubits:
                if pq not in used_phys:
                    if phys_centrality[pq] < best_score:
                        best_score = phys_centrality[pq]
                        best_pq = pq
            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                used_phys.add(best_pq)

        return m, rm

    # ---------------------------------------------------------------
    # Step 10: Spectral ordering seed
    # ---------------------------------------------------------------
    def spectral_seed():
        if len(interacting_logical) < 3:
            return None, None

        idx_map = {q: i for i, q in enumerate(interacting_logical)}
        n = len(interacting_logical)

        L = [[0.0] * n for _ in range(n)]
        for (q1, q2), w in static_weight.items():
            if q1 in idx_map and q2 in idx_map:
                i, j = idx_map[q1], idx_map[q2]
                L[i][j] -= w
                L[j][i] -= w
                L[i][i] += w
                L[j][j] += w

        def power_iter(mat, n_iter=200):
            v = [random.gauss(0, 1) for _ in range(n)]
            for _ in range(n_iter):
                new_v = [0.0] * n
                for i in range(n):
                    for j in range(n):
                        new_v[i] += mat[i][j] * v[j]
                norm = math.sqrt(sum(x * x for x in new_v)) or 1e-12
                v = [x / norm for x in new_v]
            return v

        max_diag = max(L[i][i] for i in range(n)) + 1.0
        shifted = [[0.0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                shifted[i][j] = -L[i][j]
            shifted[i][i] += max_diag

        v1 = power_iter(shifted, 150)

        dot_v1 = sum(x * x for x in v1) or 1e-12
        lam1_shifted = sum(v1[i] * sum(shifted[i][j] * v1[j] for j in range(n)) for i in range(n)) / dot_v1
        shifted2 = [row[:] for row in shifted]
        for i in range(n):
            for j in range(n):
                shifted2[i][j] -= lam1_shifted * v1[i] * v1[j] / dot_v1

        fiedler = power_iter(shifted2, 200)

        fiedler_order = sorted(range(n), key=lambda i: fiedler[i])
        sorted_logical = [interacting_logical[i] for i in fiedler_order]

        phys_sorted = sorted(physical_qubits, key=lambda pq: phys_centrality[pq])
        start_pq = phys_sorted[0]
        visited = set()
        bfs_order = []
        bfs_q = deque([start_pq])
        visited.add(start_pq)
        while bfs_q:
            pq = bfs_q.popleft()
            bfs_order.append(pq)
            for nb in sorted(hw_adj[pq]):
                if nb not in visited:
                    visited.add(nb)
                    bfs_q.append(nb)
        for pq in physical_qubits:
            if pq not in visited:
                bfs_order.append(pq)
                visited.add(pq)

        m = [-1] * num_q
        rm = [-1] * num_q
        n_interact = len(sorted_logical)
        n_phys = len(bfs_order)
        offset = max(0, (n_phys - n_interact) // 2)
        for i, lq in enumerate(sorted_logical):
            pq = bfs_order[min(offset + i, n_phys - 1)]
            if rm[pq] != -1:
                best_pq = None
                best_d = float('inf')
                for cpq in physical_qubits:
                    if rm[cpq] == -1:
                        d = dist[pq][cpq]
                        if d < best_d:
                            best_d = d
                            best_pq = cpq
                pq = best_pq
            m[lq] = pq
            rm[pq] = lq

        return m, rm

    # ---------------------------------------------------------------
    # Step 11: Greedy placement
    # ---------------------------------------------------------------
    def run_greedy_placement(start_lq, start_pq, nbrs, deg, weights=None):
        cur_max_iw = max(weights.values()) if weights else max_iw
        used_phys = {start_pq}
        m = [-1] * num_q
        rm = [-1] * num_q
        m[start_lq] = start_pq
        rm[start_pq] = start_lq
        placed = {start_lq}
        remaining = set(logical_qubits) - placed

        while remaining:
            best_lq, best_w = None, -1.0
            for lq in remaining:
                w = sum(nbrs.get(lq, {}).get(plq, 0.0) for plq in placed)
                if w > best_w:
                    best_w = w
                    best_lq = lq

            nbrs_placed = {plq: nbrs.get(best_lq, {}).get(plq, 0.0)
                           for plq in placed if plq in nbrs.get(best_lq, {})}

            if nbrs_placed:
                near_ties = []
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq in used_phys:
                        continue
                    score = 0.0
                    for plq, iw in nbrs_placed.items():
                        d = dist[pq][m[plq]]
                        cost = iw * d
                        if m[plq] in hw_adj[pq]:
                            cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                        score += cost
                    near_ties.append((score, pq))
                    if score < best_score:
                        best_score = score

                if near_ties and best_score > 0:
                    threshold = best_score * 1.05
                    candidates_list = [(s, pq) for s, pq in near_ties if s <= threshold]
                    if len(candidates_list) > 1 and best_lq in logical_degree_rank:
                        lq_rn = logical_degree_rank[best_lq] / max_logical_rank
                        best_pq = min(candidates_list, key=lambda x: (
                            abs(phys_degree_rank[x[1]] / max_phys_rank - lq_rn), x[0]))[1]
                    else:
                        best_pq = min(candidates_list, key=lambda x: x[0])[1]
                elif near_ties:
                    best_pq = min(near_ties, key=lambda x: x[0])[1]
                else:
                    best_pq = None
            else:
                best_pq = None
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq not in used_phys:
                        score = phys_centrality[pq]
                        if score < best_score:
                            best_score = score
                            best_pq = pq

            m[best_lq] = best_pq
            rm[best_pq] = best_lq
            used_phys.add(best_pq)
            placed.add(best_lq)
            remaining.discard(best_lq)
        return m, rm

    def fill_unmapped(m, rm):
        unmapped = [q for q in range(num_q) if m[q] == -1]
        free = [pq for pq in range(num_q) if rm[pq] == -1]
        for lq, pq in zip(unmapped, free):
            m[lq] = pq
            rm[pq] = lq

    # ---------------------------------------------------------------
    # Step 12: Local search with nonlinear distance penalty
    # ---------------------------------------------------------------
    def local_search(m, rm, nbrs, weights, alpha_exp, max_rounds=5):
        if len(interacting_logical) <= 1:
            return compute_cost_nonlinear(m, weights, alpha_exp)
        for _ in range(max_rounds):
            improved = False
            best_d, best_pair = 0.0, None
            active_phys = [m[q] for q in interacting_logical]
            for pq1 in active_phys:
                for pq2 in hw_adj.get(pq1, set()):
                    d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                    if d < best_d:
                        best_d = d
                        best_pair = (pq1, pq2)
            n_random = min(150, len(interacting_logical) * 3)
            for _ in range(n_random):
                i, j = random.sample(range(len(interacting_logical)), 2)
                pq1, pq2 = m[interacting_logical[i]], m[interacting_logical[j]]
                d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                if d < best_d:
                    best_d = d
                    best_pair = (pq1, pq2)
            if best_pair and best_d < -1e-12:
                do_swap(m, rm, *best_pair)
                improved = True
            if not improved:
                for i in range(len(interacting_logical)):
                    for j in range(i + 1, len(interacting_logical)):
                        pq1, pq2 = m[interacting_logical[i]], m[interacting_logical[j]]
                        d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                        if d < best_d:
                            best_d = d
                            best_pair = (pq1, pq2)
                if best_pair and best_d < -1e-12:
                    do_swap(m, rm, *best_pair)
                else:
                    break
        return compute_cost_nonlinear(m, weights, alpha_exp)

    # ---------------------------------------------------------------
    # Step 13: Perturbation modes with bandit selection
    # ---------------------------------------------------------------
    rsdiwr_iter_ref = [0]

    def perturb_random(m, rm, **kw):
        if len(interacting_logical) >= 2:
            lqs = random.sample(interacting_logical, 2)
            do_swap(m, rm, m[lqs[0]], m[lqs[1]])

    def perturb_segment_shuffle(m, rm, **kw):
        k = min(random.randint(3, 5), len(interacting_logical))
        if k < 2:
            perturb_random(m, rm)
            return
        lqs = random.sample(interacting_logical, k)
        phys_positions = [m[lq] for lq in lqs]
        random.shuffle(phys_positions)
        for lq in lqs:
            rm[m[lq]] = -1
        for lq, pq in zip(lqs, phys_positions):
            m[lq] = pq
            rm[pq] = lq

    def perturb_worst_pair(m, rm, weights=None, alpha_exp=1.5, **kw):
        if weights is None:
            perturb_random(m, rm)
            return
        pair_costs = []
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                d = dist[m[q1]][m[q2]]
                c = w * (d ** alpha_exp)
                pair_costs.append((c, q1, q2))
        if not pair_costs:
            return
        pair_costs.sort(reverse=True)
        top_n = min(3, len(pair_costs))
        _, tq1, tq2 = pair_costs[random.randint(0, top_n - 1)]
        pq1, pq2 = m[tq1], m[tq2]
        adj_of_pq2 = list(hw_adj.get(pq2, set()))
        if adj_of_pq2:
            target = random.choice(adj_of_pq2)
            if target != pq1:
                do_swap(m, rm, pq1, target)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    def perturb_edge_targeted(m, rm, weights=None, alpha_exp=1.5, **kw):
        if weights is None:
            perturb_random(m, rm)
            return
        edge_costs = []
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                c = w * (dist[m[q1]][m[q2]] ** alpha_exp)
                edge_costs.append((c, q1, q2))
        if not edge_costs:
            return
        edge_costs.sort(reverse=True)
        top_n = min(5, len(edge_costs))
        _, eq1, eq2 = edge_costs[random.randint(0, top_n - 1)]
        pq1, pq2 = m[eq1], m[eq2]
        neighbors_of_pq2 = list(hw_adj.get(pq2, set()))
        if neighbors_of_pq2:
            target = random.choice(neighbors_of_pq2)
            if target != pq1:
                do_swap(m, rm, pq1, target)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    def perturb_lns(m, rm, nbrs=None, alpha_exp=1.5, **kw):
        if nbrs is None or len(interacting_logical) < 3:
            perturb_random(m, rm)
            return
        base_lo = 3 + rsdiwr_iter_ref[0]
        base_hi = 8 + rsdiwr_iter_ref[0] * 2
        k = min(random.randint(base_lo, base_hi), len(interacting_logical))
        qcost = {}
        for lq in interacting_logical:
            c = 0.0
            for partner, w in nbrs.get(lq, {}).items():
                if m[partner] >= 0 and m[lq] >= 0:
                    c += w * (dist[m[lq]][m[partner]] ** alpha_exp)
            qcost[lq] = c
        sorted_qs = sorted(qcost, key=lambda q: qcost[q], reverse=True)
        top_half = sorted_qs[:max(k, len(sorted_qs) // 2)]
        subset = random.sample(top_half, min(k, len(top_half)))

        freed_phys = []
        for lq in subset:
            freed_phys.append(m[lq])
            rm[m[lq]] = -1
            m[lq] = -1

        placed_set = set(lq for lq in interacting_logical if m[lq] >= 0)
        for lq in sorted(subset, key=lambda q: qcost[q], reverse=True):
            best_pq, best_sc = None, float('inf')
            for pq in freed_phys:
                if rm[pq] != -1:
                    continue
                sc = 0.0
                for partner, w in nbrs.get(lq, {}).items():
                    if partner in placed_set and m[partner] >= 0:
                        sc += w * (dist[pq][m[partner]] ** alpha_exp)
                if sc < best_sc:
                    best_sc = sc
                    best_pq = pq
            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                placed_set.add(lq)
            else:
                for pq in freed_phys:
                    if rm[pq] == -1:
                        m[lq] = pq
                        rm[pq] = lq
                        placed_set.add(lq)
                        break

    perturbation_modes = [perturb_random, perturb_segment_shuffle,
                          perturb_worst_pair, perturb_edge_targeted, perturb_lns]
    K = len(perturbation_modes)

    WINDOW_SIZE = 100
    EPSILON = 0.1
    window = []
    mode_successes = [0] * K
    mode_attempts = [0] * K

    def select_perturbation_mode():
        if random.random() < EPSILON or sum(mode_attempts) < K * 2:
            return random.randint(0, K - 1)
        rates = []
        for k in range(K):
            if mode_attempts[k] > 0:
                rates.append(mode_successes[k] / mode_attempts[k])
            else:
                rates.append(1.0)
        total = sum(rates)
        if total < 1e-12:
            return random.randint(0, K - 1)
        r = random.random() * total
        cumul = 0.0
        for k in range(K):
            cumul += rates[k]
            if r <= cumul:
                return k
        return K - 1

    def update_window(mode_idx, success):
        window.append((mode_idx, success))
        mode_attempts[mode_idx] += 1
        if success:
            mode_successes[mode_idx] += 1
        if len(window) > WINDOW_SIZE:
            old_mode, old_success = window.pop(0)
            mode_attempts[old_mode] -= 1
            if old_success:
                mode_successes[old_mode] -= 1

    # ---------------------------------------------------------------
    # Step 14: Build initial mapping candidates
    # ---------------------------------------------------------------
    candidates = []

    for s_lq in seed_lqs:
        for s_pq in seed_pqs:
            m, rm = run_greedy_placement(s_lq, s_pq, static_nbrs, static_deg,
                                         weights=static_weight)
            fill_unmapped(m, rm)
            cost = compute_cost(m, static_weight)
            candidates.append((cost, m, rm))

    for s_pq in seed_pqs:
        cg_m, cg_rm = conflict_graph_seed(s_pq, static_nbrs, static_deg, static_weight)
        if cg_m is not None:
            fill_unmapped(cg_m, cg_rm)
            cost = compute_cost(cg_m, static_weight)
            candidates.append((cost, cg_m, cg_rm))

    spec_m, spec_rm = spectral_seed()
    if spec_m is not None:
        fill_unmapped(spec_m, spec_rm)
        spec_cost = compute_cost(spec_m, static_weight)
        candidates.append((spec_cost, spec_m, spec_rm))

    m_rand = [-1] * num_q
    rm_rand = [-1] * num_q
    shuffled_phys = list(physical_qubits)
    random.shuffle(shuffled_phys)
    for i, lq in enumerate(logical_qubits):
        m_rand[lq] = shuffled_phys[i]
        rm_rand[shuffled_phys[i]] = lq
    fill_unmapped(m_rand, rm_rand)
    c = compute_cost(m_rand, static_weight)
    candidates.append((c, m_rand, rm_rand))

    if not candidates:
        self.mapping_dict = list(range(num_q))
        self.reverse_mapping_dict = list(range(num_q))
        if self.use_isl:
            self.isl_mapping = dict_to_isl_map(self.mapping_dict)
        return

    candidates.sort(key=lambda x: x[0])

    _, best_m, best_rm = candidates[0]
    best_m, best_rm = list(best_m), list(best_rm)
    local_search(best_m, best_rm, static_nbrs, static_weight, alpha_exp=2.0, max_rounds=6)
    best_cost = compute_cost(best_m, static_weight)

    for idx in range(1, min(5, len(candidates))):
        _, m_c, rm_c = candidates[idx]
        m_c, rm_c = list(m_c), list(rm_c)
        local_search(m_c, rm_c, static_nbrs, static_weight, alpha_exp=2.0, max_rounds=4)
        c = compute_cost(m_c, static_weight)
        if c < best_cost:
            best_cost = c
            best_m = list(m_c)
            best_rm = list(rm_c)

    # ---------------------------------------------------------------
    # Step 15: RSDIWR + ILS with A*-guided first iteration
    # ---------------------------------------------------------------
    time_budget = 25.0
    t_start = _time()
    n_rsdiwr = 4

    cur_m = list(best_m)
    cur_rm = list(best_rm)
    swap_counts = defaultdict(float)

    for rsdiwr_iter in range(n_rsdiwr):
        rsdiwr_iter_ref[0] = rsdiwr_iter
        elapsed = _time() - t_start
        if elapsed > time_budget:
            break

        remaining_time = time_budget - elapsed
        remaining_iters = n_rsdiwr - rsdiwr_iter
        time_for_this_iter = remaining_time / max(remaining_iters, 1)
        n_ils = max(55, int(num_q * time_for_this_iter / 0.5)) if time_for_this_iter > 1.0 else max(30, num_q // 3)

        # Blend static weights with routing feedback
        if rsdiwr_iter == 0 or not swap_counts:
            eff_weights = dict(static_weight)
        else:
            max_sw = max(swap_counts.values()) if swap_counts else 1.0
            scale = max(static_weight.values()) / max(max_sw, 1e-10)
            alpha_blend = max(0.3, 1.0 - 0.3 * rsdiwr_iter)
            eff_weights = defaultdict(float)
            all_keys = set(static_weight.keys()) | set(swap_counts.keys())
            for key in all_keys:
                w_s = static_weight.get(key, 0.0)
                w_r = swap_counts.get(key, 0.0) * scale
                eff_weights[key] = alpha_blend * w_s + (1.0 - alpha_blend) * w_r

        eff_nbrs, eff_deg = build_neighbors(eff_weights)

        # Re-seed with routing-informed weights
        if rsdiwr_iter > 0 and swap_counts and (_time() - t_start) < time_budget * 0.7:
            eff_sorted = sorted(interacting_logical,
                                key=lambda q: eff_deg.get(q, 0), reverse=True)
            reseed_lqs = eff_sorted[:min(2, len(eff_sorted))]
            reseed_pqs = seed_pqs[:min(2, len(seed_pqs))]

            for s_lq in reseed_lqs:
                for s_pq in reseed_pqs:
                    rm_new, rmm_new = run_greedy_placement(
                        s_lq, s_pq, eff_nbrs, eff_deg, weights=eff_weights)
                    fill_unmapped(rm_new, rmm_new)
                    local_search(rm_new, rmm_new, eff_nbrs, eff_weights,
                                 alpha_exp=2.0, max_rounds=3)
                    sc = compute_cost(rm_new, static_weight)
                    if sc < best_cost:
                        best_cost = sc
                        best_m = list(rm_new)
                        best_rm = list(rmm_new)
                        cur_m = list(rm_new)
                        cur_rm = list(rmm_new)

            for s_pq in reseed_pqs:
                cg_m, cg_rm = conflict_graph_seed(s_pq, eff_nbrs, eff_deg, eff_weights)
                if cg_m is not None:
                    fill_unmapped(cg_m, cg_rm)
                    local_search(cg_m, cg_rm, eff_nbrs, eff_weights,
                                 alpha_exp=2.0, max_rounds=3)
                    sc = compute_cost(cg_m, static_weight)
                    if sc < best_cost:
                        best_cost = sc
                        best_m = list(cg_m)
                        best_rm = list(cg_rm)
                        cur_m = list(cg_m)
                        cur_rm = list(cg_rm)

        alpha_start = 2.0
        alpha_end = 1.0

        ls_rounds = 6 if rsdiwr_iter == 0 else 4
        cur_cost_nl = local_search(cur_m, cur_rm, eff_nbrs, eff_weights,
                                   alpha_exp=alpha_start, max_rounds=ls_rounds)

        static_cost = compute_cost(cur_m, static_weight)
        if static_cost < best_cost:
            best_cost = static_cost
            best_m = list(cur_m)
            best_rm = list(cur_rm)

        # Reset bandit window
        window.clear()
        for k in range(K):
            mode_successes[k] = 0
            mode_attempts[k] = 0

        T = max(cur_cost_nl * 0.05, 1.0)
        T_init = T
        alpha_sa = 0.94
        reheat_interval = max(n_ils // 4, 8)

        for ils_iter in range(n_ils):
            if _time() - t_start > time_budget:
                break

            progress = ils_iter / max(n_ils - 1, 1)
            alpha_exp = alpha_start + (alpha_end - alpha_start) * progress

            saved_m = list(cur_m)
            saved_rm = list(cur_rm)
            saved_cost = cur_cost_nl

            mode = select_perturbation_mode()
            perturbation_modes[mode](cur_m, cur_rm,
                                    nbrs=eff_nbrs, weights=eff_weights,
                                    alpha_exp=alpha_exp)

            new_cost_nl = local_search(cur_m, cur_rm, eff_nbrs, eff_weights,
                                       alpha_exp=alpha_exp, max_rounds=3)

            success = new_cost_nl < saved_cost - 1e-12

            improvement = saved_cost - new_cost_nl
            if improvement > 0:
                cur_cost_nl = new_cost_nl
                sc = compute_cost(cur_m, static_weight)
                if sc < best_cost:
                    best_cost = sc
                    best_m = list(cur_m)
                    best_rm = list(cur_rm)
            elif random.random() < math.exp(min(0, improvement / max(T, 1e-10))):
                cur_cost_nl = new_cost_nl
            else:
                cur_m[:] = saved_m
                cur_rm[:] = saved_rm
                cur_cost_nl = saved_cost

            update_window(mode, success)

            T *= alpha_sa
            if (ils_iter + 1) % reheat_interval == 0:
                T = max(T, T_init * 0.35)

        # Routing simulation with A*-guided feedback for first iteration
        if rsdiwr_iter < n_rsdiwr - 1:
            sim_depth = 14 + rsdiwr_iter * 7

            if rsdiwr_iter == 0 and early_layer_gates:
                # Use A*-guided hybrid routing for first RSDIWR iteration
                swap_counts, _ = simulate_routing_hybrid(best_m, best_rm, max_layers=sim_depth)
            else:
                # Standard greedy routing for subsequent iterations
                swap_counts, _ = simulate_routing_greedy(best_m, best_rm, max_layers=sim_depth)

        cur_m = list(best_m)
        cur_rm = list(best_rm)
        cur_cost_nl = compute_cost_nonlinear(cur_m, eff_weights, alpha_end)

    # ---------------------------------------------------------------
    # Step 16: Set final mapping
    # ---------------------------------------------------------------
    self.mapping_dict = best_m
    self.reverse_mapping_dict = best_rm

    if self.use_isl:
        self.isl_mapping = dict_to_isl_map(self.mapping_dict)

def init_mapping(self):
    import math
    import random
    import heapq
    from collections import defaultdict, deque
    from time import time as _time

    num_q = self.num_qubits
    physical_qubits = sorted(self.backend.keys())
    dist = self.distance_matrix

    # ---------------------------------------------------------------
    # Step 1: Build DAG and topological layers
    # ---------------------------------------------------------------
    all_gates = sorted(self.access.keys())
    two_qubit_gates = [g for g in all_gates if len(self.access[g]) == 2]

    last_gate_on_qubit = {}
    successors_dag = defaultdict(set)
    predecessors_dag = defaultdict(set)
    for g in all_gates:
        for q in self.access[g]:
            if q in last_gate_on_qubit:
                pred = last_gate_on_qubit[q]
                successors_dag[pred].add(g)
                predecessors_dag[g].add(pred)
            last_gate_on_qubit[q] = g

    in_degree = {g: len(predecessors_dag[g]) for g in all_gates}
    gate_layer = {g: 0 for g in all_gates}
    temp_in = dict(in_degree)
    queue = deque(g for g in all_gates if in_degree[g] == 0)
    topo_order = []
    while queue:
        g = queue.popleft()
        topo_order.append(g)
        for s in successors_dag[g]:
            gate_layer[s] = max(gate_layer[s], gate_layer[g] + 1)
            temp_in[s] -= 1
            if temp_in[s] == 0:
                queue.append(s)

    critical_path = {g: 0 for g in all_gates}
    for g in reversed(topo_order):
        for s in successors_dag[g]:
            if critical_path[s] + 1 > critical_path[g]:
                critical_path[g] = critical_path[s] + 1

    # 2q DAG for routing simulation
    gates_2q = {}
    dag2q_succ = defaultdict(set)
    dag2q_pred = defaultdict(set)
    last_2q_on_qubit = {}
    logical_qubits_set = set()

    for gate in all_gates:
        qubits = self.access[gate]
        if len(qubits) == 2:
            q1, q2 = qubits
            gates_2q[gate] = (q1, q2)
            logical_qubits_set.add(q1)
            logical_qubits_set.add(q2)
            for q in [q1, q2]:
                if q in last_2q_on_qubit:
                    prev = last_2q_on_qubit[q]
                    if prev != gate:
                        dag2q_succ[prev].add(gate)
                        dag2q_pred[gate].add(prev)
                last_2q_on_qubit[q] = gate
        elif len(qubits) == 1:
            logical_qubits_set.add(qubits[0])

    logical_qubits = sorted(logical_qubits_set)

    if not gates_2q:
        self.mapping_dict = list(range(num_q))
        self.reverse_mapping_dict = list(range(num_q))
        if self.use_isl:
            self.isl_mapping = dict_to_isl_map(self.mapping_dict)
        return

    # Topological order for 2q DAG
    topo_2q = []
    in_deg_2q = {g: len(dag2q_pred[g]) for g in gates_2q}
    q2 = deque(sorted(g for g in gates_2q if in_deg_2q[g] == 0))
    while q2:
        g = q2.popleft()
        topo_2q.append(g)
        for s in dag2q_succ[g]:
            in_deg_2q[s] -= 1
            if in_deg_2q[s] == 0:
                q2.append(s)

    dep_count = defaultdict(int)
    for g in reversed(topo_2q):
        for s in dag2q_succ[g]:
            dep_count[g] = max(dep_count[g], dep_count[s] + 1)

    # Reverse topological order for backward routing
    rev_topo_2q = list(reversed(topo_2q))

    # ---------------------------------------------------------------
    # Step 2: Interaction weights — critical-path weighting
    # ---------------------------------------------------------------
    max_layer = max((gate_layer[g] for g in two_qubit_gates), default=1)

    static_weight = defaultdict(float)
    logical_degree = defaultdict(float)

    for g in two_qubit_gates:
        q1, q2 = self.access[g]
        cp = critical_path[g] + 1
        layer = gate_layer[g]
        w = cp * (max_layer - layer + 1)
        key = (min(q1, q2), max(q1, q2))
        static_weight[key] += w
        logical_degree[q1] += w
        logical_degree[q2] += w

    interacting_logical = [q for q in logical_qubits if logical_degree.get(q, 0) > 0]

    # ---------------------------------------------------------------
    # Step 3: Physical graph properties
    # ---------------------------------------------------------------
    hw_adj = defaultdict(set)
    for pq in physical_qubits:
        for pq2 in self.backend.get(pq, []):
            hw_adj[pq].add(pq2)

    phys_degree = {pq: len(hw_adj[pq]) for pq in physical_qubits}
    phys_centrality = {}
    for pq in physical_qubits:
        phys_centrality[pq] = sum(dist[pq][pq2] for pq2 in physical_qubits)

    # ---------------------------------------------------------------
    # Step 4: Helper functions
    # ---------------------------------------------------------------
    def build_neighbors(weights):
        nbrs = defaultdict(dict)
        deg = defaultdict(float)
        for (q1, q2), w in weights.items():
            nbrs[q1][q2] = w
            nbrs[q2][q1] = w
            deg[q1] += w
            deg[q2] += w
        return nbrs, deg

    def compute_cost_nonlinear(m, weights, alpha_exp):
        cost = 0.0
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                d = dist[m[q1]][m[q2]]
                cost += w * (d ** alpha_exp)
        return cost

    def compute_cost(m, weights):
        cost = 0.0
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                cost += w * dist[m[q1]][m[q2]]
        return cost

    def delta_swap_cost_nonlinear(m, rm, pq_a, pq_b, nbrs, alpha_exp):
        lq_a, lq_b = rm[pq_a], rm[pq_b]
        delta = 0.0
        affected = set()
        if lq_a in nbrs:
            affected.update(nbrs[lq_a].keys())
        if lq_b in nbrs:
            affected.update(nbrs[lq_b].keys())
        for q in affected:
            if q == lq_a or q == lq_b:
                continue
            pq_q = m[q]
            w_a = nbrs.get(lq_a, {}).get(q, 0.0)
            if w_a > 0:
                old_d = dist[pq_a][pq_q] ** alpha_exp
                new_d = dist[pq_b][pq_q] ** alpha_exp
                delta += w_a * (new_d - old_d)
            w_b = nbrs.get(lq_b, {}).get(q, 0.0)
            if w_b > 0:
                old_d = dist[pq_b][pq_q] ** alpha_exp
                new_d = dist[pq_a][pq_q] ** alpha_exp
                delta += w_b * (new_d - old_d)
        return delta

    def do_swap(m, rm, pq_a, pq_b):
        lq_a, lq_b = rm[pq_a], rm[pq_b]
        m[lq_a], m[lq_b] = pq_b, pq_a
        rm[pq_a], rm[pq_b] = lq_b, lq_a

    # ---------------------------------------------------------------
    # Step 5: A* early-layer routing setup with adaptive node limit
    # ---------------------------------------------------------------
    ASTAR_LAYERS = 5
    # Adaptive node limit: smaller circuits get more thorough A*
    n_2q = len(gates_2q)
    if n_2q < 50:
        ASTAR_NODE_LIMIT = 8000
    elif n_2q < 200:
        ASTAR_NODE_LIMIT = 5000
    else:
        ASTAR_NODE_LIMIT = 3000

    pred_rem_layer = {g: len(dag2q_pred[g]) for g in gates_2q}
    front_layer_calc = set(g for g in gates_2q if pred_rem_layer[g] == 0)
    current_layer = 0
    early_layer_gates = set()

    temp_front = set(front_layer_calc)
    while temp_front:
        for g in temp_front:
            if current_layer < ASTAR_LAYERS:
                early_layer_gates.add(g)
        next_front = set()
        for g in temp_front:
            for s in dag2q_succ[g]:
                pred_rem_layer[s] -= 1
                if pred_rem_layer[s] == 0:
                    next_front.add(s)
        current_layer += 1
        temp_front = next_front

    # ---------------------------------------------------------------
    # Step 6: A*-guided routing for early layers
    # ---------------------------------------------------------------
    def astar_routing_early(m, rm):
        if not early_layer_gates:
            return defaultdict(float), 0

        early_pred = {}
        for g in early_layer_gates:
            early_pred[g] = len(dag2q_pred[g] & early_layer_gates)

        initial_front = frozenset(g for g in early_layer_gates if early_pred[g] == 0)

        init_executed = set()
        cur_front = set(initial_front)
        changed = True
        while changed:
            changed = False
            newly_exec = set()
            for g in cur_front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = m[gq1], m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    newly_exec.add(g)
            if newly_exec:
                changed = True
                init_executed |= newly_exec
                cur_front -= newly_exec
                for g in newly_exec:
                    for s in dag2q_succ[g]:
                        if s in early_layer_gates and s not in init_executed:
                            all_pred_done = True
                            for p in dag2q_pred[s]:
                                if p in early_layer_gates and p not in init_executed:
                                    all_pred_done = False
                                    break
                            if all_pred_done:
                                cur_front.add(s)

        remaining_early = early_layer_gates - init_executed
        if not remaining_early:
            return defaultdict(float), 0

        def compute_front(executed):
            front = set()
            for g in early_layer_gates:
                if g in executed:
                    continue
                all_pred = True
                for p in dag2q_pred[g]:
                    if p in early_layer_gates and p not in executed:
                        all_pred = False
                        break
                if all_pred:
                    front.add(g)
            return frozenset(front)

        init_exec_frozen = frozenset(init_executed)
        init_front_astar = compute_front(init_executed)

        active_logical = set()
        for g in remaining_early:
            gq1, gq2 = gates_2q[g]
            active_logical.add(gq1)
            active_logical.add(gq2)

        def h_func(mapping, front_gates):
            h = 0
            for g in front_gates:
                gq1, gq2 = gates_2q[g]
                h += dist[mapping[gq1]][mapping[gq2]]
            return h

        active_logical_list = sorted(active_logical)

        def mapping_key(mapping):
            return tuple(mapping[lq] for lq in active_logical_list)

        init_m = list(m)
        init_h = h_func(init_m, init_front_astar)

        counter = [0]
        start_state = (init_h, 0, 0, init_m, init_exec_frozen, init_front_astar)
        open_heap = [start_state]
        visited = {}
        best_known_total = float('inf')
        best_result = None

        swap_history = {}
        init_key = (mapping_key(init_m), init_exec_frozen)
        swap_history[init_key] = defaultdict(float)

        expansions = 0

        while open_heap and expansions < ASTAR_NODE_LIMIT:
            f, _, g_cost, cur_m_list, executed, front = heapq.heappop(open_heap)

            mk = mapping_key(cur_m_list)
            state_key = (mk, executed)

            if state_key in visited and visited[state_key] <= g_cost:
                continue
            visited[state_key] = g_cost

            if best_known_total < float('inf') and f > best_known_total * 1.2:
                continue

            new_executed = set(executed)
            new_front = set(front)
            progress = True
            while progress:
                progress = False
                newly_exec = set()
                for g in list(new_front):
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = cur_m_list[gq1], cur_m_list[gq2]
                    if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                        newly_exec.add(g)
                if newly_exec:
                    progress = True
                    new_executed |= newly_exec
                    new_front -= newly_exec
                    for g in newly_exec:
                        for s in dag2q_succ[g]:
                            if s in early_layer_gates and s not in new_executed:
                                all_pred = True
                                for p in dag2q_pred[s]:
                                    if p in early_layer_gates and p not in new_executed:
                                        all_pred = False
                                        break
                                if all_pred:
                                    new_front.add(s)

            new_exec_frozen = frozenset(new_executed)
            new_front_frozen = frozenset(new_front)

            if not (early_layer_gates - new_executed):
                if g_cost < best_known_total:
                    best_known_total = g_cost
                    parent_key = (mk, executed)
                    pair_swaps = dict(swap_history.get(parent_key, {}))
                    best_result = (g_cost, pair_swaps)
                continue

            if not new_front_frozen:
                continue

            active_phys = set()
            for g in new_front_frozen:
                gq1, gq2 = gates_2q[g]
                active_phys.add(cur_m_list[gq1])
                active_phys.add(cur_m_list[gq2])
            ext_gates = set()
            for g in new_front_frozen:
                for s in dag2q_succ[g]:
                    if s in early_layer_gates and s not in new_executed:
                        ext_gates.add(s)
            for g in ext_gates:
                gq1, gq2 = gates_2q[g]
                active_phys.add(cur_m_list[gq1])
                active_phys.add(cur_m_list[gq2])

            swaps = set()
            for pq in active_phys:
                for nb in hw_adj.get(pq, set()):
                    swaps.add((min(pq, nb), max(pq, nb)))

            expansions += 1
            parent_pair_swaps = swap_history.get((mk, executed), defaultdict(float))

            for (s1, s2) in swaps:
                new_m = list(cur_m_list)
                lq_at_s1 = -1
                lq_at_s2 = -1
                for lq in range(num_q):
                    if new_m[lq] == s1:
                        lq_at_s1 = lq
                    if new_m[lq] == s2:
                        lq_at_s2 = lq

                if lq_at_s1 >= 0:
                    new_m[lq_at_s1] = s2
                if lq_at_s2 >= 0:
                    new_m[lq_at_s2] = s1

                new_g = g_cost + 1
                new_mk = mapping_key(new_m)
                child_key = (new_mk, new_exec_frozen)

                if child_key in visited and visited[child_key] <= new_g:
                    continue

                new_h = h_func(new_m, new_front_frozen)
                new_f = new_g + new_h

                if best_known_total < float('inf') and new_f > best_known_total * 1.2:
                    continue

                counter[0] += 1

                child_pair_swaps = defaultdict(float, parent_pair_swaps)
                for g in new_front_frozen:
                    gq1, gq2 = gates_2q[g]
                    pair_key = (min(gq1, gq2), max(gq1, gq2))
                    child_pair_swaps[pair_key] += 1.0

                swap_history[child_key] = child_pair_swaps

                heapq.heappush(open_heap, (new_f, counter[0], new_g, new_m, new_exec_frozen, new_front_frozen))

        if best_result is not None:
            return defaultdict(float, best_result[1]), best_result[0]
        else:
            return defaultdict(float), 0

    # ---------------------------------------------------------------
    # Step 7: Greedy routing simulation (forward direction)
    # ---------------------------------------------------------------
    def simulate_routing_greedy(m, rm, max_layers=20):
        sim_m = list(m)
        sim_rm = list(rm)
        swap_counts = defaultdict(float)
        total_swaps = 0

        if not gates_2q:
            return swap_counts, total_swaps

        pred_remaining = {g: len(dag2q_pred[g]) for g in gates_2q}
        front = set(g for g in gates_2q if pred_remaining[g] == 0)
        layers_done = 0

        while front and layers_done < max_layers:
            executable = []
            for g in front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = sim_m[gq1], sim_m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    executable.append(g)

            if executable:
                for g in executable:
                    front.discard(g)
                    for s in dag2q_succ[g]:
                        pred_remaining[s] -= 1
                        if pred_remaining[s] == 0:
                            front.add(s)
                layers_done += 1
                continue

            active_phys = set()
            for g in front:
                gq1, gq2 = gates_2q[g]
                active_phys.add(sim_m[gq1])
                active_phys.add(sim_m[gq2])

            candidates_sw = set()
            for pq in active_phys:
                for nb in self.backend.get(pq, []):
                    candidates_sw.add((min(pq, nb), max(pq, nb)))

            best_swap, best_score = None, float('inf')
            for (s1, s2) in candidates_sw:
                l1, l2 = sim_rm[s1], sim_rm[s2]
                score = 0.0
                for g in front:
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = sim_m[gq1], sim_m[gq2]
                    if gq1 == l1: p1 = s2
                    elif gq1 == l2: p1 = s1
                    if gq2 == l1: p2 = s2
                    elif gq2 == l2: p2 = s1
                    deps = dep_count.get(g, 0) + 1
                    score += deps * dist[p1][p2]
                if score < best_score:
                    best_score = score
                    best_swap = (s1, s2)

            if best_swap is None:
                break

            s1, s2 = best_swap
            l1, l2 = sim_rm[s1], sim_rm[s2]
            sim_m[l1], sim_m[l2] = s2, s1
            sim_rm[s1], sim_rm[s2] = l2, l1
            total_swaps += 1

            for g in front:
                gq1, gq2 = gates_2q[g]
                pair_key = (min(gq1, gq2), max(gq1, gq2))
                swap_counts[pair_key] += 1.0

        return swap_counts, total_swaps

    # ---------------------------------------------------------------
    # Step 7b: Backward greedy routing simulation
    #   Runs the DAG in reverse: successors become predecessors.
    #   Provides complementary swap feedback to forward routing.
    # ---------------------------------------------------------------
    def simulate_routing_backward(m, rm, max_layers=20):
        sim_m = list(m)
        sim_rm = list(rm)
        swap_counts = defaultdict(float)
        total_swaps = 0

        if not gates_2q:
            return swap_counts, total_swaps

        # In backward mode, "predecessors" are dag2q_succ and vice versa
        succ_remaining = {g: len(dag2q_succ[g] & set(gates_2q.keys())) for g in gates_2q}
        # "front" = gates with no successors in the 2q DAG (sinks)
        front = set(g for g in gates_2q if succ_remaining[g] == 0)
        layers_done = 0

        # Backward dep count: number of predecessors transitively
        bwd_dep = defaultdict(int)
        for g in topo_2q:
            for p in dag2q_pred[g]:
                if p in gates_2q:
                    bwd_dep[g] = max(bwd_dep[g], bwd_dep[p] + 1)

        while front and layers_done < max_layers:
            executable = []
            for g in front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = sim_m[gq1], sim_m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    executable.append(g)

            if executable:
                for g in executable:
                    front.discard(g)
                    for p in dag2q_pred[g]:
                        if p in gates_2q:
                            succ_remaining[p] -= 1
                            if succ_remaining[p] == 0:
                                front.add(p)
                layers_done += 1
                continue

            active_phys = set()
            for g in front:
                gq1, gq2 = gates_2q[g]
                active_phys.add(sim_m[gq1])
                active_phys.add(sim_m[gq2])

            candidates_sw = set()
            for pq in active_phys:
                for nb in self.backend.get(pq, []):
                    candidates_sw.add((min(pq, nb), max(pq, nb)))

            best_swap, best_score = None, float('inf')
            for (s1, s2) in candidates_sw:
                l1, l2 = sim_rm[s1], sim_rm[s2]
                score = 0.0
                for g in front:
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = sim_m[gq1], sim_m[gq2]
                    if gq1 == l1: p1 = s2
                    elif gq1 == l2: p1 = s1
                    if gq2 == l1: p2 = s2
                    elif gq2 == l2: p2 = s1
                    deps = bwd_dep.get(g, 0) + 1
                    score += deps * dist[p1][p2]
                if score < best_score:
                    best_score = score
                    best_swap = (s1, s2)

            if best_swap is None:
                break

            s1, s2 = best_swap
            l1, l2 = sim_rm[s1], sim_rm[s2]
            sim_m[l1], sim_m[l2] = s2, s1
            sim_rm[s1], sim_rm[s2] = l2, l1
            total_swaps += 1

            for g in front:
                gq1, gq2 = gates_2q[g]
                pair_key = (min(gq1, gq2), max(gq1, gq2))
                swap_counts[pair_key] += 1.0

        return swap_counts, total_swaps

    # ---------------------------------------------------------------
    # Step 7c: Bidirectional routing — averages forward + backward
    # ---------------------------------------------------------------
    def simulate_routing_bidirectional(m, rm, max_layers=20):
        fwd_swaps, fwd_total = simulate_routing_greedy(m, rm, max_layers=max_layers)
        bwd_swaps, bwd_total = simulate_routing_backward(m, rm, max_layers=max_layers)

        combined = defaultdict(float)
        all_keys = set(fwd_swaps.keys()) | set(bwd_swaps.keys())
        for key in all_keys:
            combined[key] = 0.5 * fwd_swaps.get(key, 0.0) + 0.5 * bwd_swaps.get(key, 0.0)

        return combined, (fwd_total + bwd_total) // 2

    def simulate_routing_hybrid(m, rm, max_layers=20):
        astar_swaps, astar_total = astar_routing_early(m, rm)
        greedy_swaps, greedy_total = simulate_routing_greedy(m, rm, max_layers=max_layers)

        combined_swaps = defaultdict(float)
        early_pairs = set()
        for g in early_layer_gates:
            gq1, gq2 = gates_2q[g]
            early_pairs.add((min(gq1, gq2), max(gq1, gq2)))

        for pair_key in early_pairs:
            if pair_key in astar_swaps:
                combined_swaps[pair_key] = astar_swaps[pair_key]

        for pair_key, count in greedy_swaps.items():
            if pair_key not in early_pairs:
                combined_swaps[pair_key] = count

        return combined_swaps, astar_total + greedy_total

    # ---------------------------------------------------------------
    # Step 8: Seed generation setup
    # ---------------------------------------------------------------
    sorted_by_degree = sorted(interacting_logical, key=lambda q: logical_degree[q], reverse=True)
    seed_lqs = sorted_by_degree[:min(3, len(sorted_by_degree))]
    phys_by_centrality = sorted(physical_qubits, key=lambda pq: phys_centrality[pq])
    seed_pqs = phys_by_centrality[:min(3, len(phys_by_centrality))]

    logical_degree_ranked = sorted(interacting_logical, key=lambda q: logical_degree[q], reverse=True)
    logical_degree_rank = {q: i for i, q in enumerate(logical_degree_ranked)}
    max_logical_rank = max(len(logical_degree_ranked) - 1, 1)
    phys_degree_ranked = sorted(physical_qubits, key=lambda pq: phys_degree[pq], reverse=True)
    phys_degree_rank = {pq: i for i, pq in enumerate(phys_degree_ranked)}
    max_phys_rank = max(len(phys_degree_ranked) - 1, 1)

    static_nbrs, static_deg = build_neighbors(static_weight)
    max_iw = max(static_weight.values()) if static_weight else 1.0

    # ---------------------------------------------------------------
    # Step 9: Routing-Pressure-Aware Conflict-Graph MIS Seed
    # ---------------------------------------------------------------
    def conflict_graph_seed(start_pq, nbrs, deg, weights, routing_pressure=None):
        if len(interacting_logical) < 2:
            return None, None

        cur_max_iw = max(weights.values()) if weights else 1.0

        top_partners = {}
        for lq in interacting_logical:
            nbr_list = sorted(nbrs.get(lq, {}).items(), key=lambda x: x[1], reverse=True)
            top_partners[lq] = set(p for p, _ in nbr_list[:3])

        conflict_adj = defaultdict(set)
        il = interacting_logical

        qubit_pressure = defaultdict(float)
        if routing_pressure:
            for (q1, q2), cnt in routing_pressure.items():
                qubit_pressure[q1] += cnt
                qubit_pressure[q2] += cnt

        for i in range(len(il)):
            for j in range(i + 1, len(il)):
                l1, l2 = il[i], il[j]
                s1 = top_partners.get(l1, set())
                s2 = top_partners.get(l2, set())
                if not s1 and not s2:
                    continue
                intersection = len(s1 & s2)
                union = len(s1 | s2)
                if union > 0:
                    jaccard = intersection / union
                    threshold = 0.5
                    if routing_pressure and qubit_pressure[l1] > 0 and qubit_pressure[l2] > 0:
                        max_pressure = max(qubit_pressure.values()) if qubit_pressure else 1.0
                        pressure_factor = min(1.0, (qubit_pressure[l1] + qubit_pressure[l2]) /
                                              (max_pressure * 2 + 1e-10))
                        threshold = max(0.25, 0.5 - 0.25 * pressure_factor)
                    if jaccard > threshold:
                        conflict_adj[l1].add(l2)
                        conflict_adj[l2].add(l1)

        sorted_by_deg_local = sorted(interacting_logical,
                                     key=lambda q: (deg.get(q, 0), qubit_pressure.get(q, 0)),
                                     reverse=True)
        mis = set()
        excluded = set()
        for lq in sorted_by_deg_local:
            if lq not in excluded:
                mis.add(lq)
                for neighbor in conflict_adj.get(lq, set()):
                    excluded.add(neighbor)

        non_mis = [lq for lq in sorted_by_deg_local if lq not in mis]
        mis_ordered = sorted(mis, key=lambda q: (deg.get(q, 0), qubit_pressure.get(q, 0)),
                             reverse=True)

        m = [-1] * num_q
        rm = [-1] * num_q
        used_phys = set()

        if mis_ordered:
            first_lq = mis_ordered[0]
            m[first_lq] = start_pq
            rm[start_pq] = first_lq
            used_phys.add(start_pq)

            for lq in mis_ordered[1:]:
                nbrs_placed = {}
                for plq in mis:
                    if m[plq] >= 0 and plq in nbrs.get(lq, {}):
                        nbrs_placed[plq] = nbrs[lq][plq]

                if nbrs_placed:
                    best_pq = None
                    best_score = float('inf')
                    for pq in physical_qubits:
                        if pq in used_phys:
                            continue
                        score = 0.0
                        for plq, iw in nbrs_placed.items():
                            d = dist[pq][m[plq]]
                            cost = iw * d
                            if m[plq] in hw_adj[pq]:
                                cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                            score += cost
                        if score < best_score:
                            best_score = score
                            best_pq = pq
                else:
                    best_pq = None
                    best_score = float('inf')
                    for pq in physical_qubits:
                        if pq not in used_phys:
                            if phys_centrality[pq] < best_score:
                                best_score = phys_centrality[pq]
                                best_pq = pq

                if best_pq is not None:
                    m[lq] = best_pq
                    rm[best_pq] = lq
                    used_phys.add(best_pq)

        placed_set = set(lq for lq in interacting_logical if m[lq] >= 0)

        for lq in non_mis:
            nbrs_placed = {}
            for plq in placed_set:
                w = nbrs.get(lq, {}).get(plq, 0.0)
                if w > 0:
                    nbrs_placed[plq] = w

            if nbrs_placed:
                near_ties = []
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq in used_phys:
                        continue
                    score = 0.0
                    for plq, iw in nbrs_placed.items():
                        d = dist[pq][m[plq]]
                        cost = iw * d
                        if m[plq] in hw_adj[pq]:
                            cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                        score += cost
                    near_ties.append((score, pq))
                    if score < best_score:
                        best_score = score

                if near_ties and best_score > 0:
                    threshold = best_score * 1.05
                    candidates_list = [(s, pq) for s, pq in near_ties if s <= threshold]
                    if len(candidates_list) > 1 and lq in logical_degree_rank:
                        lq_rn = logical_degree_rank[lq] / max_logical_rank
                        best_pq = min(candidates_list, key=lambda x: (
                            abs(phys_degree_rank[x[1]] / max_phys_rank - lq_rn), x[0]))[1]
                    else:
                        best_pq = min(candidates_list, key=lambda x: x[0])[1]
                elif near_ties:
                    best_pq = min(near_ties, key=lambda x: x[0])[1]
                else:
                    best_pq = None
            else:
                best_pq = None
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq not in used_phys:
                        if phys_centrality[pq] < best_score:
                            best_score = phys_centrality[pq]
                            best_pq = pq

            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                used_phys.add(best_pq)
                placed_set.add(lq)

        remaining_lqs = [lq for lq in logical_qubits if m[lq] == -1]
        for lq in remaining_lqs:
            best_pq = None
            best_score = float('inf')
            for pq in physical_qubits:
                if pq not in used_phys:
                    if phys_centrality[pq] < best_score:
                        best_score = phys_centrality[pq]
                        best_pq = pq
            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                used_phys.add(best_pq)

        return m, rm

    # ---------------------------------------------------------------
    # Step 10: Spectral ordering seed
    # ---------------------------------------------------------------
    def spectral_seed():
        if len(interacting_logical) < 3:
            return None, None

        idx_map = {q: i for i, q in enumerate(interacting_logical)}
        n = len(interacting_logical)

        L = [[0.0] * n for _ in range(n)]
        for (q1, q2), w in static_weight.items():
            if q1 in idx_map and q2 in idx_map:
                i, j = idx_map[q1], idx_map[q2]
                L[i][j] -= w
                L[j][i] -= w
                L[i][i] += w
                L[j][j] += w

        def power_iter(mat, n_iter=200):
            v = [random.gauss(0, 1) for _ in range(n)]
            for _ in range(n_iter):
                new_v = [0.0] * n
                for i in range(n):
                    for j in range(n):
                        new_v[i] += mat[i][j] * v[j]
                norm = math.sqrt(sum(x * x for x in new_v)) or 1e-12
                v = [x / norm for x in new_v]
            return v

        max_diag = max(L[i][i] for i in range(n)) + 1.0
        shifted = [[0.0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                shifted[i][j] = -L[i][j]
            shifted[i][i] += max_diag

        v1 = power_iter(shifted, 150)

        dot_v1 = sum(x * x for x in v1) or 1e-12
        lam1_shifted = sum(v1[i] * sum(shifted[i][j] * v1[j] for j in range(n)) for i in range(n)) / dot_v1
        shifted2 = [row[:] for row in shifted]
        for i in range(n):
            for j in range(n):
                shifted2[i][j] -= lam1_shifted * v1[i] * v1[j] / dot_v1

        fiedler = power_iter(shifted2, 200)

        fiedler_order = sorted(range(n), key=lambda i: fiedler[i])
        sorted_logical = [interacting_logical[i] for i in fiedler_order]

        phys_sorted = sorted(physical_qubits, key=lambda pq: phys_centrality[pq])
        start_pq = phys_sorted[0]
        visited_bfs = set()
        bfs_order = []
        bfs_q = deque([start_pq])
        visited_bfs.add(start_pq)
        while bfs_q:
            pq = bfs_q.popleft()
            bfs_order.append(pq)
            for nb in sorted(hw_adj[pq]):
                if nb not in visited_bfs:
                    visited_bfs.add(nb)
                    bfs_q.append(nb)
        for pq in physical_qubits:
            if pq not in visited_bfs:
                bfs_order.append(pq)
                visited_bfs.add(pq)

        m = [-1] * num_q
        rm = [-1] * num_q
        n_interact = len(sorted_logical)
        n_phys = len(bfs_order)
        offset = max(0, (n_phys - n_interact) // 2)
        for i, lq in enumerate(sorted_logical):
            pq = bfs_order[min(offset + i, n_phys - 1)]
            if rm[pq] != -1:
                best_pq = None
                best_d = float('inf')
                for cpq in physical_qubits:
                    if rm[cpq] == -1:
                        d = dist[pq][cpq]
                        if d < best_d:
                            best_d = d
                            best_pq = cpq
                pq = best_pq
            m[lq] = pq
            rm[pq] = lq

        return m, rm

    # ---------------------------------------------------------------
    # Step 11: Greedy placement
    # ---------------------------------------------------------------
    def run_greedy_placement(start_lq, start_pq, nbrs, deg, weights=None):
        cur_max_iw = max(weights.values()) if weights else max_iw
        used_phys = {start_pq}
        m = [-1] * num_q
        rm = [-1] * num_q
        m[start_lq] = start_pq
        rm[start_pq] = start_lq
        placed = {start_lq}
        remaining = set(logical_qubits) - placed

        while remaining:
            best_lq, best_w = None, -1.0
            for lq in remaining:
                w = sum(nbrs.get(lq, {}).get(plq, 0.0) for plq in placed)
                if w > best_w:
                    best_w = w
                    best_lq = lq

            nbrs_placed = {plq: nbrs.get(best_lq, {}).get(plq, 0.0)
                           for plq in placed if plq in nbrs.get(best_lq, {})}

            if nbrs_placed:
                near_ties = []
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq in used_phys:
                        continue
                    score = 0.0
                    for plq, iw in nbrs_placed.items():
                        d = dist[pq][m[plq]]
                        cost = iw * d
                        if m[plq] in hw_adj[pq]:
                            cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                        score += cost
                    near_ties.append((score, pq))
                    if score < best_score:
                        best_score = score

                if near_ties and best_score > 0:
                    threshold = best_score * 1.05
                    candidates_list = [(s, pq) for s, pq in near_ties if s <= threshold]
                    if len(candidates_list) > 1 and best_lq in logical_degree_rank:
                        lq_rn = logical_degree_rank[best_lq] / max_logical_rank
                        best_pq = min(candidates_list, key=lambda x: (
                            abs(phys_degree_rank[x[1]] / max_phys_rank - lq_rn), x[0]))[1]
                    else:
                        best_pq = min(candidates_list, key=lambda x: x[0])[1]
                elif near_ties:
                    best_pq = min(near_ties, key=lambda x: x[0])[1]
                else:
                    best_pq = None
            else:
                best_pq = None
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq not in used_phys:
                        score = phys_centrality[pq]
                        if score < best_score:
                            best_score = score
                            best_pq = pq

            m[best_lq] = best_pq
            rm[best_pq] = best_lq
            used_phys.add(best_pq)
            placed.add(best_lq)
            remaining.discard(best_lq)
        return m, rm

    def fill_unmapped(m, rm):
        unmapped = [q for q in range(num_q) if m[q] == -1]
        free = [pq for pq in range(num_q) if rm[pq] == -1]
        for lq, pq in zip(unmapped, free):
            m[lq] = pq
            rm[pq] = lq

    # ---------------------------------------------------------------
    # Step 12: Local search with nonlinear distance penalty
    # ---------------------------------------------------------------
    def local_search(m, rm, nbrs, weights, alpha_exp, max_rounds=5):
        if len(interacting_logical) <= 1:
            return compute_cost_nonlinear(m, weights, alpha_exp)
        for _ in range(max_rounds):
            improved = False
            best_d, best_pair = 0.0, None
            active_phys = [m[q] for q in interacting_logical]
            for pq1 in active_phys:
                for pq2 in hw_adj.get(pq1, set()):
                    d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                    if d < best_d:
                        best_d = d
                        best_pair = (pq1, pq2)
            n_random = min(150, len(interacting_logical) * 3)
            for _ in range(n_random):
                i, j = random.sample(range(len(interacting_logical)), 2)
                pq1, pq2 = m[interacting_logical[i]], m[interacting_logical[j]]
                d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                if d < best_d:
                    best_d = d
                    best_pair = (pq1, pq2)
            if best_pair and best_d < -1e-12:
                do_swap(m, rm, *best_pair)
                improved = True
            if not improved:
                for i in range(len(interacting_logical)):
                    for j in range(i + 1, len(interacting_logical)):
                        pq1, pq2 = m[interacting_logical[i]], m[interacting_logical[j]]
                        d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                        if d < best_d:
                            best_d = d
                            best_pair = (pq1, pq2)
                if best_pair and best_d < -1e-12:
                    do_swap(m, rm, *best_pair)
                else:
                    break
        return compute_cost_nonlinear(m, weights, alpha_exp)

    # ---------------------------------------------------------------
    # Step 13: Perturbation modes with bandit selection
    #   LNS now uses accumulated routing pressure to bias destruction
    # ---------------------------------------------------------------
    rsdiwr_iter_ref = [0]
    # Shared accumulated routing pressure for pressure-guided LNS
    accumulated_routing_pressure_ref = [defaultdict(float)]

    def perturb_random(m, rm, **kw):
        if len(interacting_logical) >= 2:
            lqs = random.sample(interacting_logical, 2)
            do_swap(m, rm, m[lqs[0]], m[lqs[1]])

    def perturb_segment_shuffle(m, rm, **kw):
        k = min(random.randint(3, 5), len(interacting_logical))
        if k < 2:
            perturb_random(m, rm)
            return
        lqs = random.sample(interacting_logical, k)
        phys_positions = [m[lq] for lq in lqs]
        random.shuffle(phys_positions)
        for lq in lqs:
            rm[m[lq]] = -1
        for lq, pq in zip(lqs, phys_positions):
            m[lq] = pq
            rm[pq] = lq

    def perturb_worst_pair(m, rm, weights=None, alpha_exp=1.5, **kw):
        if weights is None:
            perturb_random(m, rm)
            return
        pair_costs = []
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                d = dist[m[q1]][m[q2]]
                c = w * (d ** alpha_exp)
                pair_costs.append((c, q1, q2))
        if not pair_costs:
            return
        pair_costs.sort(reverse=True)
        top_n = min(3, len(pair_costs))
        _, tq1, tq2 = pair_costs[random.randint(0, top_n - 1)]
        pq1, pq2 = m[tq1], m[tq2]
        adj_of_pq2 = list(hw_adj.get(pq2, set()))
        if adj_of_pq2:
            target = random.choice(adj_of_pq2)
            if target != pq1:
                do_swap(m, rm, pq1, target)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    def perturb_edge_targeted(m, rm, weights=None, alpha_exp=1.5, **kw):
        if weights is None:
            perturb_random(m, rm)
            return
        edge_costs = []
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                c = w * (dist[m[q1]][m[q2]] ** alpha_exp)
                edge_costs.append((c, q1, q2))
        if not edge_costs:
            return
        edge_costs.sort(reverse=True)
        top_n = min(5, len(edge_costs))
        _, eq1, eq2 = edge_costs[random.randint(0, top_n - 1)]
        pq1, pq2 = m[eq1], m[eq2]
        neighbors_of_pq2 = list(hw_adj.get(pq2, set()))
        if neighbors_of_pq2:
            target = random.choice(neighbors_of_pq2)
            if target != pq1:
                do_swap(m, rm, pq1, target)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    def perturb_lns(m, rm, nbrs=None, alpha_exp=1.5, **kw):
        """Pressure-guided LNS: blends current cost with accumulated
        routing pressure to select which qubits to destroy."""
        if nbrs is None or len(interacting_logical) < 3:
            perturb_random(m, rm)
            return
        base_lo = 3 + rsdiwr_iter_ref[0]
        base_hi = 8 + rsdiwr_iter_ref[0] * 2
        k = min(random.randint(base_lo, base_hi), len(interacting_logical))

        acc_pressure = accumulated_routing_pressure_ref[0]
        # Per-qubit accumulated pressure
        qubit_acc_pressure = defaultdict(float)
        for (q1, q2), cnt in acc_pressure.items():
            qubit_acc_pressure[q1] += cnt
            qubit_acc_pressure[q2] += cnt
        max_acc = max(qubit_acc_pressure.values()) if qubit_acc_pressure else 1.0

        qcost = {}
        for lq in interacting_logical:
            c = 0.0
            for partner, w in nbrs.get(lq, {}).items():
                if m[partner] >= 0 and m[lq] >= 0:
                    c += w * (dist[m[lq]][m[partner]] ** alpha_exp)
            # Blend current cost with accumulated routing pressure
            pressure_bonus = qubit_acc_pressure.get(lq, 0.0) / (max_acc + 1e-10)
            qcost[lq] = c * (1.0 + 0.5 * pressure_bonus)

        sorted_qs = sorted(qcost, key=lambda q: qcost[q], reverse=True)
        top_half = sorted_qs[:max(k, len(sorted_qs) // 2)]
        subset = random.sample(top_half, min(k, len(top_half)))

        freed_phys = []
        for lq in subset:
            freed_phys.append(m[lq])
            rm[m[lq]] = -1
            m[lq] = -1

        placed_set = set(lq for lq in interacting_logical if m[lq] >= 0)
        for lq in sorted(subset, key=lambda q: qcost[q], reverse=True):
            best_pq, best_sc = None, float('inf')
            for pq in freed_phys:
                if rm[pq] != -1:
                    continue
                sc = 0.0
                for partner, w in nbrs.get(lq, {}).items():
                    if partner in placed_set and m[partner] >= 0:
                        sc += w * (dist[pq][m[partner]] ** alpha_exp)
                if sc < best_sc:
                    best_sc = sc
                    best_pq = pq
            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                placed_set.add(lq)
            else:
                for pq in freed_phys:
                    if rm[pq] == -1:
                        m[lq] = pq
                        rm[pq] = lq
                        placed_set.add(lq)
                        break

    perturbation_modes = [perturb_random, perturb_segment_shuffle,
                          perturb_worst_pair, perturb_edge_targeted, perturb_lns]
    K = len(perturbation_modes)

    WINDOW_SIZE = 100
    EPSILON = 0.1
    window = []
    mode_successes = [0] * K
    mode_attempts = [0] * K

    def select_perturbation_mode():
        if random.random() < EPSILON or sum(mode_attempts) < K * 2:
            return random.randint(0, K - 1)
        rates = []
        for k in range(K):
            if mode_attempts[k] > 0:
                rates.append(mode_successes[k] / mode_attempts[k])
            else:
                rates.append(1.0)
        total = sum(rates)
        if total < 1e-12:
            return random.randint(0, K - 1)
        r = random.random() * total
        cumul = 0.0
        for k in range(K):
            cumul += rates[k]
            if r <= cumul:
                return k
        return K - 1

    def update_window(mode_idx, success):
        window.append((mode_idx, success))
        mode_attempts[mode_idx] += 1
        if success:
            mode_successes[mode_idx] += 1
        if len(window) > WINDOW_SIZE:
            old_mode, old_success = window.pop(0)
            mode_attempts[old_mode] -= 1
            if old_success:
                mode_successes[old_mode] -= 1

    # ---------------------------------------------------------------
    # Step 14: Build initial mapping candidates
    # ---------------------------------------------------------------
    candidates = []

    for s_lq in seed_lqs:
        for s_pq in seed_pqs:
            m, rm = run_greedy_placement(s_lq, s_pq, static_nbrs, static_deg,
                                         weights=static_weight)
            fill_unmapped(m, rm)
            cost = compute_cost(m, static_weight)
            candidates.append((cost, m, rm))

    for s_pq in seed_pqs:
        cg_m, cg_rm = conflict_graph_seed(s_pq, static_nbrs, static_deg, static_weight)
        if cg_m is not None:
            fill_unmapped(cg_m, cg_rm)
            cost = compute_cost(cg_m, static_weight)
            candidates.append((cost, cg_m, cg_rm))

    spec_m, spec_rm = spectral_seed()
    if spec_m is not None:
        fill_unmapped(spec_m, spec_rm)
        spec_cost = compute_cost(spec_m, static_weight)
        candidates.append((spec_cost, spec_m, spec_rm))

    m_rand = [-1] * num_q
    rm_rand = [-1] * num_q
    shuffled_phys = list(physical_qubits)
    random.shuffle(shuffled_phys)
    for i, lq in enumerate(logical_qubits):
        m_rand[lq] = shuffled_phys[i]
        rm_rand[shuffled_phys[i]] = lq
    fill_unmapped(m_rand, rm_rand)
    c = compute_cost(m_rand, static_weight)
    candidates.append((c, m_rand, rm_rand))

    if not candidates:
        self.mapping_dict = list(range(num_q))
        self.reverse_mapping_dict = list(range(num_q))
        if self.use_isl:
            self.isl_mapping = dict_to_isl_map(self.mapping_dict)
        return

    candidates.sort(key=lambda x: x[0])

    _, best_m, best_rm = candidates[0]
    best_m, best_rm = list(best_m), list(best_rm)
    local_search(best_m, best_rm, static_nbrs, static_weight, alpha_exp=2.0, max_rounds=6)
    best_cost = compute_cost(best_m, static_weight)

    for idx in range(1, min(5, len(candidates))):
        _, m_c, rm_c = candidates[idx]
        m_c, rm_c = list(m_c), list(rm_c)
        local_search(m_c, rm_c, static_nbrs, static_weight, alpha_exp=2.0, max_rounds=4)
        c = compute_cost(m_c, static_weight)
        if c < best_cost:
            best_cost = c
            best_m = list(m_c)
            best_rm = list(rm_c)

    # ---------------------------------------------------------------
    # Step 15: RSDIWR + ILS with A*-guided first iteration,
    #   bidirectional routing feedback, routing-pressure MIS reseeding,
    #   and pressure-guided LNS
    # ---------------------------------------------------------------
    time_budget = 25.0
    t_start = _time()
    n_rsdiwr = 4

    cur_m = list(best_m)
    cur_rm = list(best_rm)
    swap_counts = defaultdict(float)
    accumulated_routing_pressure = defaultdict(float)
    accumulated_routing_pressure_ref[0] = accumulated_routing_pressure

    for rsdiwr_iter in range(n_rsdiwr):
        rsdiwr_iter_ref[0] = rsdiwr_iter
        elapsed = _time() - t_start
        if elapsed > time_budget:
            break

        remaining_time = time_budget - elapsed
        remaining_iters = n_rsdiwr - rsdiwr_iter
        time_for_this_iter = remaining_time / max(remaining_iters, 1)
        n_ils = max(55, int(num_q * time_for_this_iter / 0.5)) if time_for_this_iter > 1.0 else max(30, num_q // 3)

        # Blend static weights with routing feedback
        if rsdiwr_iter == 0 or not swap_counts:
            eff_weights = dict(static_weight)
        else:
            max_sw = max(swap_counts.values()) if swap_counts else 1.0
            scale = max(static_weight.values()) / max(max_sw, 1e-10)
            alpha_blend = max(0.3, 1.0 - 0.3 * rsdiwr_iter)
            eff_weights = defaultdict(float)
            all_keys = set(static_weight.keys()) | set(swap_counts.keys())
            for key in all_keys:
                w_s = static_weight.get(key, 0.0)
                w_r = swap_counts.get(key, 0.0) * scale
                eff_weights[key] = alpha_blend * w_s + (1.0 - alpha_blend) * w_r

        eff_nbrs, eff_deg = build_neighbors(eff_weights)

        # Re-seed with routing-informed weights + routing-pressure MIS
        if rsdiwr_iter > 0 and swap_counts and (_time() - t_start) < time_budget * 0.7:
            eff_sorted = sorted(interacting_logical,
                                key=lambda q: eff_deg.get(q, 0), reverse=True)
            reseed_lqs = eff_sorted[:min(2, len(eff_sorted))]
            reseed_pqs = seed_pqs[:min(2, len(seed_pqs))]

            for s_lq in reseed_lqs:
                for s_pq in reseed_pqs:
                    rm_new, rmm_new = run_greedy_placement(
                        s_lq, s_pq, eff_nbrs, eff_deg, weights=eff_weights)
                    fill_unmapped(rm_new, rmm_new)
                    local_search(rm_new, rmm_new, eff_nbrs, eff_weights,
                                 alpha_exp=2.0, max_rounds=3)
                    sc = compute_cost(rm_new, static_weight)
                    if sc < best_cost:
                        best_cost = sc
                        best_m = list(rm_new)
                        best_rm = list(rmm_new)
                        cur_m = list(rm_new)
                        cur_rm = list(rmm_new)

            # Routing-pressure-aware MIS reseeding
            for s_pq in reseed_pqs:
                cg_m, cg_rm = conflict_graph_seed(
                    s_pq, eff_nbrs, eff_deg, eff_weights,
                    routing_pressure=accumulated_routing_pressure)
                if cg_m is not None:
                    fill_unmapped(cg_m, cg_rm)
                    local_search(cg_m, cg_rm, eff_nbrs, eff_weights,
                                 alpha_exp=2.0, max_rounds=3)
                    sc = compute_cost(cg_m, static_weight)
                    if sc < best_cost:
                        best_cost = sc
                        best_m = list(cg_m)
                        best_rm = list(cg_rm)
                        cur_m = list(cg_m)
                        cur_rm = list(cg_rm)

        alpha_start = 2.0
        alpha_end = 1.0

        ls_rounds = 6 if rsdiwr_iter == 0 else 4
        cur_cost_nl = local_search(cur_m, cur_rm, eff_nbrs, eff_weights,
                                   alpha_exp=alpha_start, max_rounds=ls_rounds)

        static_cost = compute_cost(cur_m, static_weight)
        if static_cost < best_cost:
            best_cost = static_cost
            best_m = list(cur_m)
            best_rm = list(cur_rm)

        # Reset bandit window
        window.clear()
        for k in range(K):
            mode_successes[k] = 0
            mode_attempts[k] = 0

        T = max(cur_cost_nl * 0.05, 1.0)
        T_init = T
        alpha_sa = 0.94
        reheat_interval = max(n_ils // 4, 8)

        for ils_iter in range(n_ils):
            if _time() - t_start > time_budget:
                break

            progress = ils_iter / max(n_ils - 1, 1)
            alpha_exp = alpha_start + (alpha_end - alpha_start) * progress

            saved_m = list(cur_m)
            saved_rm = list(cur_rm)
            saved_cost = cur_cost_nl

            mode = select_perturbation_mode()
            perturbation_modes[mode](cur_m, cur_rm,
                                    nbrs=eff_nbrs, weights=eff_weights,
                                    alpha_exp=alpha_exp)

            new_cost_nl = local_search(cur_m, cur_rm, eff_nbrs, eff_weights,
                                       alpha_exp=alpha_exp, max_rounds=3)

            success = new_cost_nl < saved_cost - 1e-12

            improvement = saved_cost - new_cost_nl
            if improvement > 0:
                cur_cost_nl = new_cost_nl
                sc = compute_cost(cur_m, static_weight)
                if sc < best_cost:
                    best_cost = sc
                    best_m = list(cur_m)
                    best_rm = list(cur_rm)
            elif random.random() < math.exp(min(0, improvement / max(T, 1e-10))):
                cur_cost_nl = new_cost_nl
            else:
                cur_m[:] = saved_m
                cur_rm[:] = saved_rm
                cur_cost_nl = saved_cost

            update_window(mode, success)

            T *= alpha_sa
            if (ils_iter + 1) % reheat_interval == 0:
                T = max(T, T_init * 0.35)

        # Routing simulation for RSDIWR feedback
        if rsdiwr_iter < n_rsdiwr - 1:
            sim_depth = 14 + rsdiwr_iter * 7

            if rsdiwr_iter == 0 and early_layer_gates:
                # A*-guided hybrid for first iteration
                swap_counts, _ = simulate_routing_hybrid(best_m, best_rm, max_layers=sim_depth)
            else:
                # Bidirectional routing for subsequent iterations:
                # averages forward and backward for more robust feedback
                swap_counts, _ = simulate_routing_bidirectional(best_m, best_rm, max_layers=sim_depth)

            # Accumulate routing pressure
            for pair_key, cnt in swap_counts.items():
                accumulated_routing_pressure[pair_key] += cnt

        cur_m = list(best_m)
        cur_rm = list(best_rm)
        cur_cost_nl = compute_cost_nonlinear(cur_m, eff_weights, alpha_end)

    # ---------------------------------------------------------------
    # Step 16: Set final mapping
    # ---------------------------------------------------------------
    self.mapping_dict = best_m
    self.reverse_mapping_dict = best_rm

    if self.use_isl:
        self.isl_mapping = dict_to_isl_map(self.mapping_dict)

def init_mapping(self):
    import math
    import random
    import heapq
    from collections import defaultdict, deque
    from time import time as _time

    num_q = self.num_qubits
    physical_qubits = sorted(self.backend.keys())
    dist = self.distance_matrix

    # ---------------------------------------------------------------
    # Step 1: Build DAG and topological layers
    # ---------------------------------------------------------------
    all_gates = sorted(self.access.keys())
    two_qubit_gates = [g for g in all_gates if len(self.access[g]) == 2]

    last_gate_on_qubit = {}
    successors_dag = defaultdict(set)
    predecessors_dag = defaultdict(set)
    for g in all_gates:
        for q in self.access[g]:
            if q in last_gate_on_qubit:
                pred = last_gate_on_qubit[q]
                successors_dag[pred].add(g)
                predecessors_dag[g].add(pred)
            last_gate_on_qubit[q] = g

    in_degree = {g: len(predecessors_dag[g]) for g in all_gates}
    gate_layer = {g: 0 for g in all_gates}
    temp_in = dict(in_degree)
    queue = deque(g for g in all_gates if in_degree[g] == 0)
    topo_order = []
    while queue:
        g = queue.popleft()
        topo_order.append(g)
        for s in successors_dag[g]:
            gate_layer[s] = max(gate_layer[s], gate_layer[g] + 1)
            temp_in[s] -= 1
            if temp_in[s] == 0:
                queue.append(s)

    critical_path = {g: 0 for g in all_gates}
    for g in reversed(topo_order):
        for s in successors_dag[g]:
            if critical_path[s] + 1 > critical_path[g]:
                critical_path[g] = critical_path[s] + 1

    # 2q DAG for routing simulation
    gates_2q = {}
    dag2q_succ = defaultdict(set)
    dag2q_pred = defaultdict(set)
    last_2q_on_qubit = {}
    logical_qubits_set = set()

    for gate in all_gates:
        qubits = self.access[gate]
        if len(qubits) == 2:
            q1, q2 = qubits
            gates_2q[gate] = (q1, q2)
            logical_qubits_set.add(q1)
            logical_qubits_set.add(q2)
            for q in [q1, q2]:
                if q in last_2q_on_qubit:
                    prev = last_2q_on_qubit[q]
                    if prev != gate:
                        dag2q_succ[prev].add(gate)
                        dag2q_pred[gate].add(prev)
                last_2q_on_qubit[q] = gate
        elif len(qubits) == 1:
            logical_qubits_set.add(qubits[0])

    logical_qubits = sorted(logical_qubits_set)

    if not gates_2q:
        self.mapping_dict = list(range(num_q))
        self.reverse_mapping_dict = list(range(num_q))
        if self.use_isl:
            self.isl_mapping = dict_to_isl_map(self.mapping_dict)
        return

    # Topological order for 2q DAG
    topo_2q = []
    in_deg_2q = {g: len(dag2q_pred[g]) for g in gates_2q}
    q2 = deque(sorted(g for g in gates_2q if in_deg_2q[g] == 0))
    while q2:
        g = q2.popleft()
        topo_2q.append(g)
        for s in dag2q_succ[g]:
            in_deg_2q[s] -= 1
            if in_deg_2q[s] == 0:
                q2.append(s)

    dep_count = defaultdict(int)
    for g in reversed(topo_2q):
        for s in dag2q_succ[g]:
            dep_count[g] = max(dep_count[g], dep_count[s] + 1)

    # Backward dep count for backward routing
    bwd_dep = defaultdict(int)
    for g in topo_2q:
        for p in dag2q_pred[g]:
            if p in gates_2q:
                bwd_dep[g] = max(bwd_dep[g], bwd_dep[p] + 1)

    # ---------------------------------------------------------------
    # Step 2: Interaction weights — critical-path weighting
    # ---------------------------------------------------------------
    max_layer = max((gate_layer[g] for g in two_qubit_gates), default=1)

    static_weight = defaultdict(float)
    logical_degree = defaultdict(float)

    for g in two_qubit_gates:
        q1, q2 = self.access[g]
        cp = critical_path[g] + 1
        layer = gate_layer[g]
        w = cp * (max_layer - layer + 1)
        key = (min(q1, q2), max(q1, q2))
        static_weight[key] += w
        logical_degree[q1] += w
        logical_degree[q2] += w

    interacting_logical = [q for q in logical_qubits if logical_degree.get(q, 0) > 0]

    # ---------------------------------------------------------------
    # Step 3: Physical graph properties
    # ---------------------------------------------------------------
    hw_adj = defaultdict(set)
    for pq in physical_qubits:
        for pq2 in self.backend.get(pq, []):
            hw_adj[pq].add(pq2)

    phys_degree = {pq: len(hw_adj[pq]) for pq in physical_qubits}
    phys_centrality = {}
    for pq in physical_qubits:
        phys_centrality[pq] = sum(dist[pq][pq2] for pq2 in physical_qubits)

    # ---------------------------------------------------------------
    # Step 4: Helper functions
    # ---------------------------------------------------------------
    def build_neighbors(weights):
        nbrs = defaultdict(dict)
        deg = defaultdict(float)
        for (q1, q2), w in weights.items():
            nbrs[q1][q2] = w
            nbrs[q2][q1] = w
            deg[q1] += w
            deg[q2] += w
        return nbrs, deg

    def compute_cost_nonlinear(m, weights, alpha_exp):
        cost = 0.0
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                d = dist[m[q1]][m[q2]]
                cost += w * (d ** alpha_exp)
        return cost

    def compute_cost(m, weights):
        cost = 0.0
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                cost += w * dist[m[q1]][m[q2]]
        return cost

    def delta_swap_cost_nonlinear(m, rm, pq_a, pq_b, nbrs, alpha_exp):
        lq_a, lq_b = rm[pq_a], rm[pq_b]
        delta = 0.0
        affected = set()
        if lq_a in nbrs:
            affected.update(nbrs[lq_a].keys())
        if lq_b in nbrs:
            affected.update(nbrs[lq_b].keys())
        for q in affected:
            if q == lq_a or q == lq_b:
                continue
            pq_q = m[q]
            w_a = nbrs.get(lq_a, {}).get(q, 0.0)
            if w_a > 0:
                old_d = dist[pq_a][pq_q] ** alpha_exp
                new_d = dist[pq_b][pq_q] ** alpha_exp
                delta += w_a * (new_d - old_d)
            w_b = nbrs.get(lq_b, {}).get(q, 0.0)
            if w_b > 0:
                old_d = dist[pq_b][pq_q] ** alpha_exp
                new_d = dist[pq_a][pq_q] ** alpha_exp
                delta += w_b * (new_d - old_d)
        return delta

    def do_swap(m, rm, pq_a, pq_b):
        lq_a, lq_b = rm[pq_a], rm[pq_b]
        m[lq_a], m[lq_b] = pq_b, pq_a
        rm[pq_a], rm[pq_b] = lq_b, lq_a

    # ---------------------------------------------------------------
    # Step 5: A* early-layer routing with adaptive node limit
    # ---------------------------------------------------------------
    ASTAR_LAYERS = 5
    n_2q = len(gates_2q)
    if n_2q < 50:
        ASTAR_NODE_LIMIT = 8000
    elif n_2q < 200:
        ASTAR_NODE_LIMIT = 5000
    else:
        ASTAR_NODE_LIMIT = 3000

    pred_rem_layer = {g: len(dag2q_pred[g]) for g in gates_2q}
    front_layer_calc = set(g for g in gates_2q if pred_rem_layer[g] == 0)
    current_layer = 0
    early_layer_gates = set()

    temp_front = set(front_layer_calc)
    while temp_front:
        for g in temp_front:
            if current_layer < ASTAR_LAYERS:
                early_layer_gates.add(g)
        next_front = set()
        for g in temp_front:
            for s in dag2q_succ[g]:
                pred_rem_layer[s] -= 1
                if pred_rem_layer[s] == 0:
                    next_front.add(s)
        current_layer += 1
        temp_front = next_front

    # ---------------------------------------------------------------
    # Step 6: A*-guided routing for early layers
    # ---------------------------------------------------------------
    def astar_routing_early(m, rm):
        if not early_layer_gates:
            return defaultdict(float), 0

        early_pred = {}
        for g in early_layer_gates:
            early_pred[g] = len(dag2q_pred[g] & early_layer_gates)

        initial_front = frozenset(g for g in early_layer_gates if early_pred[g] == 0)

        init_executed = set()
        cur_front = set(initial_front)
        changed = True
        while changed:
            changed = False
            newly_exec = set()
            for g in cur_front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = m[gq1], m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    newly_exec.add(g)
            if newly_exec:
                changed = True
                init_executed |= newly_exec
                cur_front -= newly_exec
                for g in newly_exec:
                    for s in dag2q_succ[g]:
                        if s in early_layer_gates and s not in init_executed:
                            all_pred_done = True
                            for p in dag2q_pred[s]:
                                if p in early_layer_gates and p not in init_executed:
                                    all_pred_done = False
                                    break
                            if all_pred_done:
                                cur_front.add(s)

        remaining_early = early_layer_gates - init_executed
        if not remaining_early:
            return defaultdict(float), 0

        def compute_front(executed):
            front = set()
            for g in early_layer_gates:
                if g in executed:
                    continue
                all_pred = True
                for p in dag2q_pred[g]:
                    if p in early_layer_gates and p not in executed:
                        all_pred = False
                        break
                if all_pred:
                    front.add(g)
            return frozenset(front)

        init_exec_frozen = frozenset(init_executed)
        init_front_astar = compute_front(init_executed)

        active_logical = set()
        for g in remaining_early:
            gq1, gq2 = gates_2q[g]
            active_logical.add(gq1)
            active_logical.add(gq2)

        def h_func(mapping, front_gates):
            h = 0
            for g in front_gates:
                gq1, gq2 = gates_2q[g]
                h += dist[mapping[gq1]][mapping[gq2]]
            return h

        active_logical_list = sorted(active_logical)

        def mapping_key(mapping):
            return tuple(mapping[lq] for lq in active_logical_list)

        init_m = list(m)
        init_h = h_func(init_m, init_front_astar)

        counter = [0]
        start_state = (init_h, 0, 0, init_m, init_exec_frozen, init_front_astar)
        open_heap = [start_state]
        visited = {}
        best_known_total = float('inf')
        best_result = None

        swap_history = {}
        init_key = (mapping_key(init_m), init_exec_frozen)
        swap_history[init_key] = defaultdict(float)

        expansions = 0

        while open_heap and expansions < ASTAR_NODE_LIMIT:
            f, _, g_cost, cur_m_list, executed, front = heapq.heappop(open_heap)

            mk = mapping_key(cur_m_list)
            state_key = (mk, executed)

            if state_key in visited and visited[state_key] <= g_cost:
                continue
            visited[state_key] = g_cost

            if best_known_total < float('inf') and f > best_known_total * 1.2:
                continue

            new_executed = set(executed)
            new_front = set(front)
            progress = True
            while progress:
                progress = False
                newly_exec = set()
                for g in list(new_front):
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = cur_m_list[gq1], cur_m_list[gq2]
                    if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                        newly_exec.add(g)
                if newly_exec:
                    progress = True
                    new_executed |= newly_exec
                    new_front -= newly_exec
                    for g in newly_exec:
                        for s in dag2q_succ[g]:
                            if s in early_layer_gates and s not in new_executed:
                                all_pred = True
                                for p in dag2q_pred[s]:
                                    if p in early_layer_gates and p not in new_executed:
                                        all_pred = False
                                        break
                                if all_pred:
                                    new_front.add(s)

            new_exec_frozen = frozenset(new_executed)
            new_front_frozen = frozenset(new_front)

            if not (early_layer_gates - new_executed):
                if g_cost < best_known_total:
                    best_known_total = g_cost
                    parent_key = (mk, executed)
                    pair_swaps = dict(swap_history.get(parent_key, {}))
                    best_result = (g_cost, pair_swaps)
                continue

            if not new_front_frozen:
                continue

            active_phys = set()
            for g in new_front_frozen:
                gq1, gq2 = gates_2q[g]
                active_phys.add(cur_m_list[gq1])
                active_phys.add(cur_m_list[gq2])
            ext_gates = set()
            for g in new_front_frozen:
                for s in dag2q_succ[g]:
                    if s in early_layer_gates and s not in new_executed:
                        ext_gates.add(s)
            for g in ext_gates:
                gq1, gq2 = gates_2q[g]
                active_phys.add(cur_m_list[gq1])
                active_phys.add(cur_m_list[gq2])

            swaps = set()
            for pq in active_phys:
                for nb in hw_adj.get(pq, set()):
                    swaps.add((min(pq, nb), max(pq, nb)))

            expansions += 1
            parent_pair_swaps = swap_history.get((mk, executed), defaultdict(float))

            for (s1, s2) in swaps:
                new_m = list(cur_m_list)
                lq_at_s1 = -1
                lq_at_s2 = -1
                for lq in range(num_q):
                    if new_m[lq] == s1:
                        lq_at_s1 = lq
                    if new_m[lq] == s2:
                        lq_at_s2 = lq

                if lq_at_s1 >= 0:
                    new_m[lq_at_s1] = s2
                if lq_at_s2 >= 0:
                    new_m[lq_at_s2] = s1

                new_g = g_cost + 1
                new_mk = mapping_key(new_m)
                child_key = (new_mk, new_exec_frozen)

                if child_key in visited and visited[child_key] <= new_g:
                    continue

                new_h = h_func(new_m, new_front_frozen)
                new_f = new_g + new_h

                if best_known_total < float('inf') and new_f > best_known_total * 1.2:
                    continue

                counter[0] += 1

                child_pair_swaps = defaultdict(float, parent_pair_swaps)
                for g in new_front_frozen:
                    gq1, gq2 = gates_2q[g]
                    pair_key = (min(gq1, gq2), max(gq1, gq2))
                    child_pair_swaps[pair_key] += 1.0

                swap_history[child_key] = child_pair_swaps

                heapq.heappush(open_heap, (new_f, counter[0], new_g, new_m, new_exec_frozen, new_front_frozen))

        if best_result is not None:
            return defaultdict(float, best_result[1]), best_result[0]
        else:
            return defaultdict(float), 0

    # ---------------------------------------------------------------
    # Step 7: Forward greedy routing simulation
    # ---------------------------------------------------------------
    def simulate_routing_greedy(m, rm, max_layers=20):
        sim_m = list(m)
        sim_rm = list(rm)
        swap_counts = defaultdict(float)
        total_swaps = 0

        if not gates_2q:
            return swap_counts, total_swaps

        pred_remaining = {g: len(dag2q_pred[g]) for g in gates_2q}
        front = set(g for g in gates_2q if pred_remaining[g] == 0)
        layers_done = 0

        while front and layers_done < max_layers:
            executable = []
            for g in front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = sim_m[gq1], sim_m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    executable.append(g)

            if executable:
                for g in executable:
                    front.discard(g)
                    for s in dag2q_succ[g]:
                        pred_remaining[s] -= 1
                        if pred_remaining[s] == 0:
                            front.add(s)
                layers_done += 1
                continue

            active_phys = set()
            for g in front:
                gq1, gq2 = gates_2q[g]
                active_phys.add(sim_m[gq1])
                active_phys.add(sim_m[gq2])

            candidates_sw = set()
            for pq in active_phys:
                for nb in self.backend.get(pq, []):
                    candidates_sw.add((min(pq, nb), max(pq, nb)))

            best_swap, best_score = None, float('inf')
            for (s1, s2) in candidates_sw:
                l1, l2 = sim_rm[s1], sim_rm[s2]
                score = 0.0
                for g in front:
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = sim_m[gq1], sim_m[gq2]
                    if gq1 == l1: p1 = s2
                    elif gq1 == l2: p1 = s1
                    if gq2 == l1: p2 = s2
                    elif gq2 == l2: p2 = s1
                    deps = dep_count.get(g, 0) + 1
                    score += deps * dist[p1][p2]
                if score < best_score:
                    best_score = score
                    best_swap = (s1, s2)

            if best_swap is None:
                break

            s1, s2 = best_swap
            l1, l2 = sim_rm[s1], sim_rm[s2]
            sim_m[l1], sim_m[l2] = s2, s1
            sim_rm[s1], sim_rm[s2] = l2, l1
            total_swaps += 1

            for g in front:
                gq1, gq2 = gates_2q[g]
                pair_key = (min(gq1, gq2), max(gq1, gq2))
                swap_counts[pair_key] += 1.0

        return swap_counts, total_swaps

    # ---------------------------------------------------------------
    # Step 7b: Backward greedy routing simulation
    # ---------------------------------------------------------------
    def simulate_routing_backward(m, rm, max_layers=20):
        sim_m = list(m)
        sim_rm = list(rm)
        swap_counts = defaultdict(float)
        total_swaps = 0

        if not gates_2q:
            return swap_counts, total_swaps

        succ_remaining = {g: len(dag2q_succ[g] & set(gates_2q.keys())) for g in gates_2q}
        front = set(g for g in gates_2q if succ_remaining[g] == 0)
        layers_done = 0

        while front and layers_done < max_layers:
            executable = []
            for g in front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = sim_m[gq1], sim_m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    executable.append(g)

            if executable:
                for g in executable:
                    front.discard(g)
                    for p in dag2q_pred[g]:
                        if p in gates_2q:
                            succ_remaining[p] -= 1
                            if succ_remaining[p] == 0:
                                front.add(p)
                layers_done += 1
                continue

            active_phys = set()
            for g in front:
                gq1, gq2 = gates_2q[g]
                active_phys.add(sim_m[gq1])
                active_phys.add(sim_m[gq2])

            candidates_sw = set()
            for pq in active_phys:
                for nb in self.backend.get(pq, []):
                    candidates_sw.add((min(pq, nb), max(pq, nb)))

            best_swap, best_score = None, float('inf')
            for (s1, s2) in candidates_sw:
                l1, l2 = sim_rm[s1], sim_rm[s2]
                score = 0.0
                for g in front:
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = sim_m[gq1], sim_m[gq2]
                    if gq1 == l1: p1 = s2
                    elif gq1 == l2: p1 = s1
                    if gq2 == l1: p2 = s2
                    elif gq2 == l2: p2 = s1
                    deps = bwd_dep.get(g, 0) + 1
                    score += deps * dist[p1][p2]
                if score < best_score:
                    best_score = score
                    best_swap = (s1, s2)

            if best_swap is None:
                break

            s1, s2 = best_swap
            l1, l2 = sim_rm[s1], sim_rm[s2]
            sim_m[l1], sim_m[l2] = s2, s1
            sim_rm[s1], sim_rm[s2] = l2, l1
            total_swaps += 1

            for g in front:
                gq1, gq2 = gates_2q[g]
                pair_key = (min(gq1, gq2), max(gq1, gq2))
                swap_counts[pair_key] += 1.0

        return swap_counts, total_swaps

    # ---------------------------------------------------------------
    # Step 7c: Asymmetric bidirectional routing (forward-biased 0.6/0.4)
    # ---------------------------------------------------------------
    def simulate_routing_asymmetric_bidir(m, rm, max_layers=20):
        fwd_swaps, fwd_total = simulate_routing_greedy(m, rm, max_layers=max_layers)
        bwd_swaps, bwd_total = simulate_routing_backward(m, rm, max_layers=max_layers)

        combined = defaultdict(float)
        all_keys = set(fwd_swaps.keys()) | set(bwd_swaps.keys())
        for key in all_keys:
            combined[key] = 0.6 * fwd_swaps.get(key, 0.0) + 0.4 * bwd_swaps.get(key, 0.0)

        return combined, (fwd_total + bwd_total) // 2

    # ---------------------------------------------------------------
    # Step 7d: Hybrid A* + greedy routing
    # ---------------------------------------------------------------
    def simulate_routing_hybrid(m, rm, max_layers=20):
        astar_swaps, astar_total = astar_routing_early(m, rm)
        greedy_swaps, greedy_total = simulate_routing_greedy(m, rm, max_layers=max_layers)

        combined_swaps = defaultdict(float)
        early_pairs = set()
        for g in early_layer_gates:
            gq1, gq2 = gates_2q[g]
            early_pairs.add((min(gq1, gq2), max(gq1, gq2)))

        for pair_key in early_pairs:
            if pair_key in astar_swaps:
                combined_swaps[pair_key] = astar_swaps[pair_key]

        for pair_key, count in greedy_swaps.items():
            if pair_key not in early_pairs:
                combined_swaps[pair_key] = count

        return combined_swaps, astar_total + greedy_total

    # ---------------------------------------------------------------
    # Step 7e: Hybrid A* + asymmetric bidirectional for later iters
    # ---------------------------------------------------------------
    def simulate_routing_hybrid_bidir(m, rm, max_layers=20):
        astar_swaps, astar_total = astar_routing_early(m, rm)
        fwd_swaps, fwd_total = simulate_routing_greedy(m, rm, max_layers=max_layers)
        bwd_swaps, bwd_total = simulate_routing_backward(m, rm, max_layers=max_layers)

        combined_swaps = defaultdict(float)
        early_pairs = set()
        for g in early_layer_gates:
            gq1, gq2 = gates_2q[g]
            early_pairs.add((min(gq1, gq2), max(gq1, gq2)))

        # Early pairs: A* exact feedback
        for pair_key in early_pairs:
            if pair_key in astar_swaps:
                combined_swaps[pair_key] = astar_swaps[pair_key]

        # Late pairs: asymmetric bidirectional
        all_late_keys = (set(fwd_swaps.keys()) | set(bwd_swaps.keys())) - early_pairs
        for pair_key in all_late_keys:
            combined_swaps[pair_key] = 0.6 * fwd_swaps.get(pair_key, 0.0) + 0.4 * bwd_swaps.get(pair_key, 0.0)

        return combined_swaps, astar_total + (fwd_total + bwd_total) // 2

    # ---------------------------------------------------------------
    # Step 8: Seed generation setup
    # ---------------------------------------------------------------
    sorted_by_degree = sorted(interacting_logical, key=lambda q: logical_degree[q], reverse=True)
    seed_lqs = sorted_by_degree[:min(3, len(sorted_by_degree))]
    phys_by_centrality = sorted(physical_qubits, key=lambda pq: phys_centrality[pq])
    seed_pqs = phys_by_centrality[:min(3, len(phys_by_centrality))]

    logical_degree_ranked = sorted(interacting_logical, key=lambda q: logical_degree[q], reverse=True)
    logical_degree_rank = {q: i for i, q in enumerate(logical_degree_ranked)}
    max_logical_rank = max(len(logical_degree_ranked) - 1, 1)
    phys_degree_ranked = sorted(physical_qubits, key=lambda pq: phys_degree[pq], reverse=True)
    phys_degree_rank = {pq: i for i, pq in enumerate(phys_degree_ranked)}
    max_phys_rank = max(len(phys_degree_ranked) - 1, 1)

    static_nbrs, static_deg = build_neighbors(static_weight)
    max_iw = max(static_weight.values()) if static_weight else 1.0

    # ---------------------------------------------------------------
    # Step 9: Routing-Pressure-Aware Conflict-Graph MIS Seed
    # ---------------------------------------------------------------
    def conflict_graph_seed(start_pq, nbrs, deg, weights, routing_pressure=None):
        if len(interacting_logical) < 2:
            return None, None

        cur_max_iw = max(weights.values()) if weights else 1.0

        top_partners = {}
        for lq in interacting_logical:
            nbr_list = sorted(nbrs.get(lq, {}).items(), key=lambda x: x[1], reverse=True)
            top_partners[lq] = set(p for p, _ in nbr_list[:3])

        conflict_adj = defaultdict(set)
        il = interacting_logical

        qubit_pressure = defaultdict(float)
        if routing_pressure:
            for (q1, q2), cnt in routing_pressure.items():
                qubit_pressure[q1] += cnt
                qubit_pressure[q2] += cnt

        for i in range(len(il)):
            for j in range(i + 1, len(il)):
                l1, l2 = il[i], il[j]
                s1 = top_partners.get(l1, set())
                s2 = top_partners.get(l2, set())
                if not s1 and not s2:
                    continue
                intersection = len(s1 & s2)
                union = len(s1 | s2)
                if union > 0:
                    jaccard = intersection / union
                    threshold = 0.5
                    if routing_pressure and qubit_pressure[l1] > 0 and qubit_pressure[l2] > 0:
                        max_pressure = max(qubit_pressure.values()) if qubit_pressure else 1.0
                        pressure_factor = min(1.0, (qubit_pressure[l1] + qubit_pressure[l2]) /
                                              (max_pressure * 2 + 1e-10))
                        threshold = max(0.25, 0.5 - 0.25 * pressure_factor)
                    if jaccard > threshold:
                        conflict_adj[l1].add(l2)
                        conflict_adj[l2].add(l1)

        sorted_by_deg_local = sorted(interacting_logical,
                                     key=lambda q: (deg.get(q, 0), qubit_pressure.get(q, 0)),
                                     reverse=True)
        mis = set()
        excluded = set()
        for lq in sorted_by_deg_local:
            if lq not in excluded:
                mis.add(lq)
                for neighbor in conflict_adj.get(lq, set()):
                    excluded.add(neighbor)

        non_mis = [lq for lq in sorted_by_deg_local if lq not in mis]
        mis_ordered = sorted(mis, key=lambda q: (deg.get(q, 0), qubit_pressure.get(q, 0)),
                             reverse=True)

        m = [-1] * num_q
        rm = [-1] * num_q
        used_phys = set()

        if mis_ordered:
            first_lq = mis_ordered[0]
            m[first_lq] = start_pq
            rm[start_pq] = first_lq
            used_phys.add(start_pq)

            for lq in mis_ordered[1:]:
                nbrs_placed = {}
                for plq in mis:
                    if m[plq] >= 0 and plq in nbrs.get(lq, {}):
                        nbrs_placed[plq] = nbrs[lq][plq]

                if nbrs_placed:
                    best_pq = None
                    best_score = float('inf')
                    for pq in physical_qubits:
                        if pq in used_phys:
                            continue
                        score = 0.0
                        for plq, iw in nbrs_placed.items():
                            d = dist[pq][m[plq]]
                            cost = iw * d
                            if m[plq] in hw_adj[pq]:
                                cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                            score += cost
                        if score < best_score:
                            best_score = score
                            best_pq = pq
                else:
                    best_pq = None
                    best_score = float('inf')
                    for pq in physical_qubits:
                        if pq not in used_phys:
                            if phys_centrality[pq] < best_score:
                                best_score = phys_centrality[pq]
                                best_pq = pq

                if best_pq is not None:
                    m[lq] = best_pq
                    rm[best_pq] = lq
                    used_phys.add(best_pq)

        placed_set = set(lq for lq in interacting_logical if m[lq] >= 0)

        for lq in non_mis:
            nbrs_placed = {}
            for plq in placed_set:
                w = nbrs.get(lq, {}).get(plq, 0.0)
                if w > 0:
                    nbrs_placed[plq] = w

            if nbrs_placed:
                near_ties = []
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq in used_phys:
                        continue
                    score = 0.0
                    for plq, iw in nbrs_placed.items():
                        d = dist[pq][m[plq]]
                        cost = iw * d
                        if m[plq] in hw_adj[pq]:
                            cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                        score += cost
                    near_ties.append((score, pq))
                    if score < best_score:
                        best_score = score

                if near_ties and best_score > 0:
                    threshold = best_score * 1.05
                    candidates_list = [(s, pq) for s, pq in near_ties if s <= threshold]
                    if len(candidates_list) > 1 and lq in logical_degree_rank:
                        lq_rn = logical_degree_rank[lq] / max_logical_rank
                        best_pq = min(candidates_list, key=lambda x: (
                            abs(phys_degree_rank[x[1]] / max_phys_rank - lq_rn), x[0]))[1]
                    else:
                        best_pq = min(candidates_list, key=lambda x: x[0])[1]
                elif near_ties:
                    best_pq = min(near_ties, key=lambda x: x[0])[1]
                else:
                    best_pq = None
            else:
                best_pq = None
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq not in used_phys:
                        if phys_centrality[pq] < best_score:
                            best_score = phys_centrality[pq]
                            best_pq = pq

            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                used_phys.add(best_pq)
                placed_set.add(lq)

        remaining_lqs = [lq for lq in logical_qubits if m[lq] == -1]
        for lq in remaining_lqs:
            best_pq = None
            best_score = float('inf')
            for pq in physical_qubits:
                if pq not in used_phys:
                    if phys_centrality[pq] < best_score:
                        best_score = phys_centrality[pq]
                        best_pq = pq
            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                used_phys.add(best_pq)

        return m, rm

    # ---------------------------------------------------------------
    # Step 10: Spectral ordering seed
    # ---------------------------------------------------------------
    def spectral_seed():
        if len(interacting_logical) < 3:
            return None, None

        idx_map = {q: i for i, q in enumerate(interacting_logical)}
        n = len(interacting_logical)

        L = [[0.0] * n for _ in range(n)]
        for (q1, q2), w in static_weight.items():
            if q1 in idx_map and q2 in idx_map:
                i, j = idx_map[q1], idx_map[q2]
                L[i][j] -= w
                L[j][i] -= w
                L[i][i] += w
                L[j][j] += w

        def power_iter(mat, n_iter=200):
            v = [random.gauss(0, 1) for _ in range(n)]
            for _ in range(n_iter):
                new_v = [0.0] * n
                for i in range(n):
                    for j in range(n):
                        new_v[i] += mat[i][j] * v[j]
                norm = math.sqrt(sum(x * x for x in new_v)) or 1e-12
                v = [x / norm for x in new_v]
            return v

        max_diag = max(L[i][i] for i in range(n)) + 1.0
        shifted = [[0.0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                shifted[i][j] = -L[i][j]
            shifted[i][i] += max_diag

        v1 = power_iter(shifted, 150)

        dot_v1 = sum(x * x for x in v1) or 1e-12
        lam1_shifted = sum(v1[i] * sum(shifted[i][j] * v1[j] for j in range(n)) for i in range(n)) / dot_v1
        shifted2 = [row[:] for row in shifted]
        for i in range(n):
            for j in range(n):
                shifted2[i][j] -= lam1_shifted * v1[i] * v1[j] / dot_v1

        fiedler = power_iter(shifted2, 200)

        fiedler_order = sorted(range(n), key=lambda i: fiedler[i])
        sorted_logical = [interacting_logical[i] for i in fiedler_order]

        phys_sorted = sorted(physical_qubits, key=lambda pq: phys_centrality[pq])
        start_pq = phys_sorted[0]
        visited_bfs = set()
        bfs_order = []
        bfs_q = deque([start_pq])
        visited_bfs.add(start_pq)
        while bfs_q:
            pq = bfs_q.popleft()
            bfs_order.append(pq)
            for nb in sorted(hw_adj[pq]):
                if nb not in visited_bfs:
                    visited_bfs.add(nb)
                    bfs_q.append(nb)
        for pq in physical_qubits:
            if pq not in visited_bfs:
                bfs_order.append(pq)
                visited_bfs.add(pq)

        m = [-1] * num_q
        rm = [-1] * num_q
        n_interact = len(sorted_logical)
        n_phys = len(bfs_order)
        offset = max(0, (n_phys - n_interact) // 2)
        for i, lq in enumerate(sorted_logical):
            pq = bfs_order[min(offset + i, n_phys - 1)]
            if rm[pq] != -1:
                best_pq = None
                best_d = float('inf')
                for cpq in physical_qubits:
                    if rm[cpq] == -1:
                        d = dist[pq][cpq]
                        if d < best_d:
                            best_d = d
                            best_pq = cpq
                pq = best_pq
            m[lq] = pq
            rm[pq] = lq

        return m, rm

    # ---------------------------------------------------------------
    # Step 11: Greedy placement
    # ---------------------------------------------------------------
    def run_greedy_placement(start_lq, start_pq, nbrs, deg, weights=None):
        cur_max_iw = max(weights.values()) if weights else max_iw
        used_phys = {start_pq}
        m = [-1] * num_q
        rm = [-1] * num_q
        m[start_lq] = start_pq
        rm[start_pq] = start_lq
        placed = {start_lq}
        remaining = set(logical_qubits) - placed

        while remaining:
            best_lq, best_w = None, -1.0
            for lq in remaining:
                w = sum(nbrs.get(lq, {}).get(plq, 0.0) for plq in placed)
                if w > best_w:
                    best_w = w
                    best_lq = lq

            nbrs_placed = {plq: nbrs.get(best_lq, {}).get(plq, 0.0)
                           for plq in placed if plq in nbrs.get(best_lq, {})}

            if nbrs_placed:
                near_ties = []
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq in used_phys:
                        continue
                    score = 0.0
                    for plq, iw in nbrs_placed.items():
                        d = dist[pq][m[plq]]
                        cost = iw * d
                        if m[plq] in hw_adj[pq]:
                            cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                        score += cost
                    near_ties.append((score, pq))
                    if score < best_score:
                        best_score = score

                if near_ties and best_score > 0:
                    threshold = best_score * 1.05
                    candidates_list = [(s, pq) for s, pq in near_ties if s <= threshold]
                    if len(candidates_list) > 1 and best_lq in logical_degree_rank:
                        lq_rn = logical_degree_rank[best_lq] / max_logical_rank
                        best_pq = min(candidates_list, key=lambda x: (
                            abs(phys_degree_rank[x[1]] / max_phys_rank - lq_rn), x[0]))[1]
                    else:
                        best_pq = min(candidates_list, key=lambda x: x[0])[1]
                elif near_ties:
                    best_pq = min(near_ties, key=lambda x: x[0])[1]
                else:
                    best_pq = None
            else:
                best_pq = None
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq not in used_phys:
                        score = phys_centrality[pq]
                        if score < best_score:
                            best_score = score
                            best_pq = pq

            m[best_lq] = best_pq
            rm[best_pq] = best_lq
            used_phys.add(best_pq)
            placed.add(best_lq)
            remaining.discard(best_lq)
        return m, rm

    def fill_unmapped(m, rm):
        unmapped = [q for q in range(num_q) if m[q] == -1]
        free = [pq for pq in range(num_q) if rm[pq] == -1]
        for lq, pq in zip(unmapped, free):
            m[lq] = pq
            rm[pq] = lq

    # ---------------------------------------------------------------
    # Step 12: Local search with nonlinear distance penalty
    # ---------------------------------------------------------------
    def local_search(m, rm, nbrs, weights, alpha_exp, max_rounds=5):
        if len(interacting_logical) <= 1:
            return compute_cost_nonlinear(m, weights, alpha_exp)
        for _ in range(max_rounds):
            improved = False
            best_d, best_pair = 0.0, None
            active_phys = [m[q] for q in interacting_logical]
            for pq1 in active_phys:
                for pq2 in hw_adj.get(pq1, set()):
                    d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                    if d < best_d:
                        best_d = d
                        best_pair = (pq1, pq2)
            n_random = min(150, len(interacting_logical) * 3)
            for _ in range(n_random):
                i, j = random.sample(range(len(interacting_logical)), 2)
                pq1, pq2 = m[interacting_logical[i]], m[interacting_logical[j]]
                d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                if d < best_d:
                    best_d = d
                    best_pair = (pq1, pq2)
            if best_pair and best_d < -1e-12:
                do_swap(m, rm, *best_pair)
                improved = True
            if not improved:
                for i in range(len(interacting_logical)):
                    for j in range(i + 1, len(interacting_logical)):
                        pq1, pq2 = m[interacting_logical[i]], m[interacting_logical[j]]
                        d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                        if d < best_d:
                            best_d = d
                            best_pair = (pq1, pq2)
                if best_pair and best_d < -1e-12:
                    do_swap(m, rm, *best_pair)
                else:
                    break
        return compute_cost_nonlinear(m, weights, alpha_exp)

    # ---------------------------------------------------------------
    # Step 13: Perturbation modes with bandit selection
    #   LNS uses accumulated routing pressure to bias destruction
    # ---------------------------------------------------------------
    rsdiwr_iter_ref = [0]
    accumulated_routing_pressure_ref = [defaultdict(float)]

    def perturb_random(m, rm, **kw):
        if len(interacting_logical) >= 2:
            lqs = random.sample(interacting_logical, 2)
            do_swap(m, rm, m[lqs[0]], m[lqs[1]])

    def perturb_segment_shuffle(m, rm, **kw):
        k = min(random.randint(3, 5), len(interacting_logical))
        if k < 2:
            perturb_random(m, rm)
            return
        lqs = random.sample(interacting_logical, k)
        phys_positions = [m[lq] for lq in lqs]
        random.shuffle(phys_positions)
        for lq in lqs:
            rm[m[lq]] = -1
        for lq, pq in zip(lqs, phys_positions):
            m[lq] = pq
            rm[pq] = lq

    def perturb_worst_pair(m, rm, weights=None, alpha_exp=1.5, **kw):
        if weights is None:
            perturb_random(m, rm)
            return
        pair_costs = []
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                d = dist[m[q1]][m[q2]]
                c = w * (d ** alpha_exp)
                pair_costs.append((c, q1, q2))
        if not pair_costs:
            return
        pair_costs.sort(reverse=True)
        top_n = min(3, len(pair_costs))
        _, tq1, tq2 = pair_costs[random.randint(0, top_n - 1)]
        pq1, pq2 = m[tq1], m[tq2]
        adj_of_pq2 = list(hw_adj.get(pq2, set()))
        if adj_of_pq2:
            target = random.choice(adj_of_pq2)
            if target != pq1:
                do_swap(m, rm, pq1, target)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    def perturb_edge_targeted(m, rm, weights=None, alpha_exp=1.5, **kw):
        if weights is None:
            perturb_random(m, rm)
            return
        edge_costs = []
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                c = w * (dist[m[q1]][m[q2]] ** alpha_exp)
                edge_costs.append((c, q1, q2))
        if not edge_costs:
            return
        edge_costs.sort(reverse=True)
        top_n = min(5, len(edge_costs))
        _, eq1, eq2 = edge_costs[random.randint(0, top_n - 1)]
        pq1, pq2 = m[eq1], m[eq2]
        neighbors_of_pq2 = list(hw_adj.get(pq2, set()))
        if neighbors_of_pq2:
            target = random.choice(neighbors_of_pq2)
            if target != pq1:
                do_swap(m, rm, pq1, target)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    def perturb_lns(m, rm, nbrs=None, alpha_exp=1.5, **kw):
        """Pressure-guided LNS: blends current cost with accumulated
        routing pressure to select which qubits to destroy."""
        if nbrs is None or len(interacting_logical) < 3:
            perturb_random(m, rm)
            return
        base_lo = 3 + rsdiwr_iter_ref[0]
        base_hi = 8 + rsdiwr_iter_ref[0] * 2
        k = min(random.randint(base_lo, base_hi), len(interacting_logical))

        acc_pressure = accumulated_routing_pressure_ref[0]
        qubit_acc_pressure = defaultdict(float)
        for (q1, q2), cnt in acc_pressure.items():
            qubit_acc_pressure[q1] += cnt
            qubit_acc_pressure[q2] += cnt
        max_acc = max(qubit_acc_pressure.values()) if qubit_acc_pressure else 1.0

        qcost = {}
        for lq in interacting_logical:
            c = 0.0
            for partner, w in nbrs.get(lq, {}).items():
                if m[partner] >= 0 and m[lq] >= 0:
                    c += w * (dist[m[lq]][m[partner]] ** alpha_exp)
            pressure_bonus = qubit_acc_pressure.get(lq, 0.0) / (max_acc + 1e-10)
            qcost[lq] = c * (1.0 + 0.5 * pressure_bonus)

        sorted_qs = sorted(qcost, key=lambda q: qcost[q], reverse=True)
        top_half = sorted_qs[:max(k, len(sorted_qs) // 2)]
        subset = random.sample(top_half, min(k, len(top_half)))

        freed_phys = []
        for lq in subset:
            freed_phys.append(m[lq])
            rm[m[lq]] = -1
            m[lq] = -1

        placed_set = set(lq for lq in interacting_logical if m[lq] >= 0)
        for lq in sorted(subset, key=lambda q: qcost[q], reverse=True):
            best_pq, best_sc = None, float('inf')
            for pq in freed_phys:
                if rm[pq] != -1:
                    continue
                sc = 0.0
                for partner, w in nbrs.get(lq, {}).items():
                    if partner in placed_set and m[partner] >= 0:
                        sc += w * (dist[pq][m[partner]] ** alpha_exp)
                if sc < best_sc:
                    best_sc = sc
                    best_pq = pq
            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                placed_set.add(lq)
            else:
                for pq in freed_phys:
                    if rm[pq] == -1:
                        m[lq] = pq
                        rm[pq] = lq
                        placed_set.add(lq)
                        break

    perturbation_modes = [perturb_random, perturb_segment_shuffle,
                          perturb_worst_pair, perturb_edge_targeted, perturb_lns]
    K = len(perturbation_modes)

    WINDOW_SIZE = 100
    EPSILON = 0.1
    window = []
    mode_successes = [0] * K
    mode_attempts = [0] * K

    def select_perturbation_mode():
        if random.random() < EPSILON or sum(mode_attempts) < K * 2:
            return random.randint(0, K - 1)
        rates = []
        for k in range(K):
            if mode_attempts[k] > 0:
                rates.append(mode_successes[k] / mode_attempts[k])
            else:
                rates.append(1.0)
        total = sum(rates)
        if total < 1e-12:
            return random.randint(0, K - 1)
        r = random.random() * total
        cumul = 0.0
        for k in range(K):
            cumul += rates[k]
            if r <= cumul:
                return k
        return K - 1

    def update_window(mode_idx, success):
        window.append((mode_idx, success))
        mode_attempts[mode_idx] += 1
        if success:
            mode_successes[mode_idx] += 1
        if len(window) > WINDOW_SIZE:
            old_mode, old_success = window.pop(0)
            mode_attempts[old_mode] -= 1
            if old_success:
                mode_successes[old_mode] -= 1

    # ---------------------------------------------------------------
    # Step 14: Build initial mapping candidates
    # ---------------------------------------------------------------
    candidates = []

    for s_lq in seed_lqs:
        for s_pq in seed_pqs:
            m, rm = run_greedy_placement(s_lq, s_pq, static_nbrs, static_deg,
                                         weights=static_weight)
            fill_unmapped(m, rm)
            cost = compute_cost(m, static_weight)
            candidates.append((cost, m, rm))

    for s_pq in seed_pqs:
        cg_m, cg_rm = conflict_graph_seed(s_pq, static_nbrs, static_deg, static_weight)
        if cg_m is not None:
            fill_unmapped(cg_m, cg_rm)
            cost = compute_cost(cg_m, static_weight)
            candidates.append((cost, cg_m, cg_rm))

    spec_m, spec_rm = spectral_seed()
    if spec_m is not None:
        fill_unmapped(spec_m, spec_rm)
        spec_cost = compute_cost(spec_m, static_weight)
        candidates.append((spec_cost, spec_m, spec_rm))

    m_rand = [-1] * num_q
    rm_rand = [-1] * num_q
    shuffled_phys = list(physical_qubits)
    random.shuffle(shuffled_phys)
    for i, lq in enumerate(logical_qubits):
        m_rand[lq] = shuffled_phys[i]
        rm_rand[shuffled_phys[i]] = lq
    fill_unmapped(m_rand, rm_rand)
    c = compute_cost(m_rand, static_weight)
    candidates.append((c, m_rand, rm_rand))

    if not candidates:
        self.mapping_dict = list(range(num_q))
        self.reverse_mapping_dict = list(range(num_q))
        if self.use_isl:
            self.isl_mapping = dict_to_isl_map(self.mapping_dict)
        return

    candidates.sort(key=lambda x: x[0])

    _, best_m, best_rm = candidates[0]
    best_m, best_rm = list(best_m), list(best_rm)
    local_search(best_m, best_rm, static_nbrs, static_weight, alpha_exp=2.0, max_rounds=6)
    best_cost = compute_cost(best_m, static_weight)

    for idx in range(1, min(5, len(candidates))):
        _, m_c, rm_c = candidates[idx]
        m_c, rm_c = list(m_c), list(rm_c)
        local_search(m_c, rm_c, static_nbrs, static_weight, alpha_exp=2.0, max_rounds=4)
        c = compute_cost(m_c, static_weight)
        if c < best_cost:
            best_cost = c
            best_m = list(m_c)
            best_rm = list(rm_c)

    # ---------------------------------------------------------------
    # Step 15: RSDIWR + ILS with A*-guided first iteration,
    #   asymmetric bidirectional routing, pressure-adaptive blending,
    #   routing-pressure MIS reseeding, and pressure-guided LNS
    # ---------------------------------------------------------------
    time_budget = 25.0
    t_start = _time()
    n_rsdiwr = 4

    cur_m = list(best_m)
    cur_rm = list(best_rm)
    swap_counts = defaultdict(float)
    accumulated_routing_pressure = defaultdict(float)
    accumulated_routing_pressure_ref[0] = accumulated_routing_pressure

    for rsdiwr_iter in range(n_rsdiwr):
        rsdiwr_iter_ref[0] = rsdiwr_iter
        elapsed = _time() - t_start
        if elapsed > time_budget:
            break

        remaining_time = time_budget - elapsed
        remaining_iters = n_rsdiwr - rsdiwr_iter
        time_for_this_iter = remaining_time / max(remaining_iters, 1)
        n_ils = max(55, int(num_q * time_for_this_iter / 0.5)) if time_for_this_iter > 1.0 else max(30, num_q // 3)

        # Pressure-adaptive blending: alpha_blend decreases faster when
        # accumulated pressure is high (routing feedback is more informative)
        if rsdiwr_iter == 0 or not swap_counts:
            eff_weights = dict(static_weight)
        else:
            max_sw = max(swap_counts.values()) if swap_counts else 1.0
            scale = max(static_weight.values()) / max(max_sw, 1e-10)

            # Compute pressure magnitude to adapt blend coefficient
            total_pressure = sum(accumulated_routing_pressure.values())
            n_pairs = len(accumulated_routing_pressure)
            avg_pressure = total_pressure / max(n_pairs, 1)
            # Higher pressure → trust routing feedback more (lower alpha_blend)
            pressure_adapt = min(0.15, 0.05 * avg_pressure / max(max_sw, 1e-10))
            alpha_blend = max(0.25, 1.0 - 0.3 * rsdiwr_iter - pressure_adapt)

            eff_weights = defaultdict(float)
            all_keys = set(static_weight.keys()) | set(swap_counts.keys())
            for key in all_keys:
                w_s = static_weight.get(key, 0.0)
                w_r = swap_counts.get(key, 0.0) * scale
                eff_weights[key] = alpha_blend * w_s + (1.0 - alpha_blend) * w_r

        eff_nbrs, eff_deg = build_neighbors(eff_weights)

        # Re-seed with routing-informed weights + routing-pressure MIS
        if rsdiwr_iter > 0 and swap_counts and (_time() - t_start) < time_budget * 0.7:
            eff_sorted = sorted(interacting_logical,
                                key=lambda q: eff_deg.get(q, 0), reverse=True)
            reseed_lqs = eff_sorted[:min(2, len(eff_sorted))]
            reseed_pqs = seed_pqs[:min(2, len(seed_pqs))]

            for s_lq in reseed_lqs:
                for s_pq in reseed_pqs:
                    rm_new, rmm_new = run_greedy_placement(
                        s_lq, s_pq, eff_nbrs, eff_deg, weights=eff_weights)
                    fill_unmapped(rm_new, rmm_new)
                    local_search(rm_new, rmm_new, eff_nbrs, eff_weights,
                                 alpha_exp=2.0, max_rounds=3)
                    sc = compute_cost(rm_new, static_weight)
                    if sc < best_cost:
                        best_cost = sc
                        best_m = list(rm_new)
                        best_rm = list(rmm_new)
                        cur_m = list(rm_new)
                        cur_rm = list(rmm_new)

            # Routing-pressure-aware MIS reseeding
            for s_pq in reseed_pqs:
                cg_m, cg_rm = conflict_graph_seed(
                    s_pq, eff_nbrs, eff_deg, eff_weights,
                    routing_pressure=accumulated_routing_pressure)
                if cg_m is not None:
                    fill_unmapped(cg_m, cg_rm)
                    local_search(cg_m, cg_rm, eff_nbrs, eff_weights,
                                 alpha_exp=2.0, max_rounds=3)
                    sc = compute_cost(cg_m, static_weight)
                    if sc < best_cost:
                        best_cost = sc
                        best_m = list(cg_m)
                        best_rm = list(cg_rm)
                        cur_m = list(cg_m)
                        cur_rm = list(cg_rm)

        alpha_start = 2.0
        alpha_end = 1.0

        ls_rounds = 6 if rsdiwr_iter == 0 else 4
        cur_cost_nl = local_search(cur_m, cur_rm, eff_nbrs, eff_weights,
                                   alpha_exp=alpha_start, max_rounds=ls_rounds)

        static_cost = compute_cost(cur_m, static_weight)
        if static_cost < best_cost:
            best_cost = static_cost
            best_m = list(cur_m)
            best_rm = list(cur_rm)

        # Reset bandit window
        window.clear()
        for k in range(K):
            mode_successes[k] = 0
            mode_attempts[k] = 0

        T = max(cur_cost_nl * 0.05, 1.0)
        T_init = T
        alpha_sa = 0.94
        reheat_interval = max(n_ils // 4, 8)

        for ils_iter in range(n_ils):
            if _time() - t_start > time_budget:
                break

            progress = ils_iter / max(n_ils - 1, 1)
            alpha_exp = alpha_start + (alpha_end - alpha_start) * progress

            saved_m = list(cur_m)
            saved_rm = list(cur_rm)
            saved_cost = cur_cost_nl

            mode = select_perturbation_mode()
            perturbation_modes[mode](cur_m, cur_rm,
                                    nbrs=eff_nbrs, weights=eff_weights,
                                    alpha_exp=alpha_exp)

            new_cost_nl = local_search(cur_m, cur_rm, eff_nbrs, eff_weights,
                                       alpha_exp=alpha_exp, max_rounds=3)

            success = new_cost_nl < saved_cost - 1e-12

            improvement = saved_cost - new_cost_nl
            if improvement > 0:
                cur_cost_nl = new_cost_nl
                sc = compute_cost(cur_m, static_weight)
                if sc < best_cost:
                    best_cost = sc
                    best_m = list(cur_m)
                    best_rm = list(cur_rm)
            elif random.random() < math.exp(min(0, improvement / max(T, 1e-10))):
                cur_cost_nl = new_cost_nl
            else:
                cur_m[:] = saved_m
                cur_rm[:] = saved_rm
                cur_cost_nl = saved_cost

            update_window(mode, success)

            T *= alpha_sa
            if (ils_iter + 1) % reheat_interval == 0:
                T = max(T, T_init * 0.35)

        # Routing simulation for RSDIWR feedback
        if rsdiwr_iter < n_rsdiwr - 1:
            sim_depth = 14 + rsdiwr_iter * 7

            if rsdiwr_iter == 0 and early_layer_gates:
                # First iteration: A*-guided hybrid routing for exact early-layer feedback
                swap_counts, _ = simulate_routing_hybrid(best_m, best_rm, max_layers=sim_depth)
            elif rsdiwr_iter == 1 and early_layer_gates:
                # Second iteration: A* + asymmetric bidirectional for full-spectrum feedback
                swap_counts, _ = simulate_routing_hybrid_bidir(best_m, best_rm, max_layers=sim_depth)
            else:
                # Later iterations: asymmetric bidirectional only (faster, A* less useful)
                swap_counts, _ = simulate_routing_asymmetric_bidir(best_m, best_rm, max_layers=sim_depth)

            # Accumulate routing pressure across iterations
            for pair_key, cnt in swap_counts.items():
                accumulated_routing_pressure[pair_key] += cnt

        cur_m = list(best_m)
        cur_rm = list(best_rm)
        cur_cost_nl = compute_cost_nonlinear(cur_m, eff_weights, alpha_end)

    # ---------------------------------------------------------------
    # Step 16: Set final mapping
    # ---------------------------------------------------------------
    self.mapping_dict = best_m
    self.reverse_mapping_dict = best_rm

    if self.use_isl:
        self.isl_mapping = dict_to_isl_map(self.mapping_dict)

def init_mapping(self):
    import math
    import random
    import heapq
    from collections import defaultdict, deque
    from time import time as _time

    num_q = self.num_qubits
    physical_qubits = sorted(self.backend.keys())
    dist = self.distance_matrix

    # ---------------------------------------------------------------
    # Step 1: Build DAG and topological layers
    # ---------------------------------------------------------------
    all_gates = sorted(self.access.keys())
    two_qubit_gates = [g for g in all_gates if len(self.access[g]) == 2]

    last_gate_on_qubit = {}
    successors_dag = defaultdict(set)
    predecessors_dag = defaultdict(set)
    for g in all_gates:
        for q in self.access[g]:
            if q in last_gate_on_qubit:
                pred = last_gate_on_qubit[q]
                successors_dag[pred].add(g)
                predecessors_dag[g].add(pred)
            last_gate_on_qubit[q] = g

    in_degree = {g: len(predecessors_dag[g]) for g in all_gates}
    gate_layer = {g: 0 for g in all_gates}
    temp_in = dict(in_degree)
    queue = deque(g for g in all_gates if in_degree[g] == 0)
    topo_order = []
    while queue:
        g = queue.popleft()
        topo_order.append(g)
        for s in successors_dag[g]:
            gate_layer[s] = max(gate_layer[s], gate_layer[g] + 1)
            temp_in[s] -= 1
            if temp_in[s] == 0:
                queue.append(s)

    critical_path = {g: 0 for g in all_gates}
    for g in reversed(topo_order):
        for s in successors_dag[g]:
            if critical_path[s] + 1 > critical_path[g]:
                critical_path[g] = critical_path[s] + 1

    # 2q DAG for routing simulation
    gates_2q = {}
    dag2q_succ = defaultdict(set)
    dag2q_pred = defaultdict(set)
    last_2q_on_qubit = {}
    logical_qubits_set = set()

    for gate in all_gates:
        qubits = self.access[gate]
        if len(qubits) == 2:
            q1, q2 = qubits
            gates_2q[gate] = (q1, q2)
            logical_qubits_set.add(q1)
            logical_qubits_set.add(q2)
            for q in [q1, q2]:
                if q in last_2q_on_qubit:
                    prev = last_2q_on_qubit[q]
                    if prev != gate:
                        dag2q_succ[prev].add(gate)
                        dag2q_pred[gate].add(prev)
                last_2q_on_qubit[q] = gate
        elif len(qubits) == 1:
            logical_qubits_set.add(qubits[0])

    logical_qubits = sorted(logical_qubits_set)

    if not gates_2q:
        self.mapping_dict = list(range(num_q))
        self.reverse_mapping_dict = list(range(num_q))
        if self.use_isl:
            self.isl_mapping = dict_to_isl_map(self.mapping_dict)
        return

    # Topological order for 2q DAG
    topo_2q = []
    in_deg_2q = {g: len(dag2q_pred[g]) for g in gates_2q}
    q2 = deque(sorted(g for g in gates_2q if in_deg_2q[g] == 0))
    while q2:
        g = q2.popleft()
        topo_2q.append(g)
        for s in dag2q_succ[g]:
            in_deg_2q[s] -= 1
            if in_deg_2q[s] == 0:
                q2.append(s)

    dep_count = defaultdict(int)
    for g in reversed(topo_2q):
        for s in dag2q_succ[g]:
            dep_count[g] = max(dep_count[g], dep_count[s] + 1)

    # Backward dep count for backward routing
    bwd_dep = defaultdict(int)
    for g in topo_2q:
        for p in dag2q_pred[g]:
            if p in gates_2q:
                bwd_dep[g] = max(bwd_dep[g], bwd_dep[p] + 1)

    # ---------------------------------------------------------------
    # Step 2: Interaction weights — critical-path weighting
    # ---------------------------------------------------------------
    max_layer = max((gate_layer[g] for g in two_qubit_gates), default=1)

    static_weight = defaultdict(float)
    logical_degree = defaultdict(float)

    for g in two_qubit_gates:
        q1, q2 = self.access[g]
        cp = critical_path[g] + 1
        layer = gate_layer[g]
        w = cp * (max_layer - layer + 1)
        key = (min(q1, q2), max(q1, q2))
        static_weight[key] += w
        logical_degree[q1] += w
        logical_degree[q2] += w

    interacting_logical = [q for q in logical_qubits if logical_degree.get(q, 0) > 0]

    # ---------------------------------------------------------------
    # Step 3: Physical graph properties
    # ---------------------------------------------------------------
    hw_adj = defaultdict(set)
    for pq in physical_qubits:
        for pq2 in self.backend.get(pq, []):
            hw_adj[pq].add(pq2)

    phys_degree = {pq: len(hw_adj[pq]) for pq in physical_qubits}
    phys_centrality = {}
    for pq in physical_qubits:
        phys_centrality[pq] = sum(dist[pq][pq2] for pq2 in physical_qubits)

    # ---------------------------------------------------------------
    # Step 4: Helper functions
    # ---------------------------------------------------------------
    def build_neighbors(weights):
        nbrs = defaultdict(dict)
        deg = defaultdict(float)
        for (q1, q2), w in weights.items():
            nbrs[q1][q2] = w
            nbrs[q2][q1] = w
            deg[q1] += w
            deg[q2] += w
        return nbrs, deg

    def compute_cost_nonlinear(m, weights, alpha_exp):
        cost = 0.0
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                d = dist[m[q1]][m[q2]]
                cost += w * (d ** alpha_exp)
        return cost

    def compute_cost(m, weights):
        cost = 0.0
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                cost += w * dist[m[q1]][m[q2]]
        return cost

    def delta_swap_cost_nonlinear(m, rm, pq_a, pq_b, nbrs, alpha_exp):
        lq_a, lq_b = rm[pq_a], rm[pq_b]
        delta = 0.0
        affected = set()
        if lq_a in nbrs:
            affected.update(nbrs[lq_a].keys())
        if lq_b in nbrs:
            affected.update(nbrs[lq_b].keys())
        for q in affected:
            if q == lq_a or q == lq_b:
                continue
            pq_q = m[q]
            w_a = nbrs.get(lq_a, {}).get(q, 0.0)
            if w_a > 0:
                old_d = dist[pq_a][pq_q] ** alpha_exp
                new_d = dist[pq_b][pq_q] ** alpha_exp
                delta += w_a * (new_d - old_d)
            w_b = nbrs.get(lq_b, {}).get(q, 0.0)
            if w_b > 0:
                old_d = dist[pq_b][pq_q] ** alpha_exp
                new_d = dist[pq_a][pq_q] ** alpha_exp
                delta += w_b * (new_d - old_d)
        return delta

    def do_swap(m, rm, pq_a, pq_b):
        lq_a, lq_b = rm[pq_a], rm[pq_b]
        m[lq_a], m[lq_b] = pq_b, pq_a
        rm[pq_a], rm[pq_b] = lq_b, lq_a

    # ---------------------------------------------------------------
    # Step 5: A* early-layer routing with adaptive node limit
    # ---------------------------------------------------------------
    ASTAR_LAYERS = 5
    n_2q = len(gates_2q)
    if n_2q < 50:
        ASTAR_NODE_LIMIT = 8000
    elif n_2q < 200:
        ASTAR_NODE_LIMIT = 5000
    else:
        ASTAR_NODE_LIMIT = 3000

    pred_rem_layer = {g: len(dag2q_pred[g]) for g in gates_2q}
    front_layer_calc = set(g for g in gates_2q if pred_rem_layer[g] == 0)
    current_layer = 0
    early_layer_gates = set()

    temp_front = set(front_layer_calc)
    while temp_front:
        for g in temp_front:
            if current_layer < ASTAR_LAYERS:
                early_layer_gates.add(g)
        next_front = set()
        for g in temp_front:
            for s in dag2q_succ[g]:
                pred_rem_layer[s] -= 1
                if pred_rem_layer[s] == 0:
                    next_front.add(s)
        current_layer += 1
        temp_front = next_front

    # ---------------------------------------------------------------
    # Step 6: A*-guided routing for early layers
    # ---------------------------------------------------------------
    def astar_routing_early(m, rm):
        if not early_layer_gates:
            return defaultdict(float), 0

        early_pred = {}
        for g in early_layer_gates:
            early_pred[g] = len(dag2q_pred[g] & early_layer_gates)

        initial_front = frozenset(g for g in early_layer_gates if early_pred[g] == 0)

        init_executed = set()
        cur_front = set(initial_front)
        changed = True
        while changed:
            changed = False
            newly_exec = set()
            for g in cur_front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = m[gq1], m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    newly_exec.add(g)
            if newly_exec:
                changed = True
                init_executed |= newly_exec
                cur_front -= newly_exec
                for g in newly_exec:
                    for s in dag2q_succ[g]:
                        if s in early_layer_gates and s not in init_executed:
                            all_pred_done = True
                            for p in dag2q_pred[s]:
                                if p in early_layer_gates and p not in init_executed:
                                    all_pred_done = False
                                    break
                            if all_pred_done:
                                cur_front.add(s)

        remaining_early = early_layer_gates - init_executed
        if not remaining_early:
            return defaultdict(float), 0

        def compute_front(executed):
            front = set()
            for g in early_layer_gates:
                if g in executed:
                    continue
                all_pred = True
                for p in dag2q_pred[g]:
                    if p in early_layer_gates and p not in executed:
                        all_pred = False
                        break
                if all_pred:
                    front.add(g)
            return frozenset(front)

        init_exec_frozen = frozenset(init_executed)
        init_front_astar = compute_front(init_executed)

        active_logical = set()
        for g in remaining_early:
            gq1, gq2 = gates_2q[g]
            active_logical.add(gq1)
            active_logical.add(gq2)

        def h_func(mapping, front_gates):
            h = 0
            for g in front_gates:
                gq1, gq2 = gates_2q[g]
                h += dist[mapping[gq1]][mapping[gq2]]
            return h

        active_logical_list = sorted(active_logical)

        def mapping_key(mapping):
            return tuple(mapping[lq] for lq in active_logical_list)

        init_m = list(m)
        init_h = h_func(init_m, init_front_astar)

        counter = [0]
        start_state = (init_h, 0, 0, init_m, init_exec_frozen, init_front_astar)
        open_heap = [start_state]
        visited = {}
        best_known_total = float('inf')
        best_result = None

        swap_history = {}
        init_key = (mapping_key(init_m), init_exec_frozen)
        swap_history[init_key] = defaultdict(float)

        expansions = 0

        while open_heap and expansions < ASTAR_NODE_LIMIT:
            f, _, g_cost, cur_m_list, executed, front = heapq.heappop(open_heap)

            mk = mapping_key(cur_m_list)
            state_key = (mk, executed)

            if state_key in visited and visited[state_key] <= g_cost:
                continue
            visited[state_key] = g_cost

            if best_known_total < float('inf') and f > best_known_total * 1.2:
                continue

            new_executed = set(executed)
            new_front = set(front)
            progress = True
            while progress:
                progress = False
                newly_exec = set()
                for g in list(new_front):
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = cur_m_list[gq1], cur_m_list[gq2]
                    if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                        newly_exec.add(g)
                if newly_exec:
                    progress = True
                    new_executed |= newly_exec
                    new_front -= newly_exec
                    for g in newly_exec:
                        for s in dag2q_succ[g]:
                            if s in early_layer_gates and s not in new_executed:
                                all_pred = True
                                for p in dag2q_pred[s]:
                                    if p in early_layer_gates and p not in new_executed:
                                        all_pred = False
                                        break
                                if all_pred:
                                    new_front.add(s)

            new_exec_frozen = frozenset(new_executed)
            new_front_frozen = frozenset(new_front)

            if not (early_layer_gates - new_executed):
                if g_cost < best_known_total:
                    best_known_total = g_cost
                    parent_key = (mk, executed)
                    pair_swaps = dict(swap_history.get(parent_key, {}))
                    best_result = (g_cost, pair_swaps)
                continue

            if not new_front_frozen:
                continue

            active_phys = set()
            for g in new_front_frozen:
                gq1, gq2 = gates_2q[g]
                active_phys.add(cur_m_list[gq1])
                active_phys.add(cur_m_list[gq2])
            ext_gates = set()
            for g in new_front_frozen:
                for s in dag2q_succ[g]:
                    if s in early_layer_gates and s not in new_executed:
                        ext_gates.add(s)
            for g in ext_gates:
                gq1, gq2 = gates_2q[g]
                active_phys.add(cur_m_list[gq1])
                active_phys.add(cur_m_list[gq2])

            swaps = set()
            for pq in active_phys:
                for nb in hw_adj.get(pq, set()):
                    swaps.add((min(pq, nb), max(pq, nb)))

            expansions += 1
            parent_pair_swaps = swap_history.get((mk, executed), defaultdict(float))

            for (s1, s2) in swaps:
                new_m = list(cur_m_list)
                lq_at_s1 = -1
                lq_at_s2 = -1
                for lq in range(num_q):
                    if new_m[lq] == s1:
                        lq_at_s1 = lq
                    if new_m[lq] == s2:
                        lq_at_s2 = lq

                if lq_at_s1 >= 0:
                    new_m[lq_at_s1] = s2
                if lq_at_s2 >= 0:
                    new_m[lq_at_s2] = s1

                new_g = g_cost + 1
                new_mk = mapping_key(new_m)
                child_key = (new_mk, new_exec_frozen)

                if child_key in visited and visited[child_key] <= new_g:
                    continue

                new_h = h_func(new_m, new_front_frozen)
                new_f = new_g + new_h

                if best_known_total < float('inf') and new_f > best_known_total * 1.2:
                    continue

                counter[0] += 1

                child_pair_swaps = defaultdict(float, parent_pair_swaps)
                for g in new_front_frozen:
                    gq1, gq2 = gates_2q[g]
                    pair_key = (min(gq1, gq2), max(gq1, gq2))
                    child_pair_swaps[pair_key] += 1.0

                swap_history[child_key] = child_pair_swaps

                heapq.heappush(open_heap, (new_f, counter[0], new_g, new_m, new_exec_frozen, new_front_frozen))

        if best_result is not None:
            return defaultdict(float, best_result[1]), best_result[0]
        else:
            return defaultdict(float), 0

    # ---------------------------------------------------------------
    # Step 7: Forward greedy routing simulation
    # ---------------------------------------------------------------
    def simulate_routing_greedy(m, rm, max_layers=20):
        sim_m = list(m)
        sim_rm = list(rm)
        swap_counts = defaultdict(float)
        total_swaps = 0

        if not gates_2q:
            return swap_counts, total_swaps

        pred_remaining = {g: len(dag2q_pred[g]) for g in gates_2q}
        front = set(g for g in gates_2q if pred_remaining[g] == 0)
        layers_done = 0

        while front and layers_done < max_layers:
            executable = []
            for g in front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = sim_m[gq1], sim_m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    executable.append(g)

            if executable:
                for g in executable:
                    front.discard(g)
                    for s in dag2q_succ[g]:
                        pred_remaining[s] -= 1
                        if pred_remaining[s] == 0:
                            front.add(s)
                layers_done += 1
                continue

            active_phys = set()
            for g in front:
                gq1, gq2 = gates_2q[g]
                active_phys.add(sim_m[gq1])
                active_phys.add(sim_m[gq2])

            candidates_sw = set()
            for pq in active_phys:
                for nb in self.backend.get(pq, []):
                    candidates_sw.add((min(pq, nb), max(pq, nb)))

            best_swap, best_score = None, float('inf')
            for (s1, s2) in candidates_sw:
                l1, l2 = sim_rm[s1], sim_rm[s2]
                score = 0.0
                for g in front:
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = sim_m[gq1], sim_m[gq2]
                    if gq1 == l1: p1 = s2
                    elif gq1 == l2: p1 = s1
                    if gq2 == l1: p2 = s2
                    elif gq2 == l2: p2 = s1
                    deps = dep_count.get(g, 0) + 1
                    score += deps * dist[p1][p2]
                if score < best_score:
                    best_score = score
                    best_swap = (s1, s2)

            if best_swap is None:
                break

            s1, s2 = best_swap
            l1, l2 = sim_rm[s1], sim_rm[s2]
            sim_m[l1], sim_m[l2] = s2, s1
            sim_rm[s1], sim_rm[s2] = l2, l1
            total_swaps += 1

            for g in front:
                gq1, gq2 = gates_2q[g]
                pair_key = (min(gq1, gq2), max(gq1, gq2))
                swap_counts[pair_key] += 1.0

        return swap_counts, total_swaps

    # ---------------------------------------------------------------
    # Step 7b: Backward greedy routing simulation
    # ---------------------------------------------------------------
    def simulate_routing_backward(m, rm, max_layers=20):
        sim_m = list(m)
        sim_rm = list(rm)
        swap_counts = defaultdict(float)
        total_swaps = 0

        if not gates_2q:
            return swap_counts, total_swaps

        succ_remaining = {g: len(dag2q_succ[g] & set(gates_2q.keys())) for g in gates_2q}
        front = set(g for g in gates_2q if succ_remaining[g] == 0)
        layers_done = 0

        while front and layers_done < max_layers:
            executable = []
            for g in front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = sim_m[gq1], sim_m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    executable.append(g)

            if executable:
                for g in executable:
                    front.discard(g)
                    for p in dag2q_pred[g]:
                        if p in gates_2q:
                            succ_remaining[p] -= 1
                            if succ_remaining[p] == 0:
                                front.add(p)
                layers_done += 1
                continue

            active_phys = set()
            for g in front:
                gq1, gq2 = gates_2q[g]
                active_phys.add(sim_m[gq1])
                active_phys.add(sim_m[gq2])

            candidates_sw = set()
            for pq in active_phys:
                for nb in self.backend.get(pq, []):
                    candidates_sw.add((min(pq, nb), max(pq, nb)))

            best_swap, best_score = None, float('inf')
            for (s1, s2) in candidates_sw:
                l1, l2 = sim_rm[s1], sim_rm[s2]
                score = 0.0
                for g in front:
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = sim_m[gq1], sim_m[gq2]
                    if gq1 == l1: p1 = s2
                    elif gq1 == l2: p1 = s1
                    if gq2 == l1: p2 = s2
                    elif gq2 == l2: p2 = s1
                    deps = bwd_dep.get(g, 0) + 1
                    score += deps * dist[p1][p2]
                if score < best_score:
                    best_score = score
                    best_swap = (s1, s2)

            if best_swap is None:
                break

            s1, s2 = best_swap
            l1, l2 = sim_rm[s1], sim_rm[s2]
            sim_m[l1], sim_m[l2] = s2, s1
            sim_rm[s1], sim_rm[s2] = l2, l1
            total_swaps += 1

            for g in front:
                gq1, gq2 = gates_2q[g]
                pair_key = (min(gq1, gq2), max(gq1, gq2))
                swap_counts[pair_key] += 1.0

        return swap_counts, total_swaps

    # ---------------------------------------------------------------
    # Step 7c: Asymmetric bidirectional routing (forward-biased 0.6/0.4)
    # ---------------------------------------------------------------
    def simulate_routing_asymmetric_bidir(m, rm, max_layers=20):
        fwd_swaps, fwd_total = simulate_routing_greedy(m, rm, max_layers=max_layers)
        bwd_swaps, bwd_total = simulate_routing_backward(m, rm, max_layers=max_layers)

        combined = defaultdict(float)
        all_keys = set(fwd_swaps.keys()) | set(bwd_swaps.keys())
        for key in all_keys:
            combined[key] = 0.6 * fwd_swaps.get(key, 0.0) + 0.4 * bwd_swaps.get(key, 0.0)

        return combined, (fwd_total + bwd_total) // 2

    # ---------------------------------------------------------------
    # Step 7d: Hybrid A* + greedy routing
    # ---------------------------------------------------------------
    def simulate_routing_hybrid(m, rm, max_layers=20):
        astar_swaps, astar_total = astar_routing_early(m, rm)
        greedy_swaps, greedy_total = simulate_routing_greedy(m, rm, max_layers=max_layers)

        combined_swaps = defaultdict(float)
        early_pairs = set()
        for g in early_layer_gates:
            gq1, gq2 = gates_2q[g]
            early_pairs.add((min(gq1, gq2), max(gq1, gq2)))

        for pair_key in early_pairs:
            if pair_key in astar_swaps:
                combined_swaps[pair_key] = astar_swaps[pair_key]

        for pair_key, count in greedy_swaps.items():
            if pair_key not in early_pairs:
                combined_swaps[pair_key] = count

        return combined_swaps, astar_total + greedy_total

    # ---------------------------------------------------------------
    # Step 7e: Hybrid A* + asymmetric bidirectional
    # ---------------------------------------------------------------
    def simulate_routing_hybrid_bidir(m, rm, max_layers=20):
        astar_swaps, astar_total = astar_routing_early(m, rm)
        fwd_swaps, fwd_total = simulate_routing_greedy(m, rm, max_layers=max_layers)
        bwd_swaps, bwd_total = simulate_routing_backward(m, rm, max_layers=max_layers)

        combined_swaps = defaultdict(float)
        early_pairs = set()
        for g in early_layer_gates:
            gq1, gq2 = gates_2q[g]
            early_pairs.add((min(gq1, gq2), max(gq1, gq2)))

        for pair_key in early_pairs:
            if pair_key in astar_swaps:
                combined_swaps[pair_key] = astar_swaps[pair_key]

        all_late_keys = (set(fwd_swaps.keys()) | set(bwd_swaps.keys())) - early_pairs
        for pair_key in all_late_keys:
            combined_swaps[pair_key] = 0.6 * fwd_swaps.get(pair_key, 0.0) + 0.4 * bwd_swaps.get(pair_key, 0.0)

        return combined_swaps, astar_total + (fwd_total + bwd_total) // 2

    # ---------------------------------------------------------------
    # Step 8: Seed generation setup
    # ---------------------------------------------------------------
    sorted_by_degree = sorted(interacting_logical, key=lambda q: logical_degree[q], reverse=True)
    seed_lqs = sorted_by_degree[:min(3, len(sorted_by_degree))]
    phys_by_centrality = sorted(physical_qubits, key=lambda pq: phys_centrality[pq])
    seed_pqs = phys_by_centrality[:min(3, len(phys_by_centrality))]

    logical_degree_ranked = sorted(interacting_logical, key=lambda q: logical_degree[q], reverse=True)
    logical_degree_rank = {q: i for i, q in enumerate(logical_degree_ranked)}
    max_logical_rank = max(len(logical_degree_ranked) - 1, 1)
    phys_degree_ranked = sorted(physical_qubits, key=lambda pq: phys_degree[pq], reverse=True)
    phys_degree_rank = {pq: i for i, pq in enumerate(phys_degree_ranked)}
    max_phys_rank = max(len(phys_degree_ranked) - 1, 1)

    static_nbrs, static_deg = build_neighbors(static_weight)
    max_iw = max(static_weight.values()) if static_weight else 1.0

    # ---------------------------------------------------------------
    # Step 9: Routing-Pressure-Aware Conflict-Graph MIS Seed
    # ---------------------------------------------------------------
    def conflict_graph_seed(start_pq, nbrs, deg, weights, routing_pressure=None):
        if len(interacting_logical) < 2:
            return None, None

        cur_max_iw = max(weights.values()) if weights else 1.0

        top_partners = {}
        for lq in interacting_logical:
            nbr_list = sorted(nbrs.get(lq, {}).items(), key=lambda x: x[1], reverse=True)
            top_partners[lq] = set(p for p, _ in nbr_list[:3])

        conflict_adj = defaultdict(set)
        il = interacting_logical

        qubit_pressure = defaultdict(float)
        if routing_pressure:
            for (q1, q2), cnt in routing_pressure.items():
                qubit_pressure[q1] += cnt
                qubit_pressure[q2] += cnt

        for i in range(len(il)):
            for j in range(i + 1, len(il)):
                l1, l2 = il[i], il[j]
                s1 = top_partners.get(l1, set())
                s2 = top_partners.get(l2, set())
                if not s1 and not s2:
                    continue
                intersection = len(s1 & s2)
                union = len(s1 | s2)
                if union > 0:
                    jaccard = intersection / union
                    threshold = 0.5
                    if routing_pressure and qubit_pressure[l1] > 0 and qubit_pressure[l2] > 0:
                        max_pressure = max(qubit_pressure.values()) if qubit_pressure else 1.0
                        pressure_factor = min(1.0, (qubit_pressure[l1] + qubit_pressure[l2]) /
                                              (max_pressure * 2 + 1e-10))
                        threshold = max(0.25, 0.5 - 0.25 * pressure_factor)
                    if jaccard > threshold:
                        conflict_adj[l1].add(l2)
                        conflict_adj[l2].add(l1)

        sorted_by_deg_local = sorted(interacting_logical,
                                     key=lambda q: (deg.get(q, 0), qubit_pressure.get(q, 0)),
                                     reverse=True)
        mis = set()
        excluded = set()
        for lq in sorted_by_deg_local:
            if lq not in excluded:
                mis.add(lq)
                for neighbor in conflict_adj.get(lq, set()):
                    excluded.add(neighbor)

        non_mis = [lq for lq in sorted_by_deg_local if lq not in mis]
        mis_ordered = sorted(mis, key=lambda q: (deg.get(q, 0), qubit_pressure.get(q, 0)),
                             reverse=True)

        m = [-1] * num_q
        rm = [-1] * num_q
        used_phys = set()

        if mis_ordered:
            first_lq = mis_ordered[0]
            m[first_lq] = start_pq
            rm[start_pq] = first_lq
            used_phys.add(start_pq)

            for lq in mis_ordered[1:]:
                nbrs_placed = {}
                for plq in mis:
                    if m[plq] >= 0 and plq in nbrs.get(lq, {}):
                        nbrs_placed[plq] = nbrs[lq][plq]

                if nbrs_placed:
                    best_pq = None
                    best_score = float('inf')
                    for pq in physical_qubits:
                        if pq in used_phys:
                            continue
                        score = 0.0
                        for plq, iw in nbrs_placed.items():
                            d = dist[pq][m[plq]]
                            cost = iw * d
                            if m[plq] in hw_adj[pq]:
                                cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                            score += cost
                        if score < best_score:
                            best_score = score
                            best_pq = pq
                else:
                    best_pq = None
                    best_score = float('inf')
                    for pq in physical_qubits:
                        if pq not in used_phys:
                            if phys_centrality[pq] < best_score:
                                best_score = phys_centrality[pq]
                                best_pq = pq

                if best_pq is not None:
                    m[lq] = best_pq
                    rm[best_pq] = lq
                    used_phys.add(best_pq)

        placed_set = set(lq for lq in interacting_logical if m[lq] >= 0)

        for lq in non_mis:
            nbrs_placed = {}
            for plq in placed_set:
                w = nbrs.get(lq, {}).get(plq, 0.0)
                if w > 0:
                    nbrs_placed[plq] = w

            if nbrs_placed:
                near_ties = []
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq in used_phys:
                        continue
                    score = 0.0
                    for plq, iw in nbrs_placed.items():
                        d = dist[pq][m[plq]]
                        cost = iw * d
                        if m[plq] in hw_adj[pq]:
                            cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                        score += cost
                    near_ties.append((score, pq))
                    if score < best_score:
                        best_score = score

                if near_ties and best_score > 0:
                    threshold = best_score * 1.05
                    candidates_list = [(s, pq) for s, pq in near_ties if s <= threshold]
                    if len(candidates_list) > 1 and lq in logical_degree_rank:
                        lq_rn = logical_degree_rank[lq] / max_logical_rank
                        best_pq = min(candidates_list, key=lambda x: (
                            abs(phys_degree_rank[x[1]] / max_phys_rank - lq_rn), x[0]))[1]
                    else:
                        best_pq = min(candidates_list, key=lambda x: x[0])[1]
                elif near_ties:
                    best_pq = min(near_ties, key=lambda x: x[0])[1]
                else:
                    best_pq = None
            else:
                best_pq = None
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq not in used_phys:
                        if phys_centrality[pq] < best_score:
                            best_score = phys_centrality[pq]
                            best_pq = pq

            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                used_phys.add(best_pq)
                placed_set.add(lq)

        remaining_lqs = [lq for lq in logical_qubits if m[lq] == -1]
        for lq in remaining_lqs:
            best_pq = None
            best_score = float('inf')
            for pq in physical_qubits:
                if pq not in used_phys:
                    if phys_centrality[pq] < best_score:
                        best_score = phys_centrality[pq]
                        best_pq = pq
            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                used_phys.add(best_pq)

        return m, rm

    # ---------------------------------------------------------------
    # Step 10: Spectral ordering seed
    # ---------------------------------------------------------------
    def spectral_seed():
        if len(interacting_logical) < 3:
            return None, None

        idx_map = {q: i for i, q in enumerate(interacting_logical)}
        n = len(interacting_logical)

        L = [[0.0] * n for _ in range(n)]
        for (q1, q2), w in static_weight.items():
            if q1 in idx_map and q2 in idx_map:
                i, j = idx_map[q1], idx_map[q2]
                L[i][j] -= w
                L[j][i] -= w
                L[i][i] += w
                L[j][j] += w

        def power_iter(mat, n_iter=200):
            v = [random.gauss(0, 1) for _ in range(n)]
            for _ in range(n_iter):
                new_v = [0.0] * n
                for i in range(n):
                    for j in range(n):
                        new_v[i] += mat[i][j] * v[j]
                norm = math.sqrt(sum(x * x for x in new_v)) or 1e-12
                v = [x / norm for x in new_v]
            return v

        max_diag = max(L[i][i] for i in range(n)) + 1.0
        shifted = [[0.0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                shifted[i][j] = -L[i][j]
            shifted[i][i] += max_diag

        v1 = power_iter(shifted, 150)

        dot_v1 = sum(x * x for x in v1) or 1e-12
        lam1_shifted = sum(v1[i] * sum(shifted[i][j] * v1[j] for j in range(n)) for i in range(n)) / dot_v1
        shifted2 = [row[:] for row in shifted]
        for i in range(n):
            for j in range(n):
                shifted2[i][j] -= lam1_shifted * v1[i] * v1[j] / dot_v1

        fiedler = power_iter(shifted2, 200)

        fiedler_order = sorted(range(n), key=lambda i: fiedler[i])
        sorted_logical = [interacting_logical[i] for i in fiedler_order]

        phys_sorted = sorted(physical_qubits, key=lambda pq: phys_centrality[pq])
        start_pq = phys_sorted[0]
        visited_bfs = set()
        bfs_order = []
        bfs_q = deque([start_pq])
        visited_bfs.add(start_pq)
        while bfs_q:
            pq = bfs_q.popleft()
            bfs_order.append(pq)
            for nb in sorted(hw_adj[pq]):
                if nb not in visited_bfs:
                    visited_bfs.add(nb)
                    bfs_q.append(nb)
        for pq in physical_qubits:
            if pq not in visited_bfs:
                bfs_order.append(pq)
                visited_bfs.add(pq)

        m = [-1] * num_q
        rm = [-1] * num_q
        n_interact = len(sorted_logical)
        n_phys = len(bfs_order)
        offset = max(0, (n_phys - n_interact) // 2)
        for i, lq in enumerate(sorted_logical):
            pq = bfs_order[min(offset + i, n_phys - 1)]
            if rm[pq] != -1:
                best_pq = None
                best_d = float('inf')
                for cpq in physical_qubits:
                    if rm[cpq] == -1:
                        d = dist[pq][cpq]
                        if d < best_d:
                            best_d = d
                            best_pq = cpq
                pq = best_pq
            m[lq] = pq
            rm[pq] = lq

        return m, rm

    # ---------------------------------------------------------------
    # Step 11: Greedy placement
    # ---------------------------------------------------------------
    def run_greedy_placement(start_lq, start_pq, nbrs, deg, weights=None):
        cur_max_iw = max(weights.values()) if weights else max_iw
        used_phys = {start_pq}
        m = [-1] * num_q
        rm = [-1] * num_q
        m[start_lq] = start_pq
        rm[start_pq] = start_lq
        placed = {start_lq}
        remaining = set(logical_qubits) - placed

        while remaining:
            best_lq, best_w = None, -1.0
            for lq in remaining:
                w = sum(nbrs.get(lq, {}).get(plq, 0.0) for plq in placed)
                if w > best_w:
                    best_w = w
                    best_lq = lq

            nbrs_placed = {plq: nbrs.get(best_lq, {}).get(plq, 0.0)
                           for plq in placed if plq in nbrs.get(best_lq, {})}

            if nbrs_placed:
                near_ties = []
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq in used_phys:
                        continue
                    score = 0.0
                    for plq, iw in nbrs_placed.items():
                        d = dist[pq][m[plq]]
                        cost = iw * d
                        if m[plq] in hw_adj[pq]:
                            cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                        score += cost
                    near_ties.append((score, pq))
                    if score < best_score:
                        best_score = score

                if near_ties and best_score > 0:
                    threshold = best_score * 1.05
                    candidates_list = [(s, pq) for s, pq in near_ties if s <= threshold]
                    if len(candidates_list) > 1 and best_lq in logical_degree_rank:
                        lq_rn = logical_degree_rank[best_lq] / max_logical_rank
                        best_pq = min(candidates_list, key=lambda x: (
                            abs(phys_degree_rank[x[1]] / max_phys_rank - lq_rn), x[0]))[1]
                    else:
                        best_pq = min(candidates_list, key=lambda x: x[0])[1]
                elif near_ties:
                    best_pq = min(near_ties, key=lambda x: x[0])[1]
                else:
                    best_pq = None
            else:
                best_pq = None
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq not in used_phys:
                        score = phys_centrality[pq]
                        if score < best_score:
                            best_score = score
                            best_pq = pq

            m[best_lq] = best_pq
            rm[best_pq] = best_lq
            used_phys.add(best_pq)
            placed.add(best_lq)
            remaining.discard(best_lq)
        return m, rm

    def fill_unmapped(m, rm):
        unmapped = [q for q in range(num_q) if m[q] == -1]
        free = [pq for pq in range(num_q) if rm[pq] == -1]
        for lq, pq in zip(unmapped, free):
            m[lq] = pq
            rm[pq] = lq

    # ---------------------------------------------------------------
    # Step 12: Congestion-biased local search with nonlinear distance penalty
    #   Incorporates accumulated routing pressure to bias swap evaluation
    #   toward qubit pairs sharing congested hardware edges
    # ---------------------------------------------------------------
    def local_search(m, rm, nbrs, weights, alpha_exp, max_rounds=5,
                     congestion_bonus=None):
        if len(interacting_logical) <= 1:
            return compute_cost_nonlinear(m, weights, alpha_exp)

        # Build congestion bias for hardware-adjacent swaps
        hw_edge_congestion = defaultdict(float)
        if congestion_bonus:
            for (q1, q2), pressure in congestion_bonus.items():
                pq1, pq2 = m[q1], m[q2]
                # Distribute pressure to hardware edges along shortest path
                hw_edge_congestion[(min(pq1, pq2), max(pq1, pq2))] += pressure

        for _ in range(max_rounds):
            improved = False
            best_d, best_pair = 0.0, None
            active_phys = [m[q] for q in interacting_logical]

            # Hardware-adjacent swaps with congestion bonus
            for pq1 in active_phys:
                for pq2 in hw_adj.get(pq1, set()):
                    d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                    # Congestion bonus: more aggressively explore swaps on congested edges
                    edge_key = (min(pq1, pq2), max(pq1, pq2))
                    if edge_key in hw_edge_congestion and d < 0:
                        d *= (1.0 + 0.15 * min(1.0, hw_edge_congestion[edge_key]))
                    if d < best_d:
                        best_d = d
                        best_pair = (pq1, pq2)

            n_random = min(150, len(interacting_logical) * 3)
            for _ in range(n_random):
                i, j = random.sample(range(len(interacting_logical)), 2)
                pq1, pq2 = m[interacting_logical[i]], m[interacting_logical[j]]
                d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                if d < best_d:
                    best_d = d
                    best_pair = (pq1, pq2)

            if best_pair and best_d < -1e-12:
                do_swap(m, rm, *best_pair)
                improved = True
            if not improved:
                for i in range(len(interacting_logical)):
                    for j in range(i + 1, len(interacting_logical)):
                        pq1, pq2 = m[interacting_logical[i]], m[interacting_logical[j]]
                        d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                        if d < best_d:
                            best_d = d
                            best_pair = (pq1, pq2)
                if best_pair and best_d < -1e-12:
                    do_swap(m, rm, *best_pair)
                else:
                    break
        return compute_cost_nonlinear(m, weights, alpha_exp)

    # ---------------------------------------------------------------
    # Step 13: Perturbation modes with bandit selection
    #   LNS uses accumulated routing pressure to bias destruction
    # ---------------------------------------------------------------
    rsdiwr_iter_ref = [0]
    accumulated_routing_pressure_ref = [defaultdict(float)]

    def perturb_random(m, rm, **kw):
        if len(interacting_logical) >= 2:
            lqs = random.sample(interacting_logical, 2)
            do_swap(m, rm, m[lqs[0]], m[lqs[1]])

    def perturb_segment_shuffle(m, rm, **kw):
        k = min(random.randint(3, 5), len(interacting_logical))
        if k < 2:
            perturb_random(m, rm)
            return
        lqs = random.sample(interacting_logical, k)
        phys_positions = [m[lq] for lq in lqs]
        random.shuffle(phys_positions)
        for lq in lqs:
            rm[m[lq]] = -1
        for lq, pq in zip(lqs, phys_positions):
            m[lq] = pq
            rm[pq] = lq

    def perturb_worst_pair(m, rm, weights=None, alpha_exp=1.5, **kw):
        if weights is None:
            perturb_random(m, rm)
            return
        pair_costs = []
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                d = dist[m[q1]][m[q2]]
                c = w * (d ** alpha_exp)
                pair_costs.append((c, q1, q2))
        if not pair_costs:
            return
        pair_costs.sort(reverse=True)
        top_n = min(3, len(pair_costs))
        _, tq1, tq2 = pair_costs[random.randint(0, top_n - 1)]
        pq1, pq2 = m[tq1], m[tq2]
        adj_of_pq2 = list(hw_adj.get(pq2, set()))
        if adj_of_pq2:
            target = random.choice(adj_of_pq2)
            if target != pq1:
                do_swap(m, rm, pq1, target)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    def perturb_edge_targeted(m, rm, weights=None, alpha_exp=1.5, **kw):
        if weights is None:
            perturb_random(m, rm)
            return
        edge_costs = []
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                c = w * (dist[m[q1]][m[q2]] ** alpha_exp)
                edge_costs.append((c, q1, q2))
        if not edge_costs:
            return
        edge_costs.sort(reverse=True)
        top_n = min(5, len(edge_costs))
        _, eq1, eq2 = edge_costs[random.randint(0, top_n - 1)]
        pq1, pq2 = m[eq1], m[eq2]
        neighbors_of_pq2 = list(hw_adj.get(pq2, set()))
        if neighbors_of_pq2:
            target = random.choice(neighbors_of_pq2)
            if target != pq1:
                do_swap(m, rm, pq1, target)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    def perturb_lns(m, rm, nbrs=None, alpha_exp=1.5, **kw):
        """Pressure-guided LNS: blends current cost with accumulated
        routing pressure to select which qubits to destroy."""
        if nbrs is None or len(interacting_logical) < 3:
            perturb_random(m, rm)
            return
        base_lo = 3 + rsdiwr_iter_ref[0]
        base_hi = 8 + rsdiwr_iter_ref[0] * 2
        k = min(random.randint(base_lo, base_hi), len(interacting_logical))

        acc_pressure = accumulated_routing_pressure_ref[0]
        qubit_acc_pressure = defaultdict(float)
        for (q1, q2), cnt in acc_pressure.items():
            qubit_acc_pressure[q1] += cnt
            qubit_acc_pressure[q2] += cnt
        max_acc = max(qubit_acc_pressure.values()) if qubit_acc_pressure else 1.0

        qcost = {}
        for lq in interacting_logical:
            c = 0.0
            for partner, w in nbrs.get(lq, {}).items():
                if m[partner] >= 0 and m[lq] >= 0:
                    c += w * (dist[m[lq]][m[partner]] ** alpha_exp)
            pressure_bonus = qubit_acc_pressure.get(lq, 0.0) / (max_acc + 1e-10)
            qcost[lq] = c * (1.0 + 0.5 * pressure_bonus)

        sorted_qs = sorted(qcost, key=lambda q: qcost[q], reverse=True)
        top_half = sorted_qs[:max(k, len(sorted_qs) // 2)]
        subset = random.sample(top_half, min(k, len(top_half)))

        freed_phys = []
        for lq in subset:
            freed_phys.append(m[lq])
            rm[m[lq]] = -1
            m[lq] = -1

        placed_set = set(lq for lq in interacting_logical if m[lq] >= 0)
        for lq in sorted(subset, key=lambda q: qcost[q], reverse=True):
            best_pq, best_sc = None, float('inf')
            for pq in freed_phys:
                if rm[pq] != -1:
                    continue
                sc = 0.0
                for partner, w in nbrs.get(lq, {}).items():
                    if partner in placed_set and m[partner] >= 0:
                        sc += w * (dist[pq][m[partner]] ** alpha_exp)
                if sc < best_sc:
                    best_sc = sc
                    best_pq = pq
            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                placed_set.add(lq)
            else:
                for pq in freed_phys:
                    if rm[pq] == -1:
                        m[lq] = pq
                        rm[pq] = lq
                        placed_set.add(lq)
                        break

    # Congestion-directed perturbation: swap qubits on the most congested
    # hardware edge according to accumulated routing pressure
    def perturb_congestion_directed(m, rm, **kw):
        acc_pressure = accumulated_routing_pressure_ref[0]
        if not acc_pressure or len(interacting_logical) < 2:
            perturb_random(m, rm)
            return

        # Find the pair with highest accumulated pressure
        sorted_pairs = sorted(acc_pressure.items(), key=lambda x: x[1], reverse=True)
        top_n = min(4, len(sorted_pairs))
        (q1, q2), _ = sorted_pairs[random.randint(0, top_n - 1)]

        pq1, pq2 = m[q1], m[q2]
        # Move q1 toward q2 along hardware graph
        adj_of_pq2 = list(hw_adj.get(pq2, set()))
        if adj_of_pq2:
            # Pick neighbor of pq2 closest to pq1
            best_nb = min(adj_of_pq2, key=lambda nb: dist[pq1][nb])
            if best_nb != pq1:
                do_swap(m, rm, pq1, best_nb)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    perturbation_modes = [perturb_random, perturb_segment_shuffle,
                          perturb_worst_pair, perturb_edge_targeted,
                          perturb_lns, perturb_congestion_directed]
    K = len(perturbation_modes)

    WINDOW_SIZE = 100
    EPSILON = 0.1
    window = []
    mode_successes = [0] * K
    mode_attempts = [0] * K

    def select_perturbation_mode(phase_exploratory=True):
        if random.random() < EPSILON or sum(mode_attempts) < K * 2:
            return random.randint(0, K - 1)

        rates = []
        for k in range(K):
            if mode_attempts[k] > 0:
                rates.append(mode_successes[k] / mode_attempts[k])
            else:
                rates.append(1.0)

        # Dual-phase bias: exploratory phase boosts LNS/segment/congestion,
        # exploitative phase boosts edge-targeted/worst-pair
        if phase_exploratory:
            # Boost exploratory perturbations (indices 1=segment, 4=lns, 5=congestion)
            for idx in [1, 4, 5]:
                rates[idx] *= 1.3
        else:
            # Boost exploitative perturbations (indices 2=worst_pair, 3=edge_targeted)
            for idx in [2, 3]:
                rates[idx] *= 1.3

        total = sum(rates)
        if total < 1e-12:
            return random.randint(0, K - 1)
        r = random.random() * total
        cumul = 0.0
        for k in range(K):
            cumul += rates[k]
            if r <= cumul:
                return k
        return K - 1

    def update_window(mode_idx, success):
        window.append((mode_idx, success))
        mode_attempts[mode_idx] += 1
        if success:
            mode_successes[mode_idx] += 1
        if len(window) > WINDOW_SIZE:
            old_mode, old_success = window.pop(0)
            mode_attempts[old_mode] -= 1
            if old_success:
                mode_successes[old_mode] -= 1

    # ---------------------------------------------------------------
    # Step 14: Build initial mapping candidates
    # ---------------------------------------------------------------
    candidates = []

    for s_lq in seed_lqs:
        for s_pq in seed_pqs:
            m, rm = run_greedy_placement(s_lq, s_pq, static_nbrs, static_deg,
                                         weights=static_weight)
            fill_unmapped(m, rm)
            cost = compute_cost(m, static_weight)
            candidates.append((cost, m, rm))

    for s_pq in seed_pqs:
        cg_m, cg_rm = conflict_graph_seed(s_pq, static_nbrs, static_deg, static_weight)
        if cg_m is not None:
            fill_unmapped(cg_m, cg_rm)
            cost = compute_cost(cg_m, static_weight)
            candidates.append((cost, cg_m, cg_rm))

    spec_m, spec_rm = spectral_seed()
    if spec_m is not None:
        fill_unmapped(spec_m, spec_rm)
        spec_cost = compute_cost(spec_m, static_weight)
        candidates.append((spec_cost, spec_m, spec_rm))

    m_rand = [-1] * num_q
    rm_rand = [-1] * num_q
    shuffled_phys = list(physical_qubits)
    random.shuffle(shuffled_phys)
    for i, lq in enumerate(logical_qubits):
        m_rand[lq] = shuffled_phys[i]
        rm_rand[shuffled_phys[i]] = lq
    fill_unmapped(m_rand, rm_rand)
    c = compute_cost(m_rand, static_weight)
    candidates.append((c, m_rand, rm_rand))

    if not candidates:
        self.mapping_dict = list(range(num_q))
        self.reverse_mapping_dict = list(range(num_q))
        if self.use_isl:
            self.isl_mapping = dict_to_isl_map(self.mapping_dict)
        return

    candidates.sort(key=lambda x: x[0])

    _, best_m, best_rm = candidates[0]
    best_m, best_rm = list(best_m), list(best_rm)
    local_search(best_m, best_rm, static_nbrs, static_weight, alpha_exp=2.0, max_rounds=6)
    best_cost = compute_cost(best_m, static_weight)

    for idx in range(1, min(5, len(candidates))):
        _, m_c, rm_c = candidates[idx]
        m_c, rm_c = list(m_c), list(rm_c)
        local_search(m_c, rm_c, static_nbrs, static_weight, alpha_exp=2.0, max_rounds=4)
        c = compute_cost(m_c, static_weight)
        if c < best_cost:
            best_cost = c
            best_m = list(m_c)
            best_rm = list(rm_c)

    # ---------------------------------------------------------------
    # Step 15: RSDIWR + Dual-Phase ILS with A*-guided first iteration,
    #   asymmetric bidirectional routing, pressure-adaptive blending,
    #   routing-pressure MIS reseeding, pressure-guided LNS,
    #   congestion-biased local search, and congestion-directed perturbation
    # ---------------------------------------------------------------
    time_budget = 25.0
    t_start = _time()
    n_rsdiwr = 4

    cur_m = list(best_m)
    cur_rm = list(best_rm)
    swap_counts = defaultdict(float)
    accumulated_routing_pressure = defaultdict(float)
    accumulated_routing_pressure_ref[0] = accumulated_routing_pressure

    for rsdiwr_iter in range(n_rsdiwr):
        rsdiwr_iter_ref[0] = rsdiwr_iter
        elapsed = _time() - t_start
        if elapsed > time_budget:
            break

        remaining_time = time_budget - elapsed
        remaining_iters = n_rsdiwr - rsdiwr_iter
        time_for_this_iter = remaining_time / max(remaining_iters, 1)
        n_ils = max(55, int(num_q * time_for_this_iter / 0.5)) if time_for_this_iter > 1.0 else max(30, num_q // 3)

        # Pressure-adaptive blending
        if rsdiwr_iter == 0 or not swap_counts:
            eff_weights = dict(static_weight)
        else:
            max_sw = max(swap_counts.values()) if swap_counts else 1.0
            scale = max(static_weight.values()) / max(max_sw, 1e-10)

            total_pressure = sum(accumulated_routing_pressure.values())
            n_pairs = len(accumulated_routing_pressure)
            avg_pressure = total_pressure / max(n_pairs, 1)
            pressure_adapt = min(0.15, 0.05 * avg_pressure / max(max_sw, 1e-10))
            alpha_blend = max(0.25, 1.0 - 0.3 * rsdiwr_iter - pressure_adapt)

            eff_weights = defaultdict(float)
            all_keys = set(static_weight.keys()) | set(swap_counts.keys())
            for key in all_keys:
                w_s = static_weight.get(key, 0.0)
                w_r = swap_counts.get(key, 0.0) * scale
                eff_weights[key] = alpha_blend * w_s + (1.0 - alpha_blend) * w_r

        eff_nbrs, eff_deg = build_neighbors(eff_weights)

        # Congestion bonus for local search (normalized accumulated pressure)
        congestion_bonus = None
        if accumulated_routing_pressure:
            max_acc_p = max(accumulated_routing_pressure.values()) if accumulated_routing_pressure else 1.0
            congestion_bonus = {k: v / (max_acc_p + 1e-10) for k, v in accumulated_routing_pressure.items()}

        # Re-seed with routing-informed weights + routing-pressure MIS
        if rsdiwr_iter > 0 and swap_counts and (_time() - t_start) < time_budget * 0.7:
            eff_sorted = sorted(interacting_logical,
                                key=lambda q: eff_deg.get(q, 0), reverse=True)
            reseed_lqs = eff_sorted[:min(2, len(eff_sorted))]
            reseed_pqs = seed_pqs[:min(2, len(seed_pqs))]

            for s_lq in reseed_lqs:
                for s_pq in reseed_pqs:
                    rm_new, rmm_new = run_greedy_placement(
                        s_lq, s_pq, eff_nbrs, eff_deg, weights=eff_weights)
                    fill_unmapped(rm_new, rmm_new)
                    local_search(rm_new, rmm_new, eff_nbrs, eff_weights,
                                 alpha_exp=2.0, max_rounds=3,
                                 congestion_bonus=congestion_bonus)
                    sc = compute_cost(rm_new, static_weight)
                    if sc < best_cost:
                        best_cost = sc
                        best_m = list(rm_new)
                        best_rm = list(rmm_new)
                        cur_m = list(rm_new)
                        cur_rm = list(rmm_new)

            # Routing-pressure-aware MIS reseeding
            for s_pq in reseed_pqs:
                cg_m, cg_rm = conflict_graph_seed(
                    s_pq, eff_nbrs, eff_deg, eff_weights,
                    routing_pressure=accumulated_routing_pressure)
                if cg_m is not None:
                    fill_unmapped(cg_m, cg_rm)
                    local_search(cg_m, cg_rm, eff_nbrs, eff_weights,
                                 alpha_exp=2.0, max_rounds=3,
                                 congestion_bonus=congestion_bonus)
                    sc = compute_cost(cg_m, static_weight)
                    if sc < best_cost:
                        best_cost = sc
                        best_m = list(cg_m)
                        best_rm = list(cg_rm)
                        cur_m = list(cg_m)
                        cur_rm = list(cg_rm)

        alpha_start = 2.0
        alpha_end = 1.0

        ls_rounds = 6 if rsdiwr_iter == 0 else 4
        cur_cost_nl = local_search(cur_m, cur_rm, eff_nbrs, eff_weights,
                                   alpha_exp=alpha_start, max_rounds=ls_rounds,
                                   congestion_bonus=congestion_bonus)

        static_cost = compute_cost(cur_m, static_weight)
        if static_cost < best_cost:
            best_cost = static_cost
            best_m = list(cur_m)
            best_rm = list(cur_rm)

        # Reset bandit window
        window.clear()
        for k in range(K):
            mode_successes[k] = 0
            mode_attempts[k] = 0

        T = max(cur_cost_nl * 0.05, 1.0)
        T_init = T
        alpha_sa = 0.94
        reheat_interval = max(n_ils // 4, 8)

        # Dual-phase ILS: first 60% exploratory, last 40% exploitative
        exploratory_cutoff = int(n_ils * 0.6)

        for ils_iter in range(n_ils):
            if _time() - t_start > time_budget:
                break

            progress = ils_iter / max(n_ils - 1, 1)
            alpha_exp = alpha_start + (alpha_end - alpha_start) * progress

            phase_exploratory = ils_iter < exploratory_cutoff

            saved_m = list(cur_m)
            saved_rm = list(cur_rm)
            saved_cost = cur_cost_nl

            mode = select_perturbation_mode(phase_exploratory=phase_exploratory)
            perturbation_modes[mode](cur_m, cur_rm,
                                    nbrs=eff_nbrs, weights=eff_weights,
                                    alpha_exp=alpha_exp)

            new_cost_nl = local_search(cur_m, cur_rm, eff_nbrs, eff_weights,
                                       alpha_exp=alpha_exp, max_rounds=3,
                                       congestion_bonus=congestion_bonus)

            success = new_cost_nl < saved_cost - 1e-12

            improvement = saved_cost - new_cost_nl
            if improvement > 0:
                cur_cost_nl = new_cost_nl
                sc = compute_cost(cur_m, static_weight)
                if sc < best_cost:
                    best_cost = sc
                    best_m = list(cur_m)
                    best_rm = list(cur_rm)
            elif random.random() < math.exp(min(0, improvement / max(T, 1e-10))):
                cur_cost_nl = new_cost_nl
            else:
                cur_m[:] = saved_m
                cur_rm[:] = saved_rm
                cur_cost_nl = saved_cost

            update_window(mode, success)

            T *= alpha_sa
            if (ils_iter + 1) % reheat_interval == 0:
                T = max(T, T_init * 0.35)

        # Routing simulation for RSDIWR feedback
        if rsdiwr_iter < n_rsdiwr - 1:
            sim_depth = 14 + rsdiwr_iter * 7

            if rsdiwr_iter == 0 and early_layer_gates:
                # First iteration: A*-guided hybrid routing for exact early-layer feedback
                swap_counts, _ = simulate_routing_hybrid(best_m, best_rm, max_layers=sim_depth)
            elif rsdiwr_iter == 1 and early_layer_gates:
                # Second iteration: A* + asymmetric bidirectional for full-spectrum feedback
                swap_counts, _ = simulate_routing_hybrid_bidir(best_m, best_rm, max_layers=sim_depth)
            else:
                # Later iterations: asymmetric bidirectional only (faster)
                swap_counts, _ = simulate_routing_asymmetric_bidir(best_m, best_rm, max_layers=sim_depth)

            # Accumulate routing pressure across iterations
            for pair_key, cnt in swap_counts.items():
                accumulated_routing_pressure[pair_key] += cnt

        cur_m = list(best_m)
        cur_rm = list(best_rm)
        cur_cost_nl = compute_cost_nonlinear(cur_m, eff_weights, alpha_end)

    # ---------------------------------------------------------------
    # Step 16: Set final mapping
    # ---------------------------------------------------------------
    self.mapping_dict = best_m
    self.reverse_mapping_dict = best_rm

    if self.use_isl:
        self.isl_mapping = dict_to_isl_map(self.mapping_dict)

def init_mapping(self):
    import math
    import random
    import heapq
    from collections import defaultdict, deque
    from time import time as _time

    num_q = self.num_qubits
    physical_qubits = sorted(self.backend.keys())
    dist = self.distance_matrix

    # ---------------------------------------------------------------
    # Step 1: Build DAG and topological layers
    # ---------------------------------------------------------------
    all_gates = sorted(self.access.keys())
    two_qubit_gates = [g for g in all_gates if len(self.access[g]) == 2]

    last_gate_on_qubit = {}
    successors_dag = defaultdict(set)
    predecessors_dag = defaultdict(set)
    for g in all_gates:
        for q in self.access[g]:
            if q in last_gate_on_qubit:
                pred = last_gate_on_qubit[q]
                successors_dag[pred].add(g)
                predecessors_dag[g].add(pred)
            last_gate_on_qubit[q] = g

    in_degree = {g: len(predecessors_dag[g]) for g in all_gates}
    gate_layer = {g: 0 for g in all_gates}
    temp_in = dict(in_degree)
    queue = deque(g for g in all_gates if in_degree[g] == 0)
    topo_order = []
    while queue:
        g = queue.popleft()
        topo_order.append(g)
        for s in successors_dag[g]:
            gate_layer[s] = max(gate_layer[s], gate_layer[g] + 1)
            temp_in[s] -= 1
            if temp_in[s] == 0:
                queue.append(s)

    critical_path = {g: 0 for g in all_gates}
    for g in reversed(topo_order):
        for s in successors_dag[g]:
            if critical_path[s] + 1 > critical_path[g]:
                critical_path[g] = critical_path[s] + 1

    # 2q DAG for routing simulation
    gates_2q = {}
    dag2q_succ = defaultdict(set)
    dag2q_pred = defaultdict(set)
    last_2q_on_qubit = {}
    logical_qubits_set = set()

    for gate in all_gates:
        qubits = self.access[gate]
        if len(qubits) == 2:
            q1, q2 = qubits
            gates_2q[gate] = (q1, q2)
            logical_qubits_set.add(q1)
            logical_qubits_set.add(q2)
            for q in [q1, q2]:
                if q in last_2q_on_qubit:
                    prev = last_2q_on_qubit[q]
                    if prev != gate:
                        dag2q_succ[prev].add(gate)
                        dag2q_pred[gate].add(prev)
                last_2q_on_qubit[q] = gate
        elif len(qubits) == 1:
            logical_qubits_set.add(qubits[0])

    logical_qubits = sorted(logical_qubits_set)

    if not gates_2q:
        self.mapping_dict = list(range(num_q))
        self.reverse_mapping_dict = list(range(num_q))
        if self.use_isl:
            self.isl_mapping = dict_to_isl_map(self.mapping_dict)
        return

    # Topological order for 2q DAG
    topo_2q = []
    in_deg_2q = {g: len(dag2q_pred[g]) for g in gates_2q}
    q2 = deque(sorted(g for g in gates_2q if in_deg_2q[g] == 0))
    while q2:
        g = q2.popleft()
        topo_2q.append(g)
        for s in dag2q_succ[g]:
            in_deg_2q[s] -= 1
            if in_deg_2q[s] == 0:
                q2.append(s)

    dep_count = defaultdict(int)
    for g in reversed(topo_2q):
        for s in dag2q_succ[g]:
            dep_count[g] = max(dep_count[g], dep_count[s] + 1)

    # Backward dep count for backward routing
    bwd_dep = defaultdict(int)
    for g in topo_2q:
        for p in dag2q_pred[g]:
            if p in gates_2q:
                bwd_dep[g] = max(bwd_dep[g], bwd_dep[p] + 1)

    # ---------------------------------------------------------------
    # Step 2: Interaction weights — critical-path weighting
    # ---------------------------------------------------------------
    max_layer = max((gate_layer[g] for g in two_qubit_gates), default=1)

    static_weight = defaultdict(float)
    logical_degree = defaultdict(float)

    for g in two_qubit_gates:
        q1, q2 = self.access[g]
        cp = critical_path[g] + 1
        layer = gate_layer[g]
        w = cp * (max_layer - layer + 1)
        key = (min(q1, q2), max(q1, q2))
        static_weight[key] += w
        logical_degree[q1] += w
        logical_degree[q2] += w

    interacting_logical = [q for q in logical_qubits if logical_degree.get(q, 0) > 0]

    # ---------------------------------------------------------------
    # Step 3: Physical graph properties
    # ---------------------------------------------------------------
    hw_adj = defaultdict(set)
    for pq in physical_qubits:
        for pq2 in self.backend.get(pq, []):
            hw_adj[pq].add(pq2)

    phys_degree = {pq: len(hw_adj[pq]) for pq in physical_qubits}
    phys_centrality = {}
    for pq in physical_qubits:
        phys_centrality[pq] = sum(dist[pq][pq2] for pq2 in physical_qubits)

    # ---------------------------------------------------------------
    # Step 4: Helper functions
    # ---------------------------------------------------------------
    def build_neighbors(weights):
        nbrs = defaultdict(dict)
        deg = defaultdict(float)
        for (q1, q2), w in weights.items():
            nbrs[q1][q2] = w
            nbrs[q2][q1] = w
            deg[q1] += w
            deg[q2] += w
        return nbrs, deg

    def compute_cost_nonlinear(m, weights, alpha_exp):
        cost = 0.0
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                d = dist[m[q1]][m[q2]]
                cost += w * (d ** alpha_exp)
        return cost

    def compute_cost(m, weights):
        cost = 0.0
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                cost += w * dist[m[q1]][m[q2]]
        return cost

    def delta_swap_cost_nonlinear(m, rm, pq_a, pq_b, nbrs, alpha_exp):
        lq_a, lq_b = rm[pq_a], rm[pq_b]
        delta = 0.0
        affected = set()
        if lq_a in nbrs:
            affected.update(nbrs[lq_a].keys())
        if lq_b in nbrs:
            affected.update(nbrs[lq_b].keys())
        for q in affected:
            if q == lq_a or q == lq_b:
                continue
            pq_q = m[q]
            w_a = nbrs.get(lq_a, {}).get(q, 0.0)
            if w_a > 0:
                old_d = dist[pq_a][pq_q] ** alpha_exp
                new_d = dist[pq_b][pq_q] ** alpha_exp
                delta += w_a * (new_d - old_d)
            w_b = nbrs.get(lq_b, {}).get(q, 0.0)
            if w_b > 0:
                old_d = dist[pq_b][pq_q] ** alpha_exp
                new_d = dist[pq_a][pq_q] ** alpha_exp
                delta += w_b * (new_d - old_d)
        return delta

    def do_swap(m, rm, pq_a, pq_b):
        lq_a, lq_b = rm[pq_a], rm[pq_b]
        m[lq_a], m[lq_b] = pq_b, pq_a
        rm[pq_a], rm[pq_b] = lq_b, lq_a

    # ---------------------------------------------------------------
    # Step 5: A* early-layer routing with adaptive node limit
    # ---------------------------------------------------------------
    ASTAR_LAYERS = 5
    n_2q = len(gates_2q)
    if n_2q < 50:
        ASTAR_NODE_LIMIT = 8000
    elif n_2q < 200:
        ASTAR_NODE_LIMIT = 5000
    else:
        ASTAR_NODE_LIMIT = 3000

    pred_rem_layer = {g: len(dag2q_pred[g]) for g in gates_2q}
    front_layer_calc = set(g for g in gates_2q if pred_rem_layer[g] == 0)
    current_layer = 0
    early_layer_gates = set()

    temp_front = set(front_layer_calc)
    while temp_front:
        for g in temp_front:
            if current_layer < ASTAR_LAYERS:
                early_layer_gates.add(g)
        next_front = set()
        for g in temp_front:
            for s in dag2q_succ[g]:
                pred_rem_layer[s] -= 1
                if pred_rem_layer[s] == 0:
                    next_front.add(s)
        current_layer += 1
        temp_front = next_front

    # ---------------------------------------------------------------
    # Step 6: A*-guided routing for early layers
    # ---------------------------------------------------------------
    def astar_routing_early(m, rm):
        if not early_layer_gates:
            return defaultdict(float), 0

        early_pred = {}
        for g in early_layer_gates:
            early_pred[g] = len(dag2q_pred[g] & early_layer_gates)

        initial_front = frozenset(g for g in early_layer_gates if early_pred[g] == 0)

        init_executed = set()
        cur_front = set(initial_front)
        changed = True
        while changed:
            changed = False
            newly_exec = set()
            for g in cur_front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = m[gq1], m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    newly_exec.add(g)
            if newly_exec:
                changed = True
                init_executed |= newly_exec
                cur_front -= newly_exec
                for g in newly_exec:
                    for s in dag2q_succ[g]:
                        if s in early_layer_gates and s not in init_executed:
                            all_pred_done = True
                            for p in dag2q_pred[s]:
                                if p in early_layer_gates and p not in init_executed:
                                    all_pred_done = False
                                    break
                            if all_pred_done:
                                cur_front.add(s)

        remaining_early = early_layer_gates - init_executed
        if not remaining_early:
            return defaultdict(float), 0

        def compute_front(executed):
            front = set()
            for g in early_layer_gates:
                if g in executed:
                    continue
                all_pred = True
                for p in dag2q_pred[g]:
                    if p in early_layer_gates and p not in executed:
                        all_pred = False
                        break
                if all_pred:
                    front.add(g)
            return frozenset(front)

        init_exec_frozen = frozenset(init_executed)
        init_front_astar = compute_front(init_executed)

        active_logical = set()
        for g in remaining_early:
            gq1, gq2 = gates_2q[g]
            active_logical.add(gq1)
            active_logical.add(gq2)

        def h_func(mapping, front_gates):
            h = 0
            for g in front_gates:
                gq1, gq2 = gates_2q[g]
                h += dist[mapping[gq1]][mapping[gq2]]
            return h

        active_logical_list = sorted(active_logical)

        def mapping_key(mapping):
            return tuple(mapping[lq] for lq in active_logical_list)

        init_m = list(m)
        init_h = h_func(init_m, init_front_astar)

        counter = [0]
        start_state = (init_h, 0, 0, init_m, init_exec_frozen, init_front_astar)
        open_heap = [start_state]
        visited = {}
        best_known_total = float('inf')
        best_result = None

        swap_history = {}
        init_key = (mapping_key(init_m), init_exec_frozen)
        swap_history[init_key] = defaultdict(float)

        expansions = 0

        while open_heap and expansions < ASTAR_NODE_LIMIT:
            f, _, g_cost, cur_m_list, executed, front = heapq.heappop(open_heap)

            mk = mapping_key(cur_m_list)
            state_key = (mk, executed)

            if state_key in visited and visited[state_key] <= g_cost:
                continue
            visited[state_key] = g_cost

            if best_known_total < float('inf') and f > best_known_total * 1.2:
                continue

            new_executed = set(executed)
            new_front = set(front)
            progress = True
            while progress:
                progress = False
                newly_exec = set()
                for g in list(new_front):
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = cur_m_list[gq1], cur_m_list[gq2]
                    if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                        newly_exec.add(g)
                if newly_exec:
                    progress = True
                    new_executed |= newly_exec
                    new_front -= newly_exec
                    for g in newly_exec:
                        for s in dag2q_succ[g]:
                            if s in early_layer_gates and s not in new_executed:
                                all_pred = True
                                for p in dag2q_pred[s]:
                                    if p in early_layer_gates and p not in new_executed:
                                        all_pred = False
                                        break
                                if all_pred:
                                    new_front.add(s)

            new_exec_frozen = frozenset(new_executed)
            new_front_frozen = frozenset(new_front)

            if not (early_layer_gates - new_executed):
                if g_cost < best_known_total:
                    best_known_total = g_cost
                    parent_key = (mk, executed)
                    pair_swaps = dict(swap_history.get(parent_key, {}))
                    best_result = (g_cost, pair_swaps)
                continue

            if not new_front_frozen:
                continue

            active_phys = set()
            for g in new_front_frozen:
                gq1, gq2 = gates_2q[g]
                active_phys.add(cur_m_list[gq1])
                active_phys.add(cur_m_list[gq2])
            ext_gates = set()
            for g in new_front_frozen:
                for s in dag2q_succ[g]:
                    if s in early_layer_gates and s not in new_executed:
                        ext_gates.add(s)
            for g in ext_gates:
                gq1, gq2 = gates_2q[g]
                active_phys.add(cur_m_list[gq1])
                active_phys.add(cur_m_list[gq2])

            swaps = set()
            for pq in active_phys:
                for nb in hw_adj.get(pq, set()):
                    swaps.add((min(pq, nb), max(pq, nb)))

            expansions += 1
            parent_pair_swaps = swap_history.get((mk, executed), defaultdict(float))

            for (s1, s2) in swaps:
                new_m = list(cur_m_list)
                lq_at_s1 = -1
                lq_at_s2 = -1
                for lq in range(num_q):
                    if new_m[lq] == s1:
                        lq_at_s1 = lq
                    if new_m[lq] == s2:
                        lq_at_s2 = lq

                if lq_at_s1 >= 0:
                    new_m[lq_at_s1] = s2
                if lq_at_s2 >= 0:
                    new_m[lq_at_s2] = s1

                new_g = g_cost + 1
                new_mk = mapping_key(new_m)
                child_key = (new_mk, new_exec_frozen)

                if child_key in visited and visited[child_key] <= new_g:
                    continue

                new_h = h_func(new_m, new_front_frozen)
                new_f = new_g + new_h

                if best_known_total < float('inf') and new_f > best_known_total * 1.2:
                    continue

                counter[0] += 1

                child_pair_swaps = defaultdict(float, parent_pair_swaps)
                for g in new_front_frozen:
                    gq1, gq2 = gates_2q[g]
                    pair_key = (min(gq1, gq2), max(gq1, gq2))
                    child_pair_swaps[pair_key] += 1.0

                swap_history[child_key] = child_pair_swaps

                heapq.heappush(open_heap, (new_f, counter[0], new_g, new_m, new_exec_frozen, new_front_frozen))

        if best_result is not None:
            return defaultdict(float, best_result[1]), best_result[0]
        else:
            return defaultdict(float), 0

    # ---------------------------------------------------------------
    # Step 7: Forward greedy routing simulation
    # ---------------------------------------------------------------
    def simulate_routing_greedy(m, rm, max_layers=20):
        sim_m = list(m)
        sim_rm = list(rm)
        swap_counts = defaultdict(float)
        total_swaps = 0

        if not gates_2q:
            return swap_counts, total_swaps

        pred_remaining = {g: len(dag2q_pred[g]) for g in gates_2q}
        front = set(g for g in gates_2q if pred_remaining[g] == 0)
        layers_done = 0

        while front and layers_done < max_layers:
            executable = []
            for g in front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = sim_m[gq1], sim_m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    executable.append(g)

            if executable:
                for g in executable:
                    front.discard(g)
                    for s in dag2q_succ[g]:
                        pred_remaining[s] -= 1
                        if pred_remaining[s] == 0:
                            front.add(s)
                layers_done += 1
                continue

            active_phys = set()
            for g in front:
                gq1, gq2 = gates_2q[g]
                active_phys.add(sim_m[gq1])
                active_phys.add(sim_m[gq2])

            candidates_sw = set()
            for pq in active_phys:
                for nb in self.backend.get(pq, []):
                    candidates_sw.add((min(pq, nb), max(pq, nb)))

            best_swap, best_score = None, float('inf')
            for (s1, s2) in candidates_sw:
                l1, l2 = sim_rm[s1], sim_rm[s2]
                score = 0.0
                for g in front:
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = sim_m[gq1], sim_m[gq2]
                    if gq1 == l1: p1 = s2
                    elif gq1 == l2: p1 = s1
                    if gq2 == l1: p2 = s2
                    elif gq2 == l2: p2 = s1
                    deps = dep_count.get(g, 0) + 1
                    score += deps * dist[p1][p2]
                if score < best_score:
                    best_score = score
                    best_swap = (s1, s2)

            if best_swap is None:
                break

            s1, s2 = best_swap
            l1, l2 = sim_rm[s1], sim_rm[s2]
            sim_m[l1], sim_m[l2] = s2, s1
            sim_rm[s1], sim_rm[s2] = l2, l1
            total_swaps += 1

            for g in front:
                gq1, gq2 = gates_2q[g]
                pair_key = (min(gq1, gq2), max(gq1, gq2))
                swap_counts[pair_key] += 1.0

        return swap_counts, total_swaps

    # ---------------------------------------------------------------
    # Step 7b: Backward greedy routing simulation
    # ---------------------------------------------------------------
    def simulate_routing_backward(m, rm, max_layers=20):
        sim_m = list(m)
        sim_rm = list(rm)
        swap_counts = defaultdict(float)
        total_swaps = 0

        if not gates_2q:
            return swap_counts, total_swaps

        succ_remaining = {g: len(dag2q_succ[g] & set(gates_2q.keys())) for g in gates_2q}
        front = set(g for g in gates_2q if succ_remaining[g] == 0)
        layers_done = 0

        while front and layers_done < max_layers:
            executable = []
            for g in front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = sim_m[gq1], sim_m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    executable.append(g)

            if executable:
                for g in executable:
                    front.discard(g)
                    for p in dag2q_pred[g]:
                        if p in gates_2q:
                            succ_remaining[p] -= 1
                            if succ_remaining[p] == 0:
                                front.add(p)
                layers_done += 1
                continue

            active_phys = set()
            for g in front:
                gq1, gq2 = gates_2q[g]
                active_phys.add(sim_m[gq1])
                active_phys.add(sim_m[gq2])

            candidates_sw = set()
            for pq in active_phys:
                for nb in self.backend.get(pq, []):
                    candidates_sw.add((min(pq, nb), max(pq, nb)))

            best_swap, best_score = None, float('inf')
            for (s1, s2) in candidates_sw:
                l1, l2 = sim_rm[s1], sim_rm[s2]
                score = 0.0
                for g in front:
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = sim_m[gq1], sim_m[gq2]
                    if gq1 == l1: p1 = s2
                    elif gq1 == l2: p1 = s1
                    if gq2 == l1: p2 = s2
                    elif gq2 == l2: p2 = s1
                    deps = bwd_dep.get(g, 0) + 1
                    score += deps * dist[p1][p2]
                if score < best_score:
                    best_score = score
                    best_swap = (s1, s2)

            if best_swap is None:
                break

            s1, s2 = best_swap
            l1, l2 = sim_rm[s1], sim_rm[s2]
            sim_m[l1], sim_m[l2] = s2, s1
            sim_rm[s1], sim_rm[s2] = l2, l1
            total_swaps += 1

            for g in front:
                gq1, gq2 = gates_2q[g]
                pair_key = (min(gq1, gq2), max(gq1, gq2))
                swap_counts[pair_key] += 1.0

        return swap_counts, total_swaps

    # ---------------------------------------------------------------
    # Step 7c: Asymmetric bidirectional routing (forward-biased 0.6/0.4)
    # ---------------------------------------------------------------
    def simulate_routing_asymmetric_bidir(m, rm, max_layers=20):
        fwd_swaps, fwd_total = simulate_routing_greedy(m, rm, max_layers=max_layers)
        bwd_swaps, bwd_total = simulate_routing_backward(m, rm, max_layers=max_layers)

        combined = defaultdict(float)
        all_keys = set(fwd_swaps.keys()) | set(bwd_swaps.keys())
        for key in all_keys:
            combined[key] = 0.6 * fwd_swaps.get(key, 0.0) + 0.4 * bwd_swaps.get(key, 0.0)

        return combined, (fwd_total + bwd_total) // 2

    # ---------------------------------------------------------------
    # Step 7d: Hybrid A* + greedy routing
    # ---------------------------------------------------------------
    def simulate_routing_hybrid(m, rm, max_layers=20):
        astar_swaps, astar_total = astar_routing_early(m, rm)
        greedy_swaps, greedy_total = simulate_routing_greedy(m, rm, max_layers=max_layers)

        combined_swaps = defaultdict(float)
        early_pairs = set()
        for g in early_layer_gates:
            gq1, gq2 = gates_2q[g]
            early_pairs.add((min(gq1, gq2), max(gq1, gq2)))

        for pair_key in early_pairs:
            if pair_key in astar_swaps:
                combined_swaps[pair_key] = astar_swaps[pair_key]

        for pair_key, count in greedy_swaps.items():
            if pair_key not in early_pairs:
                combined_swaps[pair_key] = count

        return combined_swaps, astar_total + greedy_total

    # ---------------------------------------------------------------
    # Step 7e: Hybrid A* + asymmetric bidirectional for later iters
    # ---------------------------------------------------------------
    def simulate_routing_hybrid_bidir(m, rm, max_layers=20):
        astar_swaps, astar_total = astar_routing_early(m, rm)
        fwd_swaps, fwd_total = simulate_routing_greedy(m, rm, max_layers=max_layers)
        bwd_swaps, bwd_total = simulate_routing_backward(m, rm, max_layers=max_layers)

        combined_swaps = defaultdict(float)
        early_pairs = set()
        for g in early_layer_gates:
            gq1, gq2 = gates_2q[g]
            early_pairs.add((min(gq1, gq2), max(gq1, gq2)))

        # Early pairs: A* exact feedback
        for pair_key in early_pairs:
            if pair_key in astar_swaps:
                combined_swaps[pair_key] = astar_swaps[pair_key]

        # Late pairs: asymmetric bidirectional
        all_late_keys = (set(fwd_swaps.keys()) | set(bwd_swaps.keys())) - early_pairs
        for pair_key in all_late_keys:
            combined_swaps[pair_key] = 0.6 * fwd_swaps.get(pair_key, 0.0) + 0.4 * bwd_swaps.get(pair_key, 0.0)

        return combined_swaps, astar_total + (fwd_total + bwd_total) // 2

    # ---------------------------------------------------------------
    # Step 8: Seed generation setup
    # ---------------------------------------------------------------
    sorted_by_degree = sorted(interacting_logical, key=lambda q: logical_degree[q], reverse=True)
    seed_lqs = sorted_by_degree[:min(3, len(sorted_by_degree))]
    phys_by_centrality = sorted(physical_qubits, key=lambda pq: phys_centrality[pq])
    seed_pqs = phys_by_centrality[:min(3, len(phys_by_centrality))]

    logical_degree_ranked = sorted(interacting_logical, key=lambda q: logical_degree[q], reverse=True)
    logical_degree_rank = {q: i for i, q in enumerate(logical_degree_ranked)}
    max_logical_rank = max(len(logical_degree_ranked) - 1, 1)
    phys_degree_ranked = sorted(physical_qubits, key=lambda pq: phys_degree[pq], reverse=True)
    phys_degree_rank = {pq: i for i, pq in enumerate(phys_degree_ranked)}
    max_phys_rank = max(len(phys_degree_ranked) - 1, 1)

    static_nbrs, static_deg = build_neighbors(static_weight)
    max_iw = max(static_weight.values()) if static_weight else 1.0

    # ---------------------------------------------------------------
    # Step 9: Routing-Pressure-Aware Conflict-Graph MIS Seed
    # ---------------------------------------------------------------
    def conflict_graph_seed(start_pq, nbrs, deg, weights, routing_pressure=None):
        if len(interacting_logical) < 2:
            return None, None

        cur_max_iw = max(weights.values()) if weights else 1.0

        top_partners = {}
        for lq in interacting_logical:
            nbr_list = sorted(nbrs.get(lq, {}).items(), key=lambda x: x[1], reverse=True)
            top_partners[lq] = set(p for p, _ in nbr_list[:3])

        conflict_adj = defaultdict(set)
        il = interacting_logical

        qubit_pressure = defaultdict(float)
        if routing_pressure:
            for (q1, q2), cnt in routing_pressure.items():
                qubit_pressure[q1] += cnt
                qubit_pressure[q2] += cnt

        for i in range(len(il)):
            for j in range(i + 1, len(il)):
                l1, l2 = il[i], il[j]
                s1 = top_partners.get(l1, set())
                s2 = top_partners.get(l2, set())
                if not s1 and not s2:
                    continue
                intersection = len(s1 & s2)
                union = len(s1 | s2)
                if union > 0:
                    jaccard = intersection / union
                    threshold = 0.5
                    if routing_pressure and qubit_pressure[l1] > 0 and qubit_pressure[l2] > 0:
                        max_pressure = max(qubit_pressure.values()) if qubit_pressure else 1.0
                        pressure_factor = min(1.0, (qubit_pressure[l1] + qubit_pressure[l2]) /
                                              (max_pressure * 2 + 1e-10))
                        threshold = max(0.25, 0.5 - 0.25 * pressure_factor)
                    if jaccard > threshold:
                        conflict_adj[l1].add(l2)
                        conflict_adj[l2].add(l1)

        sorted_by_deg_local = sorted(interacting_logical,
                                     key=lambda q: (deg.get(q, 0), qubit_pressure.get(q, 0)),
                                     reverse=True)
        mis = set()
        excluded = set()
        for lq in sorted_by_deg_local:
            if lq not in excluded:
                mis.add(lq)
                for neighbor in conflict_adj.get(lq, set()):
                    excluded.add(neighbor)

        non_mis = [lq for lq in sorted_by_deg_local if lq not in mis]
        mis_ordered = sorted(mis, key=lambda q: (deg.get(q, 0), qubit_pressure.get(q, 0)),
                             reverse=True)

        m = [-1] * num_q
        rm = [-1] * num_q
        used_phys = set()

        if mis_ordered:
            first_lq = mis_ordered[0]
            m[first_lq] = start_pq
            rm[start_pq] = first_lq
            used_phys.add(start_pq)

            for lq in mis_ordered[1:]:
                nbrs_placed = {}
                for plq in mis:
                    if m[plq] >= 0 and plq in nbrs.get(lq, {}):
                        nbrs_placed[plq] = nbrs[lq][plq]

                if nbrs_placed:
                    best_pq = None
                    best_score = float('inf')
                    for pq in physical_qubits:
                        if pq in used_phys:
                            continue
                        score = 0.0
                        for plq, iw in nbrs_placed.items():
                            d = dist[pq][m[plq]]
                            cost = iw * d
                            if m[plq] in hw_adj[pq]:
                                cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                            score += cost
                        if score < best_score:
                            best_score = score
                            best_pq = pq
                else:
                    best_pq = None
                    best_score = float('inf')
                    for pq in physical_qubits:
                        if pq not in used_phys:
                            if phys_centrality[pq] < best_score:
                                best_score = phys_centrality[pq]
                                best_pq = pq

                if best_pq is not None:
                    m[lq] = best_pq
                    rm[best_pq] = lq
                    used_phys.add(best_pq)

        placed_set = set(lq for lq in interacting_logical if m[lq] >= 0)

        for lq in non_mis:
            nbrs_placed = {}
            for plq in placed_set:
                w = nbrs.get(lq, {}).get(plq, 0.0)
                if w > 0:
                    nbrs_placed[plq] = w

            if nbrs_placed:
                near_ties = []
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq in used_phys:
                        continue
                    score = 0.0
                    for plq, iw in nbrs_placed.items():
                        d = dist[pq][m[plq]]
                        cost = iw * d
                        if m[plq] in hw_adj[pq]:
                            cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                        score += cost
                    near_ties.append((score, pq))
                    if score < best_score:
                        best_score = score

                if near_ties and best_score > 0:
                    threshold = best_score * 1.05
                    candidates_list = [(s, pq) for s, pq in near_ties if s <= threshold]
                    if len(candidates_list) > 1 and lq in logical_degree_rank:
                        lq_rn = logical_degree_rank[lq] / max_logical_rank
                        best_pq = min(candidates_list, key=lambda x: (
                            abs(phys_degree_rank[x[1]] / max_phys_rank - lq_rn), x[0]))[1]
                    else:
                        best_pq = min(candidates_list, key=lambda x: x[0])[1]
                elif near_ties:
                    best_pq = min(near_ties, key=lambda x: x[0])[1]
                else:
                    best_pq = None
            else:
                best_pq = None
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq not in used_phys:
                        if phys_centrality[pq] < best_score:
                            best_score = phys_centrality[pq]
                            best_pq = pq

            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                used_phys.add(best_pq)
                placed_set.add(lq)

        remaining_lqs = [lq for lq in logical_qubits if m[lq] == -1]
        for lq in remaining_lqs:
            best_pq = None
            best_score = float('inf')
            for pq in physical_qubits:
                if pq not in used_phys:
                    if phys_centrality[pq] < best_score:
                        best_score = phys_centrality[pq]
                        best_pq = pq
            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                used_phys.add(best_pq)

        return m, rm

    # ---------------------------------------------------------------
    # Step 10: Spectral ordering seed
    # ---------------------------------------------------------------
    def spectral_seed():
        if len(interacting_logical) < 3:
            return None, None

        idx_map = {q: i for i, q in enumerate(interacting_logical)}
        n = len(interacting_logical)

        L = [[0.0] * n for _ in range(n)]
        for (q1, q2), w in static_weight.items():
            if q1 in idx_map and q2 in idx_map:
                i, j = idx_map[q1], idx_map[q2]
                L[i][j] -= w
                L[j][i] -= w
                L[i][i] += w
                L[j][j] += w

        def power_iter(mat, n_iter=200):
            v = [random.gauss(0, 1) for _ in range(n)]
            for _ in range(n_iter):
                new_v = [0.0] * n
                for i in range(n):
                    for j in range(n):
                        new_v[i] += mat[i][j] * v[j]
                norm = math.sqrt(sum(x * x for x in new_v)) or 1e-12
                v = [x / norm for x in new_v]
            return v

        max_diag = max(L[i][i] for i in range(n)) + 1.0
        shifted = [[0.0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                shifted[i][j] = -L[i][j]
            shifted[i][i] += max_diag

        v1 = power_iter(shifted, 150)

        dot_v1 = sum(x * x for x in v1) or 1e-12
        lam1_shifted = sum(v1[i] * sum(shifted[i][j] * v1[j] for j in range(n)) for i in range(n)) / dot_v1
        shifted2 = [row[:] for row in shifted]
        for i in range(n):
            for j in range(n):
                shifted2[i][j] -= lam1_shifted * v1[i] * v1[j] / dot_v1

        fiedler = power_iter(shifted2, 200)

        fiedler_order = sorted(range(n), key=lambda i: fiedler[i])
        sorted_logical = [interacting_logical[i] for i in fiedler_order]

        phys_sorted = sorted(physical_qubits, key=lambda pq: phys_centrality[pq])
        start_pq = phys_sorted[0]
        visited_bfs = set()
        bfs_order = []
        bfs_q = deque([start_pq])
        visited_bfs.add(start_pq)
        while bfs_q:
            pq = bfs_q.popleft()
            bfs_order.append(pq)
            for nb in sorted(hw_adj[pq]):
                if nb not in visited_bfs:
                    visited_bfs.add(nb)
                    bfs_q.append(nb)
        for pq in physical_qubits:
            if pq not in visited_bfs:
                bfs_order.append(pq)
                visited_bfs.add(pq)

        m = [-1] * num_q
        rm = [-1] * num_q
        n_interact = len(sorted_logical)
        n_phys = len(bfs_order)
        offset = max(0, (n_phys - n_interact) // 2)
        for i, lq in enumerate(sorted_logical):
            pq = bfs_order[min(offset + i, n_phys - 1)]
            if rm[pq] != -1:
                best_pq = None
                best_d = float('inf')
                for cpq in physical_qubits:
                    if rm[cpq] == -1:
                        d = dist[pq][cpq]
                        if d < best_d:
                            best_d = d
                            best_pq = cpq
                pq = best_pq
            m[lq] = pq
            rm[pq] = lq

        return m, rm

    # ---------------------------------------------------------------
    # Step 11: Greedy placement
    # ---------------------------------------------------------------
    def run_greedy_placement(start_lq, start_pq, nbrs, deg, weights=None):
        cur_max_iw = max(weights.values()) if weights else max_iw
        used_phys = {start_pq}
        m = [-1] * num_q
        rm = [-1] * num_q
        m[start_lq] = start_pq
        rm[start_pq] = start_lq
        placed = {start_lq}
        remaining = set(logical_qubits) - placed

        while remaining:
            best_lq, best_w = None, -1.0
            for lq in remaining:
                w = sum(nbrs.get(lq, {}).get(plq, 0.0) for plq in placed)
                if w > best_w:
                    best_w = w
                    best_lq = lq

            nbrs_placed = {plq: nbrs.get(best_lq, {}).get(plq, 0.0)
                           for plq in placed if plq in nbrs.get(best_lq, {})}

            if nbrs_placed:
                near_ties = []
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq in used_phys:
                        continue
                    score = 0.0
                    for plq, iw in nbrs_placed.items():
                        d = dist[pq][m[plq]]
                        cost = iw * d
                        if m[plq] in hw_adj[pq]:
                            cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                        score += cost
                    near_ties.append((score, pq))
                    if score < best_score:
                        best_score = score

                if near_ties and best_score > 0:
                    threshold = best_score * 1.05
                    candidates_list = [(s, pq) for s, pq in near_ties if s <= threshold]
                    if len(candidates_list) > 1 and best_lq in logical_degree_rank:
                        lq_rn = logical_degree_rank[best_lq] / max_logical_rank
                        best_pq = min(candidates_list, key=lambda x: (
                            abs(phys_degree_rank[x[1]] / max_phys_rank - lq_rn), x[0]))[1]
                    else:
                        best_pq = min(candidates_list, key=lambda x: x[0])[1]
                elif near_ties:
                    best_pq = min(near_ties, key=lambda x: x[0])[1]
                else:
                    best_pq = None
            else:
                best_pq = None
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq not in used_phys:
                        score = phys_centrality[pq]
                        if score < best_score:
                            best_score = score
                            best_pq = pq

            m[best_lq] = best_pq
            rm[best_pq] = best_lq
            used_phys.add(best_pq)
            placed.add(best_lq)
            remaining.discard(best_lq)
        return m, rm

    def fill_unmapped(m, rm):
        unmapped = [q for q in range(num_q) if m[q] == -1]
        free = [pq for pq in range(num_q) if rm[pq] == -1]
        for lq, pq in zip(unmapped, free):
            m[lq] = pq
            rm[pq] = lq

    # ---------------------------------------------------------------
    # Step 12: Local search with selective congestion bias
    #   Congestion bias only activates in later RSDIWR iterations (>=2)
    #   with a reduced coefficient to avoid premature distortion
    # ---------------------------------------------------------------
    def local_search(m, rm, nbrs, weights, alpha_exp, max_rounds=5,
                     congestion_bonus=None):
        if len(interacting_logical) <= 1:
            return compute_cost_nonlinear(m, weights, alpha_exp)

        # Build lightweight congestion bias for hardware-adjacent swaps
        hw_edge_congestion = defaultdict(float)
        if congestion_bonus:
            for (q1, q2), pressure in congestion_bonus.items():
                pq1, pq2 = m[q1], m[q2]
                hw_edge_congestion[(min(pq1, pq2), max(pq1, pq2))] += pressure

        for _ in range(max_rounds):
            improved = False
            best_d, best_pair = 0.0, None
            active_phys = [m[q] for q in interacting_logical]
            for pq1 in active_phys:
                for pq2 in hw_adj.get(pq1, set()):
                    d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                    # Selective congestion bonus: amplify improving swaps on congested edges
                    if congestion_bonus:
                        edge_key = (min(pq1, pq2), max(pq1, pq2))
                        if edge_key in hw_edge_congestion and d < 0:
                            d *= (1.0 + 0.08 * min(1.0, hw_edge_congestion[edge_key]))
                    if d < best_d:
                        best_d = d
                        best_pair = (pq1, pq2)
            n_random = min(150, len(interacting_logical) * 3)
            for _ in range(n_random):
                i, j = random.sample(range(len(interacting_logical)), 2)
                pq1, pq2 = m[interacting_logical[i]], m[interacting_logical[j]]
                d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                if d < best_d:
                    best_d = d
                    best_pair = (pq1, pq2)
            if best_pair and best_d < -1e-12:
                do_swap(m, rm, *best_pair)
                improved = True
            if not improved:
                for i in range(len(interacting_logical)):
                    for j in range(i + 1, len(interacting_logical)):
                        pq1, pq2 = m[interacting_logical[i]], m[interacting_logical[j]]
                        d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                        if d < best_d:
                            best_d = d
                            best_pair = (pq1, pq2)
                if best_pair and best_d < -1e-12:
                    do_swap(m, rm, *best_pair)
                else:
                    break
        return compute_cost_nonlinear(m, weights, alpha_exp)

    # ---------------------------------------------------------------
    # Step 13: Perturbation modes with bandit selection
    #   6 modes: Parent 1's 5 + Parent 2's congestion-directed
    # ---------------------------------------------------------------
    rsdiwr_iter_ref = [0]
    accumulated_routing_pressure_ref = [defaultdict(float)]

    def perturb_random(m, rm, **kw):
        if len(interacting_logical) >= 2:
            lqs = random.sample(interacting_logical, 2)
            do_swap(m, rm, m[lqs[0]], m[lqs[1]])

    def perturb_segment_shuffle(m, rm, **kw):
        k = min(random.randint(3, 5), len(interacting_logical))
        if k < 2:
            perturb_random(m, rm)
            return
        lqs = random.sample(interacting_logical, k)
        phys_positions = [m[lq] for lq in lqs]
        random.shuffle(phys_positions)
        for lq in lqs:
            rm[m[lq]] = -1
        for lq, pq in zip(lqs, phys_positions):
            m[lq] = pq
            rm[pq] = lq

    def perturb_worst_pair(m, rm, weights=None, alpha_exp=1.5, **kw):
        if weights is None:
            perturb_random(m, rm)
            return
        pair_costs = []
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                d = dist[m[q1]][m[q2]]
                c = w * (d ** alpha_exp)
                pair_costs.append((c, q1, q2))
        if not pair_costs:
            return
        pair_costs.sort(reverse=True)
        top_n = min(3, len(pair_costs))
        _, tq1, tq2 = pair_costs[random.randint(0, top_n - 1)]
        pq1, pq2 = m[tq1], m[tq2]
        adj_of_pq2 = list(hw_adj.get(pq2, set()))
        if adj_of_pq2:
            target = random.choice(adj_of_pq2)
            if target != pq1:
                do_swap(m, rm, pq1, target)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    def perturb_edge_targeted(m, rm, weights=None, alpha_exp=1.5, **kw):
        if weights is None:
            perturb_random(m, rm)
            return
        edge_costs = []
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                c = w * (dist[m[q1]][m[q2]] ** alpha_exp)
                edge_costs.append((c, q1, q2))
        if not edge_costs:
            return
        edge_costs.sort(reverse=True)
        top_n = min(5, len(edge_costs))
        _, eq1, eq2 = edge_costs[random.randint(0, top_n - 1)]
        pq1, pq2 = m[eq1], m[eq2]
        neighbors_of_pq2 = list(hw_adj.get(pq2, set()))
        if neighbors_of_pq2:
            target = random.choice(neighbors_of_pq2)
            if target != pq1:
                do_swap(m, rm, pq1, target)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    def perturb_lns(m, rm, nbrs=None, alpha_exp=1.5, **kw):
        """Pressure-guided LNS: blends current cost with accumulated
        routing pressure to select which qubits to destroy."""
        if nbrs is None or len(interacting_logical) < 3:
            perturb_random(m, rm)
            return
        base_lo = 3 + rsdiwr_iter_ref[0]
        base_hi = 8 + rsdiwr_iter_ref[0] * 2
        k = min(random.randint(base_lo, base_hi), len(interacting_logical))

        acc_pressure = accumulated_routing_pressure_ref[0]
        qubit_acc_pressure = defaultdict(float)
        for (q1, q2), cnt in acc_pressure.items():
            qubit_acc_pressure[q1] += cnt
            qubit_acc_pressure[q2] += cnt
        max_acc = max(qubit_acc_pressure.values()) if qubit_acc_pressure else 1.0

        qcost = {}
        for lq in interacting_logical:
            c = 0.0
            for partner, w in nbrs.get(lq, {}).items():
                if m[partner] >= 0 and m[lq] >= 0:
                    c += w * (dist[m[lq]][m[partner]] ** alpha_exp)
            pressure_bonus = qubit_acc_pressure.get(lq, 0.0) / (max_acc + 1e-10)
            qcost[lq] = c * (1.0 + 0.5 * pressure_bonus)

        sorted_qs = sorted(qcost, key=lambda q: qcost[q], reverse=True)
        top_half = sorted_qs[:max(k, len(sorted_qs) // 2)]
        subset = random.sample(top_half, min(k, len(top_half)))

        freed_phys = []
        for lq in subset:
            freed_phys.append(m[lq])
            rm[m[lq]] = -1
            m[lq] = -1

        placed_set = set(lq for lq in interacting_logical if m[lq] >= 0)
        for lq in sorted(subset, key=lambda q: qcost[q], reverse=True):
            best_pq, best_sc = None, float('inf')
            for pq in freed_phys:
                if rm[pq] != -1:
                    continue
                sc = 0.0
                for partner, w in nbrs.get(lq, {}).items():
                    if partner in placed_set and m[partner] >= 0:
                        sc += w * (dist[pq][m[partner]] ** alpha_exp)
                if sc < best_sc:
                    best_sc = sc
                    best_pq = pq
            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                placed_set.add(lq)
            else:
                for pq in freed_phys:
                    if rm[pq] == -1:
                        m[lq] = pq
                        rm[pq] = lq
                        placed_set.add(lq)
                        break

    # Congestion-directed perturbation from Parent 2: swap qubits on
    # the most congested pair according to accumulated routing pressure
    def perturb_congestion_directed(m, rm, **kw):
        acc_pressure = accumulated_routing_pressure_ref[0]
        if not acc_pressure or len(interacting_logical) < 2:
            perturb_random(m, rm)
            return

        sorted_pairs = sorted(acc_pressure.items(), key=lambda x: x[1], reverse=True)
        top_n = min(4, len(sorted_pairs))
        (q1, q2), _ = sorted_pairs[random.randint(0, top_n - 1)]

        pq1, pq2 = m[q1], m[q2]
        adj_of_pq2 = list(hw_adj.get(pq2, set()))
        if adj_of_pq2:
            best_nb = min(adj_of_pq2, key=lambda nb: dist[pq1][nb])
            if best_nb != pq1:
                do_swap(m, rm, pq1, best_nb)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    perturbation_modes = [perturb_random, perturb_segment_shuffle,
                          perturb_worst_pair, perturb_edge_targeted,
                          perturb_lns, perturb_congestion_directed]
    K = len(perturbation_modes)

    WINDOW_SIZE = 100
    EPSILON = 0.1
    window = []
    mode_successes = [0] * K
    mode_attempts = [0] * K

    def select_perturbation_mode(phase_exploratory=True):
        if random.random() < EPSILON or sum(mode_attempts) < K * 2:
            return random.randint(0, K - 1)

        rates = []
        for k in range(K):
            if mode_attempts[k] > 0:
                rates.append(mode_successes[k] / mode_attempts[k])
            else:
                rates.append(1.0)

        # Dual-phase bias from Parent 2:
        # exploratory phase boosts LNS/segment/congestion,
        # exploitative phase boosts edge-targeted/worst-pair
        if phase_exploratory:
            for idx in [1, 4, 5]:
                rates[idx] *= 1.3
        else:
            for idx in [2, 3]:
                rates[idx] *= 1.3

        total = sum(rates)
        if total < 1e-12:
            return random.randint(0, K - 1)
        r = random.random() * total
        cumul = 0.0
        for k in range(K):
            cumul += rates[k]
            if r <= cumul:
                return k
        return K - 1

    def update_window(mode_idx, success):
        window.append((mode_idx, success))
        mode_attempts[mode_idx] += 1
        if success:
            mode_successes[mode_idx] += 1
        if len(window) > WINDOW_SIZE:
            old_mode, old_success = window.pop(0)
            mode_attempts[old_mode] -= 1
            if old_success:
                mode_successes[old_mode] -= 1

    # ---------------------------------------------------------------
    # Step 14: Build initial mapping candidates
    # ---------------------------------------------------------------
    candidates = []

    for s_lq in seed_lqs:
        for s_pq in seed_pqs:
            m, rm = run_greedy_placement(s_lq, s_pq, static_nbrs, static_deg,
                                         weights=static_weight)
            fill_unmapped(m, rm)
            cost = compute_cost(m, static_weight)
            candidates.append((cost, m, rm))

    for s_pq in seed_pqs:
        cg_m, cg_rm = conflict_graph_seed(s_pq, static_nbrs, static_deg, static_weight)
        if cg_m is not None:
            fill_unmapped(cg_m, cg_rm)
            cost = compute_cost(cg_m, static_weight)
            candidates.append((cost, cg_m, cg_rm))

    spec_m, spec_rm = spectral_seed()
    if spec_m is not None:
        fill_unmapped(spec_m, spec_rm)
        spec_cost = compute_cost(spec_m, static_weight)
        candidates.append((spec_cost, spec_m, spec_rm))

    m_rand = [-1] * num_q
    rm_rand = [-1] * num_q
    shuffled_phys = list(physical_qubits)
    random.shuffle(shuffled_phys)
    for i, lq in enumerate(logical_qubits):
        m_rand[lq] = shuffled_phys[i]
        rm_rand[shuffled_phys[i]] = lq
    fill_unmapped(m_rand, rm_rand)
    c = compute_cost(m_rand, static_weight)
    candidates.append((c, m_rand, rm_rand))

    if not candidates:
        self.mapping_dict = list(range(num_q))
        self.reverse_mapping_dict = list(range(num_q))
        if self.use_isl:
            self.isl_mapping = dict_to_isl_map(self.mapping_dict)
        return

    candidates.sort(key=lambda x: x[0])

    _, best_m, best_rm = candidates[0]
    best_m, best_rm = list(best_m), list(best_rm)
    local_search(best_m, best_rm, static_nbrs, static_weight, alpha_exp=2.0, max_rounds=6)
    best_cost = compute_cost(best_m, static_weight)

    for idx in range(1, min(5, len(candidates))):
        _, m_c, rm_c = candidates[idx]
        m_c, rm_c = list(m_c), list(rm_c)
        local_search(m_c, rm_c, static_nbrs, static_weight, alpha_exp=2.0, max_rounds=4)
        c = compute_cost(m_c, static_weight)
        if c < best_cost:
            best_cost = c
            best_m = list(m_c)
            best_rm = list(rm_c)

    # ---------------------------------------------------------------
    # Step 15: RSDIWR + Dual-Phase ILS with selective congestion bias
    #   - A*-guided first iteration (Parent 1)
    #   - Asymmetric bidirectional routing (Parent 1)
    #   - Pressure-adaptive blending (Parent 1)
    #   - Routing-pressure MIS reseeding (Parent 1)
    #   - Pressure-guided LNS (Parent 1)
    #   - Congestion-directed perturbation (Parent 2)
    #   - Dual-phase ILS (Parent 2)
    #   - Selective congestion-biased local search (Parent 2, reduced)
    # ---------------------------------------------------------------
    time_budget = 25.0
    t_start = _time()
    n_rsdiwr = 4

    cur_m = list(best_m)
    cur_rm = list(best_rm)
    swap_counts = defaultdict(float)
    accumulated_routing_pressure = defaultdict(float)
    accumulated_routing_pressure_ref[0] = accumulated_routing_pressure

    for rsdiwr_iter in range(n_rsdiwr):
        rsdiwr_iter_ref[0] = rsdiwr_iter
        elapsed = _time() - t_start
        if elapsed > time_budget:
            break

        remaining_time = time_budget - elapsed
        remaining_iters = n_rsdiwr - rsdiwr_iter
        time_for_this_iter = remaining_time / max(remaining_iters, 1)
        n_ils = max(55, int(num_q * time_for_this_iter / 0.5)) if time_for_this_iter > 1.0 else max(30, num_q // 3)

        # Pressure-adaptive blending
        if rsdiwr_iter == 0 or not swap_counts:
            eff_weights = dict(static_weight)
        else:
            max_sw = max(swap_counts.values()) if swap_counts else 1.0
            scale = max(static_weight.values()) / max(max_sw, 1e-10)

            total_pressure = sum(accumulated_routing_pressure.values())
            n_pairs = len(accumulated_routing_pressure)
            avg_pressure = total_pressure / max(n_pairs, 1)
            pressure_adapt = min(0.15, 0.05 * avg_pressure / max(max_sw, 1e-10))
            alpha_blend = max(0.25, 1.0 - 0.3 * rsdiwr_iter - pressure_adapt)

            eff_weights = defaultdict(float)
            all_keys = set(static_weight.keys()) | set(swap_counts.keys())
            for key in all_keys:
                w_s = static_weight.get(key, 0.0)
                w_r = swap_counts.get(key, 0.0) * scale
                eff_weights[key] = alpha_blend * w_s + (1.0 - alpha_blend) * w_r

        eff_nbrs, eff_deg = build_neighbors(eff_weights)

        # Selective congestion bonus: only activate in later RSDIWR iterations (>=2)
        # when accumulated pressure is reliable enough to inform local search
        congestion_bonus = None
        if rsdiwr_iter >= 2 and accumulated_routing_pressure:
            max_acc_p = max(accumulated_routing_pressure.values()) if accumulated_routing_pressure else 1.0
            congestion_bonus = {k: v / (max_acc_p + 1e-10) for k, v in accumulated_routing_pressure.items()}

        # Re-seed with routing-informed weights + routing-pressure MIS
        if rsdiwr_iter > 0 and swap_counts and (_time() - t_start) < time_budget * 0.7:
            eff_sorted = sorted(interacting_logical,
                                key=lambda q: eff_deg.get(q, 0), reverse=True)
            reseed_lqs = eff_sorted[:min(2, len(eff_sorted))]
            reseed_pqs = seed_pqs[:min(2, len(seed_pqs))]

            for s_lq in reseed_lqs:
                for s_pq in reseed_pqs:
                    rm_new, rmm_new = run_greedy_placement(
                        s_lq, s_pq, eff_nbrs, eff_deg, weights=eff_weights)
                    fill_unmapped(rm_new, rmm_new)
                    local_search(rm_new, rmm_new, eff_nbrs, eff_weights,
                                 alpha_exp=2.0, max_rounds=3,
                                 congestion_bonus=congestion_bonus)
                    sc = compute_cost(rm_new, static_weight)
                    if sc < best_cost:
                        best_cost = sc
                        best_m = list(rm_new)
                        best_rm = list(rmm_new)
                        cur_m = list(rm_new)
                        cur_rm = list(rmm_new)

            # Routing-pressure-aware MIS reseeding
            for s_pq in reseed_pqs:
                cg_m, cg_rm = conflict_graph_seed(
                    s_pq, eff_nbrs, eff_deg, eff_weights,
                    routing_pressure=accumulated_routing_pressure)
                if cg_m is not None:
                    fill_unmapped(cg_m, cg_rm)
                    local_search(cg_m, cg_rm, eff_nbrs, eff_weights,
                                 alpha_exp=2.0, max_rounds=3,
                                 congestion_bonus=congestion_bonus)
                    sc = compute_cost(cg_m, static_weight)
                    if sc < best_cost:
                        best_cost = sc
                        best_m = list(cg_m)
                        best_rm = list(cg_rm)
                        cur_m = list(cg_m)
                        cur_rm = list(cg_rm)

        alpha_start = 2.0
        alpha_end = 1.0

        ls_rounds = 6 if rsdiwr_iter == 0 else 4
        cur_cost_nl = local_search(cur_m, cur_rm, eff_nbrs, eff_weights,
                                   alpha_exp=alpha_start, max_rounds=ls_rounds,
                                   congestion_bonus=congestion_bonus)

        static_cost = compute_cost(cur_m, static_weight)
        if static_cost < best_cost:
            best_cost = static_cost
            best_m = list(cur_m)
            best_rm = list(cur_rm)

        # Reset bandit window
        window.clear()
        for k in range(K):
            mode_successes[k] = 0
            mode_attempts[k] = 0

        T = max(cur_cost_nl * 0.05, 1.0)
        T_init = T
        alpha_sa = 0.94
        reheat_interval = max(n_ils // 4, 8)

        # Dual-phase ILS from Parent 2: first 60% exploratory, last 40% exploitative
        exploratory_cutoff = int(n_ils * 0.6)

        for ils_iter in range(n_ils):
            if _time() - t_start > time_budget:
                break

            progress = ils_iter / max(n_ils - 1, 1)
            alpha_exp = alpha_start + (alpha_end - alpha_start) * progress

            phase_exploratory = ils_iter < exploratory_cutoff

            saved_m = list(cur_m)
            saved_rm = list(cur_rm)
            saved_cost = cur_cost_nl

            mode = select_perturbation_mode(phase_exploratory=phase_exploratory)
            perturbation_modes[mode](cur_m, cur_rm,
                                    nbrs=eff_nbrs, weights=eff_weights,
                                    alpha_exp=alpha_exp)

            new_cost_nl = local_search(cur_m, cur_rm, eff_nbrs, eff_weights,
                                       alpha_exp=alpha_exp, max_rounds=3,
                                       congestion_bonus=congestion_bonus)

            success = new_cost_nl < saved_cost - 1e-12

            improvement = saved_cost - new_cost_nl
            if improvement > 0:
                cur_cost_nl = new_cost_nl
                sc = compute_cost(cur_m, static_weight)
                if sc < best_cost:
                    best_cost = sc
                    best_m = list(cur_m)
                    best_rm = list(cur_rm)
            elif random.random() < math.exp(min(0, improvement / max(T, 1e-10))):
                cur_cost_nl = new_cost_nl
            else:
                cur_m[:] = saved_m
                cur_rm[:] = saved_rm
                cur_cost_nl = saved_cost

            update_window(mode, success)

            T *= alpha_sa
            if (ils_iter + 1) % reheat_interval == 0:
                T = max(T, T_init * 0.35)

        # Routing simulation for RSDIWR feedback
        if rsdiwr_iter < n_rsdiwr - 1:
            sim_depth = 14 + rsdiwr_iter * 7

            if rsdiwr_iter == 0 and early_layer_gates:
                swap_counts, _ = simulate_routing_hybrid(best_m, best_rm, max_layers=sim_depth)
            elif rsdiwr_iter == 1 and early_layer_gates:
                swap_counts, _ = simulate_routing_hybrid_bidir(best_m, best_rm, max_layers=sim_depth)
            else:
                swap_counts, _ = simulate_routing_asymmetric_bidir(best_m, best_rm, max_layers=sim_depth)

            # Accumulate routing pressure across iterations
            for pair_key, cnt in swap_counts.items():
                accumulated_routing_pressure[pair_key] += cnt

        cur_m = list(best_m)
        cur_rm = list(best_rm)
        cur_cost_nl = compute_cost_nonlinear(cur_m, eff_weights, alpha_end)

    # ---------------------------------------------------------------
    # Step 16: Set final mapping
    # ---------------------------------------------------------------
    self.mapping_dict = best_m
    self.reverse_mapping_dict = best_rm

    if self.use_isl:
        self.isl_mapping = dict_to_isl_map(self.mapping_dict)

def init_mapping(self):
    import math
    import random
    import heapq
    from collections import defaultdict, deque
    from time import time as _time

    num_q = self.num_qubits
    physical_qubits = sorted(self.backend.keys())
    dist = self.distance_matrix

    # ---------------------------------------------------------------
    # Step 1: Build DAG and topological layers
    # ---------------------------------------------------------------
    all_gates = sorted(self.access.keys())
    two_qubit_gates = [g for g in all_gates if len(self.access[g]) == 2]

    last_gate_on_qubit = {}
    successors_dag = defaultdict(set)
    predecessors_dag = defaultdict(set)
    for g in all_gates:
        for q in self.access[g]:
            if q in last_gate_on_qubit:
                pred = last_gate_on_qubit[q]
                successors_dag[pred].add(g)
                predecessors_dag[g].add(pred)
            last_gate_on_qubit[q] = g

    in_degree = {g: len(predecessors_dag[g]) for g in all_gates}
    gate_layer = {g: 0 for g in all_gates}
    temp_in = dict(in_degree)
    queue = deque(g for g in all_gates if in_degree[g] == 0)
    topo_order = []
    while queue:
        g = queue.popleft()
        topo_order.append(g)
        for s in successors_dag[g]:
            gate_layer[s] = max(gate_layer[s], gate_layer[g] + 1)
            temp_in[s] -= 1
            if temp_in[s] == 0:
                queue.append(s)

    critical_path = {g: 0 for g in all_gates}
    for g in reversed(topo_order):
        for s in successors_dag[g]:
            if critical_path[s] + 1 > critical_path[g]:
                critical_path[g] = critical_path[s] + 1

    # 2q DAG for routing simulation
    gates_2q = {}
    dag2q_succ = defaultdict(set)
    dag2q_pred = defaultdict(set)
    last_2q_on_qubit = {}
    logical_qubits_set = set()

    for gate in all_gates:
        qubits = self.access[gate]
        if len(qubits) == 2:
            q1, q2 = qubits
            gates_2q[gate] = (q1, q2)
            logical_qubits_set.add(q1)
            logical_qubits_set.add(q2)
            for q in [q1, q2]:
                if q in last_2q_on_qubit:
                    prev = last_2q_on_qubit[q]
                    if prev != gate:
                        dag2q_succ[prev].add(gate)
                        dag2q_pred[gate].add(prev)
                last_2q_on_qubit[q] = gate
        elif len(qubits) == 1:
            logical_qubits_set.add(qubits[0])

    logical_qubits = sorted(logical_qubits_set)

    if not gates_2q:
        self.mapping_dict = list(range(num_q))
        self.reverse_mapping_dict = list(range(num_q))
        if self.use_isl:
            self.isl_mapping = dict_to_isl_map(self.mapping_dict)
        return

    # Topological order for 2q DAG
    topo_2q = []
    in_deg_2q = {g: len(dag2q_pred[g]) for g in gates_2q}
    q2 = deque(sorted(g for g in gates_2q if in_deg_2q[g] == 0))
    while q2:
        g = q2.popleft()
        topo_2q.append(g)
        for s in dag2q_succ[g]:
            in_deg_2q[s] -= 1
            if in_deg_2q[s] == 0:
                q2.append(s)

    dep_count = defaultdict(int)
    for g in reversed(topo_2q):
        for s in dag2q_succ[g]:
            dep_count[g] = max(dep_count[g], dep_count[s] + 1)

    # Backward dep count for backward routing
    bwd_dep = defaultdict(int)
    for g in topo_2q:
        for p in dag2q_pred[g]:
            if p in gates_2q:
                bwd_dep[g] = max(bwd_dep[g], bwd_dep[p] + 1)

    # ---------------------------------------------------------------
    # Step 2: Interaction weights — critical-path weighting
    # ---------------------------------------------------------------
    max_layer = max((gate_layer[g] for g in two_qubit_gates), default=1)

    static_weight = defaultdict(float)
    logical_degree = defaultdict(float)

    for g in two_qubit_gates:
        q1, q2 = self.access[g]
        cp = critical_path[g] + 1
        layer = gate_layer[g]
        w = cp * (max_layer - layer + 1)
        key = (min(q1, q2), max(q1, q2))
        static_weight[key] += w
        logical_degree[q1] += w
        logical_degree[q2] += w

    interacting_logical = [q for q in logical_qubits if logical_degree.get(q, 0) > 0]

    # ---------------------------------------------------------------
    # Step 3: Physical graph properties
    # ---------------------------------------------------------------
    hw_adj = defaultdict(set)
    for pq in physical_qubits:
        for pq2 in self.backend.get(pq, []):
            hw_adj[pq].add(pq2)

    phys_degree = {pq: len(hw_adj[pq]) for pq in physical_qubits}
    phys_centrality = {}
    for pq in physical_qubits:
        phys_centrality[pq] = sum(dist[pq][pq2] for pq2 in physical_qubits)

    # ---------------------------------------------------------------
    # Step 4: Helper functions
    # ---------------------------------------------------------------
    def build_neighbors(weights):
        nbrs = defaultdict(dict)
        deg = defaultdict(float)
        for (q1, q2), w in weights.items():
            nbrs[q1][q2] = w
            nbrs[q2][q1] = w
            deg[q1] += w
            deg[q2] += w
        return nbrs, deg

    def compute_cost_nonlinear(m, weights, alpha_exp):
        cost = 0.0
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                d = dist[m[q1]][m[q2]]
                cost += w * (d ** alpha_exp)
        return cost

    def compute_cost(m, weights):
        cost = 0.0
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                cost += w * dist[m[q1]][m[q2]]
        return cost

    def delta_swap_cost_nonlinear(m, rm, pq_a, pq_b, nbrs, alpha_exp):
        lq_a, lq_b = rm[pq_a], rm[pq_b]
        delta = 0.0
        affected = set()
        if lq_a in nbrs:
            affected.update(nbrs[lq_a].keys())
        if lq_b in nbrs:
            affected.update(nbrs[lq_b].keys())
        for q in affected:
            if q == lq_a or q == lq_b:
                continue
            pq_q = m[q]
            w_a = nbrs.get(lq_a, {}).get(q, 0.0)
            if w_a > 0:
                old_d = dist[pq_a][pq_q] ** alpha_exp
                new_d = dist[pq_b][pq_q] ** alpha_exp
                delta += w_a * (new_d - old_d)
            w_b = nbrs.get(lq_b, {}).get(q, 0.0)
            if w_b > 0:
                old_d = dist[pq_b][pq_q] ** alpha_exp
                new_d = dist[pq_a][pq_q] ** alpha_exp
                delta += w_b * (new_d - old_d)
        return delta

    def do_swap(m, rm, pq_a, pq_b):
        lq_a, lq_b = rm[pq_a], rm[pq_b]
        m[lq_a], m[lq_b] = pq_b, pq_a
        rm[pq_a], rm[pq_b] = lq_b, lq_a

    # ---------------------------------------------------------------
    # Step 5: A* early-layer routing with adaptive node limit
    # ---------------------------------------------------------------
    ASTAR_LAYERS = 5
    n_2q = len(gates_2q)
    if n_2q < 50:
        ASTAR_NODE_LIMIT = 8000
    elif n_2q < 200:
        ASTAR_NODE_LIMIT = 5000
    else:
        ASTAR_NODE_LIMIT = 3000

    pred_rem_layer = {g: len(dag2q_pred[g]) for g in gates_2q}
    front_layer_calc = set(g for g in gates_2q if pred_rem_layer[g] == 0)
    current_layer = 0
    early_layer_gates = set()

    temp_front = set(front_layer_calc)
    while temp_front:
        for g in temp_front:
            if current_layer < ASTAR_LAYERS:
                early_layer_gates.add(g)
        next_front = set()
        for g in temp_front:
            for s in dag2q_succ[g]:
                pred_rem_layer[s] -= 1
                if pred_rem_layer[s] == 0:
                    next_front.add(s)
        current_layer += 1
        temp_front = next_front

    # ---------------------------------------------------------------
    # Step 6: A*-guided routing for early layers
    # ---------------------------------------------------------------
    def astar_routing_early(m, rm):
        if not early_layer_gates:
            return defaultdict(float), 0

        early_pred = {}
        for g in early_layer_gates:
            early_pred[g] = len(dag2q_pred[g] & early_layer_gates)

        initial_front = frozenset(g for g in early_layer_gates if early_pred[g] == 0)

        init_executed = set()
        cur_front = set(initial_front)
        changed = True
        while changed:
            changed = False
            newly_exec = set()
            for g in cur_front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = m[gq1], m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    newly_exec.add(g)
            if newly_exec:
                changed = True
                init_executed |= newly_exec
                cur_front -= newly_exec
                for g in newly_exec:
                    for s in dag2q_succ[g]:
                        if s in early_layer_gates and s not in init_executed:
                            all_pred_done = True
                            for p in dag2q_pred[s]:
                                if p in early_layer_gates and p not in init_executed:
                                    all_pred_done = False
                                    break
                            if all_pred_done:
                                cur_front.add(s)

        remaining_early = early_layer_gates - init_executed
        if not remaining_early:
            return defaultdict(float), 0

        def compute_front(executed):
            front = set()
            for g in early_layer_gates:
                if g in executed:
                    continue
                all_pred = True
                for p in dag2q_pred[g]:
                    if p in early_layer_gates and p not in executed:
                        all_pred = False
                        break
                if all_pred:
                    front.add(g)
            return frozenset(front)

        init_exec_frozen = frozenset(init_executed)
        init_front_astar = compute_front(init_executed)

        active_logical = set()
        for g in remaining_early:
            gq1, gq2 = gates_2q[g]
            active_logical.add(gq1)
            active_logical.add(gq2)

        def h_func(mapping, front_gates):
            h = 0
            for g in front_gates:
                gq1, gq2 = gates_2q[g]
                h += dist[mapping[gq1]][mapping[gq2]]
            return h

        active_logical_list = sorted(active_logical)

        def mapping_key(mapping):
            return tuple(mapping[lq] for lq in active_logical_list)

        init_m = list(m)
        init_h = h_func(init_m, init_front_astar)

        counter = [0]
        start_state = (init_h, 0, 0, init_m, init_exec_frozen, init_front_astar)
        open_heap = [start_state]
        visited = {}
        best_known_total = float('inf')
        best_result = None

        swap_history = {}
        init_key = (mapping_key(init_m), init_exec_frozen)
        swap_history[init_key] = defaultdict(float)

        expansions = 0

        while open_heap and expansions < ASTAR_NODE_LIMIT:
            f, _, g_cost, cur_m_list, executed, front = heapq.heappop(open_heap)

            mk = mapping_key(cur_m_list)
            state_key = (mk, executed)

            if state_key in visited and visited[state_key] <= g_cost:
                continue
            visited[state_key] = g_cost

            if best_known_total < float('inf') and f > best_known_total * 1.2:
                continue

            new_executed = set(executed)
            new_front = set(front)
            progress = True
            while progress:
                progress = False
                newly_exec = set()
                for g in list(new_front):
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = cur_m_list[gq1], cur_m_list[gq2]
                    if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                        newly_exec.add(g)
                if newly_exec:
                    progress = True
                    new_executed |= newly_exec
                    new_front -= newly_exec
                    for g in newly_exec:
                        for s in dag2q_succ[g]:
                            if s in early_layer_gates and s not in new_executed:
                                all_pred = True
                                for p in dag2q_pred[s]:
                                    if p in early_layer_gates and p not in new_executed:
                                        all_pred = False
                                        break
                                if all_pred:
                                    new_front.add(s)

            new_exec_frozen = frozenset(new_executed)
            new_front_frozen = frozenset(new_front)

            if not (early_layer_gates - new_executed):
                if g_cost < best_known_total:
                    best_known_total = g_cost
                    parent_key = (mk, executed)
                    pair_swaps = dict(swap_history.get(parent_key, {}))
                    best_result = (g_cost, pair_swaps)
                continue

            if not new_front_frozen:
                continue

            active_phys = set()
            for g in new_front_frozen:
                gq1, gq2 = gates_2q[g]
                active_phys.add(cur_m_list[gq1])
                active_phys.add(cur_m_list[gq2])
            ext_gates = set()
            for g in new_front_frozen:
                for s in dag2q_succ[g]:
                    if s in early_layer_gates and s not in new_executed:
                        ext_gates.add(s)
            for g in ext_gates:
                gq1, gq2 = gates_2q[g]
                active_phys.add(cur_m_list[gq1])
                active_phys.add(cur_m_list[gq2])

            swaps = set()
            for pq in active_phys:
                for nb in hw_adj.get(pq, set()):
                    swaps.add((min(pq, nb), max(pq, nb)))

            expansions += 1
            parent_pair_swaps = swap_history.get((mk, executed), defaultdict(float))

            for (s1, s2) in swaps:
                new_m = list(cur_m_list)
                lq_at_s1 = -1
                lq_at_s2 = -1
                for lq in range(num_q):
                    if new_m[lq] == s1:
                        lq_at_s1 = lq
                    if new_m[lq] == s2:
                        lq_at_s2 = lq

                if lq_at_s1 >= 0:
                    new_m[lq_at_s1] = s2
                if lq_at_s2 >= 0:
                    new_m[lq_at_s2] = s1

                new_g = g_cost + 1
                new_mk = mapping_key(new_m)
                child_key = (new_mk, new_exec_frozen)

                if child_key in visited and visited[child_key] <= new_g:
                    continue

                new_h = h_func(new_m, new_front_frozen)
                new_f = new_g + new_h

                if best_known_total < float('inf') and new_f > best_known_total * 1.2:
                    continue

                counter[0] += 1

                child_pair_swaps = defaultdict(float, parent_pair_swaps)
                for g in new_front_frozen:
                    gq1, gq2 = gates_2q[g]
                    pair_key = (min(gq1, gq2), max(gq1, gq2))
                    child_pair_swaps[pair_key] += 1.0

                swap_history[child_key] = child_pair_swaps

                heapq.heappush(open_heap, (new_f, counter[0], new_g, new_m, new_exec_frozen, new_front_frozen))

        if best_result is not None:
            return defaultdict(float, best_result[1]), best_result[0]
        else:
            return defaultdict(float), 0

    # ---------------------------------------------------------------
    # Step 7: Forward greedy routing simulation with congestion-cascading
    #   Novel: accumulated pressure biases swap scoring during simulation
    # ---------------------------------------------------------------
    def simulate_routing_greedy(m, rm, max_layers=20, pair_pressure=None):
        sim_m = list(m)
        sim_rm = list(rm)
        swap_counts = defaultdict(float)
        total_swaps = 0

        if not gates_2q:
            return swap_counts, total_swaps

        # Build per-pair pressure lookup for congestion-cascading
        pp = pair_pressure if pair_pressure else {}
        max_pp = max(pp.values()) if pp else 1.0

        pred_remaining = {g: len(dag2q_pred[g]) for g in gates_2q}
        front = set(g for g in gates_2q if pred_remaining[g] == 0)
        layers_done = 0

        while front and layers_done < max_layers:
            executable = []
            for g in front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = sim_m[gq1], sim_m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    executable.append(g)

            if executable:
                for g in executable:
                    front.discard(g)
                    for s in dag2q_succ[g]:
                        pred_remaining[s] -= 1
                        if pred_remaining[s] == 0:
                            front.add(s)
                layers_done += 1
                continue

            active_phys = set()
            for g in front:
                gq1, gq2 = gates_2q[g]
                active_phys.add(sim_m[gq1])
                active_phys.add(sim_m[gq2])

            candidates_sw = set()
            for pq in active_phys:
                for nb in self.backend.get(pq, []):
                    candidates_sw.add((min(pq, nb), max(pq, nb)))

            best_swap, best_score = None, float('inf')
            for (s1, s2) in candidates_sw:
                l1, l2 = sim_rm[s1], sim_rm[s2]
                score = 0.0
                for g in front:
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = sim_m[gq1], sim_m[gq2]
                    if gq1 == l1: p1 = s2
                    elif gq1 == l2: p1 = s1
                    if gq2 == l1: p2 = s2
                    elif gq2 == l2: p2 = s1
                    deps = dep_count.get(g, 0) + 1
                    d = dist[p1][p2]
                    # Congestion-cascading: amplify score for pairs with high
                    # accumulated pressure — forces routing sim to prioritize
                    # resolving historically congested pairs
                    if pp:
                        pair_key = (min(gq1, gq2), max(gq1, gq2))
                        pressure_mult = 1.0 + 0.3 * pp.get(pair_key, 0.0) / (max_pp + 1e-10)
                        score += deps * d * pressure_mult
                    else:
                        score += deps * d
                if score < best_score:
                    best_score = score
                    best_swap = (s1, s2)

            if best_swap is None:
                break

            s1, s2 = best_swap
            l1, l2 = sim_rm[s1], sim_rm[s2]
            sim_m[l1], sim_m[l2] = s2, s1
            sim_rm[s1], sim_rm[s2] = l2, l1
            total_swaps += 1

            for g in front:
                gq1, gq2 = gates_2q[g]
                pair_key = (min(gq1, gq2), max(gq1, gq2))
                swap_counts[pair_key] += 1.0

        return swap_counts, total_swaps

    # ---------------------------------------------------------------
    # Step 7b: Backward greedy routing simulation with congestion-cascading
    # ---------------------------------------------------------------
    def simulate_routing_backward(m, rm, max_layers=20, pair_pressure=None):
        sim_m = list(m)
        sim_rm = list(rm)
        swap_counts = defaultdict(float)
        total_swaps = 0

        if not gates_2q:
            return swap_counts, total_swaps

        pp = pair_pressure if pair_pressure else {}
        max_pp = max(pp.values()) if pp else 1.0

        succ_remaining = {g: len(dag2q_succ[g] & set(gates_2q.keys())) for g in gates_2q}
        front = set(g for g in gates_2q if succ_remaining[g] == 0)
        layers_done = 0

        while front and layers_done < max_layers:
            executable = []
            for g in front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = sim_m[gq1], sim_m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    executable.append(g)

            if executable:
                for g in executable:
                    front.discard(g)
                    for p in dag2q_pred[g]:
                        if p in gates_2q:
                            succ_remaining[p] -= 1
                            if succ_remaining[p] == 0:
                                front.add(p)
                layers_done += 1
                continue

            active_phys = set()
            for g in front:
                gq1, gq2 = gates_2q[g]
                active_phys.add(sim_m[gq1])
                active_phys.add(sim_m[gq2])

            candidates_sw = set()
            for pq in active_phys:
                for nb in self.backend.get(pq, []):
                    candidates_sw.add((min(pq, nb), max(pq, nb)))

            best_swap, best_score = None, float('inf')
            for (s1, s2) in candidates_sw:
                l1, l2 = sim_rm[s1], sim_rm[s2]
                score = 0.0
                for g in front:
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = sim_m[gq1], sim_m[gq2]
                    if gq1 == l1: p1 = s2
                    elif gq1 == l2: p1 = s1
                    if gq2 == l1: p2 = s2
                    elif gq2 == l2: p2 = s1
                    deps = bwd_dep.get(g, 0) + 1
                    d = dist[p1][p2]
                    if pp:
                        pair_key = (min(gq1, gq2), max(gq1, gq2))
                        pressure_mult = 1.0 + 0.3 * pp.get(pair_key, 0.0) / (max_pp + 1e-10)
                        score += deps * d * pressure_mult
                    else:
                        score += deps * d
                if score < best_score:
                    best_score = score
                    best_swap = (s1, s2)

            if best_swap is None:
                break

            s1, s2 = best_swap
            l1, l2 = sim_rm[s1], sim_rm[s2]
            sim_m[l1], sim_m[l2] = s2, s1
            sim_rm[s1], sim_rm[s2] = l2, l1
            total_swaps += 1

            for g in front:
                gq1, gq2 = gates_2q[g]
                pair_key = (min(gq1, gq2), max(gq1, gq2))
                swap_counts[pair_key] += 1.0

        return swap_counts, total_swaps

    # ---------------------------------------------------------------
    # Step 7c: Asymmetric bidirectional routing (forward-biased 0.6/0.4)
    # ---------------------------------------------------------------
    def simulate_routing_asymmetric_bidir(m, rm, max_layers=20, pair_pressure=None):
        fwd_swaps, fwd_total = simulate_routing_greedy(m, rm, max_layers=max_layers, pair_pressure=pair_pressure)
        bwd_swaps, bwd_total = simulate_routing_backward(m, rm, max_layers=max_layers, pair_pressure=pair_pressure)

        combined = defaultdict(float)
        all_keys = set(fwd_swaps.keys()) | set(bwd_swaps.keys())
        for key in all_keys:
            combined[key] = 0.6 * fwd_swaps.get(key, 0.0) + 0.4 * bwd_swaps.get(key, 0.0)

        return combined, (fwd_total + bwd_total) // 2

    # ---------------------------------------------------------------
    # Step 7d: Hybrid A* + greedy routing
    # ---------------------------------------------------------------
    def simulate_routing_hybrid(m, rm, max_layers=20, pair_pressure=None):
        astar_swaps, astar_total = astar_routing_early(m, rm)
        greedy_swaps, greedy_total = simulate_routing_greedy(m, rm, max_layers=max_layers, pair_pressure=pair_pressure)

        combined_swaps = defaultdict(float)
        early_pairs = set()
        for g in early_layer_gates:
            gq1, gq2 = gates_2q[g]
            early_pairs.add((min(gq1, gq2), max(gq1, gq2)))

        for pair_key in early_pairs:
            if pair_key in astar_swaps:
                combined_swaps[pair_key] = astar_swaps[pair_key]

        for pair_key, count in greedy_swaps.items():
            if pair_key not in early_pairs:
                combined_swaps[pair_key] = count

        return combined_swaps, astar_total + greedy_total

    # ---------------------------------------------------------------
    # Step 7e: Hybrid A* + asymmetric bidirectional
    # ---------------------------------------------------------------
    def simulate_routing_hybrid_bidir(m, rm, max_layers=20, pair_pressure=None):
        astar_swaps, astar_total = astar_routing_early(m, rm)
        fwd_swaps, fwd_total = simulate_routing_greedy(m, rm, max_layers=max_layers, pair_pressure=pair_pressure)
        bwd_swaps, bwd_total = simulate_routing_backward(m, rm, max_layers=max_layers, pair_pressure=pair_pressure)

        combined_swaps = defaultdict(float)
        early_pairs = set()
        for g in early_layer_gates:
            gq1, gq2 = gates_2q[g]
            early_pairs.add((min(gq1, gq2), max(gq1, gq2)))

        for pair_key in early_pairs:
            if pair_key in astar_swaps:
                combined_swaps[pair_key] = astar_swaps[pair_key]

        all_late_keys = (set(fwd_swaps.keys()) | set(bwd_swaps.keys())) - early_pairs
        for pair_key in all_late_keys:
            combined_swaps[pair_key] = 0.6 * fwd_swaps.get(pair_key, 0.0) + 0.4 * bwd_swaps.get(pair_key, 0.0)

        return combined_swaps, astar_total + (fwd_total + bwd_total) // 2

    # ---------------------------------------------------------------
    # Step 8: Seed generation setup
    # ---------------------------------------------------------------
    sorted_by_degree = sorted(interacting_logical, key=lambda q: logical_degree[q], reverse=True)
    seed_lqs = sorted_by_degree[:min(3, len(sorted_by_degree))]
    phys_by_centrality = sorted(physical_qubits, key=lambda pq: phys_centrality[pq])
    seed_pqs = phys_by_centrality[:min(3, len(phys_by_centrality))]

    logical_degree_ranked = sorted(interacting_logical, key=lambda q: logical_degree[q], reverse=True)
    logical_degree_rank = {q: i for i, q in enumerate(logical_degree_ranked)}
    max_logical_rank = max(len(logical_degree_ranked) - 1, 1)
    phys_degree_ranked = sorted(physical_qubits, key=lambda pq: phys_degree[pq], reverse=True)
    phys_degree_rank = {pq: i for i, pq in enumerate(phys_degree_ranked)}
    max_phys_rank = max(len(phys_degree_ranked) - 1, 1)

    static_nbrs, static_deg = build_neighbors(static_weight)
    max_iw = max(static_weight.values()) if static_weight else 1.0

    # ---------------------------------------------------------------
    # Step 9: Routing-Pressure-Aware Conflict-Graph MIS Seed
    # ---------------------------------------------------------------
    def conflict_graph_seed(start_pq, nbrs, deg, weights, routing_pressure=None):
        if len(interacting_logical) < 2:
            return None, None

        cur_max_iw = max(weights.values()) if weights else 1.0

        top_partners = {}
        for lq in interacting_logical:
            nbr_list = sorted(nbrs.get(lq, {}).items(), key=lambda x: x[1], reverse=True)
            top_partners[lq] = set(p for p, _ in nbr_list[:3])

        conflict_adj = defaultdict(set)
        il = interacting_logical

        qubit_pressure = defaultdict(float)
        if routing_pressure:
            for (q1, q2), cnt in routing_pressure.items():
                qubit_pressure[q1] += cnt
                qubit_pressure[q2] += cnt

        for i in range(len(il)):
            for j in range(i + 1, len(il)):
                l1, l2 = il[i], il[j]
                s1 = top_partners.get(l1, set())
                s2 = top_partners.get(l2, set())
                if not s1 and not s2:
                    continue
                intersection = len(s1 & s2)
                union = len(s1 | s2)
                if union > 0:
                    jaccard = intersection / union
                    threshold = 0.5
                    if routing_pressure and qubit_pressure[l1] > 0 and qubit_pressure[l2] > 0:
                        max_pressure = max(qubit_pressure.values()) if qubit_pressure else 1.0
                        pressure_factor = min(1.0, (qubit_pressure[l1] + qubit_pressure[l2]) /
                                              (max_pressure * 2 + 1e-10))
                        threshold = max(0.25, 0.5 - 0.25 * pressure_factor)
                    if jaccard > threshold:
                        conflict_adj[l1].add(l2)
                        conflict_adj[l2].add(l1)

        sorted_by_deg_local = sorted(interacting_logical,
                                     key=lambda q: (deg.get(q, 0), qubit_pressure.get(q, 0)),
                                     reverse=True)
        mis = set()
        excluded = set()
        for lq in sorted_by_deg_local:
            if lq not in excluded:
                mis.add(lq)
                for neighbor in conflict_adj.get(lq, set()):
                    excluded.add(neighbor)

        non_mis = [lq for lq in sorted_by_deg_local if lq not in mis]
        mis_ordered = sorted(mis, key=lambda q: (deg.get(q, 0), qubit_pressure.get(q, 0)),
                             reverse=True)

        m = [-1] * num_q
        rm = [-1] * num_q
        used_phys = set()

        if mis_ordered:
            first_lq = mis_ordered[0]
            m[first_lq] = start_pq
            rm[start_pq] = first_lq
            used_phys.add(start_pq)

            for lq in mis_ordered[1:]:
                nbrs_placed = {}
                for plq in mis:
                    if m[plq] >= 0 and plq in nbrs.get(lq, {}):
                        nbrs_placed[plq] = nbrs[lq][plq]

                if nbrs_placed:
                    best_pq = None
                    best_score = float('inf')
                    for pq in physical_qubits:
                        if pq in used_phys:
                            continue
                        score = 0.0
                        for plq, iw in nbrs_placed.items():
                            d = dist[pq][m[plq]]
                            cost = iw * d
                            if m[plq] in hw_adj[pq]:
                                cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                            score += cost
                        if score < best_score:
                            best_score = score
                            best_pq = pq
                else:
                    best_pq = None
                    best_score = float('inf')
                    for pq in physical_qubits:
                        if pq not in used_phys:
                            if phys_centrality[pq] < best_score:
                                best_score = phys_centrality[pq]
                                best_pq = pq

                if best_pq is not None:
                    m[lq] = best_pq
                    rm[best_pq] = lq
                    used_phys.add(best_pq)

        placed_set = set(lq for lq in interacting_logical if m[lq] >= 0)

        for lq in non_mis:
            nbrs_placed = {}
            for plq in placed_set:
                w = nbrs.get(lq, {}).get(plq, 0.0)
                if w > 0:
                    nbrs_placed[plq] = w

            if nbrs_placed:
                near_ties = []
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq in used_phys:
                        continue
                    score = 0.0
                    for plq, iw in nbrs_placed.items():
                        d = dist[pq][m[plq]]
                        cost = iw * d
                        if m[plq] in hw_adj[pq]:
                            cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                        score += cost
                    near_ties.append((score, pq))
                    if score < best_score:
                        best_score = score

                if near_ties and best_score > 0:
                    threshold = best_score * 1.05
                    candidates_list = [(s, pq) for s, pq in near_ties if s <= threshold]
                    if len(candidates_list) > 1 and lq in logical_degree_rank:
                        lq_rn = logical_degree_rank[lq] / max_logical_rank
                        best_pq = min(candidates_list, key=lambda x: (
                            abs(phys_degree_rank[x[1]] / max_phys_rank - lq_rn), x[0]))[1]
                    else:
                        best_pq = min(candidates_list, key=lambda x: x[0])[1]
                elif near_ties:
                    best_pq = min(near_ties, key=lambda x: x[0])[1]
                else:
                    best_pq = None
            else:
                best_pq = None
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq not in used_phys:
                        if phys_centrality[pq] < best_score:
                            best_score = phys_centrality[pq]
                            best_pq = pq

            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                used_phys.add(best_pq)
                placed_set.add(lq)

        remaining_lqs = [lq for lq in logical_qubits if m[lq] == -1]
        for lq in remaining_lqs:
            best_pq = None
            best_score = float('inf')
            for pq in physical_qubits:
                if pq not in used_phys:
                    if phys_centrality[pq] < best_score:
                        best_score = phys_centrality[pq]
                        best_pq = pq
            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                used_phys.add(best_pq)

        return m, rm

    # ---------------------------------------------------------------
    # Step 10: Spectral ordering seed
    # ---------------------------------------------------------------
    def spectral_seed():
        if len(interacting_logical) < 3:
            return None, None

        idx_map = {q: i for i, q in enumerate(interacting_logical)}
        n = len(interacting_logical)

        L = [[0.0] * n for _ in range(n)]
        for (q1, q2), w in static_weight.items():
            if q1 in idx_map and q2 in idx_map:
                i, j = idx_map[q1], idx_map[q2]
                L[i][j] -= w
                L[j][i] -= w
                L[i][i] += w
                L[j][j] += w

        def power_iter(mat, n_iter=200):
            v = [random.gauss(0, 1) for _ in range(n)]
            for _ in range(n_iter):
                new_v = [0.0] * n
                for i in range(n):
                    for j in range(n):
                        new_v[i] += mat[i][j] * v[j]
                norm = math.sqrt(sum(x * x for x in new_v)) or 1e-12
                v = [x / norm for x in new_v]
            return v

        max_diag = max(L[i][i] for i in range(n)) + 1.0
        shifted = [[0.0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                shifted[i][j] = -L[i][j]
            shifted[i][i] += max_diag

        v1 = power_iter(shifted, 150)

        dot_v1 = sum(x * x for x in v1) or 1e-12
        lam1_shifted = sum(v1[i] * sum(shifted[i][j] * v1[j] for j in range(n)) for i in range(n)) / dot_v1
        shifted2 = [row[:] for row in shifted]
        for i in range(n):
            for j in range(n):
                shifted2[i][j] -= lam1_shifted * v1[i] * v1[j] / dot_v1

        fiedler = power_iter(shifted2, 200)

        fiedler_order = sorted(range(n), key=lambda i: fiedler[i])
        sorted_logical = [interacting_logical[i] for i in fiedler_order]

        phys_sorted = sorted(physical_qubits, key=lambda pq: phys_centrality[pq])
        start_pq = phys_sorted[0]
        visited_bfs = set()
        bfs_order = []
        bfs_q = deque([start_pq])
        visited_bfs.add(start_pq)
        while bfs_q:
            pq = bfs_q.popleft()
            bfs_order.append(pq)
            for nb in sorted(hw_adj[pq]):
                if nb not in visited_bfs:
                    visited_bfs.add(nb)
                    bfs_q.append(nb)
        for pq in physical_qubits:
            if pq not in visited_bfs:
                bfs_order.append(pq)
                visited_bfs.add(pq)

        m = [-1] * num_q
        rm = [-1] * num_q
        n_interact = len(sorted_logical)
        n_phys = len(bfs_order)
        offset = max(0, (n_phys - n_interact) // 2)
        for i, lq in enumerate(sorted_logical):
            pq = bfs_order[min(offset + i, n_phys - 1)]
            if rm[pq] != -1:
                best_pq = None
                best_d = float('inf')
                for cpq in physical_qubits:
                    if rm[cpq] == -1:
                        d = dist[pq][cpq]
                        if d < best_d:
                            best_d = d
                            best_pq = cpq
                pq = best_pq
            m[lq] = pq
            rm[pq] = lq

        return m, rm

    # ---------------------------------------------------------------
    # Step 11: Greedy placement
    # ---------------------------------------------------------------
    def run_greedy_placement(start_lq, start_pq, nbrs, deg, weights=None):
        cur_max_iw = max(weights.values()) if weights else max_iw
        used_phys = {start_pq}
        m = [-1] * num_q
        rm = [-1] * num_q
        m[start_lq] = start_pq
        rm[start_pq] = start_lq
        placed = {start_lq}
        remaining = set(logical_qubits) - placed

        while remaining:
            best_lq, best_w = None, -1.0
            for lq in remaining:
                w = sum(nbrs.get(lq, {}).get(plq, 0.0) for plq in placed)
                if w > best_w:
                    best_w = w
                    best_lq = lq

            nbrs_placed = {plq: nbrs.get(best_lq, {}).get(plq, 0.0)
                           for plq in placed if plq in nbrs.get(best_lq, {})}

            if nbrs_placed:
                near_ties = []
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq in used_phys:
                        continue
                    score = 0.0
                    for plq, iw in nbrs_placed.items():
                        d = dist[pq][m[plq]]
                        cost = iw * d
                        if m[plq] in hw_adj[pq]:
                            cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                        score += cost
                    near_ties.append((score, pq))
                    if score < best_score:
                        best_score = score

                if near_ties and best_score > 0:
                    threshold = best_score * 1.05
                    candidates_list = [(s, pq) for s, pq in near_ties if s <= threshold]
                    if len(candidates_list) > 1 and best_lq in logical_degree_rank:
                        lq_rn = logical_degree_rank[best_lq] / max_logical_rank
                        best_pq = min(candidates_list, key=lambda x: (
                            abs(phys_degree_rank[x[1]] / max_phys_rank - lq_rn), x[0]))[1]
                    else:
                        best_pq = min(candidates_list, key=lambda x: x[0])[1]
                elif near_ties:
                    best_pq = min(near_ties, key=lambda x: x[0])[1]
                else:
                    best_pq = None
            else:
                best_pq = None
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq not in used_phys:
                        score = phys_centrality[pq]
                        if score < best_score:
                            best_score = score
                            best_pq = pq

            m[best_lq] = best_pq
            rm[best_pq] = best_lq
            used_phys.add(best_pq)
            placed.add(best_lq)
            remaining.discard(best_lq)
        return m, rm

    def fill_unmapped(m, rm):
        unmapped = [q for q in range(num_q) if m[q] == -1]
        free = [pq for pq in range(num_q) if rm[pq] == -1]
        for lq, pq in zip(unmapped, free):
            m[lq] = pq
            rm[pq] = lq

    # ---------------------------------------------------------------
    # Step 12: Congestion-biased local search with nonlinear distance penalty
    #   From Parent 2: congestion_bonus amplifies improving swaps on
    #   congested hardware edges
    # ---------------------------------------------------------------
    def local_search(m, rm, nbrs, weights, alpha_exp, max_rounds=5,
                     congestion_bonus=None):
        if len(interacting_logical) <= 1:
            return compute_cost_nonlinear(m, weights, alpha_exp)

        hw_edge_congestion = defaultdict(float)
        if congestion_bonus:
            for (q1, q2), pressure in congestion_bonus.items():
                pq1, pq2 = m[q1], m[q2]
                hw_edge_congestion[(min(pq1, pq2), max(pq1, pq2))] += pressure

        for _ in range(max_rounds):
            improved = False
            best_d, best_pair = 0.0, None
            active_phys = [m[q] for q in interacting_logical]

            for pq1 in active_phys:
                for pq2 in hw_adj.get(pq1, set()):
                    d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                    edge_key = (min(pq1, pq2), max(pq1, pq2))
                    if edge_key in hw_edge_congestion and d < 0:
                        d *= (1.0 + 0.15 * min(1.0, hw_edge_congestion[edge_key]))
                    if d < best_d:
                        best_d = d
                        best_pair = (pq1, pq2)

            n_random = min(150, len(interacting_logical) * 3)
            for _ in range(n_random):
                i, j = random.sample(range(len(interacting_logical)), 2)
                pq1, pq2 = m[interacting_logical[i]], m[interacting_logical[j]]
                d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                if d < best_d:
                    best_d = d
                    best_pair = (pq1, pq2)

            if best_pair and best_d < -1e-12:
                do_swap(m, rm, *best_pair)
                improved = True
            if not improved:
                for i in range(len(interacting_logical)):
                    for j in range(i + 1, len(interacting_logical)):
                        pq1, pq2 = m[interacting_logical[i]], m[interacting_logical[j]]
                        d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                        if d < best_d:
                            best_d = d
                            best_pair = (pq1, pq2)
                if best_pair and best_d < -1e-12:
                    do_swap(m, rm, *best_pair)
                else:
                    break
        return compute_cost_nonlinear(m, weights, alpha_exp)

    # ---------------------------------------------------------------
    # Step 13: Perturbation modes with bandit selection
    #   Merged: 6 modes from Parent 2 (includes congestion-directed)
    #   + pressure-guided LNS from Parent 1
    # ---------------------------------------------------------------
    rsdiwr_iter_ref = [0]
    accumulated_routing_pressure_ref = [defaultdict(float)]

    def perturb_random(m, rm, **kw):
        if len(interacting_logical) >= 2:
            lqs = random.sample(interacting_logical, 2)
            do_swap(m, rm, m[lqs[0]], m[lqs[1]])

    def perturb_segment_shuffle(m, rm, **kw):
        k = min(random.randint(3, 5), len(interacting_logical))
        if k < 2:
            perturb_random(m, rm)
            return
        lqs = random.sample(interacting_logical, k)
        phys_positions = [m[lq] for lq in lqs]
        random.shuffle(phys_positions)
        for lq in lqs:
            rm[m[lq]] = -1
        for lq, pq in zip(lqs, phys_positions):
            m[lq] = pq
            rm[pq] = lq

    def perturb_worst_pair(m, rm, weights=None, alpha_exp=1.5, **kw):
        if weights is None:
            perturb_random(m, rm)
            return
        pair_costs = []
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                d = dist[m[q1]][m[q2]]
                c = w * (d ** alpha_exp)
                pair_costs.append((c, q1, q2))
        if not pair_costs:
            return
        pair_costs.sort(reverse=True)
        top_n = min(3, len(pair_costs))
        _, tq1, tq2 = pair_costs[random.randint(0, top_n - 1)]
        pq1, pq2 = m[tq1], m[tq2]
        adj_of_pq2 = list(hw_adj.get(pq2, set()))
        if adj_of_pq2:
            target = random.choice(adj_of_pq2)
            if target != pq1:
                do_swap(m, rm, pq1, target)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    def perturb_edge_targeted(m, rm, weights=None, alpha_exp=1.5, **kw):
        if weights is None:
            perturb_random(m, rm)
            return
        edge_costs = []
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                c = w * (dist[m[q1]][m[q2]] ** alpha_exp)
                edge_costs.append((c, q1, q2))
        if not edge_costs:
            return
        edge_costs.sort(reverse=True)
        top_n = min(5, len(edge_costs))
        _, eq1, eq2 = edge_costs[random.randint(0, top_n - 1)]
        pq1, pq2 = m[eq1], m[eq2]
        neighbors_of_pq2 = list(hw_adj.get(pq2, set()))
        if neighbors_of_pq2:
            target = random.choice(neighbors_of_pq2)
            if target != pq1:
                do_swap(m, rm, pq1, target)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    def perturb_lns(m, rm, nbrs=None, alpha_exp=1.5, **kw):
        if nbrs is None or len(interacting_logical) < 3:
            perturb_random(m, rm)
            return
        base_lo = 3 + rsdiwr_iter_ref[0]
        base_hi = 8 + rsdiwr_iter_ref[0] * 2
        k = min(random.randint(base_lo, base_hi), len(interacting_logical))

        acc_pressure = accumulated_routing_pressure_ref[0]
        qubit_acc_pressure = defaultdict(float)
        for (q1, q2), cnt in acc_pressure.items():
            qubit_acc_pressure[q1] += cnt
            qubit_acc_pressure[q2] += cnt
        max_acc = max(qubit_acc_pressure.values()) if qubit_acc_pressure else 1.0

        qcost = {}
        for lq in interacting_logical:
            c = 0.0
            for partner, w in nbrs.get(lq, {}).items():
                if m[partner] >= 0 and m[lq] >= 0:
                    c += w * (dist[m[lq]][m[partner]] ** alpha_exp)
            pressure_bonus = qubit_acc_pressure.get(lq, 0.0) / (max_acc + 1e-10)
            qcost[lq] = c * (1.0 + 0.5 * pressure_bonus)

        sorted_qs = sorted(qcost, key=lambda q: qcost[q], reverse=True)
        top_half = sorted_qs[:max(k, len(sorted_qs) // 2)]
        subset = random.sample(top_half, min(k, len(top_half)))

        freed_phys = []
        for lq in subset:
            freed_phys.append(m[lq])
            rm[m[lq]] = -1
            m[lq] = -1

        placed_set = set(lq for lq in interacting_logical if m[lq] >= 0)
        for lq in sorted(subset, key=lambda q: qcost[q], reverse=True):
            best_pq, best_sc = None, float('inf')
            for pq in freed_phys:
                if rm[pq] != -1:
                    continue
                sc = 0.0
                for partner, w in nbrs.get(lq, {}).items():
                    if partner in placed_set and m[partner] >= 0:
                        sc += w * (dist[pq][m[partner]] ** alpha_exp)
                if sc < best_sc:
                    best_sc = sc
                    best_pq = pq
            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                placed_set.add(lq)
            else:
                for pq in freed_phys:
                    if rm[pq] == -1:
                        m[lq] = pq
                        rm[pq] = lq
                        placed_set.add(lq)
                        break

    # From Parent 2: congestion-directed perturbation
    def perturb_congestion_directed(m, rm, **kw):
        acc_pressure = accumulated_routing_pressure_ref[0]
        if not acc_pressure or len(interacting_logical) < 2:
            perturb_random(m, rm)
            return

        sorted_pairs = sorted(acc_pressure.items(), key=lambda x: x[1], reverse=True)
        top_n = min(4, len(sorted_pairs))
        (q1, q2), _ = sorted_pairs[random.randint(0, top_n - 1)]

        pq1, pq2 = m[q1], m[q2]
        adj_of_pq2 = list(hw_adj.get(pq2, set()))
        if adj_of_pq2:
            best_nb = min(adj_of_pq2, key=lambda nb: dist[pq1][nb])
            if best_nb != pq1:
                do_swap(m, rm, pq1, best_nb)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    perturbation_modes = [perturb_random, perturb_segment_shuffle,
                          perturb_worst_pair, perturb_edge_targeted,
                          perturb_lns, perturb_congestion_directed]
    K = len(perturbation_modes)

    WINDOW_SIZE = 100
    EPSILON = 0.1
    window = []
    mode_successes = [0] * K
    mode_attempts = [0] * K

    def select_perturbation_mode(phase_exploratory=True):
        if random.random() < EPSILON or sum(mode_attempts) < K * 2:
            return random.randint(0, K - 1)

        rates = []
        for k in range(K):
            if mode_attempts[k] > 0:
                rates.append(mode_successes[k] / mode_attempts[k])
            else:
                rates.append(1.0)

        # Dual-phase bias from Parent 2
        if phase_exploratory:
            for idx in [1, 4, 5]:
                rates[idx] *= 1.3
        else:
            for idx in [2, 3]:
                rates[idx] *= 1.3

        total = sum(rates)
        if total < 1e-12:
            return random.randint(0, K - 1)
        r = random.random() * total
        cumul = 0.0
        for k in range(K):
            cumul += rates[k]
            if r <= cumul:
                return k
        return K - 1

    def update_window(mode_idx, success):
        window.append((mode_idx, success))
        mode_attempts[mode_idx] += 1
        if success:
            mode_successes[mode_idx] += 1
        if len(window) > WINDOW_SIZE:
            old_mode, old_success = window.pop(0)
            mode_attempts[old_mode] -= 1
            if old_success:
                mode_successes[old_mode] -= 1

    # ---------------------------------------------------------------
    # Step 14: Build initial mapping candidates
    # ---------------------------------------------------------------
    candidates = []

    for s_lq in seed_lqs:
        for s_pq in seed_pqs:
            m, rm = run_greedy_placement(s_lq, s_pq, static_nbrs, static_deg,
                                         weights=static_weight)
            fill_unmapped(m, rm)
            cost = compute_cost(m, static_weight)
            candidates.append((cost, m, rm))

    for s_pq in seed_pqs:
        cg_m, cg_rm = conflict_graph_seed(s_pq, static_nbrs, static_deg, static_weight)
        if cg_m is not None:
            fill_unmapped(cg_m, cg_rm)
            cost = compute_cost(cg_m, static_weight)
            candidates.append((cost, cg_m, cg_rm))

    spec_m, spec_rm = spectral_seed()
    if spec_m is not None:
        fill_unmapped(spec_m, spec_rm)
        spec_cost = compute_cost(spec_m, static_weight)
        candidates.append((spec_cost, spec_m, spec_rm))

    m_rand = [-1] * num_q
    rm_rand = [-1] * num_q
    shuffled_phys = list(physical_qubits)
    random.shuffle(shuffled_phys)
    for i, lq in enumerate(logical_qubits):
        m_rand[lq] = shuffled_phys[i]
        rm_rand[shuffled_phys[i]] = lq
    fill_unmapped(m_rand, rm_rand)
    c = compute_cost(m_rand, static_weight)
    candidates.append((c, m_rand, rm_rand))

    if not candidates:
        self.mapping_dict = list(range(num_q))
        self.reverse_mapping_dict = list(range(num_q))
        if self.use_isl:
            self.isl_mapping = dict_to_isl_map(self.mapping_dict)
        return

    candidates.sort(key=lambda x: x[0])

    _, best_m, best_rm = candidates[0]
    best_m, best_rm = list(best_m), list(best_rm)
    local_search(best_m, best_rm, static_nbrs, static_weight, alpha_exp=2.0, max_rounds=6)
    best_cost = compute_cost(best_m, static_weight)

    for idx in range(1, min(5, len(candidates))):
        _, m_c, rm_c = candidates[idx]
        m_c, rm_c = list(m_c), list(rm_c)
        local_search(m_c, rm_c, static_nbrs, static_weight, alpha_exp=2.0, max_rounds=4)
        c = compute_cost(m_c, static_weight)
        if c < best_cost:
            best_cost = c
            best_m = list(m_c)
            best_rm = list(rm_c)

    # ---------------------------------------------------------------
    # Step 15: RSDIWR + Dual-Phase ILS with congestion-cascading routing,
    #   A*-guided first iteration, asymmetric bidirectional routing,
    #   pressure-adaptive blending, routing-pressure MIS reseeding,
    #   pressure-guided LNS, congestion-biased local search,
    #   congestion-directed perturbation, and adaptive phase ratio
    # ---------------------------------------------------------------
    time_budget = 25.0
    t_start = _time()
    n_rsdiwr = 4

    cur_m = list(best_m)
    cur_rm = list(best_rm)
    swap_counts = defaultdict(float)
    accumulated_routing_pressure = defaultdict(float)
    accumulated_routing_pressure_ref[0] = accumulated_routing_pressure

    for rsdiwr_iter in range(n_rsdiwr):
        rsdiwr_iter_ref[0] = rsdiwr_iter
        elapsed = _time() - t_start
        if elapsed > time_budget:
            break

        remaining_time = time_budget - elapsed
        remaining_iters = n_rsdiwr - rsdiwr_iter
        time_for_this_iter = remaining_time / max(remaining_iters, 1)
        n_ils = max(55, int(num_q * time_for_this_iter / 0.5)) if time_for_this_iter > 1.0 else max(30, num_q // 3)

        # Pressure-adaptive blending from Parent 1
        if rsdiwr_iter == 0 or not swap_counts:
            eff_weights = dict(static_weight)
        else:
            max_sw = max(swap_counts.values()) if swap_counts else 1.0
            scale = max(static_weight.values()) / max(max_sw, 1e-10)

            total_pressure = sum(accumulated_routing_pressure.values())
            n_pairs = len(accumulated_routing_pressure)
            avg_pressure = total_pressure / max(n_pairs, 1)
            pressure_adapt = min(0.15, 0.05 * avg_pressure / max(max_sw, 1e-10))
            alpha_blend = max(0.25, 1.0 - 0.3 * rsdiwr_iter - pressure_adapt)

            eff_weights = defaultdict(float)
            all_keys = set(static_weight.keys()) | set(swap_counts.keys())
            for key in all_keys:
                w_s = static_weight.get(key, 0.0)
                w_r = swap_counts.get(key, 0.0) * scale
                eff_weights[key] = alpha_blend * w_s + (1.0 - alpha_blend) * w_r

        eff_nbrs, eff_deg = build_neighbors(eff_weights)

        # Congestion bonus for local search from Parent 2
        congestion_bonus = None
        if accumulated_routing_pressure:
            max_acc_p = max(accumulated_routing_pressure.values()) if accumulated_routing_pressure else 1.0
            congestion_bonus = {k: v / (max_acc_p + 1e-10) for k, v in accumulated_routing_pressure.items()}

        # Re-seed with routing-informed weights + routing-pressure MIS
        if rsdiwr_iter > 0 and swap_counts and (_time() - t_start) < time_budget * 0.7:
            eff_sorted = sorted(interacting_logical,
                                key=lambda q: eff_deg.get(q, 0), reverse=True)
            reseed_lqs = eff_sorted[:min(2, len(eff_sorted))]
            reseed_pqs = seed_pqs[:min(2, len(seed_pqs))]

            for s_lq in reseed_lqs:
                for s_pq in reseed_pqs:
                    rm_new, rmm_new = run_greedy_placement(
                        s_lq, s_pq, eff_nbrs, eff_deg, weights=eff_weights)
                    fill_unmapped(rm_new, rmm_new)
                    local_search(rm_new, rmm_new, eff_nbrs, eff_weights,
                                 alpha_exp=2.0, max_rounds=3,
                                 congestion_bonus=congestion_bonus)
                    sc = compute_cost(rm_new, static_weight)
                    if sc < best_cost:
                        best_cost = sc
                        best_m = list(rm_new)
                        best_rm = list(rmm_new)
                        cur_m = list(rm_new)
                        cur_rm = list(rmm_new)

            for s_pq in reseed_pqs:
                cg_m, cg_rm = conflict_graph_seed(
                    s_pq, eff_nbrs, eff_deg, eff_weights,
                    routing_pressure=accumulated_routing_pressure)
                if cg_m is not None:
                    fill_unmapped(cg_m, cg_rm)
                    local_search(cg_m, cg_rm, eff_nbrs, eff_weights,
                                 alpha_exp=2.0, max_rounds=3,
                                 congestion_bonus=congestion_bonus)
                    sc = compute_cost(cg_m, static_weight)
                    if sc < best_cost:
                        best_cost = sc
                        best_m = list(cg_m)
                        best_rm = list(cg_rm)
                        cur_m = list(cg_m)
                        cur_rm = list(cg_rm)

        alpha_start = 2.0
        alpha_end = 1.0

        ls_rounds = 6 if rsdiwr_iter == 0 else 4
        cur_cost_nl = local_search(cur_m, cur_rm, eff_nbrs, eff_weights,
                                   alpha_exp=alpha_start, max_rounds=ls_rounds,
                                   congestion_bonus=congestion_bonus)

        static_cost = compute_cost(cur_m, static_weight)
        if static_cost < best_cost:
            best_cost = static_cost
            best_m = list(cur_m)
            best_rm = list(cur_rm)

        # Reset bandit window
        window.clear()
        for k in range(K):
            mode_successes[k] = 0
            mode_attempts[k] = 0

        T = max(cur_cost_nl * 0.05, 1.0)
        T_init = T
        alpha_sa = 0.94
        reheat_interval = max(n_ils // 4, 8)

        # Dual-phase from Parent 2 with adaptive ratio:
        # Earlier RSDIWR iterations get more exploration (70/30),
        # later iterations shift toward exploitation (50/50)
        explore_ratio = max(0.5, 0.7 - 0.07 * rsdiwr_iter)
        exploratory_cutoff = int(n_ils * explore_ratio)

        for ils_iter in range(n_ils):
            if _time() - t_start > time_budget:
                break

            progress = ils_iter / max(n_ils - 1, 1)
            alpha_exp = alpha_start + (alpha_end - alpha_start) * progress

            phase_exploratory = ils_iter < exploratory_cutoff

            saved_m = list(cur_m)
            saved_rm = list(cur_rm)
            saved_cost = cur_cost_nl

            mode = select_perturbation_mode(phase_exploratory=phase_exploratory)
            perturbation_modes[mode](cur_m, cur_rm,
                                    nbrs=eff_nbrs, weights=eff_weights,
                                    alpha_exp=alpha_exp)

            new_cost_nl = local_search(cur_m, cur_rm, eff_nbrs, eff_weights,
                                       alpha_exp=alpha_exp, max_rounds=3,
                                       congestion_bonus=congestion_bonus)

            success = new_cost_nl < saved_cost - 1e-12

            improvement = saved_cost - new_cost_nl
            if improvement > 0:
                cur_cost_nl = new_cost_nl
                sc = compute_cost(cur_m, static_weight)
                if sc < best_cost:
                    best_cost = sc
                    best_m = list(cur_m)
                    best_rm = list(cur_rm)
            elif random.random() < math.exp(min(0, improvement / max(T, 1e-10))):
                cur_cost_nl = new_cost_nl
            else:
                cur_m[:] = saved_m
                cur_rm[:] = saved_rm
                cur_cost_nl = saved_cost

            update_window(mode, success)

            T *= alpha_sa
            if (ils_iter + 1) % reheat_interval == 0:
                T = max(T, T_init * 0.35)

        # Routing simulation for RSDIWR feedback with congestion-cascading
        if rsdiwr_iter < n_rsdiwr - 1:
            sim_depth = 14 + rsdiwr_iter * 7

            # Pass accumulated pressure to routing sim for congestion-cascading
            # (only after first iteration when pressure data exists)
            routing_pressure_arg = accumulated_routing_pressure if rsdiwr_iter > 0 else None

            if rsdiwr_iter == 0 and early_layer_gates:
                swap_counts, _ = simulate_routing_hybrid(best_m, best_rm, max_layers=sim_depth, pair_pressure=routing_pressure_arg)
            elif rsdiwr_iter == 1 and early_layer_gates:
                swap_counts, _ = simulate_routing_hybrid_bidir(best_m, best_rm, max_layers=sim_depth, pair_pressure=routing_pressure_arg)
            else:
                swap_counts, _ = simulate_routing_asymmetric_bidir(best_m, best_rm, max_layers=sim_depth, pair_pressure=routing_pressure_arg)

            for pair_key, cnt in swap_counts.items():
                accumulated_routing_pressure[pair_key] += cnt

        cur_m = list(best_m)
        cur_rm = list(best_rm)
        cur_cost_nl = compute_cost_nonlinear(cur_m, eff_weights, alpha_end)

    # ---------------------------------------------------------------
    # Step 16: Set final mapping
    # ---------------------------------------------------------------
    self.mapping_dict = best_m
    self.reverse_mapping_dict = best_rm

    if self.use_isl:
        self.isl_mapping = dict_to_isl_map(self.mapping_dict)

def init_mapping(self):
    import math
    import random
    import heapq
    from collections import defaultdict, deque
    from time import time as _time

    num_q = self.num_qubits
    physical_qubits = sorted(self.backend.keys())
    dist = self.distance_matrix

    # ---------------------------------------------------------------
    # Step 1: Build DAG and topological layers
    # ---------------------------------------------------------------
    all_gates = sorted(self.access.keys())
    two_qubit_gates = [g for g in all_gates if len(self.access[g]) == 2]

    last_gate_on_qubit = {}
    successors_dag = defaultdict(set)
    predecessors_dag = defaultdict(set)
    for g in all_gates:
        for q in self.access[g]:
            if q in last_gate_on_qubit:
                pred = last_gate_on_qubit[q]
                successors_dag[pred].add(g)
                predecessors_dag[g].add(pred)
            last_gate_on_qubit[q] = g

    in_degree = {g: len(predecessors_dag[g]) for g in all_gates}
    gate_layer = {g: 0 for g in all_gates}
    temp_in = dict(in_degree)
    queue = deque(g for g in all_gates if in_degree[g] == 0)
    topo_order = []
    while queue:
        g = queue.popleft()
        topo_order.append(g)
        for s in successors_dag[g]:
            gate_layer[s] = max(gate_layer[s], gate_layer[g] + 1)
            temp_in[s] -= 1
            if temp_in[s] == 0:
                queue.append(s)

    critical_path = {g: 0 for g in all_gates}
    for g in reversed(topo_order):
        for s in successors_dag[g]:
            if critical_path[s] + 1 > critical_path[g]:
                critical_path[g] = critical_path[s] + 1

    # 2q DAG for routing simulation
    gates_2q = {}
    dag2q_succ = defaultdict(set)
    dag2q_pred = defaultdict(set)
    last_2q_on_qubit = {}
    logical_qubits_set = set()

    for gate in all_gates:
        qubits = self.access[gate]
        if len(qubits) == 2:
            q1, q2 = qubits
            gates_2q[gate] = (q1, q2)
            logical_qubits_set.add(q1)
            logical_qubits_set.add(q2)
            for q in [q1, q2]:
                if q in last_2q_on_qubit:
                    prev = last_2q_on_qubit[q]
                    if prev != gate:
                        dag2q_succ[prev].add(gate)
                        dag2q_pred[gate].add(prev)
                last_2q_on_qubit[q] = gate
        elif len(qubits) == 1:
            logical_qubits_set.add(qubits[0])

    logical_qubits = sorted(logical_qubits_set)

    if not gates_2q:
        self.mapping_dict = list(range(num_q))
        self.reverse_mapping_dict = list(range(num_q))
        if self.use_isl:
            self.isl_mapping = dict_to_isl_map(self.mapping_dict)
        return

    # Topological order for 2q DAG
    topo_2q = []
    in_deg_2q = {g: len(dag2q_pred[g]) for g in gates_2q}
    q2 = deque(sorted(g for g in gates_2q if in_deg_2q[g] == 0))
    while q2:
        g = q2.popleft()
        topo_2q.append(g)
        for s in dag2q_succ[g]:
            in_deg_2q[s] -= 1
            if in_deg_2q[s] == 0:
                q2.append(s)

    dep_count = defaultdict(int)
    for g in reversed(topo_2q):
        for s in dag2q_succ[g]:
            dep_count[g] = max(dep_count[g], dep_count[s] + 1)

    # Backward dep count for backward routing
    bwd_dep = defaultdict(int)
    for g in topo_2q:
        for p in dag2q_pred[g]:
            if p in gates_2q:
                bwd_dep[g] = max(bwd_dep[g], bwd_dep[p] + 1)

    # ---------------------------------------------------------------
    # Step 2: Interaction weights — critical-path weighting
    # ---------------------------------------------------------------
    max_layer = max((gate_layer[g] for g in two_qubit_gates), default=1)

    static_weight = defaultdict(float)
    logical_degree = defaultdict(float)

    for g in two_qubit_gates:
        q1, q2 = self.access[g]
        cp = critical_path[g] + 1
        layer = gate_layer[g]
        w = cp * (max_layer - layer + 1)
        key = (min(q1, q2), max(q1, q2))
        static_weight[key] += w
        logical_degree[q1] += w
        logical_degree[q2] += w

    interacting_logical = [q for q in logical_qubits if logical_degree.get(q, 0) > 0]

    # ---------------------------------------------------------------
    # Step 3: Physical graph properties
    # ---------------------------------------------------------------
    hw_adj = defaultdict(set)
    for pq in physical_qubits:
        for pq2 in self.backend.get(pq, []):
            hw_adj[pq].add(pq2)

    phys_degree = {pq: len(hw_adj[pq]) for pq in physical_qubits}
    phys_centrality = {}
    for pq in physical_qubits:
        phys_centrality[pq] = sum(dist[pq][pq2] for pq2 in physical_qubits)

    # ---------------------------------------------------------------
    # Step 4: Helper functions
    # ---------------------------------------------------------------
    def build_neighbors(weights):
        nbrs = defaultdict(dict)
        deg = defaultdict(float)
        for (q1, q2), w in weights.items():
            nbrs[q1][q2] = w
            nbrs[q2][q1] = w
            deg[q1] += w
            deg[q2] += w
        return nbrs, deg

    def compute_cost_nonlinear(m, weights, alpha_exp):
        cost = 0.0
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                d = dist[m[q1]][m[q2]]
                cost += w * (d ** alpha_exp)
        return cost

    def compute_cost(m, weights):
        cost = 0.0
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                cost += w * dist[m[q1]][m[q2]]
        return cost

    def delta_swap_cost_nonlinear(m, rm, pq_a, pq_b, nbrs, alpha_exp):
        lq_a, lq_b = rm[pq_a], rm[pq_b]
        delta = 0.0
        affected = set()
        if lq_a in nbrs:
            affected.update(nbrs[lq_a].keys())
        if lq_b in nbrs:
            affected.update(nbrs[lq_b].keys())
        for q in affected:
            if q == lq_a or q == lq_b:
                continue
            pq_q = m[q]
            w_a = nbrs.get(lq_a, {}).get(q, 0.0)
            if w_a > 0:
                old_d = dist[pq_a][pq_q] ** alpha_exp
                new_d = dist[pq_b][pq_q] ** alpha_exp
                delta += w_a * (new_d - old_d)
            w_b = nbrs.get(lq_b, {}).get(q, 0.0)
            if w_b > 0:
                old_d = dist[pq_b][pq_q] ** alpha_exp
                new_d = dist[pq_a][pq_q] ** alpha_exp
                delta += w_b * (new_d - old_d)
        return delta

    def do_swap(m, rm, pq_a, pq_b):
        lq_a, lq_b = rm[pq_a], rm[pq_b]
        m[lq_a], m[lq_b] = pq_b, pq_a
        rm[pq_a], rm[pq_b] = lq_b, lq_a

    # ---------------------------------------------------------------
    # Step 5: A* early-layer routing with adaptive node limit
    # ---------------------------------------------------------------
    ASTAR_LAYERS = 5
    n_2q = len(gates_2q)
    if n_2q < 50:
        ASTAR_NODE_LIMIT = 8000
    elif n_2q < 200:
        ASTAR_NODE_LIMIT = 5000
    else:
        ASTAR_NODE_LIMIT = 3000

    pred_rem_layer = {g: len(dag2q_pred[g]) for g in gates_2q}
    front_layer_calc = set(g for g in gates_2q if pred_rem_layer[g] == 0)
    current_layer = 0
    early_layer_gates = set()

    temp_front = set(front_layer_calc)
    while temp_front:
        for g in temp_front:
            if current_layer < ASTAR_LAYERS:
                early_layer_gates.add(g)
        next_front = set()
        for g in temp_front:
            for s in dag2q_succ[g]:
                pred_rem_layer[s] -= 1
                if pred_rem_layer[s] == 0:
                    next_front.add(s)
        current_layer += 1
        temp_front = next_front

    # ---------------------------------------------------------------
    # Step 6: A*-guided routing for early layers
    # ---------------------------------------------------------------
    def astar_routing_early(m, rm):
        if not early_layer_gates:
            return defaultdict(float), 0

        early_pred = {}
        for g in early_layer_gates:
            early_pred[g] = len(dag2q_pred[g] & early_layer_gates)

        initial_front = frozenset(g for g in early_layer_gates if early_pred[g] == 0)

        init_executed = set()
        cur_front = set(initial_front)
        changed = True
        while changed:
            changed = False
            newly_exec = set()
            for g in cur_front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = m[gq1], m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    newly_exec.add(g)
            if newly_exec:
                changed = True
                init_executed |= newly_exec
                cur_front -= newly_exec
                for g in newly_exec:
                    for s in dag2q_succ[g]:
                        if s in early_layer_gates and s not in init_executed:
                            all_pred_done = True
                            for p in dag2q_pred[s]:
                                if p in early_layer_gates and p not in init_executed:
                                    all_pred_done = False
                                    break
                            if all_pred_done:
                                cur_front.add(s)

        remaining_early = early_layer_gates - init_executed
        if not remaining_early:
            return defaultdict(float), 0

        def compute_front(executed):
            front = set()
            for g in early_layer_gates:
                if g in executed:
                    continue
                all_pred = True
                for p in dag2q_pred[g]:
                    if p in early_layer_gates and p not in executed:
                        all_pred = False
                        break
                if all_pred:
                    front.add(g)
            return frozenset(front)

        init_exec_frozen = frozenset(init_executed)
        init_front_astar = compute_front(init_executed)

        active_logical = set()
        for g in remaining_early:
            gq1, gq2 = gates_2q[g]
            active_logical.add(gq1)
            active_logical.add(gq2)

        def h_func(mapping, front_gates):
            h = 0
            for g in front_gates:
                gq1, gq2 = gates_2q[g]
                h += dist[mapping[gq1]][mapping[gq2]]
            return h

        active_logical_list = sorted(active_logical)

        def mapping_key(mapping):
            return tuple(mapping[lq] for lq in active_logical_list)

        init_m = list(m)
        init_h = h_func(init_m, init_front_astar)

        counter = [0]
        start_state = (init_h, 0, 0, init_m, init_exec_frozen, init_front_astar)
        open_heap = [start_state]
        visited = {}
        best_known_total = float('inf')
        best_result = None

        swap_history = {}
        init_key = (mapping_key(init_m), init_exec_frozen)
        swap_history[init_key] = defaultdict(float)

        expansions = 0

        while open_heap and expansions < ASTAR_NODE_LIMIT:
            f, _, g_cost, cur_m_list, executed, front = heapq.heappop(open_heap)

            mk = mapping_key(cur_m_list)
            state_key = (mk, executed)

            if state_key in visited and visited[state_key] <= g_cost:
                continue
            visited[state_key] = g_cost

            if best_known_total < float('inf') and f > best_known_total * 1.2:
                continue

            new_executed = set(executed)
            new_front = set(front)
            progress = True
            while progress:
                progress = False
                newly_exec = set()
                for g in list(new_front):
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = cur_m_list[gq1], cur_m_list[gq2]
                    if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                        newly_exec.add(g)
                if newly_exec:
                    progress = True
                    new_executed |= newly_exec
                    new_front -= newly_exec
                    for g in newly_exec:
                        for s in dag2q_succ[g]:
                            if s in early_layer_gates and s not in new_executed:
                                all_pred = True
                                for p in dag2q_pred[s]:
                                    if p in early_layer_gates and p not in new_executed:
                                        all_pred = False
                                        break
                                if all_pred:
                                    new_front.add(s)

            new_exec_frozen = frozenset(new_executed)
            new_front_frozen = frozenset(new_front)

            if not (early_layer_gates - new_executed):
                if g_cost < best_known_total:
                    best_known_total = g_cost
                    parent_key = (mk, executed)
                    pair_swaps = dict(swap_history.get(parent_key, {}))
                    best_result = (g_cost, pair_swaps)
                continue

            if not new_front_frozen:
                continue

            active_phys = set()
            for g in new_front_frozen:
                gq1, gq2 = gates_2q[g]
                active_phys.add(cur_m_list[gq1])
                active_phys.add(cur_m_list[gq2])
            ext_gates = set()
            for g in new_front_frozen:
                for s in dag2q_succ[g]:
                    if s in early_layer_gates and s not in new_executed:
                        ext_gates.add(s)
            for g in ext_gates:
                gq1, gq2 = gates_2q[g]
                active_phys.add(cur_m_list[gq1])
                active_phys.add(cur_m_list[gq2])

            swaps = set()
            for pq in active_phys:
                for nb in hw_adj.get(pq, set()):
                    swaps.add((min(pq, nb), max(pq, nb)))

            expansions += 1
            parent_pair_swaps = swap_history.get((mk, executed), defaultdict(float))

            for (s1, s2) in swaps:
                new_m = list(cur_m_list)
                lq_at_s1 = -1
                lq_at_s2 = -1
                for lq in range(num_q):
                    if new_m[lq] == s1:
                        lq_at_s1 = lq
                    if new_m[lq] == s2:
                        lq_at_s2 = lq

                if lq_at_s1 >= 0:
                    new_m[lq_at_s1] = s2
                if lq_at_s2 >= 0:
                    new_m[lq_at_s2] = s1

                new_g = g_cost + 1
                new_mk = mapping_key(new_m)
                child_key = (new_mk, new_exec_frozen)

                if child_key in visited and visited[child_key] <= new_g:
                    continue

                new_h = h_func(new_m, new_front_frozen)
                new_f = new_g + new_h

                if best_known_total < float('inf') and new_f > best_known_total * 1.2:
                    continue

                counter[0] += 1

                child_pair_swaps = defaultdict(float, parent_pair_swaps)
                for g in new_front_frozen:
                    gq1, gq2 = gates_2q[g]
                    pair_key = (min(gq1, gq2), max(gq1, gq2))
                    child_pair_swaps[pair_key] += 1.0

                swap_history[child_key] = child_pair_swaps

                heapq.heappush(open_heap, (new_f, counter[0], new_g, new_m, new_exec_frozen, new_front_frozen))

        if best_result is not None:
            return defaultdict(float, best_result[1]), best_result[0]
        else:
            return defaultdict(float), 0

    # ---------------------------------------------------------------
    # Step 7: Forward greedy routing simulation with graduated congestion
    #   Congestion multiplier strength is controlled by cong_strength param
    #   (graduated across RSDIWR iterations: mild early, strong late)
    # ---------------------------------------------------------------
    def simulate_routing_greedy(m, rm, max_layers=20, pair_pressure=None, cong_strength=0.2):
        sim_m = list(m)
        sim_rm = list(rm)
        swap_counts = defaultdict(float)
        total_swaps = 0

        if not gates_2q:
            return swap_counts, total_swaps

        pp = pair_pressure if pair_pressure else {}
        max_pp = max(pp.values()) if pp else 1.0

        pred_remaining = {g: len(dag2q_pred[g]) for g in gates_2q}
        front = set(g for g in gates_2q if pred_remaining[g] == 0)
        layers_done = 0

        while front and layers_done < max_layers:
            executable = []
            for g in front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = sim_m[gq1], sim_m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    executable.append(g)

            if executable:
                for g in executable:
                    front.discard(g)
                    for s in dag2q_succ[g]:
                        pred_remaining[s] -= 1
                        if pred_remaining[s] == 0:
                            front.add(s)
                layers_done += 1
                continue

            active_phys = set()
            for g in front:
                gq1, gq2 = gates_2q[g]
                active_phys.add(sim_m[gq1])
                active_phys.add(sim_m[gq2])

            candidates_sw = set()
            for pq in active_phys:
                for nb in self.backend.get(pq, []):
                    candidates_sw.add((min(pq, nb), max(pq, nb)))

            best_swap, best_score = None, float('inf')
            for (s1, s2) in candidates_sw:
                l1, l2 = sim_rm[s1], sim_rm[s2]
                score = 0.0
                for g in front:
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = sim_m[gq1], sim_m[gq2]
                    if gq1 == l1: p1 = s2
                    elif gq1 == l2: p1 = s1
                    if gq2 == l1: p2 = s2
                    elif gq2 == l2: p2 = s1
                    deps = dep_count.get(g, 0) + 1
                    d = dist[p1][p2]
                    if pp:
                        pair_key = (min(gq1, gq2), max(gq1, gq2))
                        pressure_mult = 1.0 + cong_strength * pp.get(pair_key, 0.0) / (max_pp + 1e-10)
                        score += deps * d * pressure_mult
                    else:
                        score += deps * d
                if score < best_score:
                    best_score = score
                    best_swap = (s1, s2)

            if best_swap is None:
                break

            s1, s2 = best_swap
            l1, l2 = sim_rm[s1], sim_rm[s2]
            sim_m[l1], sim_m[l2] = s2, s1
            sim_rm[s1], sim_rm[s2] = l2, l1
            total_swaps += 1

            for g in front:
                gq1, gq2 = gates_2q[g]
                pair_key = (min(gq1, gq2), max(gq1, gq2))
                swap_counts[pair_key] += 1.0

        return swap_counts, total_swaps

    # ---------------------------------------------------------------
    # Step 7b: Backward greedy routing simulation with graduated congestion
    # ---------------------------------------------------------------
    def simulate_routing_backward(m, rm, max_layers=20, pair_pressure=None, cong_strength=0.2):
        sim_m = list(m)
        sim_rm = list(rm)
        swap_counts = defaultdict(float)
        total_swaps = 0

        if not gates_2q:
            return swap_counts, total_swaps

        pp = pair_pressure if pair_pressure else {}
        max_pp = max(pp.values()) if pp else 1.0

        succ_remaining = {g: len(dag2q_succ[g] & set(gates_2q.keys())) for g in gates_2q}
        front = set(g for g in gates_2q if succ_remaining[g] == 0)
        layers_done = 0

        while front and layers_done < max_layers:
            executable = []
            for g in front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = sim_m[gq1], sim_m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    executable.append(g)

            if executable:
                for g in executable:
                    front.discard(g)
                    for p in dag2q_pred[g]:
                        if p in gates_2q:
                            succ_remaining[p] -= 1
                            if succ_remaining[p] == 0:
                                front.add(p)
                layers_done += 1
                continue

            active_phys = set()
            for g in front:
                gq1, gq2 = gates_2q[g]
                active_phys.add(sim_m[gq1])
                active_phys.add(sim_m[gq2])

            candidates_sw = set()
            for pq in active_phys:
                for nb in self.backend.get(pq, []):
                    candidates_sw.add((min(pq, nb), max(pq, nb)))

            best_swap, best_score = None, float('inf')
            for (s1, s2) in candidates_sw:
                l1, l2 = sim_rm[s1], sim_rm[s2]
                score = 0.0
                for g in front:
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = sim_m[gq1], sim_m[gq2]
                    if gq1 == l1: p1 = s2
                    elif gq1 == l2: p1 = s1
                    if gq2 == l1: p2 = s2
                    elif gq2 == l2: p2 = s1
                    deps = bwd_dep.get(g, 0) + 1
                    d = dist[p1][p2]
                    if pp:
                        pair_key = (min(gq1, gq2), max(gq1, gq2))
                        pressure_mult = 1.0 + cong_strength * pp.get(pair_key, 0.0) / (max_pp + 1e-10)
                        score += deps * d * pressure_mult
                    else:
                        score += deps * d
                if score < best_score:
                    best_score = score
                    best_swap = (s1, s2)

            if best_swap is None:
                break

            s1, s2 = best_swap
            l1, l2 = sim_rm[s1], sim_rm[s2]
            sim_m[l1], sim_m[l2] = s2, s1
            sim_rm[s1], sim_rm[s2] = l2, l1
            total_swaps += 1

            for g in front:
                gq1, gq2 = gates_2q[g]
                pair_key = (min(gq1, gq2), max(gq1, gq2))
                swap_counts[pair_key] += 1.0

        return swap_counts, total_swaps

    # ---------------------------------------------------------------
    # Step 7c: Asymmetric bidirectional routing (forward-biased 0.6/0.4)
    # ---------------------------------------------------------------
    def simulate_routing_asymmetric_bidir(m, rm, max_layers=20, pair_pressure=None, cong_strength=0.2):
        fwd_swaps, fwd_total = simulate_routing_greedy(m, rm, max_layers=max_layers,
                                                        pair_pressure=pair_pressure, cong_strength=cong_strength)
        bwd_swaps, bwd_total = simulate_routing_backward(m, rm, max_layers=max_layers,
                                                          pair_pressure=pair_pressure, cong_strength=cong_strength)

        combined = defaultdict(float)
        all_keys = set(fwd_swaps.keys()) | set(bwd_swaps.keys())
        for key in all_keys:
            combined[key] = 0.6 * fwd_swaps.get(key, 0.0) + 0.4 * bwd_swaps.get(key, 0.0)

        return combined, (fwd_total + bwd_total) // 2

    # ---------------------------------------------------------------
    # Step 7d: Hybrid A* + greedy routing
    # ---------------------------------------------------------------
    def simulate_routing_hybrid(m, rm, max_layers=20, pair_pressure=None, cong_strength=0.2):
        astar_swaps, astar_total = astar_routing_early(m, rm)
        greedy_swaps, greedy_total = simulate_routing_greedy(m, rm, max_layers=max_layers,
                                                              pair_pressure=pair_pressure, cong_strength=cong_strength)

        combined_swaps = defaultdict(float)
        early_pairs = set()
        for g in early_layer_gates:
            gq1, gq2 = gates_2q[g]
            early_pairs.add((min(gq1, gq2), max(gq1, gq2)))

        for pair_key in early_pairs:
            if pair_key in astar_swaps:
                combined_swaps[pair_key] = astar_swaps[pair_key]

        for pair_key, count in greedy_swaps.items():
            if pair_key not in early_pairs:
                combined_swaps[pair_key] = count

        return combined_swaps, astar_total + greedy_total

    # ---------------------------------------------------------------
    # Step 7e: Hybrid A* + asymmetric bidirectional
    # ---------------------------------------------------------------
    def simulate_routing_hybrid_bidir(m, rm, max_layers=20, pair_pressure=None, cong_strength=0.2):
        astar_swaps, astar_total = astar_routing_early(m, rm)
        fwd_swaps, fwd_total = simulate_routing_greedy(m, rm, max_layers=max_layers,
                                                        pair_pressure=pair_pressure, cong_strength=cong_strength)
        bwd_swaps, bwd_total = simulate_routing_backward(m, rm, max_layers=max_layers,
                                                          pair_pressure=pair_pressure, cong_strength=cong_strength)

        combined_swaps = defaultdict(float)
        early_pairs = set()
        for g in early_layer_gates:
            gq1, gq2 = gates_2q[g]
            early_pairs.add((min(gq1, gq2), max(gq1, gq2)))

        for pair_key in early_pairs:
            if pair_key in astar_swaps:
                combined_swaps[pair_key] = astar_swaps[pair_key]

        all_late_keys = (set(fwd_swaps.keys()) | set(bwd_swaps.keys())) - early_pairs
        for pair_key in all_late_keys:
            combined_swaps[pair_key] = 0.6 * fwd_swaps.get(pair_key, 0.0) + 0.4 * bwd_swaps.get(pair_key, 0.0)

        return combined_swaps, astar_total + (fwd_total + bwd_total) // 2

    # ---------------------------------------------------------------
    # Step 8: Seed generation setup
    # ---------------------------------------------------------------
    sorted_by_degree = sorted(interacting_logical, key=lambda q: logical_degree[q], reverse=True)
    seed_lqs = sorted_by_degree[:min(3, len(sorted_by_degree))]
    phys_by_centrality = sorted(physical_qubits, key=lambda pq: phys_centrality[pq])
    seed_pqs = phys_by_centrality[:min(3, len(phys_by_centrality))]

    logical_degree_ranked = sorted(interacting_logical, key=lambda q: logical_degree[q], reverse=True)
    logical_degree_rank = {q: i for i, q in enumerate(logical_degree_ranked)}
    max_logical_rank = max(len(logical_degree_ranked) - 1, 1)
    phys_degree_ranked = sorted(physical_qubits, key=lambda pq: phys_degree[pq], reverse=True)
    phys_degree_rank = {pq: i for i, pq in enumerate(phys_degree_ranked)}
    max_phys_rank = max(len(phys_degree_ranked) - 1, 1)

    static_nbrs, static_deg = build_neighbors(static_weight)
    max_iw = max(static_weight.values()) if static_weight else 1.0

    # ---------------------------------------------------------------
    # Step 9: Routing-Pressure-Aware Conflict-Graph MIS Seed
    # ---------------------------------------------------------------
    def conflict_graph_seed(start_pq, nbrs, deg, weights, routing_pressure=None):
        if len(interacting_logical) < 2:
            return None, None

        cur_max_iw = max(weights.values()) if weights else 1.0

        top_partners = {}
        for lq in interacting_logical:
            nbr_list = sorted(nbrs.get(lq, {}).items(), key=lambda x: x[1], reverse=True)
            top_partners[lq] = set(p for p, _ in nbr_list[:3])

        conflict_adj = defaultdict(set)
        il = interacting_logical

        qubit_pressure = defaultdict(float)
        if routing_pressure:
            for (q1, q2), cnt in routing_pressure.items():
                qubit_pressure[q1] += cnt
                qubit_pressure[q2] += cnt

        for i in range(len(il)):
            for j in range(i + 1, len(il)):
                l1, l2 = il[i], il[j]
                s1 = top_partners.get(l1, set())
                s2 = top_partners.get(l2, set())
                if not s1 and not s2:
                    continue
                intersection = len(s1 & s2)
                union = len(s1 | s2)
                if union > 0:
                    jaccard = intersection / union
                    threshold = 0.5
                    if routing_pressure and qubit_pressure[l1] > 0 and qubit_pressure[l2] > 0:
                        max_pressure = max(qubit_pressure.values()) if qubit_pressure else 1.0
                        pressure_factor = min(1.0, (qubit_pressure[l1] + qubit_pressure[l2]) /
                                              (max_pressure * 2 + 1e-10))
                        threshold = max(0.25, 0.5 - 0.25 * pressure_factor)
                    if jaccard > threshold:
                        conflict_adj[l1].add(l2)
                        conflict_adj[l2].add(l1)

        sorted_by_deg_local = sorted(interacting_logical,
                                     key=lambda q: (deg.get(q, 0), qubit_pressure.get(q, 0)),
                                     reverse=True)
        mis = set()
        excluded = set()
        for lq in sorted_by_deg_local:
            if lq not in excluded:
                mis.add(lq)
                for neighbor in conflict_adj.get(lq, set()):
                    excluded.add(neighbor)

        non_mis = [lq for lq in sorted_by_deg_local if lq not in mis]
        mis_ordered = sorted(mis, key=lambda q: (deg.get(q, 0), qubit_pressure.get(q, 0)),
                             reverse=True)

        m = [-1] * num_q
        rm = [-1] * num_q
        used_phys = set()

        if mis_ordered:
            first_lq = mis_ordered[0]
            m[first_lq] = start_pq
            rm[start_pq] = first_lq
            used_phys.add(start_pq)

            for lq in mis_ordered[1:]:
                nbrs_placed = {}
                for plq in mis:
                    if m[plq] >= 0 and plq in nbrs.get(lq, {}):
                        nbrs_placed[plq] = nbrs[lq][plq]

                if nbrs_placed:
                    best_pq = None
                    best_score = float('inf')
                    for pq in physical_qubits:
                        if pq in used_phys:
                            continue
                        score = 0.0
                        for plq, iw in nbrs_placed.items():
                            d = dist[pq][m[plq]]
                            cost = iw * d
                            if m[plq] in hw_adj[pq]:
                                cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                            score += cost
                        if score < best_score:
                            best_score = score
                            best_pq = pq
                else:
                    best_pq = None
                    best_score = float('inf')
                    for pq in physical_qubits:
                        if pq not in used_phys:
                            if phys_centrality[pq] < best_score:
                                best_score = phys_centrality[pq]
                                best_pq = pq

                if best_pq is not None:
                    m[lq] = best_pq
                    rm[best_pq] = lq
                    used_phys.add(best_pq)

        placed_set = set(lq for lq in interacting_logical if m[lq] >= 0)

        for lq in non_mis:
            nbrs_placed = {}
            for plq in placed_set:
                w = nbrs.get(lq, {}).get(plq, 0.0)
                if w > 0:
                    nbrs_placed[plq] = w

            if nbrs_placed:
                near_ties = []
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq in used_phys:
                        continue
                    score = 0.0
                    for plq, iw in nbrs_placed.items():
                        d = dist[pq][m[plq]]
                        cost = iw * d
                        if m[plq] in hw_adj[pq]:
                            cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                        score += cost
                    near_ties.append((score, pq))
                    if score < best_score:
                        best_score = score

                if near_ties and best_score > 0:
                    threshold = best_score * 1.05
                    candidates_list = [(s, pq) for s, pq in near_ties if s <= threshold]
                    if len(candidates_list) > 1 and lq in logical_degree_rank:
                        lq_rn = logical_degree_rank[lq] / max_logical_rank
                        best_pq = min(candidates_list, key=lambda x: (
                            abs(phys_degree_rank[x[1]] / max_phys_rank - lq_rn), x[0]))[1]
                    else:
                        best_pq = min(candidates_list, key=lambda x: x[0])[1]
                elif near_ties:
                    best_pq = min(near_ties, key=lambda x: x[0])[1]
                else:
                    best_pq = None
            else:
                best_pq = None
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq not in used_phys:
                        if phys_centrality[pq] < best_score:
                            best_score = phys_centrality[pq]
                            best_pq = pq

            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                used_phys.add(best_pq)
                placed_set.add(lq)

        remaining_lqs = [lq for lq in logical_qubits if m[lq] == -1]
        for lq in remaining_lqs:
            best_pq = None
            best_score = float('inf')
            for pq in physical_qubits:
                if pq not in used_phys:
                    if phys_centrality[pq] < best_score:
                        best_score = phys_centrality[pq]
                        best_pq = pq
            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                used_phys.add(best_pq)

        return m, rm

    # ---------------------------------------------------------------
    # Step 10: Spectral ordering seed
    # ---------------------------------------------------------------
    def spectral_seed():
        if len(interacting_logical) < 3:
            return None, None

        idx_map = {q: i for i, q in enumerate(interacting_logical)}
        n = len(interacting_logical)

        L = [[0.0] * n for _ in range(n)]
        for (q1, q2), w in static_weight.items():
            if q1 in idx_map and q2 in idx_map:
                i, j = idx_map[q1], idx_map[q2]
                L[i][j] -= w
                L[j][i] -= w
                L[i][i] += w
                L[j][j] += w

        def power_iter(mat, n_iter=200):
            v = [random.gauss(0, 1) for _ in range(n)]
            for _ in range(n_iter):
                new_v = [0.0] * n
                for i in range(n):
                    for j in range(n):
                        new_v[i] += mat[i][j] * v[j]
                norm = math.sqrt(sum(x * x for x in new_v)) or 1e-12
                v = [x / norm for x in new_v]
            return v

        max_diag = max(L[i][i] for i in range(n)) + 1.0
        shifted = [[0.0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                shifted[i][j] = -L[i][j]
            shifted[i][i] += max_diag

        v1 = power_iter(shifted, 150)

        dot_v1 = sum(x * x for x in v1) or 1e-12
        lam1_shifted = sum(v1[i] * sum(shifted[i][j] * v1[j] for j in range(n)) for i in range(n)) / dot_v1
        shifted2 = [row[:] for row in shifted]
        for i in range(n):
            for j in range(n):
                shifted2[i][j] -= lam1_shifted * v1[i] * v1[j] / dot_v1

        fiedler = power_iter(shifted2, 200)

        fiedler_order = sorted(range(n), key=lambda i: fiedler[i])
        sorted_logical = [interacting_logical[i] for i in fiedler_order]

        phys_sorted = sorted(physical_qubits, key=lambda pq: phys_centrality[pq])
        start_pq = phys_sorted[0]
        visited_bfs = set()
        bfs_order = []
        bfs_q = deque([start_pq])
        visited_bfs.add(start_pq)
        while bfs_q:
            pq = bfs_q.popleft()
            bfs_order.append(pq)
            for nb in sorted(hw_adj[pq]):
                if nb not in visited_bfs:
                    visited_bfs.add(nb)
                    bfs_q.append(nb)
        for pq in physical_qubits:
            if pq not in visited_bfs:
                bfs_order.append(pq)
                visited_bfs.add(pq)

        m = [-1] * num_q
        rm = [-1] * num_q
        n_interact = len(sorted_logical)
        n_phys = len(bfs_order)
        offset = max(0, (n_phys - n_interact) // 2)
        for i, lq in enumerate(sorted_logical):
            pq = bfs_order[min(offset + i, n_phys - 1)]
            if rm[pq] != -1:
                best_pq = None
                best_d = float('inf')
                for cpq in physical_qubits:
                    if rm[cpq] == -1:
                        d = dist[pq][cpq]
                        if d < best_d:
                            best_d = d
                            best_pq = cpq
                pq = best_pq
            m[lq] = pq
            rm[pq] = lq

        return m, rm

    # ---------------------------------------------------------------
    # Step 11: Greedy placement
    # ---------------------------------------------------------------
    def run_greedy_placement(start_lq, start_pq, nbrs, deg, weights=None):
        cur_max_iw = max(weights.values()) if weights else max_iw
        used_phys = {start_pq}
        m = [-1] * num_q
        rm = [-1] * num_q
        m[start_lq] = start_pq
        rm[start_pq] = start_lq
        placed = {start_lq}
        remaining = set(logical_qubits) - placed

        while remaining:
            best_lq, best_w = None, -1.0
            for lq in remaining:
                w = sum(nbrs.get(lq, {}).get(plq, 0.0) for plq in placed)
                if w > best_w:
                    best_w = w
                    best_lq = lq

            nbrs_placed = {plq: nbrs.get(best_lq, {}).get(plq, 0.0)
                           for plq in placed if plq in nbrs.get(best_lq, {})}

            if nbrs_placed:
                near_ties = []
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq in used_phys:
                        continue
                    score = 0.0
                    for plq, iw in nbrs_placed.items():
                        d = dist[pq][m[plq]]
                        cost = iw * d
                        if m[plq] in hw_adj[pq]:
                            cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                        score += cost
                    near_ties.append((score, pq))
                    if score < best_score:
                        best_score = score

                if near_ties and best_score > 0:
                    threshold = best_score * 1.05
                    candidates_list = [(s, pq) for s, pq in near_ties if s <= threshold]
                    if len(candidates_list) > 1 and best_lq in logical_degree_rank:
                        lq_rn = logical_degree_rank[best_lq] / max_logical_rank
                        best_pq = min(candidates_list, key=lambda x: (
                            abs(phys_degree_rank[x[1]] / max_phys_rank - lq_rn), x[0]))[1]
                    else:
                        best_pq = min(candidates_list, key=lambda x: x[0])[1]
                elif near_ties:
                    best_pq = min(near_ties, key=lambda x: x[0])[1]
                else:
                    best_pq = None
            else:
                best_pq = None
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq not in used_phys:
                        score = phys_centrality[pq]
                        if score < best_score:
                            best_score = score
                            best_pq = pq

            m[best_lq] = best_pq
            rm[best_pq] = best_lq
            used_phys.add(best_pq)
            placed.add(best_lq)
            remaining.discard(best_lq)
        return m, rm

    def fill_unmapped(m, rm):
        unmapped = [q for q in range(num_q) if m[q] == -1]
        free = [pq for pq in range(num_q) if rm[pq] == -1]
        for lq, pq in zip(unmapped, free):
            m[lq] = pq
            rm[pq] = lq

    # ---------------------------------------------------------------
    # Step 12: Congestion-biased local search with nonlinear distance penalty
    #   Graduated congestion bonus scales with RSDIWR iteration
    # ---------------------------------------------------------------
    def local_search(m, rm, nbrs, weights, alpha_exp, max_rounds=5,
                     congestion_bonus=None, cong_ls_strength=0.15):
        if len(interacting_logical) <= 1:
            return compute_cost_nonlinear(m, weights, alpha_exp)

        hw_edge_congestion = defaultdict(float)
        if congestion_bonus:
            for (q1, q2), pressure in congestion_bonus.items():
                pq1, pq2 = m[q1], m[q2]
                hw_edge_congestion[(min(pq1, pq2), max(pq1, pq2))] += pressure

        for _ in range(max_rounds):
            improved = False
            best_d, best_pair = 0.0, None
            active_phys = [m[q] for q in interacting_logical]

            for pq1 in active_phys:
                for pq2 in hw_adj.get(pq1, set()):
                    d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                    edge_key = (min(pq1, pq2), max(pq1, pq2))
                    if edge_key in hw_edge_congestion and d < 0:
                        d *= (1.0 + cong_ls_strength * min(1.0, hw_edge_congestion[edge_key]))
                    if d < best_d:
                        best_d = d
                        best_pair = (pq1, pq2)

            n_random = min(150, len(interacting_logical) * 3)
            for _ in range(n_random):
                i, j = random.sample(range(len(interacting_logical)), 2)
                pq1, pq2 = m[interacting_logical[i]], m[interacting_logical[j]]
                d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                if d < best_d:
                    best_d = d
                    best_pair = (pq1, pq2)

            if best_pair and best_d < -1e-12:
                do_swap(m, rm, *best_pair)
                improved = True
            if not improved:
                for i in range(len(interacting_logical)):
                    for j in range(i + 1, len(interacting_logical)):
                        pq1, pq2 = m[interacting_logical[i]], m[interacting_logical[j]]
                        d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                        if d < best_d:
                            best_d = d
                            best_pair = (pq1, pq2)
                if best_pair and best_d < -1e-12:
                    do_swap(m, rm, *best_pair)
                else:
                    break
        return compute_cost_nonlinear(m, weights, alpha_exp)

    # ---------------------------------------------------------------
    # Step 13: Perturbation modes with bandit selection
    #   6 modes: random, segment, worst-pair, edge-targeted, LNS,
    #   congestion-directed. Dual-phase bias from Parent 1.
    # ---------------------------------------------------------------
    rsdiwr_iter_ref = [0]
    accumulated_routing_pressure_ref = [defaultdict(float)]

    def perturb_random(m, rm, **kw):
        if len(interacting_logical) >= 2:
            lqs = random.sample(interacting_logical, 2)
            do_swap(m, rm, m[lqs[0]], m[lqs[1]])

    def perturb_segment_shuffle(m, rm, **kw):
        k = min(random.randint(3, 5), len(interacting_logical))
        if k < 2:
            perturb_random(m, rm)
            return
        lqs = random.sample(interacting_logical, k)
        phys_positions = [m[lq] for lq in lqs]
        random.shuffle(phys_positions)
        for lq in lqs:
            rm[m[lq]] = -1
        for lq, pq in zip(lqs, phys_positions):
            m[lq] = pq
            rm[pq] = lq

    def perturb_worst_pair(m, rm, weights=None, alpha_exp=1.5, **kw):
        if weights is None:
            perturb_random(m, rm)
            return
        pair_costs = []
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                d = dist[m[q1]][m[q2]]
                c = w * (d ** alpha_exp)
                pair_costs.append((c, q1, q2))
        if not pair_costs:
            return
        pair_costs.sort(reverse=True)
        top_n = min(3, len(pair_costs))
        _, tq1, tq2 = pair_costs[random.randint(0, top_n - 1)]
        pq1, pq2 = m[tq1], m[tq2]
        adj_of_pq2 = list(hw_adj.get(pq2, set()))
        if adj_of_pq2:
            target = random.choice(adj_of_pq2)
            if target != pq1:
                do_swap(m, rm, pq1, target)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    def perturb_edge_targeted(m, rm, weights=None, alpha_exp=1.5, **kw):
        if weights is None:
            perturb_random(m, rm)
            return
        edge_costs = []
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                c = w * (dist[m[q1]][m[q2]] ** alpha_exp)
                edge_costs.append((c, q1, q2))
        if not edge_costs:
            return
        edge_costs.sort(reverse=True)
        top_n = min(5, len(edge_costs))
        _, eq1, eq2 = edge_costs[random.randint(0, top_n - 1)]
        pq1, pq2 = m[eq1], m[eq2]
        neighbors_of_pq2 = list(hw_adj.get(pq2, set()))
        if neighbors_of_pq2:
            target = random.choice(neighbors_of_pq2)
            if target != pq1:
                do_swap(m, rm, pq1, target)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    def perturb_lns(m, rm, nbrs=None, alpha_exp=1.5, **kw):
        if nbrs is None or len(interacting_logical) < 3:
            perturb_random(m, rm)
            return
        base_lo = 3 + rsdiwr_iter_ref[0]
        base_hi = 8 + rsdiwr_iter_ref[0] * 2
        k = min(random.randint(base_lo, base_hi), len(interacting_logical))

        acc_pressure = accumulated_routing_pressure_ref[0]
        qubit_acc_pressure = defaultdict(float)
        for (q1, q2), cnt in acc_pressure.items():
            qubit_acc_pressure[q1] += cnt
            qubit_acc_pressure[q2] += cnt
        max_acc = max(qubit_acc_pressure.values()) if qubit_acc_pressure else 1.0

        qcost = {}
        for lq in interacting_logical:
            c = 0.0
            for partner, w in nbrs.get(lq, {}).items():
                if m[partner] >= 0 and m[lq] >= 0:
                    c += w * (dist[m[lq]][m[partner]] ** alpha_exp)
            pressure_bonus = qubit_acc_pressure.get(lq, 0.0) / (max_acc + 1e-10)
            qcost[lq] = c * (1.0 + 0.5 * pressure_bonus)

        sorted_qs = sorted(qcost, key=lambda q: qcost[q], reverse=True)
        top_half = sorted_qs[:max(k, len(sorted_qs) // 2)]
        subset = random.sample(top_half, min(k, len(top_half)))

        freed_phys = []
        for lq in subset:
            freed_phys.append(m[lq])
            rm[m[lq]] = -1
            m[lq] = -1

        placed_set = set(lq for lq in interacting_logical if m[lq] >= 0)
        for lq in sorted(subset, key=lambda q: qcost[q], reverse=True):
            best_pq, best_sc = None, float('inf')
            for pq in freed_phys:
                if rm[pq] != -1:
                    continue
                sc = 0.0
                for partner, w in nbrs.get(lq, {}).items():
                    if partner in placed_set and m[partner] >= 0:
                        sc += w * (dist[pq][m[partner]] ** alpha_exp)
                if sc < best_sc:
                    best_sc = sc
                    best_pq = pq
            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                placed_set.add(lq)
            else:
                for pq in freed_phys:
                    if rm[pq] == -1:
                        m[lq] = pq
                        rm[pq] = lq
                        placed_set.add(lq)
                        break

    def perturb_congestion_directed(m, rm, **kw):
        acc_pressure = accumulated_routing_pressure_ref[0]
        if not acc_pressure or len(interacting_logical) < 2:
            perturb_random(m, rm)
            return

        sorted_pairs = sorted(acc_pressure.items(), key=lambda x: x[1], reverse=True)
        top_n = min(4, len(sorted_pairs))
        (q1, q2), _ = sorted_pairs[random.randint(0, top_n - 1)]

        pq1, pq2 = m[q1], m[q2]
        adj_of_pq2 = list(hw_adj.get(pq2, set()))
        if adj_of_pq2:
            best_nb = min(adj_of_pq2, key=lambda nb: dist[pq1][nb])
            if best_nb != pq1:
                do_swap(m, rm, pq1, best_nb)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    perturbation_modes = [perturb_random, perturb_segment_shuffle,
                          perturb_worst_pair, perturb_edge_targeted,
                          perturb_lns, perturb_congestion_directed]
    K = len(perturbation_modes)

    WINDOW_SIZE = 100
    EPSILON = 0.1
    window = []
    mode_successes = [0] * K
    mode_attempts = [0] * K

    def select_perturbation_mode(phase_exploratory=True):
        if random.random() < EPSILON or sum(mode_attempts) < K * 2:
            return random.randint(0, K - 1)

        rates = []
        for k in range(K):
            if mode_attempts[k] > 0:
                rates.append(mode_successes[k] / mode_attempts[k])
            else:
                rates.append(1.0)

        if phase_exploratory:
            for idx in [1, 4, 5]:
                rates[idx] *= 1.3
        else:
            for idx in [2, 3]:
                rates[idx] *= 1.3

        total = sum(rates)
        if total < 1e-12:
            return random.randint(0, K - 1)
        r = random.random() * total
        cumul = 0.0
        for k in range(K):
            cumul += rates[k]
            if r <= cumul:
                return k
        return K - 1

    def update_window(mode_idx, success):
        window.append((mode_idx, success))
        mode_attempts[mode_idx] += 1
        if success:
            mode_successes[mode_idx] += 1
        if len(window) > WINDOW_SIZE:
            old_mode, old_success = window.pop(0)
            mode_attempts[old_mode] -= 1
            if old_success:
                mode_successes[old_mode] -= 1

    # ---------------------------------------------------------------
    # Step 14: Build initial mapping candidates
    # ---------------------------------------------------------------
    candidates = []

    for s_lq in seed_lqs:
        for s_pq in seed_pqs:
            m, rm = run_greedy_placement(s_lq, s_pq, static_nbrs, static_deg,
                                         weights=static_weight)
            fill_unmapped(m, rm)
            cost = compute_cost(m, static_weight)
            candidates.append((cost, m, rm))

    for s_pq in seed_pqs:
        cg_m, cg_rm = conflict_graph_seed(s_pq, static_nbrs, static_deg, static_weight)
        if cg_m is not None:
            fill_unmapped(cg_m, cg_rm)
            cost = compute_cost(cg_m, static_weight)
            candidates.append((cost, cg_m, cg_rm))

    spec_m, spec_rm = spectral_seed()
    if spec_m is not None:
        fill_unmapped(spec_m, spec_rm)
        spec_cost = compute_cost(spec_m, static_weight)
        candidates.append((spec_cost, spec_m, spec_rm))

    m_rand = [-1] * num_q
    rm_rand = [-1] * num_q
    shuffled_phys = list(physical_qubits)
    random.shuffle(shuffled_phys)
    for i, lq in enumerate(logical_qubits):
        m_rand[lq] = shuffled_phys[i]
        rm_rand[shuffled_phys[i]] = lq
    fill_unmapped(m_rand, rm_rand)
    c = compute_cost(m_rand, static_weight)
    candidates.append((c, m_rand, rm_rand))

    if not candidates:
        self.mapping_dict = list(range(num_q))
        self.reverse_mapping_dict = list(range(num_q))
        if self.use_isl:
            self.isl_mapping = dict_to_isl_map(self.mapping_dict)
        return

    candidates.sort(key=lambda x: x[0])

    _, best_m, best_rm = candidates[0]
    best_m, best_rm = list(best_m), list(best_rm)
    local_search(best_m, best_rm, static_nbrs, static_weight, alpha_exp=2.0, max_rounds=6)
    best_cost = compute_cost(best_m, static_weight)

    for idx in range(1, min(5, len(candidates))):
        _, m_c, rm_c = candidates[idx]
        m_c, rm_c = list(m_c), list(rm_c)
        local_search(m_c, rm_c, static_nbrs, static_weight, alpha_exp=2.0, max_rounds=4)
        c = compute_cost(m_c, static_weight)
        if c < best_cost:
            best_cost = c
            best_m = list(m_c)
            best_rm = list(rm_c)

    # ---------------------------------------------------------------
    # Step 15: RSDIWR + Dual-Phase ILS with:
    #   - Decaying accumulated pressure (0.7x per iteration)
    #   - Elite pool of top-3 diverse mappings for restart diversity
    #   - Graduated congestion multiplier (mild→strong across iterations)
    #   - A*-guided first iteration, asymmetric bidirectional routing
    #   - Pressure-adaptive blending, routing-pressure MIS reseeding
    #   - Pressure-guided LNS, congestion-biased local search
    #   - Congestion-directed perturbation, adaptive phase ratio
    # ---------------------------------------------------------------
    time_budget = 25.0
    t_start = _time()
    n_rsdiwr = 4

    cur_m = list(best_m)
    cur_rm = list(best_rm)
    swap_counts = defaultdict(float)
    accumulated_routing_pressure = defaultdict(float)
    accumulated_routing_pressure_ref[0] = accumulated_routing_pressure

    # Elite pool: maintain top-3 diverse solutions
    ELITE_SIZE = 3
    elite_pool = [(best_cost, list(best_m), list(best_rm))]

    def mapping_fingerprint(m):
        return tuple(m[lq] for lq in interacting_logical[:min(10, len(interacting_logical))])

    def add_to_elite(cost, m, rm):
        fp = mapping_fingerprint(m)
        # Check diversity: don't add if fingerprint matches existing elite
        for ec, em, erm in elite_pool:
            if mapping_fingerprint(em) == fp:
                if cost < ec:
                    elite_pool.remove((ec, em, erm))
                    elite_pool.append((cost, list(m), list(rm)))
                    elite_pool.sort(key=lambda x: x[0])
                return
        if len(elite_pool) < ELITE_SIZE:
            elite_pool.append((cost, list(m), list(rm)))
            elite_pool.sort(key=lambda x: x[0])
        elif cost < elite_pool[-1][0]:
            elite_pool[-1] = (cost, list(m), list(rm))
            elite_pool.sort(key=lambda x: x[0])

    # Pressure decay factor: older pressure is discounted
    PRESSURE_DECAY = 0.7

    for rsdiwr_iter in range(n_rsdiwr):
        rsdiwr_iter_ref[0] = rsdiwr_iter
        elapsed = _time() - t_start
        if elapsed > time_budget:
            break

        remaining_time = time_budget - elapsed
        remaining_iters = n_rsdiwr - rsdiwr_iter
        time_for_this_iter = remaining_time / max(remaining_iters, 1)
        n_ils = max(55, int(num_q * time_for_this_iter / 0.5)) if time_for_this_iter > 1.0 else max(30, num_q // 3)

        # Graduated congestion strength: starts mild, increases with iterations
        cong_routing_strength = 0.1 + 0.07 * rsdiwr_iter  # 0.1, 0.17, 0.24, 0.31
        cong_ls_strength = 0.08 + 0.05 * rsdiwr_iter       # 0.08, 0.13, 0.18, 0.23

        # Pressure-adaptive blending with decay-aware computation
        if rsdiwr_iter == 0 or not swap_counts:
            eff_weights = dict(static_weight)
        else:
            max_sw = max(swap_counts.values()) if swap_counts else 1.0
            scale = max(static_weight.values()) / max(max_sw, 1e-10)

            # Use decayed pressure magnitude for adaptation
            total_pressure = sum(accumulated_routing_pressure.values())
            n_pairs = len(accumulated_routing_pressure)
            avg_pressure = total_pressure / max(n_pairs, 1)
            pressure_adapt = min(0.15, 0.05 * avg_pressure / max(max_sw, 1e-10))
            alpha_blend = max(0.25, 1.0 - 0.3 * rsdiwr_iter - pressure_adapt)

            eff_weights = defaultdict(float)
            all_keys = set(static_weight.keys()) | set(swap_counts.keys())
            for key in all_keys:
                w_s = static_weight.get(key, 0.0)
                w_r = swap_counts.get(key, 0.0) * scale
                eff_weights[key] = alpha_blend * w_s + (1.0 - alpha_blend) * w_r

        eff_nbrs, eff_deg = build_neighbors(eff_weights)

        # Congestion bonus for local search (graduated)
        congestion_bonus = None
        if accumulated_routing_pressure:
            max_acc_p = max(accumulated_routing_pressure.values()) if accumulated_routing_pressure else 1.0
            congestion_bonus = {k: v / (max_acc_p + 1e-10) for k, v in accumulated_routing_pressure.items()}

        # Re-seed with routing-informed weights + routing-pressure MIS + elite diversity
        if rsdiwr_iter > 0 and swap_counts and (_time() - t_start) < time_budget * 0.7:
            eff_sorted = sorted(interacting_logical,
                                key=lambda q: eff_deg.get(q, 0), reverse=True)
            reseed_lqs = eff_sorted[:min(2, len(eff_sorted))]
            reseed_pqs = seed_pqs[:min(2, len(seed_pqs))]

            for s_lq in reseed_lqs:
                for s_pq in reseed_pqs:
                    rm_new, rmm_new = run_greedy_placement(
                        s_lq, s_pq, eff_nbrs, eff_deg, weights=eff_weights)
                    fill_unmapped(rm_new, rmm_new)
                    local_search(rm_new, rmm_new, eff_nbrs, eff_weights,
                                 alpha_exp=2.0, max_rounds=3,
                                 congestion_bonus=congestion_bonus,
                                 cong_ls_strength=cong_ls_strength)
                    sc = compute_cost(rm_new, static_weight)
                    if sc < best_cost:
                        best_cost = sc
                        best_m = list(rm_new)
                        best_rm = list(rmm_new)
                        cur_m = list(rm_new)
                        cur_rm = list(rmm_new)
                    add_to_elite(sc, rm_new, rmm_new)

            for s_pq in reseed_pqs:
                cg_m, cg_rm = conflict_graph_seed(
                    s_pq, eff_nbrs, eff_deg, eff_weights,
                    routing_pressure=accumulated_routing_pressure)
                if cg_m is not None:
                    fill_unmapped(cg_m, cg_rm)
                    local_search(cg_m, cg_rm, eff_nbrs, eff_weights,
                                 alpha_exp=2.0, max_rounds=3,
                                 congestion_bonus=congestion_bonus,
                                 cong_ls_strength=cong_ls_strength)
                    sc = compute_cost(cg_m, static_weight)
                    if sc < best_cost:
                        best_cost = sc
                        best_m = list(cg_m)
                        best_rm = list(cg_rm)
                        cur_m = list(cg_m)
                        cur_rm = list(cg_rm)
                    add_to_elite(sc, cg_m, cg_rm)

            # Elite pool restart: occasionally restart from a non-best elite
            # for diversity (only if we have multiple elites)
            if len(elite_pool) > 1 and rsdiwr_iter >= 2:
                # Pick a non-best elite to explore from
                elite_idx = random.randint(1, len(elite_pool) - 1)
                elite_cost, elite_m, elite_rm = elite_pool[elite_idx]
                e_m, e_rm = list(elite_m), list(elite_rm)
                local_search(e_m, e_rm, eff_nbrs, eff_weights,
                             alpha_exp=2.0, max_rounds=3,
                             congestion_bonus=congestion_bonus,
                             cong_ls_strength=cong_ls_strength)
                sc = compute_cost(e_m, static_weight)
                if sc < best_cost:
                    best_cost = sc
                    best_m = list(e_m)
                    best_rm = list(e_rm)
                    cur_m = list(e_m)
                    cur_rm = list(e_rm)

        alpha_start = 2.0
        alpha_end = 1.0

        ls_rounds = 6 if rsdiwr_iter == 0 else 4
        cur_cost_nl = local_search(cur_m, cur_rm, eff_nbrs, eff_weights,
                                   alpha_exp=alpha_start, max_rounds=ls_rounds,
                                   congestion_bonus=congestion_bonus,
                                   cong_ls_strength=cong_ls_strength)

        static_cost = compute_cost(cur_m, static_weight)
        if static_cost < best_cost:
            best_cost = static_cost
            best_m = list(cur_m)
            best_rm = list(cur_rm)
        add_to_elite(static_cost, cur_m, cur_rm)

        # Reset bandit window
        window.clear()
        for k in range(K):
            mode_successes[k] = 0
            mode_attempts[k] = 0

        T = max(cur_cost_nl * 0.05, 1.0)
        T_init = T
        alpha_sa = 0.94
        reheat_interval = max(n_ils // 4, 8)

        # Dual-phase with adaptive ratio
        explore_ratio = max(0.5, 0.7 - 0.07 * rsdiwr_iter)
        exploratory_cutoff = int(n_ils * explore_ratio)

        for ils_iter in range(n_ils):
            if _time() - t_start > time_budget:
                break

            progress = ils_iter / max(n_ils - 1, 1)
            alpha_exp = alpha_start + (alpha_end - alpha_start) * progress

            phase_exploratory = ils_iter < exploratory_cutoff

            saved_m = list(cur_m)
            saved_rm = list(cur_rm)
            saved_cost = cur_cost_nl

            mode = select_perturbation_mode(phase_exploratory=phase_exploratory)
            perturbation_modes[mode](cur_m, cur_rm,
                                    nbrs=eff_nbrs, weights=eff_weights,
                                    alpha_exp=alpha_exp)

            new_cost_nl = local_search(cur_m, cur_rm, eff_nbrs, eff_weights,
                                       alpha_exp=alpha_exp, max_rounds=3,
                                       congestion_bonus=congestion_bonus,
                                       cong_ls_strength=cong_ls_strength)

            success = new_cost_nl < saved_cost - 1e-12

            improvement = saved_cost - new_cost_nl
            if improvement > 0:
                cur_cost_nl = new_cost_nl
                sc = compute_cost(cur_m, static_weight)
                if sc < best_cost:
                    best_cost = sc
                    best_m = list(cur_m)
                    best_rm = list(cur_rm)
                add_to_elite(sc, cur_m, cur_rm)
            elif random.random() < math.exp(min(0, improvement / max(T, 1e-10))):
                cur_cost_nl = new_cost_nl
            else:
                cur_m[:] = saved_m
                cur_rm[:] = saved_rm
                cur_cost_nl = saved_cost

            update_window(mode, success)

            T *= alpha_sa
            if (ils_iter + 1) % reheat_interval == 0:
                T = max(T, T_init * 0.35)

        # Routing simulation for RSDIWR feedback
        if rsdiwr_iter < n_rsdiwr - 1:
            sim_depth = 14 + rsdiwr_iter * 7

            # Decay accumulated pressure before adding new data
            # This prevents old pressure from dominating and causing over-correction
            for pair_key in list(accumulated_routing_pressure.keys()):
                accumulated_routing_pressure[pair_key] *= PRESSURE_DECAY

            # Pass decayed pressure to routing sim with graduated congestion strength
            routing_pressure_arg = accumulated_routing_pressure if rsdiwr_iter > 0 else None

            if rsdiwr_iter == 0 and early_layer_gates:
                swap_counts, _ = simulate_routing_hybrid(best_m, best_rm,
                    max_layers=sim_depth, pair_pressure=routing_pressure_arg,
                    cong_strength=cong_routing_strength)
            elif rsdiwr_iter == 1 and early_layer_gates:
                swap_counts, _ = simulate_routing_hybrid_bidir(best_m, best_rm,
                    max_layers=sim_depth, pair_pressure=routing_pressure_arg,
                    cong_strength=cong_routing_strength)
            else:
                swap_counts, _ = simulate_routing_asymmetric_bidir(best_m, best_rm,
                    max_layers=sim_depth, pair_pressure=routing_pressure_arg,
                    cong_strength=cong_routing_strength)

            for pair_key, cnt in swap_counts.items():
                accumulated_routing_pressure[pair_key] += cnt

        cur_m = list(best_m)
        cur_rm = list(best_rm)
        cur_cost_nl = compute_cost_nonlinear(cur_m, eff_weights, alpha_end)

    # ---------------------------------------------------------------
    # Step 16: Set final mapping
    # ---------------------------------------------------------------
    self.mapping_dict = best_m
    self.reverse_mapping_dict = best_rm

    if self.use_isl:
        self.isl_mapping = dict_to_isl_map(self.mapping_dict)

def init_mapping(self):
    import math
    import random
    import heapq
    from collections import defaultdict, deque
    from time import time as _time

    num_q = self.num_qubits
    physical_qubits = sorted(self.backend.keys())
    dist = self.distance_matrix

    # ---------------------------------------------------------------
    # Step 1: Build DAG and topological layers
    # ---------------------------------------------------------------
    all_gates = sorted(self.access.keys())
    two_qubit_gates = [g for g in all_gates if len(self.access[g]) == 2]

    last_gate_on_qubit = {}
    successors_dag = defaultdict(set)
    predecessors_dag = defaultdict(set)
    for g in all_gates:
        for q in self.access[g]:
            if q in last_gate_on_qubit:
                pred = last_gate_on_qubit[q]
                successors_dag[pred].add(g)
                predecessors_dag[g].add(pred)
            last_gate_on_qubit[q] = g

    in_degree = {g: len(predecessors_dag[g]) for g in all_gates}
    gate_layer = {g: 0 for g in all_gates}
    temp_in = dict(in_degree)
    queue = deque(g for g in all_gates if in_degree[g] == 0)
    topo_order = []
    while queue:
        g = queue.popleft()
        topo_order.append(g)
        for s in successors_dag[g]:
            gate_layer[s] = max(gate_layer[s], gate_layer[g] + 1)
            temp_in[s] -= 1
            if temp_in[s] == 0:
                queue.append(s)

    critical_path = {g: 0 for g in all_gates}
    for g in reversed(topo_order):
        for s in successors_dag[g]:
            if critical_path[s] + 1 > critical_path[g]:
                critical_path[g] = critical_path[s] + 1

    # 2q DAG for routing simulation
    gates_2q = {}
    dag2q_succ = defaultdict(set)
    dag2q_pred = defaultdict(set)
    last_2q_on_qubit = {}
    logical_qubits_set = set()

    for gate in all_gates:
        qubits = self.access[gate]
        if len(qubits) == 2:
            q1, q2 = qubits
            gates_2q[gate] = (q1, q2)
            logical_qubits_set.add(q1)
            logical_qubits_set.add(q2)
            for q in [q1, q2]:
                if q in last_2q_on_qubit:
                    prev = last_2q_on_qubit[q]
                    if prev != gate:
                        dag2q_succ[prev].add(gate)
                        dag2q_pred[gate].add(prev)
                last_2q_on_qubit[q] = gate
        elif len(qubits) == 1:
            logical_qubits_set.add(qubits[0])

    logical_qubits = sorted(logical_qubits_set)

    if not gates_2q:
        self.mapping_dict = list(range(num_q))
        self.reverse_mapping_dict = list(range(num_q))
        if self.use_isl:
            self.isl_mapping = dict_to_isl_map(self.mapping_dict)
        return

    # Topological order for 2q DAG
    topo_2q = []
    in_deg_2q = {g: len(dag2q_pred[g]) for g in gates_2q}
    q2 = deque(sorted(g for g in gates_2q if in_deg_2q[g] == 0))
    while q2:
        g = q2.popleft()
        topo_2q.append(g)
        for s in dag2q_succ[g]:
            in_deg_2q[s] -= 1
            if in_deg_2q[s] == 0:
                q2.append(s)

    dep_count = defaultdict(int)
    for g in reversed(topo_2q):
        for s in dag2q_succ[g]:
            dep_count[g] = max(dep_count[g], dep_count[s] + 1)

    # Backward dep count for backward routing
    bwd_dep = defaultdict(int)
    for g in topo_2q:
        for p in dag2q_pred[g]:
            if p in gates_2q:
                bwd_dep[g] = max(bwd_dep[g], bwd_dep[p] + 1)

    # ---------------------------------------------------------------
    # Step 2: Interaction weights — critical-path weighting
    # ---------------------------------------------------------------
    max_layer = max((gate_layer[g] for g in two_qubit_gates), default=1)

    static_weight = defaultdict(float)
    logical_degree = defaultdict(float)

    for g in two_qubit_gates:
        q1, q2 = self.access[g]
        cp = critical_path[g] + 1
        layer = gate_layer[g]
        w = cp * (max_layer - layer + 1)
        key = (min(q1, q2), max(q1, q2))
        static_weight[key] += w
        logical_degree[q1] += w
        logical_degree[q2] += w

    interacting_logical = [q for q in logical_qubits if logical_degree.get(q, 0) > 0]

    # ---------------------------------------------------------------
    # Step 3: Physical graph properties
    # ---------------------------------------------------------------
    hw_adj = defaultdict(set)
    for pq in physical_qubits:
        for pq2 in self.backend.get(pq, []):
            hw_adj[pq].add(pq2)

    phys_degree = {pq: len(hw_adj[pq]) for pq in physical_qubits}
    phys_centrality = {}
    for pq in physical_qubits:
        phys_centrality[pq] = sum(dist[pq][pq2] for pq2 in physical_qubits)

    # ---------------------------------------------------------------
    # Step 4: Helper functions
    # ---------------------------------------------------------------
    def build_neighbors(weights):
        nbrs = defaultdict(dict)
        deg = defaultdict(float)
        for (q1, q2), w in weights.items():
            nbrs[q1][q2] = w
            nbrs[q2][q1] = w
            deg[q1] += w
            deg[q2] += w
        return nbrs, deg

    def compute_cost_nonlinear(m, weights, alpha_exp):
        cost = 0.0
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                d = dist[m[q1]][m[q2]]
                cost += w * (d ** alpha_exp)
        return cost

    def compute_cost(m, weights):
        cost = 0.0
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                cost += w * dist[m[q1]][m[q2]]
        return cost

    def delta_swap_cost_nonlinear(m, rm, pq_a, pq_b, nbrs, alpha_exp):
        lq_a, lq_b = rm[pq_a], rm[pq_b]
        delta = 0.0
        affected = set()
        if lq_a in nbrs:
            affected.update(nbrs[lq_a].keys())
        if lq_b in nbrs:
            affected.update(nbrs[lq_b].keys())
        for q in affected:
            if q == lq_a or q == lq_b:
                continue
            pq_q = m[q]
            w_a = nbrs.get(lq_a, {}).get(q, 0.0)
            if w_a > 0:
                old_d = dist[pq_a][pq_q] ** alpha_exp
                new_d = dist[pq_b][pq_q] ** alpha_exp
                delta += w_a * (new_d - old_d)
            w_b = nbrs.get(lq_b, {}).get(q, 0.0)
            if w_b > 0:
                old_d = dist[pq_b][pq_q] ** alpha_exp
                new_d = dist[pq_a][pq_q] ** alpha_exp
                delta += w_b * (new_d - old_d)
        return delta

    def do_swap(m, rm, pq_a, pq_b):
        lq_a, lq_b = rm[pq_a], rm[pq_b]
        m[lq_a], m[lq_b] = pq_b, pq_a
        rm[pq_a], rm[pq_b] = lq_b, lq_a

    # ---------------------------------------------------------------
    # Step 5: A* early-layer routing with adaptive node limit
    # ---------------------------------------------------------------
    ASTAR_LAYERS = 5
    n_2q = len(gates_2q)
    if n_2q < 50:
        ASTAR_NODE_LIMIT = 8000
    elif n_2q < 200:
        ASTAR_NODE_LIMIT = 5000
    else:
        ASTAR_NODE_LIMIT = 3000

    pred_rem_layer = {g: len(dag2q_pred[g]) for g in gates_2q}
    front_layer_calc = set(g for g in gates_2q if pred_rem_layer[g] == 0)
    current_layer = 0
    early_layer_gates = set()

    temp_front = set(front_layer_calc)
    while temp_front:
        for g in temp_front:
            if current_layer < ASTAR_LAYERS:
                early_layer_gates.add(g)
        next_front = set()
        for g in temp_front:
            for s in dag2q_succ[g]:
                pred_rem_layer[s] -= 1
                if pred_rem_layer[s] == 0:
                    next_front.add(s)
        current_layer += 1
        temp_front = next_front

    # ---------------------------------------------------------------
    # Step 6: A*-guided routing for early layers
    # ---------------------------------------------------------------
    def astar_routing_early(m, rm):
        if not early_layer_gates:
            return defaultdict(float), 0

        early_pred = {}
        for g in early_layer_gates:
            early_pred[g] = len(dag2q_pred[g] & early_layer_gates)

        initial_front = frozenset(g for g in early_layer_gates if early_pred[g] == 0)

        init_executed = set()
        cur_front = set(initial_front)
        changed = True
        while changed:
            changed = False
            newly_exec = set()
            for g in cur_front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = m[gq1], m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    newly_exec.add(g)
            if newly_exec:
                changed = True
                init_executed |= newly_exec
                cur_front -= newly_exec
                for g in newly_exec:
                    for s in dag2q_succ[g]:
                        if s in early_layer_gates and s not in init_executed:
                            all_pred_done = True
                            for p in dag2q_pred[s]:
                                if p in early_layer_gates and p not in init_executed:
                                    all_pred_done = False
                                    break
                            if all_pred_done:
                                cur_front.add(s)

        remaining_early = early_layer_gates - init_executed
        if not remaining_early:
            return defaultdict(float), 0

        def compute_front(executed):
            front = set()
            for g in early_layer_gates:
                if g in executed:
                    continue
                all_pred = True
                for p in dag2q_pred[g]:
                    if p in early_layer_gates and p not in executed:
                        all_pred = False
                        break
                if all_pred:
                    front.add(g)
            return frozenset(front)

        init_exec_frozen = frozenset(init_executed)
        init_front_astar = compute_front(init_executed)

        active_logical = set()
        for g in remaining_early:
            gq1, gq2 = gates_2q[g]
            active_logical.add(gq1)
            active_logical.add(gq2)

        def h_func(mapping, front_gates):
            h = 0
            for g in front_gates:
                gq1, gq2 = gates_2q[g]
                h += dist[mapping[gq1]][mapping[gq2]]
            return h

        active_logical_list = sorted(active_logical)

        def mapping_key(mapping):
            return tuple(mapping[lq] for lq in active_logical_list)

        init_m = list(m)
        init_h = h_func(init_m, init_front_astar)

        counter = [0]
        start_state = (init_h, 0, 0, init_m, init_exec_frozen, init_front_astar)
        open_heap = [start_state]
        visited = {}
        best_known_total = float('inf')
        best_result = None

        swap_history = {}
        init_key = (mapping_key(init_m), init_exec_frozen)
        swap_history[init_key] = defaultdict(float)

        expansions = 0

        while open_heap and expansions < ASTAR_NODE_LIMIT:
            f, _, g_cost, cur_m_list, executed, front = heapq.heappop(open_heap)

            mk = mapping_key(cur_m_list)
            state_key = (mk, executed)

            if state_key in visited and visited[state_key] <= g_cost:
                continue
            visited[state_key] = g_cost

            if best_known_total < float('inf') and f > best_known_total * 1.2:
                continue

            new_executed = set(executed)
            new_front = set(front)
            progress = True
            while progress:
                progress = False
                newly_exec = set()
                for g in list(new_front):
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = cur_m_list[gq1], cur_m_list[gq2]
                    if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                        newly_exec.add(g)
                if newly_exec:
                    progress = True
                    new_executed |= newly_exec
                    new_front -= newly_exec
                    for g in newly_exec:
                        for s in dag2q_succ[g]:
                            if s in early_layer_gates and s not in new_executed:
                                all_pred = True
                                for p in dag2q_pred[s]:
                                    if p in early_layer_gates and p not in new_executed:
                                        all_pred = False
                                        break
                                if all_pred:
                                    new_front.add(s)

            new_exec_frozen = frozenset(new_executed)
            new_front_frozen = frozenset(new_front)

            if not (early_layer_gates - new_executed):
                if g_cost < best_known_total:
                    best_known_total = g_cost
                    parent_key = (mk, executed)
                    pair_swaps = dict(swap_history.get(parent_key, {}))
                    best_result = (g_cost, pair_swaps)
                continue

            if not new_front_frozen:
                continue

            active_phys = set()
            for g in new_front_frozen:
                gq1, gq2 = gates_2q[g]
                active_phys.add(cur_m_list[gq1])
                active_phys.add(cur_m_list[gq2])
            ext_gates = set()
            for g in new_front_frozen:
                for s in dag2q_succ[g]:
                    if s in early_layer_gates and s not in new_executed:
                        ext_gates.add(s)
            for g in ext_gates:
                gq1, gq2 = gates_2q[g]
                active_phys.add(cur_m_list[gq1])
                active_phys.add(cur_m_list[gq2])

            swaps = set()
            for pq in active_phys:
                for nb in hw_adj.get(pq, set()):
                    swaps.add((min(pq, nb), max(pq, nb)))

            expansions += 1
            parent_pair_swaps = swap_history.get((mk, executed), defaultdict(float))

            for (s1, s2) in swaps:
                new_m = list(cur_m_list)
                lq_at_s1 = -1
                lq_at_s2 = -1
                for lq in range(num_q):
                    if new_m[lq] == s1:
                        lq_at_s1 = lq
                    if new_m[lq] == s2:
                        lq_at_s2 = lq

                if lq_at_s1 >= 0:
                    new_m[lq_at_s1] = s2
                if lq_at_s2 >= 0:
                    new_m[lq_at_s2] = s1

                new_g = g_cost + 1
                new_mk = mapping_key(new_m)
                child_key = (new_mk, new_exec_frozen)

                if child_key in visited and visited[child_key] <= new_g:
                    continue

                new_h = h_func(new_m, new_front_frozen)
                new_f = new_g + new_h

                if best_known_total < float('inf') and new_f > best_known_total * 1.2:
                    continue

                counter[0] += 1

                child_pair_swaps = defaultdict(float, parent_pair_swaps)
                for g in new_front_frozen:
                    gq1, gq2 = gates_2q[g]
                    pair_key = (min(gq1, gq2), max(gq1, gq2))
                    child_pair_swaps[pair_key] += 1.0

                swap_history[child_key] = child_pair_swaps

                heapq.heappush(open_heap, (new_f, counter[0], new_g, new_m, new_exec_frozen, new_front_frozen))

        if best_result is not None:
            return defaultdict(float, best_result[1]), best_result[0]
        else:
            return defaultdict(float), 0

    # ---------------------------------------------------------------
    # Step 7: Forward greedy routing simulation with pressure-gated
    #   congestion cascading (from P1, but only activates when pressure
    #   exceeds significance threshold)
    # ---------------------------------------------------------------
    def simulate_routing_greedy(m, rm, max_layers=20, pair_pressure=None):
        sim_m = list(m)
        sim_rm = list(rm)
        swap_counts = defaultdict(float)
        total_swaps = 0

        if not gates_2q:
            return swap_counts, total_swaps

        # Pressure-gated: only apply congestion cascading when pressure
        # data is statistically significant (>= 3 pairs with nonzero pressure)
        pp = None
        max_pp = 1.0
        if pair_pressure:
            nonzero_pressure = sum(1 for v in pair_pressure.values() if v > 0)
            if nonzero_pressure >= 3:
                pp = pair_pressure
                max_pp = max(pair_pressure.values()) if pair_pressure else 1.0

        pred_remaining = {g: len(dag2q_pred[g]) for g in gates_2q}
        front = set(g for g in gates_2q if pred_remaining[g] == 0)
        layers_done = 0

        while front and layers_done < max_layers:
            executable = []
            for g in front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = sim_m[gq1], sim_m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    executable.append(g)

            if executable:
                for g in executable:
                    front.discard(g)
                    for s in dag2q_succ[g]:
                        pred_remaining[s] -= 1
                        if pred_remaining[s] == 0:
                            front.add(s)
                layers_done += 1
                continue

            active_phys = set()
            for g in front:
                gq1, gq2 = gates_2q[g]
                active_phys.add(sim_m[gq1])
                active_phys.add(sim_m[gq2])

            candidates_sw = set()
            for pq in active_phys:
                for nb in self.backend.get(pq, []):
                    candidates_sw.add((min(pq, nb), max(pq, nb)))

            best_swap, best_score = None, float('inf')
            for (s1, s2) in candidates_sw:
                l1, l2 = sim_rm[s1], sim_rm[s2]
                score = 0.0
                for g in front:
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = sim_m[gq1], sim_m[gq2]
                    if gq1 == l1: p1 = s2
                    elif gq1 == l2: p1 = s1
                    if gq2 == l1: p2 = s2
                    elif gq2 == l2: p2 = s1
                    deps = dep_count.get(g, 0) + 1
                    d = dist[p1][p2]
                    if pp:
                        pair_key = (min(gq1, gq2), max(gq1, gq2))
                        pressure_mult = 1.0 + 0.3 * pp.get(pair_key, 0.0) / (max_pp + 1e-10)
                        score += deps * d * pressure_mult
                    else:
                        score += deps * d
                if score < best_score:
                    best_score = score
                    best_swap = (s1, s2)

            if best_swap is None:
                break

            s1, s2 = best_swap
            l1, l2 = sim_rm[s1], sim_rm[s2]
            sim_m[l1], sim_m[l2] = s2, s1
            sim_rm[s1], sim_rm[s2] = l2, l1
            total_swaps += 1

            for g in front:
                gq1, gq2 = gates_2q[g]
                pair_key = (min(gq1, gq2), max(gq1, gq2))
                swap_counts[pair_key] += 1.0

        return swap_counts, total_swaps

    # ---------------------------------------------------------------
    # Step 7b: Backward greedy routing simulation with pressure-gated
    #   congestion cascading
    # ---------------------------------------------------------------
    def simulate_routing_backward(m, rm, max_layers=20, pair_pressure=None):
        sim_m = list(m)
        sim_rm = list(rm)
        swap_counts = defaultdict(float)
        total_swaps = 0

        if not gates_2q:
            return swap_counts, total_swaps

        pp = None
        max_pp = 1.0
        if pair_pressure:
            nonzero_pressure = sum(1 for v in pair_pressure.values() if v > 0)
            if nonzero_pressure >= 3:
                pp = pair_pressure
                max_pp = max(pair_pressure.values()) if pair_pressure else 1.0

        succ_remaining = {g: len(dag2q_succ[g] & set(gates_2q.keys())) for g in gates_2q}
        front = set(g for g in gates_2q if succ_remaining[g] == 0)
        layers_done = 0

        while front and layers_done < max_layers:
            executable = []
            for g in front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = sim_m[gq1], sim_m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    executable.append(g)

            if executable:
                for g in executable:
                    front.discard(g)
                    for p in dag2q_pred[g]:
                        if p in gates_2q:
                            succ_remaining[p] -= 1
                            if succ_remaining[p] == 0:
                                front.add(p)
                layers_done += 1
                continue

            active_phys = set()
            for g in front:
                gq1, gq2 = gates_2q[g]
                active_phys.add(sim_m[gq1])
                active_phys.add(sim_m[gq2])

            candidates_sw = set()
            for pq in active_phys:
                for nb in self.backend.get(pq, []):
                    candidates_sw.add((min(pq, nb), max(pq, nb)))

            best_swap, best_score = None, float('inf')
            for (s1, s2) in candidates_sw:
                l1, l2 = sim_rm[s1], sim_rm[s2]
                score = 0.0
                for g in front:
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = sim_m[gq1], sim_m[gq2]
                    if gq1 == l1: p1 = s2
                    elif gq1 == l2: p1 = s1
                    if gq2 == l1: p2 = s2
                    elif gq2 == l2: p2 = s1
                    deps = bwd_dep.get(g, 0) + 1
                    d = dist[p1][p2]
                    if pp:
                        pair_key = (min(gq1, gq2), max(gq1, gq2))
                        pressure_mult = 1.0 + 0.3 * pp.get(pair_key, 0.0) / (max_pp + 1e-10)
                        score += deps * d * pressure_mult
                    else:
                        score += deps * d
                if score < best_score:
                    best_score = score
                    best_swap = (s1, s2)

            if best_swap is None:
                break

            s1, s2 = best_swap
            l1, l2 = sim_rm[s1], sim_rm[s2]
            sim_m[l1], sim_m[l2] = s2, s1
            sim_rm[s1], sim_rm[s2] = l2, l1
            total_swaps += 1

            for g in front:
                gq1, gq2 = gates_2q[g]
                pair_key = (min(gq1, gq2), max(gq1, gq2))
                swap_counts[pair_key] += 1.0

        return swap_counts, total_swaps

    # ---------------------------------------------------------------
    # Step 7c: Asymmetric bidirectional routing (forward-biased 0.6/0.4)
    # ---------------------------------------------------------------
    def simulate_routing_asymmetric_bidir(m, rm, max_layers=20, pair_pressure=None):
        fwd_swaps, fwd_total = simulate_routing_greedy(m, rm, max_layers=max_layers, pair_pressure=pair_pressure)
        bwd_swaps, bwd_total = simulate_routing_backward(m, rm, max_layers=max_layers, pair_pressure=pair_pressure)

        combined = defaultdict(float)
        all_keys = set(fwd_swaps.keys()) | set(bwd_swaps.keys())
        for key in all_keys:
            combined[key] = 0.6 * fwd_swaps.get(key, 0.0) + 0.4 * bwd_swaps.get(key, 0.0)

        return combined, (fwd_total + bwd_total) // 2

    # ---------------------------------------------------------------
    # Step 7d: Hybrid A* + greedy routing
    # ---------------------------------------------------------------
    def simulate_routing_hybrid(m, rm, max_layers=20, pair_pressure=None):
        astar_swaps, astar_total = astar_routing_early(m, rm)
        greedy_swaps, greedy_total = simulate_routing_greedy(m, rm, max_layers=max_layers, pair_pressure=pair_pressure)

        combined_swaps = defaultdict(float)
        early_pairs = set()
        for g in early_layer_gates:
            gq1, gq2 = gates_2q[g]
            early_pairs.add((min(gq1, gq2), max(gq1, gq2)))

        for pair_key in early_pairs:
            if pair_key in astar_swaps:
                combined_swaps[pair_key] = astar_swaps[pair_key]

        for pair_key, count in greedy_swaps.items():
            if pair_key not in early_pairs:
                combined_swaps[pair_key] = count

        return combined_swaps, astar_total + greedy_total

    # ---------------------------------------------------------------
    # Step 7e: Hybrid A* + asymmetric bidirectional
    # ---------------------------------------------------------------
    def simulate_routing_hybrid_bidir(m, rm, max_layers=20, pair_pressure=None):
        astar_swaps, astar_total = astar_routing_early(m, rm)
        fwd_swaps, fwd_total = simulate_routing_greedy(m, rm, max_layers=max_layers, pair_pressure=pair_pressure)
        bwd_swaps, bwd_total = simulate_routing_backward(m, rm, max_layers=max_layers, pair_pressure=pair_pressure)

        combined_swaps = defaultdict(float)
        early_pairs = set()
        for g in early_layer_gates:
            gq1, gq2 = gates_2q[g]
            early_pairs.add((min(gq1, gq2), max(gq1, gq2)))

        for pair_key in early_pairs:
            if pair_key in astar_swaps:
                combined_swaps[pair_key] = astar_swaps[pair_key]

        all_late_keys = (set(fwd_swaps.keys()) | set(bwd_swaps.keys())) - early_pairs
        for pair_key in all_late_keys:
            combined_swaps[pair_key] = 0.6 * fwd_swaps.get(pair_key, 0.0) + 0.4 * bwd_swaps.get(pair_key, 0.0)

        return combined_swaps, astar_total + (fwd_total + bwd_total) // 2

    # ---------------------------------------------------------------
    # Step 7f: Quick shallow routing for seed validation (NEW)
    #   Runs a fast forward-only routing over 8 layers to score a
    #   candidate mapping by actual swap count, not just static cost
    # ---------------------------------------------------------------
    def quick_routing_score(m, rm):
        sim_m = list(m)
        sim_rm = list(rm)
        total_swaps = 0

        if not gates_2q:
            return 0

        pred_remaining = {g: len(dag2q_pred[g]) for g in gates_2q}
        front = set(g for g in gates_2q if pred_remaining[g] == 0)
        layers_done = 0

        while front and layers_done < 8:
            executable = []
            for g in front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = sim_m[gq1], sim_m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    executable.append(g)

            if executable:
                for g in executable:
                    front.discard(g)
                    for s in dag2q_succ[g]:
                        pred_remaining[s] -= 1
                        if pred_remaining[s] == 0:
                            front.add(s)
                layers_done += 1
                continue

            active_phys = set()
            for g in front:
                gq1, gq2 = gates_2q[g]
                active_phys.add(sim_m[gq1])
                active_phys.add(sim_m[gq2])

            candidates_sw = set()
            for pq in active_phys:
                for nb in self.backend.get(pq, []):
                    candidates_sw.add((min(pq, nb), max(pq, nb)))

            best_swap, best_score = None, float('inf')
            for (s1, s2) in candidates_sw:
                l1, l2 = sim_rm[s1], sim_rm[s2]
                score = 0.0
                for g in front:
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = sim_m[gq1], sim_m[gq2]
                    if gq1 == l1: p1 = s2
                    elif gq1 == l2: p1 = s1
                    if gq2 == l1: p2 = s2
                    elif gq2 == l2: p2 = s1
                    deps = dep_count.get(g, 0) + 1
                    score += deps * dist[p1][p2]
                if score < best_score:
                    best_score = score
                    best_swap = (s1, s2)

            if best_swap is None:
                break

            s1, s2 = best_swap
            l1, l2 = sim_rm[s1], sim_rm[s2]
            sim_m[l1], sim_m[l2] = s2, s1
            sim_rm[s1], sim_rm[s2] = l2, l1
            total_swaps += 1

        return total_swaps

    # ---------------------------------------------------------------
    # Step 8: Seed generation setup
    # ---------------------------------------------------------------
    sorted_by_degree = sorted(interacting_logical, key=lambda q: logical_degree[q], reverse=True)
    seed_lqs = sorted_by_degree[:min(3, len(sorted_by_degree))]
    phys_by_centrality = sorted(physical_qubits, key=lambda pq: phys_centrality[pq])
    seed_pqs = phys_by_centrality[:min(3, len(phys_by_centrality))]

    logical_degree_ranked = sorted(interacting_logical, key=lambda q: logical_degree[q], reverse=True)
    logical_degree_rank = {q: i for i, q in enumerate(logical_degree_ranked)}
    max_logical_rank = max(len(logical_degree_ranked) - 1, 1)
    phys_degree_ranked = sorted(physical_qubits, key=lambda pq: phys_degree[pq], reverse=True)
    phys_degree_rank = {pq: i for i, pq in enumerate(phys_degree_ranked)}
    max_phys_rank = max(len(phys_degree_ranked) - 1, 1)

    static_nbrs, static_deg = build_neighbors(static_weight)
    max_iw = max(static_weight.values()) if static_weight else 1.0

    # ---------------------------------------------------------------
    # Step 9: Routing-Pressure-Aware Conflict-Graph MIS Seed
    # ---------------------------------------------------------------
    def conflict_graph_seed(start_pq, nbrs, deg, weights, routing_pressure=None):
        if len(interacting_logical) < 2:
            return None, None

        cur_max_iw = max(weights.values()) if weights else 1.0

        top_partners = {}
        for lq in interacting_logical:
            nbr_list = sorted(nbrs.get(lq, {}).items(), key=lambda x: x[1], reverse=True)
            top_partners[lq] = set(p for p, _ in nbr_list[:3])

        conflict_adj = defaultdict(set)
        il = interacting_logical

        qubit_pressure = defaultdict(float)
        if routing_pressure:
            for (q1, q2), cnt in routing_pressure.items():
                qubit_pressure[q1] += cnt
                qubit_pressure[q2] += cnt

        for i in range(len(il)):
            for j in range(i + 1, len(il)):
                l1, l2 = il[i], il[j]
                s1 = top_partners.get(l1, set())
                s2 = top_partners.get(l2, set())
                if not s1 and not s2:
                    continue
                intersection = len(s1 & s2)
                union = len(s1 | s2)
                if union > 0:
                    jaccard = intersection / union
                    threshold = 0.5
                    if routing_pressure and qubit_pressure[l1] > 0 and qubit_pressure[l2] > 0:
                        max_pressure = max(qubit_pressure.values()) if qubit_pressure else 1.0
                        pressure_factor = min(1.0, (qubit_pressure[l1] + qubit_pressure[l2]) /
                                              (max_pressure * 2 + 1e-10))
                        threshold = max(0.25, 0.5 - 0.25 * pressure_factor)
                    if jaccard > threshold:
                        conflict_adj[l1].add(l2)
                        conflict_adj[l2].add(l1)

        sorted_by_deg_local = sorted(interacting_logical,
                                     key=lambda q: (deg.get(q, 0), qubit_pressure.get(q, 0)),
                                     reverse=True)
        mis = set()
        excluded = set()
        for lq in sorted_by_deg_local:
            if lq not in excluded:
                mis.add(lq)
                for neighbor in conflict_adj.get(lq, set()):
                    excluded.add(neighbor)

        non_mis = [lq for lq in sorted_by_deg_local if lq not in mis]
        mis_ordered = sorted(mis, key=lambda q: (deg.get(q, 0), qubit_pressure.get(q, 0)),
                             reverse=True)

        m = [-1] * num_q
        rm = [-1] * num_q
        used_phys = set()

        if mis_ordered:
            first_lq = mis_ordered[0]
            m[first_lq] = start_pq
            rm[start_pq] = first_lq
            used_phys.add(start_pq)

            for lq in mis_ordered[1:]:
                nbrs_placed = {}
                for plq in mis:
                    if m[plq] >= 0 and plq in nbrs.get(lq, {}):
                        nbrs_placed[plq] = nbrs[lq][plq]

                if nbrs_placed:
                    best_pq = None
                    best_score = float('inf')
                    for pq in physical_qubits:
                        if pq in used_phys:
                            continue
                        score = 0.0
                        for plq, iw in nbrs_placed.items():
                            d = dist[pq][m[plq]]
                            cost = iw * d
                            if m[plq] in hw_adj[pq]:
                                cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                            score += cost
                        if score < best_score:
                            best_score = score
                            best_pq = pq
                else:
                    best_pq = None
                    best_score = float('inf')
                    for pq in physical_qubits:
                        if pq not in used_phys:
                            if phys_centrality[pq] < best_score:
                                best_score = phys_centrality[pq]
                                best_pq = pq

                if best_pq is not None:
                    m[lq] = best_pq
                    rm[best_pq] = lq
                    used_phys.add(best_pq)

        placed_set = set(lq for lq in interacting_logical if m[lq] >= 0)

        for lq in non_mis:
            nbrs_placed = {}
            for plq in placed_set:
                w = nbrs.get(lq, {}).get(plq, 0.0)
                if w > 0:
                    nbrs_placed[plq] = w

            if nbrs_placed:
                near_ties = []
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq in used_phys:
                        continue
                    score = 0.0
                    for plq, iw in nbrs_placed.items():
                        d = dist[pq][m[plq]]
                        cost = iw * d
                        if m[plq] in hw_adj[pq]:
                            cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                        score += cost
                    near_ties.append((score, pq))
                    if score < best_score:
                        best_score = score

                if near_ties and best_score > 0:
                    threshold = best_score * 1.05
                    candidates_list = [(s, pq) for s, pq in near_ties if s <= threshold]
                    if len(candidates_list) > 1 and lq in logical_degree_rank:
                        lq_rn = logical_degree_rank[lq] / max_logical_rank
                        best_pq = min(candidates_list, key=lambda x: (
                            abs(phys_degree_rank[x[1]] / max_phys_rank - lq_rn), x[0]))[1]
                    else:
                        best_pq = min(candidates_list, key=lambda x: x[0])[1]
                elif near_ties:
                    best_pq = min(near_ties, key=lambda x: x[0])[1]
                else:
                    best_pq = None
            else:
                best_pq = None
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq not in used_phys:
                        if phys_centrality[pq] < best_score:
                            best_score = phys_centrality[pq]
                            best_pq = pq

            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                used_phys.add(best_pq)
                placed_set.add(lq)

        remaining_lqs = [lq for lq in logical_qubits if m[lq] == -1]
        for lq in remaining_lqs:
            best_pq = None
            best_score = float('inf')
            for pq in physical_qubits:
                if pq not in used_phys:
                    if phys_centrality[pq] < best_score:
                        best_score = phys_centrality[pq]
                        best_pq = pq
            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                used_phys.add(best_pq)

        return m, rm

    # ---------------------------------------------------------------
    # Step 10: Spectral ordering seed
    # ---------------------------------------------------------------
    def spectral_seed():
        if len(interacting_logical) < 3:
            return None, None

        idx_map = {q: i for i, q in enumerate(interacting_logical)}
        n = len(interacting_logical)

        L = [[0.0] * n for _ in range(n)]
        for (q1, q2), w in static_weight.items():
            if q1 in idx_map and q2 in idx_map:
                i, j = idx_map[q1], idx_map[q2]
                L[i][j] -= w
                L[j][i] -= w
                L[i][i] += w
                L[j][j] += w

        def power_iter(mat, n_iter=200):
            v = [random.gauss(0, 1) for _ in range(n)]
            for _ in range(n_iter):
                new_v = [0.0] * n
                for i in range(n):
                    for j in range(n):
                        new_v[i] += mat[i][j] * v[j]
                norm = math.sqrt(sum(x * x for x in new_v)) or 1e-12
                v = [x / norm for x in new_v]
            return v

        max_diag = max(L[i][i] for i in range(n)) + 1.0
        shifted = [[0.0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                shifted[i][j] = -L[i][j]
            shifted[i][i] += max_diag

        v1 = power_iter(shifted, 150)

        dot_v1 = sum(x * x for x in v1) or 1e-12
        lam1_shifted = sum(v1[i] * sum(shifted[i][j] * v1[j] for j in range(n)) for i in range(n)) / dot_v1
        shifted2 = [row[:] for row in shifted]
        for i in range(n):
            for j in range(n):
                shifted2[i][j] -= lam1_shifted * v1[i] * v1[j] / dot_v1

        fiedler = power_iter(shifted2, 200)

        fiedler_order = sorted(range(n), key=lambda i: fiedler[i])
        sorted_logical = [interacting_logical[i] for i in fiedler_order]

        phys_sorted = sorted(physical_qubits, key=lambda pq: phys_centrality[pq])
        start_pq = phys_sorted[0]
        visited_bfs = set()
        bfs_order = []
        bfs_q = deque([start_pq])
        visited_bfs.add(start_pq)
        while bfs_q:
            pq = bfs_q.popleft()
            bfs_order.append(pq)
            for nb in sorted(hw_adj[pq]):
                if nb not in visited_bfs:
                    visited_bfs.add(nb)
                    bfs_q.append(nb)
        for pq in physical_qubits:
            if pq not in visited_bfs:
                bfs_order.append(pq)
                visited_bfs.add(pq)

        m = [-1] * num_q
        rm = [-1] * num_q
        n_interact = len(sorted_logical)
        n_phys = len(bfs_order)
        offset = max(0, (n_phys - n_interact) // 2)
        for i, lq in enumerate(sorted_logical):
            pq = bfs_order[min(offset + i, n_phys - 1)]
            if rm[pq] != -1:
                best_pq = None
                best_d = float('inf')
                for cpq in physical_qubits:
                    if rm[cpq] == -1:
                        d = dist[pq][cpq]
                        if d < best_d:
                            best_d = d
                            best_pq = cpq
                pq = best_pq
            m[lq] = pq
            rm[pq] = lq

        return m, rm

    # ---------------------------------------------------------------
    # Step 11: Greedy placement
    # ---------------------------------------------------------------
    def run_greedy_placement(start_lq, start_pq, nbrs, deg, weights=None):
        cur_max_iw = max(weights.values()) if weights else max_iw
        used_phys = {start_pq}
        m = [-1] * num_q
        rm = [-1] * num_q
        m[start_lq] = start_pq
        rm[start_pq] = start_lq
        placed = {start_lq}
        remaining = set(logical_qubits) - placed

        while remaining:
            best_lq, best_w = None, -1.0
            for lq in remaining:
                w = sum(nbrs.get(lq, {}).get(plq, 0.0) for plq in placed)
                if w > best_w:
                    best_w = w
                    best_lq = lq

            nbrs_placed = {plq: nbrs.get(best_lq, {}).get(plq, 0.0)
                           for plq in placed if plq in nbrs.get(best_lq, {})}

            if nbrs_placed:
                near_ties = []
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq in used_phys:
                        continue
                    score = 0.0
                    for plq, iw in nbrs_placed.items():
                        d = dist[pq][m[plq]]
                        cost = iw * d
                        if m[plq] in hw_adj[pq]:
                            cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                        score += cost
                    near_ties.append((score, pq))
                    if score < best_score:
                        best_score = score

                if near_ties and best_score > 0:
                    threshold = best_score * 1.05
                    candidates_list = [(s, pq) for s, pq in near_ties if s <= threshold]
                    if len(candidates_list) > 1 and best_lq in logical_degree_rank:
                        lq_rn = logical_degree_rank[best_lq] / max_logical_rank
                        best_pq = min(candidates_list, key=lambda x: (
                            abs(phys_degree_rank[x[1]] / max_phys_rank - lq_rn), x[0]))[1]
                    else:
                        best_pq = min(candidates_list, key=lambda x: x[0])[1]
                elif near_ties:
                    best_pq = min(near_ties, key=lambda x: x[0])[1]
                else:
                    best_pq = None
            else:
                best_pq = None
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq not in used_phys:
                        score = phys_centrality[pq]
                        if score < best_score:
                            best_score = score
                            best_pq = pq

            m[best_lq] = best_pq
            rm[best_pq] = best_lq
            used_phys.add(best_pq)
            placed.add(best_lq)
            remaining.discard(best_lq)
        return m, rm

    def fill_unmapped(m, rm):
        unmapped = [q for q in range(num_q) if m[q] == -1]
        free = [pq for pq in range(num_q) if rm[pq] == -1]
        for lq, pq in zip(unmapped, free):
            m[lq] = pq
            rm[pq] = lq

    # ---------------------------------------------------------------
    # Step 12: Congestion-biased local search with nonlinear distance
    #   penalty (from P1, with pressure-gated activation)
    # ---------------------------------------------------------------
    def local_search(m, rm, nbrs, weights, alpha_exp, max_rounds=5,
                     congestion_bonus=None):
        if len(interacting_logical) <= 1:
            return compute_cost_nonlinear(m, weights, alpha_exp)

        # Pressure-gated: build congestion map only when bonus is significant
        hw_edge_congestion = defaultdict(float)
        use_congestion = False
        if congestion_bonus:
            max_cb = max(congestion_bonus.values()) if congestion_bonus else 0
            if max_cb > 0.1:  # Only activate when pressure is meaningful
                use_congestion = True
                for (q1, q2), pressure in congestion_bonus.items():
                    pq1, pq2 = m[q1], m[q2]
                    hw_edge_congestion[(min(pq1, pq2), max(pq1, pq2))] += pressure

        for _ in range(max_rounds):
            improved = False
            best_d, best_pair = 0.0, None
            active_phys = [m[q] for q in interacting_logical]

            for pq1 in active_phys:
                for pq2 in hw_adj.get(pq1, set()):
                    d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                    if use_congestion and d < 0:
                        edge_key = (min(pq1, pq2), max(pq1, pq2))
                        if edge_key in hw_edge_congestion:
                            d *= (1.0 + 0.15 * min(1.0, hw_edge_congestion[edge_key]))
                    if d < best_d:
                        best_d = d
                        best_pair = (pq1, pq2)

            n_random = min(150, len(interacting_logical) * 3)
            for _ in range(n_random):
                i, j = random.sample(range(len(interacting_logical)), 2)
                pq1, pq2 = m[interacting_logical[i]], m[interacting_logical[j]]
                d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                if d < best_d:
                    best_d = d
                    best_pair = (pq1, pq2)

            if best_pair and best_d < -1e-12:
                do_swap(m, rm, *best_pair)
                improved = True
            if not improved:
                for i in range(len(interacting_logical)):
                    for j in range(i + 1, len(interacting_logical)):
                        pq1, pq2 = m[interacting_logical[i]], m[interacting_logical[j]]
                        d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                        if d < best_d:
                            best_d = d
                            best_pair = (pq1, pq2)
                if best_pair and best_d < -1e-12:
                    do_swap(m, rm, *best_pair)
                else:
                    break
        return compute_cost_nonlinear(m, weights, alpha_exp)

    # ---------------------------------------------------------------
    # Step 13: Perturbation modes with bandit selection
    #   6 modes: random, segment_shuffle, worst_pair, edge_targeted,
    #   pressure-guided LNS, congestion-directed (from P1)
    # ---------------------------------------------------------------
    rsdiwr_iter_ref = [0]
    accumulated_routing_pressure_ref = [defaultdict(float)]

    def perturb_random(m, rm, **kw):
        if len(interacting_logical) >= 2:
            lqs = random.sample(interacting_logical, 2)
            do_swap(m, rm, m[lqs[0]], m[lqs[1]])

    def perturb_segment_shuffle(m, rm, **kw):
        k = min(random.randint(3, 5), len(interacting_logical))
        if k < 2:
            perturb_random(m, rm)
            return
        lqs = random.sample(interacting_logical, k)
        phys_positions = [m[lq] for lq in lqs]
        random.shuffle(phys_positions)
        for lq in lqs:
            rm[m[lq]] = -1
        for lq, pq in zip(lqs, phys_positions):
            m[lq] = pq
            rm[pq] = lq

    def perturb_worst_pair(m, rm, weights=None, alpha_exp=1.5, **kw):
        if weights is None:
            perturb_random(m, rm)
            return
        pair_costs = []
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                d = dist[m[q1]][m[q2]]
                c = w * (d ** alpha_exp)
                pair_costs.append((c, q1, q2))
        if not pair_costs:
            return
        pair_costs.sort(reverse=True)
        top_n = min(3, len(pair_costs))
        _, tq1, tq2 = pair_costs[random.randint(0, top_n - 1)]
        pq1, pq2 = m[tq1], m[tq2]
        adj_of_pq2 = list(hw_adj.get(pq2, set()))
        if adj_of_pq2:
            target = random.choice(adj_of_pq2)
            if target != pq1:
                do_swap(m, rm, pq1, target)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    def perturb_edge_targeted(m, rm, weights=None, alpha_exp=1.5, **kw):
        if weights is None:
            perturb_random(m, rm)
            return
        edge_costs = []
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                c = w * (dist[m[q1]][m[q2]] ** alpha_exp)
                edge_costs.append((c, q1, q2))
        if not edge_costs:
            return
        edge_costs.sort(reverse=True)
        top_n = min(5, len(edge_costs))
        _, eq1, eq2 = edge_costs[random.randint(0, top_n - 1)]
        pq1, pq2 = m[eq1], m[eq2]
        neighbors_of_pq2 = list(hw_adj.get(pq2, set()))
        if neighbors_of_pq2:
            target = random.choice(neighbors_of_pq2)
            if target != pq1:
                do_swap(m, rm, pq1, target)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    def perturb_lns(m, rm, nbrs=None, alpha_exp=1.5, **kw):
        if nbrs is None or len(interacting_logical) < 3:
            perturb_random(m, rm)
            return
        base_lo = 3 + rsdiwr_iter_ref[0]
        base_hi = 8 + rsdiwr_iter_ref[0] * 2
        k = min(random.randint(base_lo, base_hi), len(interacting_logical))

        acc_pressure = accumulated_routing_pressure_ref[0]
        qubit_acc_pressure = defaultdict(float)
        for (q1, q2), cnt in acc_pressure.items():
            qubit_acc_pressure[q1] += cnt
            qubit_acc_pressure[q2] += cnt
        max_acc = max(qubit_acc_pressure.values()) if qubit_acc_pressure else 1.0

        qcost = {}
        for lq in interacting_logical:
            c = 0.0
            for partner, w in nbrs.get(lq, {}).items():
                if m[partner] >= 0 and m[lq] >= 0:
                    c += w * (dist[m[lq]][m[partner]] ** alpha_exp)
            pressure_bonus = qubit_acc_pressure.get(lq, 0.0) / (max_acc + 1e-10)
            qcost[lq] = c * (1.0 + 0.5 * pressure_bonus)

        sorted_qs = sorted(qcost, key=lambda q: qcost[q], reverse=True)
        top_half = sorted_qs[:max(k, len(sorted_qs) // 2)]
        subset = random.sample(top_half, min(k, len(top_half)))

        freed_phys = []
        for lq in subset:
            freed_phys.append(m[lq])
            rm[m[lq]] = -1
            m[lq] = -1

        placed_set = set(lq for lq in interacting_logical if m[lq] >= 0)
        for lq in sorted(subset, key=lambda q: qcost[q], reverse=True):
            best_pq, best_sc = None, float('inf')
            for pq in freed_phys:
                if rm[pq] != -1:
                    continue
                sc = 0.0
                for partner, w in nbrs.get(lq, {}).items():
                    if partner in placed_set and m[partner] >= 0:
                        sc += w * (dist[pq][m[partner]] ** alpha_exp)
                if sc < best_sc:
                    best_sc = sc
                    best_pq = pq
            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                placed_set.add(lq)
            else:
                for pq in freed_phys:
                    if rm[pq] == -1:
                        m[lq] = pq
                        rm[pq] = lq
                        placed_set.add(lq)
                        break

    def perturb_congestion_directed(m, rm, **kw):
        acc_pressure = accumulated_routing_pressure_ref[0]
        if not acc_pressure or len(interacting_logical) < 2:
            perturb_random(m, rm)
            return

        sorted_pairs = sorted(acc_pressure.items(), key=lambda x: x[1], reverse=True)
        top_n = min(4, len(sorted_pairs))
        (q1, q2), _ = sorted_pairs[random.randint(0, top_n - 1)]

        pq1, pq2 = m[q1], m[q2]
        adj_of_pq2 = list(hw_adj.get(pq2, set()))
        if adj_of_pq2:
            best_nb = min(adj_of_pq2, key=lambda nb: dist[pq1][nb])
            if best_nb != pq1:
                do_swap(m, rm, pq1, best_nb)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    perturbation_modes = [perturb_random, perturb_segment_shuffle,
                          perturb_worst_pair, perturb_edge_targeted,
                          perturb_lns, perturb_congestion_directed]
    K = len(perturbation_modes)

    WINDOW_SIZE = 100
    EPSILON = 0.1
    window = []
    mode_successes = [0] * K
    mode_attempts = [0] * K

    def select_perturbation_mode(phase_exploratory=True):
        if random.random() < EPSILON or sum(mode_attempts) < K * 2:
            return random.randint(0, K - 1)

        rates = []
        for k in range(K):
            if mode_attempts[k] > 0:
                rates.append(mode_successes[k] / mode_attempts[k])
            else:
                rates.append(1.0)

        # Dual-phase bias: exploration favors LNS/shuffle/congestion,
        # exploitation favors worst_pair/edge_targeted
        if phase_exploratory:
            for idx in [1, 4, 5]:
                rates[idx] *= 1.3
        else:
            for idx in [2, 3]:
                rates[idx] *= 1.3

        total = sum(rates)
        if total < 1e-12:
            return random.randint(0, K - 1)
        r = random.random() * total
        cumul = 0.0
        for k in range(K):
            cumul += rates[k]
            if r <= cumul:
                return k
        return K - 1

    def update_window(mode_idx, success):
        window.append((mode_idx, success))
        mode_attempts[mode_idx] += 1
        if success:
            mode_successes[mode_idx] += 1
        if len(window) > WINDOW_SIZE:
            old_mode, old_success = window.pop(0)
            mode_attempts[old_mode] -= 1
            if old_success:
                mode_successes[old_mode] -= 1

    # ---------------------------------------------------------------
    # Step 14: Build initial mapping candidates with routing-validated
    #   selection (NEW: top candidates are scored by quick routing sim
    #   before committing to ILS, not just static cost)
    # ---------------------------------------------------------------
    candidates = []

    for s_lq in seed_lqs:
        for s_pq in seed_pqs:
            m, rm = run_greedy_placement(s_lq, s_pq, static_nbrs, static_deg,
                                         weights=static_weight)
            fill_unmapped(m, rm)
            cost = compute_cost(m, static_weight)
            candidates.append((cost, m, rm))

    for s_pq in seed_pqs:
        cg_m, cg_rm = conflict_graph_seed(s_pq, static_nbrs, static_deg, static_weight)
        if cg_m is not None:
            fill_unmapped(cg_m, cg_rm)
            cost = compute_cost(cg_m, static_weight)
            candidates.append((cost, cg_m, cg_rm))

    spec_m, spec_rm = spectral_seed()
    if spec_m is not None:
        fill_unmapped(spec_m, spec_rm)
        spec_cost = compute_cost(spec_m, static_weight)
        candidates.append((spec_cost, spec_m, spec_rm))

    m_rand = [-1] * num_q
    rm_rand = [-1] * num_q
    shuffled_phys = list(physical_qubits)
    random.shuffle(shuffled_phys)
    for i, lq in enumerate(logical_qubits):
        m_rand[lq] = shuffled_phys[i]
        rm_rand[shuffled_phys[i]] = lq
    fill_unmapped(m_rand, rm_rand)
    c = compute_cost(m_rand, static_weight)
    candidates.append((c, m_rand, rm_rand))

    if not candidates:
        self.mapping_dict = list(range(num_q))
        self.reverse_mapping_dict = list(range(num_q))
        if self.use_isl:
            self.isl_mapping = dict_to_isl_map(self.mapping_dict)
        return

    candidates.sort(key=lambda x: x[0])

    # Apply local search to top candidates
    refined_candidates = []
    for idx in range(min(6, len(candidates))):
        _, m_c, rm_c = candidates[idx]
        m_c, rm_c = list(m_c), list(rm_c)
        ls_rounds = 6 if idx == 0 else 4
        local_search(m_c, rm_c, static_nbrs, static_weight, alpha_exp=2.0, max_rounds=ls_rounds)
        sc = compute_cost(m_c, static_weight)
        refined_candidates.append((sc, m_c, rm_c))

    # Routing-validated selection (NEW): among top candidates with
    # similar static cost, pick the one with lowest actual routing cost
    refined_candidates.sort(key=lambda x: x[0])
    best_static_cost = refined_candidates[0][0]
    # Consider candidates within 10% of best static cost for routing validation
    routing_threshold = best_static_cost * 1.10
    validation_pool = [rc for rc in refined_candidates if rc[0] <= routing_threshold]

    if len(validation_pool) > 1 and n_2q >= 5:
        # Score each by quick routing simulation
        best_routing_score = float('inf')
        best_m, best_rm = list(validation_pool[0][1]), list(validation_pool[0][2])
        best_cost = validation_pool[0][0]

        for sc, m_c, rm_c in validation_pool:
            rs = quick_routing_score(m_c, rm_c)
            # Combined score: static cost normalized + routing swaps
            combined = sc / (best_static_cost + 1e-10) + rs * 0.5
            if combined < best_routing_score:
                best_routing_score = combined
                best_m = list(m_c)
                best_rm = list(rm_c)
                best_cost = sc
    else:
        best_cost = refined_candidates[0][0]
        best_m = list(refined_candidates[0][1])
        best_rm = list(refined_candidates[0][2])

    # ---------------------------------------------------------------
    # Step 15: RSDIWR + Dual-Phase ILS with pressure-gated congestion
    #   cascading, A*-guided first iteration, asymmetric bidirectional
    #   routing, pressure-adaptive blending, routing-pressure MIS
    #   reseeding, pressure-guided LNS, congestion-biased local search,
    #   congestion-directed perturbation, adaptive phase ratio,
    #   and front-loaded ILS budget allocation (NEW)
    # ---------------------------------------------------------------
    time_budget = 25.0
    t_start = _time()
    n_rsdiwr = 4

    cur_m = list(best_m)
    cur_rm = list(best_rm)
    swap_counts = defaultdict(float)
    accumulated_routing_pressure = defaultdict(float)
    accumulated_routing_pressure_ref[0] = accumulated_routing_pressure

    for rsdiwr_iter in range(n_rsdiwr):
        rsdiwr_iter_ref[0] = rsdiwr_iter
        elapsed = _time() - t_start
        if elapsed > time_budget:
            break

        remaining_time = time_budget - elapsed
        remaining_iters = n_rsdiwr - rsdiwr_iter

        # Front-loaded ILS budget allocation (NEW):
        # Earlier iterations get proportionally more ILS iterations
        # because exploration yields the most benefit before pressure
        # data has converged. Weight: [1.4, 1.1, 0.9, 0.6] across 4 iters
        iter_weight = max(0.6, 1.4 - 0.27 * rsdiwr_iter)
        total_weight = sum(max(0.6, 1.4 - 0.27 * k) for k in range(rsdiwr_iter, n_rsdiwr))
        time_for_this_iter = remaining_time * iter_weight / max(total_weight, 1e-10)

        n_ils = max(55, int(num_q * time_for_this_iter / 0.5)) if time_for_this_iter > 1.0 else max(30, num_q // 3)

        # Pressure-adaptive blending
        if rsdiwr_iter == 0 or not swap_counts:
            eff_weights = dict(static_weight)
        else:
            max_sw = max(swap_counts.values()) if swap_counts else 1.0
            scale = max(static_weight.values()) / max(max_sw, 1e-10)

            total_pressure = sum(accumulated_routing_pressure.values())
            n_pairs = len(accumulated_routing_pressure)
            avg_pressure = total_pressure / max(n_pairs, 1)
            pressure_adapt = min(0.15, 0.05 * avg_pressure / max(max_sw, 1e-10))
            alpha_blend = max(0.25, 1.0 - 0.3 * rsdiwr_iter - pressure_adapt)

            eff_weights = defaultdict(float)
            all_keys = set(static_weight.keys()) | set(swap_counts.keys())
            for key in all_keys:
                w_s = static_weight.get(key, 0.0)
                w_r = swap_counts.get(key, 0.0) * scale
                eff_weights[key] = alpha_blend * w_s + (1.0 - alpha_blend) * w_r

        eff_nbrs, eff_deg = build_neighbors(eff_weights)

        # Pressure-gated congestion bonus for local search
        congestion_bonus = None
        if accumulated_routing_pressure:
            max_acc_p = max(accumulated_routing_pressure.values()) if accumulated_routing_pressure else 1.0
            if max_acc_p > 0:
                congestion_bonus = {k: v / (max_acc_p + 1e-10) for k, v in accumulated_routing_pressure.items()}

        # Re-seed with routing-informed weights + routing-pressure MIS
        if rsdiwr_iter > 0 and swap_counts and (_time() - t_start) < time_budget * 0.7:
            eff_sorted = sorted(interacting_logical,
                                key=lambda q: eff_deg.get(q, 0), reverse=True)
            reseed_lqs = eff_sorted[:min(2, len(eff_sorted))]
            reseed_pqs = seed_pqs[:min(2, len(seed_pqs))]

            for s_lq in reseed_lqs:
                for s_pq in reseed_pqs:
                    rm_new, rmm_new = run_greedy_placement(
                        s_lq, s_pq, eff_nbrs, eff_deg, weights=eff_weights)
                    fill_unmapped(rm_new, rmm_new)
                    local_search(rm_new, rmm_new, eff_nbrs, eff_weights,
                                 alpha_exp=2.0, max_rounds=3,
                                 congestion_bonus=congestion_bonus)
                    sc = compute_cost(rm_new, static_weight)
                    if sc < best_cost:
                        best_cost = sc
                        best_m = list(rm_new)
                        best_rm = list(rmm_new)
                        cur_m = list(rm_new)
                        cur_rm = list(rmm_new)

            for s_pq in reseed_pqs:
                cg_m, cg_rm = conflict_graph_seed(
                    s_pq, eff_nbrs, eff_deg, eff_weights,
                    routing_pressure=accumulated_routing_pressure)
                if cg_m is not None:
                    fill_unmapped(cg_m, cg_rm)
                    local_search(cg_m, cg_rm, eff_nbrs, eff_weights,
                                 alpha_exp=2.0, max_rounds=3,
                                 congestion_bonus=congestion_bonus)
                    sc = compute_cost(cg_m, static_weight)
                    if sc < best_cost:
                        best_cost = sc
                        best_m = list(cg_m)
                        best_rm = list(cg_rm)
                        cur_m = list(cg_m)
                        cur_rm = list(cg_rm)

        alpha_start = 2.0
        alpha_end = 1.0

        ls_rounds = 6 if rsdiwr_iter == 0 else 4
        cur_cost_nl = local_search(cur_m, cur_rm, eff_nbrs, eff_weights,
                                   alpha_exp=alpha_start, max_rounds=ls_rounds,
                                   congestion_bonus=congestion_bonus)

        static_cost = compute_cost(cur_m, static_weight)
        if static_cost < best_cost:
            best_cost = static_cost
            best_m = list(cur_m)
            best_rm = list(cur_rm)

        # Reset bandit window
        window.clear()
        for k in range(K):
            mode_successes[k] = 0
            mode_attempts[k] = 0

        T = max(cur_cost_nl * 0.05, 1.0)
        T_init = T
        alpha_sa = 0.94
        reheat_interval = max(n_ils // 4, 8)

        # Dual-phase with adaptive ratio
        explore_ratio = max(0.5, 0.7 - 0.07 * rsdiwr_iter)
        exploratory_cutoff = int(n_ils * explore_ratio)

        for ils_iter in range(n_ils):
            if _time() - t_start > time_budget:
                break

            progress = ils_iter / max(n_ils - 1, 1)
            alpha_exp = alpha_start + (alpha_end - alpha_start) * progress

            phase_exploratory = ils_iter < exploratory_cutoff

            saved_m = list(cur_m)
            saved_rm = list(cur_rm)
            saved_cost = cur_cost_nl

            mode = select_perturbation_mode(phase_exploratory=phase_exploratory)
            perturbation_modes[mode](cur_m, cur_rm,
                                    nbrs=eff_nbrs, weights=eff_weights,
                                    alpha_exp=alpha_exp)

            new_cost_nl = local_search(cur_m, cur_rm, eff_nbrs, eff_weights,
                                       alpha_exp=alpha_exp, max_rounds=3,
                                       congestion_bonus=congestion_bonus)

            success = new_cost_nl < saved_cost - 1e-12

            improvement = saved_cost - new_cost_nl
            if improvement > 0:
                cur_cost_nl = new_cost_nl
                sc = compute_cost(cur_m, static_weight)
                if sc < best_cost:
                    best_cost = sc
                    best_m = list(cur_m)
                    best_rm = list(cur_rm)
            elif random.random() < math.exp(min(0, improvement / max(T, 1e-10))):
                cur_cost_nl = new_cost_nl
            else:
                cur_m[:] = saved_m
                cur_rm[:] = saved_rm
                cur_cost_nl = saved_cost

            update_window(mode, success)

            T *= alpha_sa
            if (ils_iter + 1) % reheat_interval == 0:
                T = max(T, T_init * 0.35)

        # Routing simulation for RSDIWR feedback with pressure-gated congestion
        if rsdiwr_iter < n_rsdiwr - 1:
            sim_depth = 14 + rsdiwr_iter * 7

            # Pass accumulated pressure only after first iteration when
            # pressure data exists and is significant
            routing_pressure_arg = accumulated_routing_pressure if rsdiwr_iter > 0 else None

            if rsdiwr_iter == 0 and early_layer_gates:
                swap_counts, _ = simulate_routing_hybrid(best_m, best_rm, max_layers=sim_depth, pair_pressure=routing_pressure_arg)
            elif rsdiwr_iter == 1 and early_layer_gates:
                swap_counts, _ = simulate_routing_hybrid_bidir(best_m, best_rm, max_layers=sim_depth, pair_pressure=routing_pressure_arg)
            else:
                swap_counts, _ = simulate_routing_asymmetric_bidir(best_m, best_rm, max_layers=sim_depth, pair_pressure=routing_pressure_arg)

            for pair_key, cnt in swap_counts.items():
                accumulated_routing_pressure[pair_key] += cnt

        cur_m = list(best_m)
        cur_rm = list(best_rm)
        cur_cost_nl = compute_cost_nonlinear(cur_m, eff_weights, alpha_end)

    # ---------------------------------------------------------------
    # Step 16: Set final mapping
    # ---------------------------------------------------------------
    self.mapping_dict = best_m
    self.reverse_mapping_dict = best_rm

    if self.use_isl:
        self.isl_mapping = dict_to_isl_map(self.mapping_dict)

def init_mapping(self):
    import math
    import random
    from collections import defaultdict, deque
    from time import time as _time

    num_q = self.num_qubits
    physical_qubits = sorted(self.backend.keys())
    dist = self.distance_matrix

    # ---------------------------------------------------------------
    # Step 1: Build DAG
    # ---------------------------------------------------------------
    all_gates = sorted(self.access.keys())
    two_qubit_gates = [g for g in all_gates if len(self.access[g]) == 2]

    last_gate_on_qubit = {}
    successors_dag = defaultdict(set)
    predecessors_dag = defaultdict(set)
    for g in all_gates:
        for q in self.access[g]:
            if q in last_gate_on_qubit:
                pred = last_gate_on_qubit[q]
                successors_dag[pred].add(g)
                predecessors_dag[g].add(pred)
            last_gate_on_qubit[q] = g

    # 2q DAG
    gates_2q = {}
    dag2q_succ = defaultdict(set)
    dag2q_pred = defaultdict(set)
    last_2q_on_qubit = {}
    logical_qubits_set = set()

    for gate in all_gates:
        qubits = self.access[gate]
        if len(qubits) == 2:
            q1, q2 = qubits
            gates_2q[gate] = (q1, q2)
            logical_qubits_set.add(q1)
            logical_qubits_set.add(q2)
            for q in [q1, q2]:
                if q in last_2q_on_qubit:
                    prev = last_2q_on_qubit[q]
                    if prev != gate:
                        dag2q_succ[prev].add(gate)
                        dag2q_pred[gate].add(prev)
                last_2q_on_qubit[q] = gate
        elif len(qubits) == 1:
            logical_qubits_set.add(qubits[0])

    logical_qubits = sorted(logical_qubits_set)

    if not gates_2q:
        self.mapping_dict = list(range(num_q))
        self.reverse_mapping_dict = list(range(num_q))
        if self.use_isl:
            self.isl_mapping = dict_to_isl_map(self.mapping_dict)
        return

    # ---------------------------------------------------------------
    # Step 2: Generate 3 diverse topological orderings of the full DAG
    # ---------------------------------------------------------------
    in_degree_base = {g: len(predecessors_dag[g]) for g in all_gates}

    def topo_bfs():
        """BFS-based topological sort (Kahn's, level-order, prioritizes breadth)."""
        in_deg = dict(in_degree_base)
        queue = deque(sorted(g for g in all_gates if in_deg[g] == 0))
        order = []
        while queue:
            g = queue.popleft()
            order.append(g)
            for s in sorted(successors_dag[g]):
                in_deg[s] -= 1
                if in_deg[s] == 0:
                    queue.append(s)
        return order

    def topo_dfs():
        """DFS-based topological sort (prioritizes deep chains)."""
        in_deg = dict(in_degree_base)
        stack = sorted([g for g in all_gates if in_deg[g] == 0], reverse=True)
        order = []
        visited = set()
        while stack:
            g = stack.pop()
            if g in visited:
                continue
            if in_deg[g] > 0:
                continue
            visited.add(g)
            order.append(g)
            for s in sorted(successors_dag[g], reverse=True):
                in_deg[s] -= 1
                if in_deg[s] == 0:
                    stack.append(s)
        return order

    def topo_random():
        """Random topological sort (random tie-breaking)."""
        in_deg = dict(in_degree_base)
        available = [g for g in all_gates if in_deg[g] == 0]
        order = []
        while available:
            random.shuffle(available)
            g = available.pop()
            order.append(g)
            for s in successors_dag[g]:
                in_deg[s] -= 1
                if in_deg[s] == 0:
                    available.append(s)
        return order

    orderings = [topo_bfs(), topo_dfs(), topo_random()]

    # ---------------------------------------------------------------
    # Step 3: For each ordering, compute gate_layer, critical_path, weights
    # ---------------------------------------------------------------
    def compute_layers_and_weights(topo_order):
        gate_layer = {g: 0 for g in all_gates}
        for g in topo_order:
            for s in successors_dag[g]:
                gate_layer[s] = max(gate_layer[s], gate_layer[g] + 1)

        critical_path = {g: 0 for g in all_gates}
        for g in reversed(topo_order):
            for s in successors_dag[g]:
                if critical_path[s] + 1 > critical_path[g]:
                    critical_path[g] = critical_path[s] + 1

        max_layer = max((gate_layer[g] for g in two_qubit_gates), default=1)
        weights = defaultdict(float)
        log_deg = defaultdict(float)
        for g in two_qubit_gates:
            q1, q2 = self.access[g]
            cp = critical_path[g] + 1
            layer = gate_layer[g]
            w = cp * (max_layer - layer + 1)
            key = (min(q1, q2), max(q1, q2))
            weights[key] += w
            log_deg[q1] += w
            log_deg[q2] += w
        return weights, log_deg, critical_path, gate_layer

    ordering_data = []
    for topo_ord in orderings:
        w, ld, cp, gl = compute_layers_and_weights(topo_ord)
        ordering_data.append({'weights': w, 'logical_degree': ld,
                              'critical_path': cp, 'gate_layer': gl})

    # Use ordering 0 (BFS) as the primary for seeding/structural info
    static_weight = ordering_data[0]['weights']
    logical_degree = ordering_data[0]['logical_degree']

    interacting_logical = [q for q in logical_qubits if logical_degree.get(q, 0) > 0]

    # Dep count for routing simulation (from 2q DAG)
    topo_2q = []
    in_deg_2q = {g: len(dag2q_pred[g]) for g in gates_2q}
    q2 = deque(sorted(g for g in gates_2q if in_deg_2q[g] == 0))
    while q2:
        g = q2.popleft()
        topo_2q.append(g)
        for s in dag2q_succ[g]:
            in_deg_2q[s] -= 1
            if in_deg_2q[s] == 0:
                q2.append(s)

    dep_count = defaultdict(int)
    for g in reversed(topo_2q):
        for s in dag2q_succ[g]:
            dep_count[g] = max(dep_count[g], dep_count[s] + 1)

    # ---------------------------------------------------------------
    # Step 4: Physical graph properties
    # ---------------------------------------------------------------
    hw_adj = defaultdict(set)
    for pq in physical_qubits:
        for pq2 in self.backend.get(pq, []):
            hw_adj[pq].add(pq2)

    phys_degree = {pq: len(hw_adj[pq]) for pq in physical_qubits}
    phys_centrality = {}
    for pq in physical_qubits:
        phys_centrality[pq] = sum(dist[pq][pq2] for pq2 in physical_qubits)

    # ---------------------------------------------------------------
    # Step 5: Helper functions
    # ---------------------------------------------------------------
    def build_neighbors(weights):
        nbrs = defaultdict(dict)
        deg = defaultdict(float)
        for (q1, q2), w in weights.items():
            nbrs[q1][q2] = w
            nbrs[q2][q1] = w
            deg[q1] += w
            deg[q2] += w
        return nbrs, deg

    def compute_cost(m, weights):
        cost = 0.0
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                cost += w * dist[m[q1]][m[q2]]
        return cost

    def compute_cost_nonlinear(m, weights, alpha_exp):
        cost = 0.0
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                cost += w * (dist[m[q1]][m[q2]] ** alpha_exp)
        return cost

    def delta_swap_cost_nonlinear(m, rm, pq_a, pq_b, nbrs, alpha_exp):
        lq_a, lq_b = rm[pq_a], rm[pq_b]
        delta = 0.0
        affected = set()
        if lq_a in nbrs:
            affected.update(nbrs[lq_a].keys())
        if lq_b in nbrs:
            affected.update(nbrs[lq_b].keys())
        for q in affected:
            if q == lq_a or q == lq_b:
                continue
            pq_q = m[q]
            w_a = nbrs.get(lq_a, {}).get(q, 0.0)
            if w_a > 0:
                old_d = dist[pq_a][pq_q] ** alpha_exp
                new_d = dist[pq_b][pq_q] ** alpha_exp
                delta += w_a * (new_d - old_d)
            w_b = nbrs.get(lq_b, {}).get(q, 0.0)
            if w_b > 0:
                old_d = dist[pq_b][pq_q] ** alpha_exp
                new_d = dist[pq_a][pq_q] ** alpha_exp
                delta += w_b * (new_d - old_d)
        return delta

    def do_swap(m, rm, pq_a, pq_b):
        lq_a, lq_b = rm[pq_a], rm[pq_b]
        m[lq_a], m[lq_b] = pq_b, pq_a
        rm[pq_a], rm[pq_b] = lq_b, lq_a

    def fill_unmapped(m, rm):
        unmapped = [q for q in range(num_q) if m[q] == -1]
        free = [pq for pq in range(num_q) if rm[pq] == -1]
        for lq, pq in zip(unmapped, free):
            m[lq] = pq
            rm[pq] = lq

    # ---------------------------------------------------------------
    # Step 6: Seed construction (MIS + greedy + spectral + random)
    # ---------------------------------------------------------------
    static_nbrs, static_deg = build_neighbors(static_weight)
    max_iw = max(static_weight.values()) if static_weight else 1.0

    sorted_by_degree = sorted(interacting_logical, key=lambda q: logical_degree[q], reverse=True)
    seed_lqs = sorted_by_degree[:min(3, len(sorted_by_degree))]
    phys_by_centrality = sorted(physical_qubits, key=lambda pq: phys_centrality[pq])
    seed_pqs = phys_by_centrality[:min(3, len(phys_by_centrality))]

    logical_degree_ranked = sorted(interacting_logical, key=lambda q: logical_degree[q], reverse=True)
    logical_degree_rank = {q: i for i, q in enumerate(logical_degree_ranked)}
    max_logical_rank = max(len(logical_degree_ranked) - 1, 1)
    phys_degree_ranked = sorted(physical_qubits, key=lambda pq: phys_degree[pq], reverse=True)
    phys_degree_rank = {pq: i for i, pq in enumerate(phys_degree_ranked)}
    max_phys_rank = max(len(phys_degree_ranked) - 1, 1)

    def run_greedy_placement(start_lq, start_pq, nbrs, deg):
        used_phys = {start_pq}
        m = [-1] * num_q
        rm = [-1] * num_q
        m[start_lq] = start_pq
        rm[start_pq] = start_lq
        placed = {start_lq}
        remaining = set(logical_qubits) - placed

        while remaining:
            best_lq, best_w = None, -1.0
            for lq in remaining:
                w = sum(nbrs.get(lq, {}).get(plq, 0.0) for plq in placed)
                if w > best_w:
                    best_w = w
                    best_lq = lq

            nbrs_placed = {plq: nbrs.get(best_lq, {}).get(plq, 0.0)
                           for plq in placed if plq in nbrs.get(best_lq, {})}

            if nbrs_placed:
                near_ties = []
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq in used_phys:
                        continue
                    score = 0.0
                    for plq, iw in nbrs_placed.items():
                        d = dist[pq][m[plq]]
                        cost = iw * d
                        if m[plq] in hw_adj[pq]:
                            cost *= 0.90 - 0.10 * (iw / max_iw)
                        score += cost
                    near_ties.append((score, pq))
                    if score < best_score:
                        best_score = score

                if near_ties and best_score > 0:
                    threshold = best_score * 1.05
                    candidates_list = [(s, pq) for s, pq in near_ties if s <= threshold]
                    if len(candidates_list) > 1 and best_lq in logical_degree_rank:
                        lq_rn = logical_degree_rank[best_lq] / max_logical_rank
                        best_pq = min(candidates_list, key=lambda x: (
                            abs(phys_degree_rank[x[1]] / max_phys_rank - lq_rn), x[0]))[1]
                    else:
                        best_pq = min(candidates_list, key=lambda x: x[0])[1]
                elif near_ties:
                    best_pq = min(near_ties, key=lambda x: x[0])[1]
                else:
                    best_pq = None
            else:
                best_pq = None
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq not in used_phys:
                        score = phys_centrality[pq]
                        if score < best_score:
                            best_score = score
                            best_pq = pq

            m[best_lq] = best_pq
            rm[best_pq] = best_lq
            used_phys.add(best_pq)
            placed.add(best_lq)
            remaining.discard(best_lq)
        return m, rm

    def conflict_graph_seed(start_pq):
        if len(interacting_logical) < 2:
            return None, None

        top_partners = {}
        for lq in interacting_logical:
            nbr_list = sorted(static_nbrs.get(lq, {}).items(),
                              key=lambda x: x[1], reverse=True)
            top_partners[lq] = set(p for p, _ in nbr_list[:3])

        conflict_adj = defaultdict(set)
        il = interacting_logical
        for i in range(len(il)):
            for j in range(i + 1, len(il)):
                l1, l2 = il[i], il[j]
                s1 = top_partners.get(l1, set())
                s2 = top_partners.get(l2, set())
                if not s1 and not s2:
                    continue
                intersection = len(s1 & s2)
                union = len(s1 | s2)
                if union > 0 and intersection / union > 0.5:
                    conflict_adj[l1].add(l2)
                    conflict_adj[l2].add(l1)

        sorted_by_deg_local = sorted(interacting_logical,
                                     key=lambda q: logical_degree[q], reverse=True)
        mis = set()
        excluded = set()
        for lq in sorted_by_deg_local:
            if lq not in excluded:
                mis.add(lq)
                for neighbor in conflict_adj.get(lq, set()):
                    excluded.add(neighbor)

        non_mis = [lq for lq in sorted_by_deg_local if lq not in mis]
        mis_ordered = sorted(mis, key=lambda q: logical_degree[q], reverse=True)

        m = [-1] * num_q
        rm = [-1] * num_q
        used_phys = set()

        if mis_ordered:
            first_lq = mis_ordered[0]
            m[first_lq] = start_pq
            rm[start_pq] = first_lq
            used_phys.add(start_pq)

            for lq in mis_ordered[1:]:
                nbrs_placed = {}
                for plq in mis:
                    if m[plq] >= 0 and plq in static_nbrs.get(lq, {}):
                        nbrs_placed[plq] = static_nbrs[lq][plq]

                if nbrs_placed:
                    best_pq = None
                    best_score = float('inf')
                    for pq in physical_qubits:
                        if pq in used_phys:
                            continue
                        score = 0.0
                        for plq, iw in nbrs_placed.items():
                            d = dist[pq][m[plq]]
                            cost = iw * d
                            if m[plq] in hw_adj[pq]:
                                cost *= 0.90 - 0.10 * (iw / max_iw)
                            score += cost
                        if score < best_score:
                            best_score = score
                            best_pq = pq
                else:
                    best_pq = None
                    best_score = float('inf')
                    for pq in physical_qubits:
                        if pq not in used_phys:
                            if phys_centrality[pq] < best_score:
                                best_score = phys_centrality[pq]
                                best_pq = pq

                if best_pq is not None:
                    m[lq] = best_pq
                    rm[best_pq] = lq
                    used_phys.add(best_pq)

        placed_set = set(lq for lq in interacting_logical if m[lq] >= 0)
        for lq in non_mis:
            nbrs_placed = {}
            for plq in placed_set:
                w = static_nbrs.get(lq, {}).get(plq, 0.0)
                if w > 0:
                    nbrs_placed[plq] = w

            if nbrs_placed:
                near_ties = []
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq in used_phys:
                        continue
                    score = 0.0
                    for plq, iw in nbrs_placed.items():
                        d = dist[pq][m[plq]]
                        cost = iw * d
                        if m[plq] in hw_adj[pq]:
                            cost *= 0.90 - 0.10 * (iw / max_iw)
                        score += cost
                    near_ties.append((score, pq))
                    if score < best_score:
                        best_score = score

                if near_ties and best_score > 0:
                    threshold = best_score * 1.05
                    candidates_list = [(s, pq) for s, pq in near_ties if s <= threshold]
                    if len(candidates_list) > 1 and lq in logical_degree_rank:
                        lq_rn = logical_degree_rank[lq] / max_logical_rank
                        best_pq = min(candidates_list, key=lambda x: (
                            abs(phys_degree_rank[x[1]] / max_phys_rank - lq_rn), x[0]))[1]
                    else:
                        best_pq = min(candidates_list, key=lambda x: x[0])[1]
                elif near_ties:
                    best_pq = min(near_ties, key=lambda x: x[0])[1]
                else:
                    best_pq = None
            else:
                best_pq = None
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq not in used_phys:
                        if phys_centrality[pq] < best_score:
                            best_score = phys_centrality[pq]
                            best_pq = pq

            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                used_phys.add(best_pq)
                placed_set.add(lq)

        remaining_lqs = [lq for lq in logical_qubits if m[lq] == -1]
        for lq in remaining_lqs:
            best_pq = None
            best_score = float('inf')
            for pq in physical_qubits:
                if pq not in used_phys:
                    if phys_centrality[pq] < best_score:
                        best_score = phys_centrality[pq]
                        best_pq = pq
            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                used_phys.add(best_pq)

        return m, rm

    def spectral_seed():
        if len(interacting_logical) < 3:
            return None, None

        idx_map = {q: i for i, q in enumerate(interacting_logical)}
        n = len(interacting_logical)

        L = [[0.0] * n for _ in range(n)]
        for (q1, q2), w in static_weight.items():
            if q1 in idx_map and q2 in idx_map:
                i, j = idx_map[q1], idx_map[q2]
                L[i][j] -= w
                L[j][i] -= w
                L[i][i] += w
                L[j][j] += w

        def power_iter(mat, n_iter=200):
            v = [random.gauss(0, 1) for _ in range(n)]
            for _ in range(n_iter):
                new_v = [0.0] * n
                for i in range(n):
                    for j in range(n):
                        new_v[i] += mat[i][j] * v[j]
                norm = math.sqrt(sum(x * x for x in new_v)) or 1e-12
                v = [x / norm for x in new_v]
            return v

        max_diag = max(L[i][i] for i in range(n)) + 1.0
        shifted = [[0.0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                shifted[i][j] = -L[i][j]
            shifted[i][i] += max_diag

        v1 = power_iter(shifted, 150)
        dot_v1 = sum(x * x for x in v1) or 1e-12
        lam1_shifted = sum(v1[i] * sum(shifted[i][j] * v1[j] for j in range(n)) for i in range(n)) / dot_v1
        shifted2 = [row[:] for row in shifted]
        for i in range(n):
            for j in range(n):
                shifted2[i][j] -= lam1_shifted * v1[i] * v1[j] / dot_v1

        fiedler = power_iter(shifted2, 200)
        fiedler_order = sorted(range(n), key=lambda i: fiedler[i])
        sorted_logical = [interacting_logical[i] for i in fiedler_order]

        phys_sorted = sorted(physical_qubits, key=lambda pq: phys_centrality[pq])
        start_pq = phys_sorted[0]
        visited = set()
        bfs_order = []
        bfs_q = deque([start_pq])
        visited.add(start_pq)
        while bfs_q:
            pq = bfs_q.popleft()
            bfs_order.append(pq)
            for nb in sorted(hw_adj[pq]):
                if nb not in visited:
                    visited.add(nb)
                    bfs_q.append(nb)
        for pq in physical_qubits:
            if pq not in visited:
                bfs_order.append(pq)
                visited.add(pq)

        m = [-1] * num_q
        rm = [-1] * num_q
        n_interact = len(sorted_logical)
        n_phys = len(bfs_order)
        offset = max(0, (n_phys - n_interact) // 2)
        for i, lq in enumerate(sorted_logical):
            pq = bfs_order[min(offset + i, n_phys - 1)]
            if rm[pq] != -1:
                best_pq = None
                best_d = float('inf')
                for cpq in physical_qubits:
                    if rm[cpq] == -1:
                        d = dist[pq][cpq]
                        if d < best_d:
                            best_d = d
                            best_pq = cpq
                pq = best_pq
            m[lq] = pq
            rm[pq] = lq

        return m, rm

    # ---------------------------------------------------------------
    # Step 7: Local search
    # ---------------------------------------------------------------
    def local_search(m, rm, nbrs, weights, alpha_exp, max_rounds=5):
        if len(interacting_logical) <= 1:
            return compute_cost_nonlinear(m, weights, alpha_exp)
        for _ in range(max_rounds):
            improved = False
            best_d, best_pair = 0.0, None
            active_phys = [m[q] for q in interacting_logical]
            for pq1 in active_phys:
                for pq2 in hw_adj.get(pq1, set()):
                    d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                    if d < best_d:
                        best_d = d
                        best_pair = (pq1, pq2)
            n_random = min(150, len(interacting_logical) * 3)
            for _ in range(n_random):
                i, j = random.sample(range(len(interacting_logical)), 2)
                pq1, pq2 = m[interacting_logical[i]], m[interacting_logical[j]]
                d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                if d < best_d:
                    best_d = d
                    best_pair = (pq1, pq2)
            if best_pair and best_d < -1e-12:
                do_swap(m, rm, *best_pair)
                improved = True
            if not improved:
                for i in range(len(interacting_logical)):
                    for j in range(i + 1, len(interacting_logical)):
                        pq1, pq2 = m[interacting_logical[i]], m[interacting_logical[j]]
                        d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                        if d < best_d:
                            best_d = d
                            best_pair = (pq1, pq2)
                if best_pair and best_d < -1e-12:
                    do_swap(m, rm, *best_pair)
                else:
                    break
        return compute_cost_nonlinear(m, weights, alpha_exp)

    # ---------------------------------------------------------------
    # Step 8: Routing simulation (per-ordering aware)
    # ---------------------------------------------------------------
    def simulate_routing(m, rm, max_layers=20):
        sim_m = list(m)
        sim_rm = list(rm)
        swap_counts = defaultdict(float)

        if not gates_2q:
            return swap_counts

        pred_remaining = {g: len(dag2q_pred[g]) for g in gates_2q}
        front = set(g for g in gates_2q if pred_remaining[g] == 0)
        layers_done = 0

        while front and layers_done < max_layers:
            executable = []
            for g in front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = sim_m[gq1], sim_m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    executable.append(g)

            if executable:
                for g in executable:
                    front.discard(g)
                    for s in dag2q_succ[g]:
                        pred_remaining[s] -= 1
                        if pred_remaining[s] == 0:
                            front.add(s)
                layers_done += 1
                continue

            active_phys = set()
            for g in front:
                gq1, gq2 = gates_2q[g]
                active_phys.add(sim_m[gq1])
                active_phys.add(sim_m[gq2])

            candidates_sw = set()
            for pq in active_phys:
                for nb in self.backend.get(pq, []):
                    candidates_sw.add((min(pq, nb), max(pq, nb)))

            best_swap_rt, best_score = None, float('inf')
            for (s1, s2) in candidates_sw:
                l1, l2 = sim_rm[s1], sim_rm[s2]
                score = 0.0
                for g in front:
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = sim_m[gq1], sim_m[gq2]
                    if gq1 == l1: p1 = s2
                    elif gq1 == l2: p1 = s1
                    if gq2 == l1: p2 = s2
                    elif gq2 == l2: p2 = s1
                    deps = dep_count.get(g, 0) + 1
                    score += deps * dist[p1][p2]
                if score < best_score:
                    best_score = score
                    best_swap_rt = (s1, s2)

            if best_swap_rt is None:
                break

            s1, s2 = best_swap_rt
            l1, l2 = sim_rm[s1], sim_rm[s2]
            sim_m[l1], sim_m[l2] = s2, s1
            sim_rm[s1], sim_rm[s2] = l2, l1

            for g in front:
                gq1, gq2 = gates_2q[g]
                pair_key = (min(gq1, gq2), max(gq1, gq2))
                swap_counts[pair_key] += 1.0

        return swap_counts

    # ---------------------------------------------------------------
    # Step 9: Perturbation modes with bandit selection
    # ---------------------------------------------------------------
    def perturb_random(m, rm, **kw):
        if len(interacting_logical) >= 2:
            lqs = random.sample(interacting_logical, 2)
            do_swap(m, rm, m[lqs[0]], m[lqs[1]])

    def perturb_segment_shuffle(m, rm, **kw):
        k = min(random.randint(3, 5), len(interacting_logical))
        if k < 2:
            perturb_random(m, rm)
            return
        lqs = random.sample(interacting_logical, k)
        phys_positions = [m[lq] for lq in lqs]
        random.shuffle(phys_positions)
        for lq in lqs:
            rm[m[lq]] = -1
        for lq, pq in zip(lqs, phys_positions):
            m[lq] = pq
            rm[pq] = lq

    def perturb_worst_pair(m, rm, weights=None, alpha_exp=1.5, **kw):
        if weights is None:
            perturb_random(m, rm)
            return
        pair_costs = []
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                d = dist[m[q1]][m[q2]]
                c = w * (d ** alpha_exp)
                pair_costs.append((c, q1, q2))
        if not pair_costs:
            return
        pair_costs.sort(reverse=True)
        top_n = min(3, len(pair_costs))
        _, tq1, tq2 = pair_costs[random.randint(0, top_n - 1)]
        pq1, pq2 = m[tq1], m[tq2]
        adj_of_pq2 = list(hw_adj.get(pq2, set()))
        if adj_of_pq2:
            target = random.choice(adj_of_pq2)
            if target != pq1:
                do_swap(m, rm, pq1, target)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    def perturb_edge_targeted(m, rm, weights=None, alpha_exp=1.5, **kw):
        if weights is None:
            perturb_random(m, rm)
            return
        edge_costs = []
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                c = w * (dist[m[q1]][m[q2]] ** alpha_exp)
                edge_costs.append((c, q1, q2))
        if not edge_costs:
            return
        edge_costs.sort(reverse=True)
        top_n = min(5, len(edge_costs))
        _, eq1, eq2 = edge_costs[random.randint(0, top_n - 1)]
        pq1, pq2 = m[eq1], m[eq2]
        neighbors_of_pq2 = list(hw_adj.get(pq2, set()))
        if neighbors_of_pq2:
            target = random.choice(neighbors_of_pq2)
            if target != pq1:
                do_swap(m, rm, pq1, target)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    def perturb_lns(m, rm, nbrs=None, alpha_exp=1.5, **kw):
        if nbrs is None or len(interacting_logical) < 3:
            perturb_random(m, rm)
            return
        k = min(random.randint(3, 8), len(interacting_logical))
        qcost = {}
        for lq in interacting_logical:
            c = 0.0
            for partner, w in nbrs.get(lq, {}).items():
                if m[partner] >= 0 and m[lq] >= 0:
                    c += w * (dist[m[lq]][m[partner]] ** alpha_exp)
            qcost[lq] = c
        sorted_qs = sorted(qcost, key=lambda q: qcost[q], reverse=True)
        top_half = sorted_qs[:max(k, len(sorted_qs) // 2)]
        subset = random.sample(top_half, min(k, len(top_half)))

        freed_phys = []
        for lq in subset:
            freed_phys.append(m[lq])
            rm[m[lq]] = -1
            m[lq] = -1

        placed_set = set(lq for lq in interacting_logical if m[lq] >= 0)
        for lq in sorted(subset, key=lambda q: qcost[q], reverse=True):
            best_pq, best_sc = None, float('inf')
            for pq in freed_phys:
                if rm[pq] != -1:
                    continue
                sc = 0.0
                for partner, w in nbrs.get(lq, {}).items():
                    if partner in placed_set and m[partner] >= 0:
                        sc += w * (dist[pq][m[partner]] ** alpha_exp)
                if sc < best_sc:
                    best_sc = sc
                    best_pq = pq
            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                placed_set.add(lq)
            else:
                for pq in freed_phys:
                    if rm[pq] == -1:
                        m[lq] = pq
                        rm[pq] = lq
                        placed_set.add(lq)
                        break

    perturbation_modes = [perturb_random, perturb_segment_shuffle,
                          perturb_worst_pair, perturb_edge_targeted, perturb_lns]
    K = len(perturbation_modes)

    # ---------------------------------------------------------------
    # Step 10: Build initial candidate pool (shared across orderings)
    # ---------------------------------------------------------------
    candidates = []

    for s_lq in seed_lqs:
        for s_pq in seed_pqs:
            m, rm = run_greedy_placement(s_lq, s_pq, static_nbrs, static_deg)
            fill_unmapped(m, rm)
            cost = compute_cost(m, static_weight)
            candidates.append((cost, m, rm))

    for s_pq in seed_pqs:
        cg_m, cg_rm = conflict_graph_seed(s_pq)
        if cg_m is not None:
            fill_unmapped(cg_m, cg_rm)
            cost = compute_cost(cg_m, static_weight)
            candidates.append((cost, cg_m, cg_rm))

    spec_m, spec_rm = spectral_seed()
    if spec_m is not None:
        fill_unmapped(spec_m, spec_rm)
        spec_cost = compute_cost(spec_m, static_weight)
        candidates.append((spec_cost, spec_m, spec_rm))

    m_rand = [-1] * num_q
    rm_rand = [-1] * num_q
    shuffled_phys = list(physical_qubits)
    random.shuffle(shuffled_phys)
    for i, lq in enumerate(logical_qubits):
        m_rand[lq] = shuffled_phys[i]
        rm_rand[shuffled_phys[i]] = lq
    fill_unmapped(m_rand, rm_rand)
    c = compute_cost(m_rand, static_weight)
    candidates.append((c, m_rand, rm_rand))

    if not candidates:
        self.mapping_dict = list(range(num_q))
        self.reverse_mapping_dict = list(range(num_q))
        if self.use_isl:
            self.isl_mapping = dict_to_isl_map(self.mapping_dict)
        return

    candidates.sort(key=lambda x: x[0])

    # Refine top candidates
    top_refined = []
    for idx in range(min(5, len(candidates))):
        _, m_c, rm_c = candidates[idx]
        m_c, rm_c = list(m_c), list(rm_c)
        local_search(m_c, rm_c, static_nbrs, static_weight, alpha_exp=2.0,
                     max_rounds=6 if idx == 0 else 4)
        c = compute_cost(m_c, static_weight)
        top_refined.append((c, m_c, rm_c))
    top_refined.sort(key=lambda x: x[0])

    # ---------------------------------------------------------------
    # Step 11: ENSEMBLE RSDIWR — 3 orderings with cross-pollination
    # ---------------------------------------------------------------
    T_COUNT = 3  # number of topological orderings
    time_budget = 25.0
    t_start = _time()
    n_rsdiwr = 4

    # Initialize per-ordering state
    # Each ordering maintains its own best mapping + current mapping
    ord_best_m = []
    ord_best_rm = []
    ord_best_cost = []
    ord_cur_m = []
    ord_cur_rm = []
    ord_swap_counts = []

    for t in range(T_COUNT):
        w_t = ordering_data[t]['weights']
        # Pick the best initial candidate scored under this ordering's weights
        best_c = float('inf')
        best_idx = 0
        for idx, (_, m_c, rm_c) in enumerate(top_refined):
            c = compute_cost(m_c, w_t)
            if c < best_c:
                best_c = c
                best_idx = idx

        _, bm, brm = top_refined[best_idx]
        ord_best_m.append(list(bm))
        ord_best_rm.append(list(brm))
        ord_best_cost.append(best_c)
        ord_cur_m.append(list(bm))
        ord_cur_rm.append(list(brm))
        ord_swap_counts.append(defaultdict(float))

    # Global best (scored under static_weight = ordering 0)
    global_best_cost = top_refined[0][0]
    global_best_m = list(top_refined[0][1])
    global_best_rm = list(top_refined[0][2])

    for rsdiwr_iter in range(n_rsdiwr):
        elapsed = _time() - t_start
        if elapsed > time_budget:
            break

        remaining_time = time_budget - elapsed
        remaining_iters = n_rsdiwr - rsdiwr_iter
        time_per_iter = remaining_time / max(remaining_iters, 1)
        # Split time across T orderings
        time_per_ordering = time_per_iter / T_COUNT
        n_ils = max(30, int(num_q * time_per_ordering / 0.6)) if time_per_ordering > 0.5 else max(20, num_q // 4)

        for t in range(T_COUNT):
            if _time() - t_start > time_budget:
                break

            w_t = ordering_data[t]['weights']
            swap_counts_t = ord_swap_counts[t]

            # Blend weights with routing feedback
            if rsdiwr_iter == 0 or not swap_counts_t:
                eff_weights = dict(w_t)
            else:
                max_sw = max(swap_counts_t.values()) if swap_counts_t else 1.0
                max_wt = max(w_t.values()) if w_t else 1.0
                scale = max_wt / max(max_sw, 1e-10)
                alpha_blend = max(0.3, 1.0 - 0.3 * rsdiwr_iter)
                eff_weights = defaultdict(float)
                all_keys = set(w_t.keys()) | set(swap_counts_t.keys())
                for key in all_keys:
                    w_s = w_t.get(key, 0.0)
                    w_r = swap_counts_t.get(key, 0.0) * scale
                    eff_weights[key] = alpha_blend * w_s + (1.0 - alpha_blend) * w_r

            eff_nbrs, eff_deg = build_neighbors(eff_weights)

            cur_m = ord_cur_m[t]
            cur_rm = ord_cur_rm[t]

            # Cross-pollination: inject best from other orderings as seeds
            if rsdiwr_iter > 0:
                for t2 in range(T_COUNT):
                    if t2 == t:
                        continue
                    cross_m = list(ord_best_m[t2])
                    cross_rm = list(ord_best_rm[t2])
                    cross_cost = compute_cost_nonlinear(cross_m, eff_weights, 2.0)
                    cur_cost_check = compute_cost_nonlinear(cur_m, eff_weights, 2.0)
                    if cross_cost < cur_cost_check:
                        cur_m = list(cross_m)
                        cur_rm = list(cross_rm)

            alpha_start = 2.0
            alpha_end = 1.0

            ls_rounds = 5 if rsdiwr_iter == 0 else 3
            cur_cost_nl = local_search(cur_m, cur_rm, eff_nbrs, eff_weights,
                                       alpha_exp=alpha_start, max_rounds=ls_rounds)

            sc = compute_cost(cur_m, static_weight)
            if sc < ord_best_cost[t]:
                ord_best_cost[t] = sc
                ord_best_m[t] = list(cur_m)
                ord_best_rm[t] = list(cur_rm)
            if sc < global_best_cost:
                global_best_cost = sc
                global_best_m = list(cur_m)
                global_best_rm = list(cur_rm)

            # Per-ordering bandit state
            window = []
            mode_successes = [0] * K
            mode_attempts = [0] * K

            def select_perturbation_mode():
                EPSILON = 0.1
                if random.random() < EPSILON or sum(mode_attempts) < K * 2:
                    return random.randint(0, K - 1)
                rates = []
                for k in range(K):
                    if mode_attempts[k] > 0:
                        rates.append(mode_successes[k] / mode_attempts[k])
                    else:
                        rates.append(1.0)
                total = sum(rates)
                if total < 1e-12:
                    return random.randint(0, K - 1)
                r = random.random() * total
                cumul = 0.0
                for k in range(K):
                    cumul += rates[k]
                    if r <= cumul:
                        return k
                return K - 1

            T_sa = max(cur_cost_nl * 0.05, 1.0)
            T_init = T_sa
            alpha_sa = 0.94
            reheat_interval = max(n_ils // 4, 8)

            for ils_iter in range(n_ils):
                if _time() - t_start > time_budget:
                    break

                progress = ils_iter / max(n_ils - 1, 1)
                alpha_exp = alpha_start + (alpha_end - alpha_start) * progress

                saved_m = list(cur_m)
                saved_rm = list(cur_rm)
                saved_cost = cur_cost_nl

                mode = select_perturbation_mode()
                perturbation_modes[mode](cur_m, cur_rm,
                                         nbrs=eff_nbrs, weights=eff_weights,
                                         alpha_exp=alpha_exp)

                new_cost_nl = local_search(cur_m, cur_rm, eff_nbrs, eff_weights,
                                           alpha_exp=alpha_exp, max_rounds=3)

                success = new_cost_nl < saved_cost - 1e-12
                improvement = saved_cost - new_cost_nl

                if improvement > 0:
                    cur_cost_nl = new_cost_nl
                    sc = compute_cost(cur_m, static_weight)
                    if sc < ord_best_cost[t]:
                        ord_best_cost[t] = sc
                        ord_best_m[t] = list(cur_m)
                        ord_best_rm[t] = list(cur_rm)
                    if sc < global_best_cost:
                        global_best_cost = sc
                        global_best_m = list(cur_m)
                        global_best_rm = list(cur_rm)
                elif random.random() < math.exp(min(0, improvement / max(T_sa, 1e-10))):
                    cur_cost_nl = new_cost_nl
                else:
                    cur_m[:] = saved_m
                    cur_rm[:] = saved_rm
                    cur_cost_nl = saved_cost

                # Update bandit window
                mode_attempts[mode] += 1
                if success:
                    mode_successes[mode] += 1
                window.append((mode, success))
                if len(window) > 100:
                    old_mode, old_success = window.pop(0)
                    mode_attempts[old_mode] -= 1
                    if old_success:
                        mode_successes[old_mode] -= 1

                T_sa *= alpha_sa
                if (ils_iter + 1) % reheat_interval == 0:
                    T_sa = max(T_sa, T_init * 0.35)

            ord_cur_m[t] = cur_m
            ord_cur_rm[t] = cur_rm

        # Routing simulation with all 3 orderings — worst-case feedback
        if rsdiwr_iter < n_rsdiwr - 1:
            sim_depth = 12 + rsdiwr_iter * 6
            for t in range(T_COUNT):
                # Simulate routing for each ordering's best mapping
                sc_t = simulate_routing(ord_best_m[t], ord_best_rm[t], max_layers=sim_depth)
                # Merge using max across orderings for worst-case pressure
                if t == 0:
                    merged_swap_counts = defaultdict(float, sc_t)
                else:
                    for key, val in sc_t.items():
                        merged_swap_counts[key] = max(merged_swap_counts.get(key, 0.0), val)

            # Distribute merged worst-case feedback to all orderings
            for t in range(T_COUNT):
                ord_swap_counts[t] = merged_swap_counts

    # ---------------------------------------------------------------
    # Step 12: Final selection — route all T best candidates, pick lowest
    # ---------------------------------------------------------------
    # Score each ordering's best under the primary static weight
    final_candidates = []
    for t in range(T_COUNT):
        sc = compute_cost(ord_best_m[t], static_weight)
        final_candidates.append((sc, ord_best_m[t], ord_best_rm[t]))

    # Also consider the global best
    final_candidates.append((global_best_cost, global_best_m, global_best_rm))

    # Route-simulate all candidates and pick best
    best_route_score = float('inf')
    best_final_m = global_best_m
    best_final_rm = global_best_rm

    for sc, m_c, rm_c in final_candidates:
        route_swaps = simulate_routing(m_c, rm_c, max_layers=30)
        route_score = sum(route_swaps.values()) + sc * 0.001  # tie-break by static cost
        if route_score < best_route_score:
            best_route_score = route_score
            best_final_m = m_c
            best_final_rm = rm_c

    # ---------------------------------------------------------------
    # Step 13: Set final mapping
    # ---------------------------------------------------------------
    self.mapping_dict = best_final_m
    self.reverse_mapping_dict = best_final_rm

    if self.use_isl:
        self.isl_mapping = dict_to_isl_map(self.mapping_dict)

def init_mapping(self):
    import math
    import random
    import heapq
    from collections import defaultdict, deque
    from time import time as _time

    num_q = self.num_qubits
    physical_qubits = sorted(self.backend.keys())
    dist = self.distance_matrix

    # ---------------------------------------------------------------
    # Step 1: Build DAG and topological layers
    # ---------------------------------------------------------------
    all_gates = sorted(self.access.keys())
    two_qubit_gates = [g for g in all_gates if len(self.access[g]) == 2]

    last_gate_on_qubit = {}
    successors_dag = defaultdict(set)
    predecessors_dag = defaultdict(set)
    for g in all_gates:
        for q in self.access[g]:
            if q in last_gate_on_qubit:
                pred = last_gate_on_qubit[q]
                successors_dag[pred].add(g)
                predecessors_dag[g].add(pred)
            last_gate_on_qubit[q] = g

    in_degree = {g: len(predecessors_dag[g]) for g in all_gates}
    gate_layer = {g: 0 for g in all_gates}
    temp_in = dict(in_degree)
    queue = deque(g for g in all_gates if in_degree[g] == 0)
    topo_order = []
    while queue:
        g = queue.popleft()
        topo_order.append(g)
        for s in successors_dag[g]:
            gate_layer[s] = max(gate_layer[s], gate_layer[g] + 1)
            temp_in[s] -= 1
            if temp_in[s] == 0:
                queue.append(s)

    critical_path = {g: 0 for g in all_gates}
    for g in reversed(topo_order):
        for s in successors_dag[g]:
            if critical_path[s] + 1 > critical_path[g]:
                critical_path[g] = critical_path[s] + 1

    # 2q DAG for routing simulation
    gates_2q = {}
    dag2q_succ = defaultdict(set)
    dag2q_pred = defaultdict(set)
    last_2q_on_qubit = {}
    logical_qubits_set = set()

    for gate in all_gates:
        qubits = self.access[gate]
        if len(qubits) == 2:
            q1, q2 = qubits
            gates_2q[gate] = (q1, q2)
            logical_qubits_set.add(q1)
            logical_qubits_set.add(q2)
            for q in [q1, q2]:
                if q in last_2q_on_qubit:
                    prev = last_2q_on_qubit[q]
                    if prev != gate:
                        dag2q_succ[prev].add(gate)
                        dag2q_pred[gate].add(prev)
                last_2q_on_qubit[q] = gate
        elif len(qubits) == 1:
            logical_qubits_set.add(qubits[0])

    logical_qubits = sorted(logical_qubits_set)

    if not gates_2q:
        self.mapping_dict = list(range(num_q))
        self.reverse_mapping_dict = list(range(num_q))
        if self.use_isl:
            self.isl_mapping = dict_to_isl_map(self.mapping_dict)
        return

    # Topological order for 2q DAG
    topo_2q = []
    in_deg_2q = {g: len(dag2q_pred[g]) for g in gates_2q}
    q2 = deque(sorted(g for g in gates_2q if in_deg_2q[g] == 0))
    while q2:
        g = q2.popleft()
        topo_2q.append(g)
        for s in dag2q_succ[g]:
            in_deg_2q[s] -= 1
            if in_deg_2q[s] == 0:
                q2.append(s)

    dep_count = defaultdict(int)
    for g in reversed(topo_2q):
        for s in dag2q_succ[g]:
            dep_count[g] = max(dep_count[g], dep_count[s] + 1)

    bwd_dep = defaultdict(int)
    for g in topo_2q:
        for p in dag2q_pred[g]:
            if p in gates_2q:
                bwd_dep[g] = max(bwd_dep[g], bwd_dep[p] + 1)

    # ---------------------------------------------------------------
    # Step 2: Commutativity-aware structures
    # Build adjacency in topo order and commutativity checker
    # Two CX gates commute iff they act on disjoint qubit sets
    # ---------------------------------------------------------------
    def gates_commute(g1, g2):
        """Check if two 2-qubit gates commute (disjoint qubit sets)."""
        q1a, q1b = gates_2q[g1]
        q2a, q2b = gates_2q[g2]
        return q1a != q2a and q1a != q2b and q1b != q2a and q1b != q2b

    def recompute_topo_and_deps():
        """Recompute topological order and dependency counts after DAG relinearization."""
        nonlocal topo_2q, dep_count, bwd_dep
        new_in_deg = {g: len(dag2q_pred[g]) for g in gates_2q}
        new_topo = []
        qq = deque(sorted(g for g in gates_2q if new_in_deg[g] == 0))
        while qq:
            g = qq.popleft()
            new_topo.append(g)
            for s in dag2q_succ[g]:
                new_in_deg[s] -= 1
                if new_in_deg[s] == 0:
                    qq.append(s)
        topo_2q = new_topo

        dep_count = defaultdict(int)
        for g in reversed(topo_2q):
            for s in dag2q_succ[g]:
                dep_count[g] = max(dep_count[g], dep_count[s] + 1)

        bwd_dep = defaultdict(int)
        for g in topo_2q:
            for p in dag2q_pred[g]:
                if p in gates_2q:
                    bwd_dep[g] = max(bwd_dep[g], bwd_dep[p] + 1)

    # ---------------------------------------------------------------
    # Step 3: Interaction weights — critical-path weighting
    # ---------------------------------------------------------------
    def compute_interaction_weights():
        max_layer_val = max((gate_layer[g] for g in two_qubit_gates), default=1)
        sw = defaultdict(float)
        ld = defaultdict(float)
        for g in two_qubit_gates:
            q1, q2 = self.access[g]
            cp = critical_path[g] + 1
            layer = gate_layer[g]
            w = cp * (max_layer_val - layer + 1)
            key = (min(q1, q2), max(q1, q2))
            sw[key] += w
            ld[q1] += w
            ld[q2] += w
        return sw, ld

    static_weight, logical_degree = compute_interaction_weights()
    interacting_logical = [q for q in logical_qubits if logical_degree.get(q, 0) > 0]

    # ---------------------------------------------------------------
    # Step 4: Physical graph properties
    # ---------------------------------------------------------------
    hw_adj = defaultdict(set)
    for pq in physical_qubits:
        for pq2 in self.backend.get(pq, []):
            hw_adj[pq].add(pq2)

    phys_degree = {pq: len(hw_adj[pq]) for pq in physical_qubits}
    phys_centrality = {}
    for pq in physical_qubits:
        phys_centrality[pq] = sum(dist[pq][pq2] for pq2 in physical_qubits)

    # ---------------------------------------------------------------
    # Step 5: Helper functions
    # ---------------------------------------------------------------
    def build_neighbors(weights):
        nbrs = defaultdict(dict)
        deg = defaultdict(float)
        for (q1, q2), w in weights.items():
            nbrs[q1][q2] = w
            nbrs[q2][q1] = w
            deg[q1] += w
            deg[q2] += w
        return nbrs, deg

    def compute_cost_nonlinear(m, weights, alpha_exp):
        cost = 0.0
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                d = dist[m[q1]][m[q2]]
                cost += w * (d ** alpha_exp)
        return cost

    def compute_cost(m, weights):
        cost = 0.0
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                cost += w * dist[m[q1]][m[q2]]
        return cost

    def delta_swap_cost_nonlinear(m, rm, pq_a, pq_b, nbrs, alpha_exp):
        lq_a, lq_b = rm[pq_a], rm[pq_b]
        delta = 0.0
        affected = set()
        if lq_a in nbrs:
            affected.update(nbrs[lq_a].keys())
        if lq_b in nbrs:
            affected.update(nbrs[lq_b].keys())
        for q in affected:
            if q == lq_a or q == lq_b:
                continue
            pq_q = m[q]
            w_a = nbrs.get(lq_a, {}).get(q, 0.0)
            if w_a > 0:
                old_d = dist[pq_a][pq_q] ** alpha_exp
                new_d = dist[pq_b][pq_q] ** alpha_exp
                delta += w_a * (new_d - old_d)
            w_b = nbrs.get(lq_b, {}).get(q, 0.0)
            if w_b > 0:
                old_d = dist[pq_b][pq_q] ** alpha_exp
                new_d = dist[pq_a][pq_q] ** alpha_exp
                delta += w_b * (new_d - old_d)
        return delta

    def do_swap(m, rm, pq_a, pq_b):
        lq_a, lq_b = rm[pq_a], rm[pq_b]
        m[lq_a], m[lq_b] = pq_b, pq_a
        rm[pq_a], rm[pq_b] = lq_b, lq_a

    # ---------------------------------------------------------------
    # Step 6: Forward greedy routing simulation with bottleneck tracking
    # ---------------------------------------------------------------
    def simulate_routing_greedy(m, rm, max_layers=20, track_bottlenecks=False):
        sim_m = list(m)
        sim_rm = list(rm)
        swap_counts = defaultdict(float)
        total_swaps = 0
        gate_swap_cost = defaultdict(int)  # per-gate swap cost for bottleneck detection

        if not gates_2q:
            return swap_counts, total_swaps, gate_swap_cost

        pred_remaining = {g: len(dag2q_pred[g]) for g in gates_2q}
        front = set(g for g in gates_2q if pred_remaining[g] == 0)
        layers_done = 0

        while front and layers_done < max_layers:
            executable = []
            for g in front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = sim_m[gq1], sim_m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    executable.append(g)

            if executable:
                for g in executable:
                    front.discard(g)
                    for s in dag2q_succ[g]:
                        pred_remaining[s] -= 1
                        if pred_remaining[s] == 0:
                            front.add(s)
                layers_done += 1
                continue

            active_phys = set()
            for g in front:
                gq1, gq2 = gates_2q[g]
                active_phys.add(sim_m[gq1])
                active_phys.add(sim_m[gq2])

            candidates_sw = set()
            for pq in active_phys:
                for nb in self.backend.get(pq, []):
                    candidates_sw.add((min(pq, nb), max(pq, nb)))

            best_swap, best_score = None, float('inf')
            for (s1, s2) in candidates_sw:
                l1, l2 = sim_rm[s1], sim_rm[s2]
                score = 0.0
                for g in front:
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = sim_m[gq1], sim_m[gq2]
                    if gq1 == l1: p1 = s2
                    elif gq1 == l2: p1 = s1
                    if gq2 == l1: p2 = s2
                    elif gq2 == l2: p2 = s1
                    deps = dep_count.get(g, 0) + 1
                    score += deps * dist[p1][p2]
                if score < best_score:
                    best_score = score
                    best_swap = (s1, s2)

            if best_swap is None:
                break

            s1, s2 = best_swap
            l1, l2 = sim_rm[s1], sim_rm[s2]
            sim_m[l1], sim_m[l2] = s2, s1
            sim_rm[s1], sim_rm[s2] = l2, l1
            total_swaps += 1

            for g in front:
                gq1, gq2 = gates_2q[g]
                pair_key = (min(gq1, gq2), max(gq1, gq2))
                swap_counts[pair_key] += 1.0
                if track_bottlenecks:
                    gate_swap_cost[g] += 1

        return swap_counts, total_swaps, gate_swap_cost

    def simulate_routing_backward(m, rm, max_layers=20):
        sim_m = list(m)
        sim_rm = list(rm)
        swap_counts = defaultdict(float)
        total_swaps = 0

        if not gates_2q:
            return swap_counts, total_swaps

        succ_remaining = {g: len(dag2q_succ[g] & set(gates_2q.keys())) for g in gates_2q}
        front = set(g for g in gates_2q if succ_remaining[g] == 0)
        layers_done = 0

        while front and layers_done < max_layers:
            executable = []
            for g in front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = sim_m[gq1], sim_m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    executable.append(g)

            if executable:
                for g in executable:
                    front.discard(g)
                    for p in dag2q_pred[g]:
                        if p in gates_2q:
                            succ_remaining[p] -= 1
                            if succ_remaining[p] == 0:
                                front.add(p)
                layers_done += 1
                continue

            active_phys = set()
            for g in front:
                gq1, gq2 = gates_2q[g]
                active_phys.add(sim_m[gq1])
                active_phys.add(sim_m[gq2])

            candidates_sw = set()
            for pq in active_phys:
                for nb in self.backend.get(pq, []):
                    candidates_sw.add((min(pq, nb), max(pq, nb)))

            best_swap, best_score = None, float('inf')
            for (s1, s2) in candidates_sw:
                l1, l2 = sim_rm[s1], sim_rm[s2]
                score = 0.0
                for g in front:
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = sim_m[gq1], sim_m[gq2]
                    if gq1 == l1: p1 = s2
                    elif gq1 == l2: p1 = s1
                    if gq2 == l1: p2 = s2
                    elif gq2 == l2: p2 = s1
                    deps = bwd_dep.get(g, 0) + 1
                    score += deps * dist[p1][p2]
                if score < best_score:
                    best_score = score
                    best_swap = (s1, s2)

            if best_swap is None:
                break

            s1, s2 = best_swap
            l1, l2 = sim_rm[s1], sim_rm[s2]
            sim_m[l1], sim_m[l2] = s2, s1
            sim_rm[s1], sim_rm[s2] = l2, l1
            total_swaps += 1

            for g in front:
                gq1, gq2 = gates_2q[g]
                pair_key = (min(gq1, gq2), max(gq1, gq2))
                swap_counts[pair_key] += 1.0

        return swap_counts, total_swaps

    def simulate_routing_asymmetric_bidir(m, rm, max_layers=20, track_bottlenecks=False):
        fwd_swaps, fwd_total, fwd_bottlenecks = simulate_routing_greedy(m, rm, max_layers=max_layers, track_bottlenecks=track_bottlenecks)
        bwd_swaps, bwd_total = simulate_routing_backward(m, rm, max_layers=max_layers)

        combined = defaultdict(float)
        all_keys = set(fwd_swaps.keys()) | set(bwd_swaps.keys())
        for key in all_keys:
            combined[key] = 0.6 * fwd_swaps.get(key, 0.0) + 0.4 * bwd_swaps.get(key, 0.0)

        return combined, (fwd_total + bwd_total) // 2, fwd_bottlenecks

    # ---------------------------------------------------------------
    # Step 7: DAG Relinearization — the key novelty
    # Swap adjacent commuting gates in topo order when bottleneck
    # gates could benefit from different front-layer composition
    # ---------------------------------------------------------------
    def relinearize_dag(gate_swap_cost, m, rm, max_swaps=20):
        """Reorder commuting adjacent gates in the DAG to reduce bottlenecks."""
        if not gate_swap_cost:
            return False

        # Identify bottleneck gates (needed >=2 SWAPs)
        bottleneck_gates = set(g for g, cost in gate_swap_cost.items() if cost >= 2)
        if not bottleneck_gates:
            return False

        # Build topo position index
        topo_pos = {g: i for i, g in enumerate(topo_2q)}

        # Find commuting adjacent pairs involving bottleneck gates
        # Adjacent = one is direct predecessor of the other in 2q DAG
        swaps_done = 0
        changed = False

        for bn_gate in sorted(bottleneck_gates, key=lambda g: gate_swap_cost.get(g, 0), reverse=True):
            if swaps_done >= max_swaps:
                break

            # Try swapping with predecessors
            for pred_gate in list(dag2q_pred.get(bn_gate, set())):
                if pred_gate not in gates_2q:
                    continue
                if swaps_done >= max_swaps:
                    break

                # Check commutativity (disjoint qubit sets)
                if not gates_commute(bn_gate, pred_gate):
                    continue

                # Check that pred_gate is the ONLY connection between them
                # i.e., we can safely swap their order
                # pred_gate -> bn_gate edge exists; check if removing it
                # and adding bn_gate -> pred_gate maintains a valid DAG

                # Verify: bn_gate has no other dependency on pred_gate through other paths
                # and pred_gate has no dependency on bn_gate through other paths
                # Since they commute (disjoint qubits), swapping is always safe
                # as long as it doesn't create a cycle

                # Check no other path from pred_gate to bn_gate
                other_preds_of_bn = dag2q_pred[bn_gate] - {pred_gate}
                other_succs_of_pred = dag2q_succ[pred_gate] - {bn_gate}

                # Simple cycle check: ensure bn_gate is not an ancestor of pred_gate
                # through any other path
                safe = True
                # BFS from bn_gate through other successors to see if we reach pred_gate
                visited = set()
                bfs_q = deque()
                for s in dag2q_succ.get(bn_gate, set()):
                    if s != pred_gate:
                        bfs_q.append(s)
                        visited.add(s)
                while bfs_q:
                    node = bfs_q.popleft()
                    if node == pred_gate:
                        safe = False
                        break
                    for s in dag2q_succ.get(node, set()):
                        if s not in visited:
                            visited.add(s)
                            bfs_q.append(s)

                if not safe:
                    continue

                # Perform the swap: remove pred->bn edge, add bn->pred edge
                dag2q_succ[pred_gate].discard(bn_gate)
                dag2q_pred[bn_gate].discard(pred_gate)
                dag2q_succ[bn_gate].add(pred_gate)
                dag2q_pred[pred_gate].add(bn_gate)

                swaps_done += 1
                changed = True

            # Try swapping with successors
            for succ_gate in list(dag2q_succ.get(bn_gate, set())):
                if succ_gate not in gates_2q:
                    continue
                if swaps_done >= max_swaps:
                    break

                if not gates_commute(bn_gate, succ_gate):
                    continue

                # Check no cycle: ensure succ_gate is not an ancestor of bn_gate
                # through other paths
                safe = True
                visited = set()
                bfs_q = deque()
                for p in dag2q_pred.get(succ_gate, set()):
                    if p != bn_gate and p in gates_2q:
                        bfs_q.append(p)
                        visited.add(p)
                while bfs_q:
                    node = bfs_q.popleft()
                    if node == bn_gate:
                        safe = False
                        break
                    for p in dag2q_pred.get(node, set()):
                        if p in gates_2q and p not in visited:
                            visited.add(p)
                            bfs_q.append(p)

                if not safe:
                    continue

                # Swap: remove bn->succ edge, add succ->bn edge
                dag2q_succ[bn_gate].discard(succ_gate)
                dag2q_pred[succ_gate].discard(bn_gate)
                dag2q_succ[succ_gate].add(bn_gate)
                dag2q_pred[bn_gate].add(succ_gate)

                swaps_done += 1
                changed = True

        if changed:
            recompute_topo_and_deps()

        return changed

    # ---------------------------------------------------------------
    # Step 8: A*-guided early-layer routing
    # ---------------------------------------------------------------
    ASTAR_LAYERS = 5
    n_2q = len(gates_2q)
    if n_2q < 50:
        ASTAR_NODE_LIMIT = 8000
    elif n_2q < 200:
        ASTAR_NODE_LIMIT = 5000
    else:
        ASTAR_NODE_LIMIT = 3000

    pred_rem_layer = {g: len(dag2q_pred[g]) for g in gates_2q}
    front_layer_calc = set(g for g in gates_2q if pred_rem_layer[g] == 0)
    current_layer = 0
    early_layer_gates = set()

    temp_front = set(front_layer_calc)
    while temp_front:
        for g in temp_front:
            if current_layer < ASTAR_LAYERS:
                early_layer_gates.add(g)
        next_front = set()
        for g in temp_front:
            for s in dag2q_succ[g]:
                pred_rem_layer[s] -= 1
                if pred_rem_layer[s] == 0:
                    next_front.add(s)
        current_layer += 1
        temp_front = next_front

    def astar_routing_early(m, rm):
        if not early_layer_gates:
            return defaultdict(float), 0

        early_pred = {}
        for g in early_layer_gates:
            early_pred[g] = len(dag2q_pred[g] & early_layer_gates)

        initial_front = frozenset(g for g in early_layer_gates if early_pred[g] == 0)

        init_executed = set()
        cur_front = set(initial_front)
        changed_flag = True
        while changed_flag:
            changed_flag = False
            newly_exec = set()
            for g in cur_front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = m[gq1], m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    newly_exec.add(g)
            if newly_exec:
                changed_flag = True
                init_executed |= newly_exec
                cur_front -= newly_exec
                for g in newly_exec:
                    for s in dag2q_succ[g]:
                        if s in early_layer_gates and s not in init_executed:
                            all_pred_done = True
                            for p in dag2q_pred[s]:
                                if p in early_layer_gates and p not in init_executed:
                                    all_pred_done = False
                                    break
                            if all_pred_done:
                                cur_front.add(s)

        remaining_early = early_layer_gates - init_executed
        if not remaining_early:
            return defaultdict(float), 0

        def compute_front(executed):
            front = set()
            for g in early_layer_gates:
                if g in executed:
                    continue
                all_pred = True
                for p in dag2q_pred[g]:
                    if p in early_layer_gates and p not in executed:
                        all_pred = False
                        break
                if all_pred:
                    front.add(g)
            return frozenset(front)

        init_exec_frozen = frozenset(init_executed)
        init_front_astar = compute_front(init_executed)

        active_logical = set()
        for g in remaining_early:
            gq1, gq2 = gates_2q[g]
            active_logical.add(gq1)
            active_logical.add(gq2)

        def h_func(mapping, front_gates):
            h = 0
            for g in front_gates:
                gq1, gq2 = gates_2q[g]
                h += dist[mapping[gq1]][mapping[gq2]]
            return h

        active_logical_list = sorted(active_logical)

        def mapping_key(mapping):
            return tuple(mapping[lq] for lq in active_logical_list)

        init_m = list(m)
        init_h = h_func(init_m, init_front_astar)

        counter = [0]
        start_state = (init_h, 0, 0, init_m, init_exec_frozen, init_front_astar)
        open_heap = [start_state]
        visited = {}
        best_known_total = float('inf')
        best_result = None

        swap_history = {}
        init_key = (mapping_key(init_m), init_exec_frozen)
        swap_history[init_key] = defaultdict(float)

        expansions = 0

        while open_heap and expansions < ASTAR_NODE_LIMIT:
            f, _, g_cost, cur_m_list, executed, front = heapq.heappop(open_heap)

            mk = mapping_key(cur_m_list)
            state_key = (mk, executed)

            if state_key in visited and visited[state_key] <= g_cost:
                continue
            visited[state_key] = g_cost

            if best_known_total < float('inf') and f > best_known_total * 1.2:
                continue

            new_executed = set(executed)
            new_front = set(front)
            progress = True
            while progress:
                progress = False
                newly_exec = set()
                for g in list(new_front):
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = cur_m_list[gq1], cur_m_list[gq2]
                    if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                        newly_exec.add(g)
                if newly_exec:
                    progress = True
                    new_executed |= newly_exec
                    new_front -= newly_exec
                    for g in newly_exec:
                        for s in dag2q_succ[g]:
                            if s in early_layer_gates and s not in new_executed:
                                all_pred = True
                                for p in dag2q_pred[s]:
                                    if p in early_layer_gates and p not in new_executed:
                                        all_pred = False
                                        break
                                if all_pred:
                                    new_front.add(s)

            new_exec_frozen = frozenset(new_executed)
            new_front_frozen = frozenset(new_front)

            if not (early_layer_gates - new_executed):
                if g_cost < best_known_total:
                    best_known_total = g_cost
                    parent_key = (mk, executed)
                    pair_swaps = dict(swap_history.get(parent_key, {}))
                    best_result = (g_cost, pair_swaps)
                continue

            if not new_front_frozen:
                continue

            active_phys = set()
            for g in new_front_frozen:
                gq1, gq2 = gates_2q[g]
                active_phys.add(cur_m_list[gq1])
                active_phys.add(cur_m_list[gq2])
            ext_gates = set()
            for g in new_front_frozen:
                for s in dag2q_succ[g]:
                    if s in early_layer_gates and s not in new_executed:
                        ext_gates.add(s)
            for g in ext_gates:
                gq1, gq2 = gates_2q[g]
                active_phys.add(cur_m_list[gq1])
                active_phys.add(cur_m_list[gq2])

            swaps = set()
            for pq in active_phys:
                for nb in hw_adj.get(pq, set()):
                    swaps.add((min(pq, nb), max(pq, nb)))

            expansions += 1
            parent_pair_swaps = swap_history.get((mk, executed), defaultdict(float))

            for (s1, s2) in swaps:
                new_m = list(cur_m_list)
                lq_at_s1 = -1
                lq_at_s2 = -1
                for lq in range(num_q):
                    if new_m[lq] == s1:
                        lq_at_s1 = lq
                    if new_m[lq] == s2:
                        lq_at_s2 = lq

                if lq_at_s1 >= 0:
                    new_m[lq_at_s1] = s2
                if lq_at_s2 >= 0:
                    new_m[lq_at_s2] = s1

                new_g = g_cost + 1
                new_mk = mapping_key(new_m)
                child_key = (new_mk, new_exec_frozen)

                if child_key in visited and visited[child_key] <= new_g:
                    continue

                new_h = h_func(new_m, new_front_frozen)
                new_f = new_g + new_h

                if best_known_total < float('inf') and new_f > best_known_total * 1.2:
                    continue

                counter[0] += 1

                child_pair_swaps = defaultdict(float, parent_pair_swaps)
                for g in new_front_frozen:
                    gq1, gq2 = gates_2q[g]
                    pair_key = (min(gq1, gq2), max(gq1, gq2))
                    child_pair_swaps[pair_key] += 1.0

                swap_history[child_key] = child_pair_swaps
                heapq.heappush(open_heap, (new_f, counter[0], new_g, new_m, new_exec_frozen, new_front_frozen))

        if best_result is not None:
            return defaultdict(float, best_result[1]), best_result[0]
        else:
            return defaultdict(float), 0

    def simulate_routing_hybrid(m, rm, max_layers=20):
        astar_swaps, astar_total = astar_routing_early(m, rm)
        greedy_swaps, greedy_total, _ = simulate_routing_greedy(m, rm, max_layers=max_layers)

        combined_swaps = defaultdict(float)
        early_pairs = set()
        for g in early_layer_gates:
            gq1, gq2 = gates_2q[g]
            early_pairs.add((min(gq1, gq2), max(gq1, gq2)))

        for pair_key in early_pairs:
            if pair_key in astar_swaps:
                combined_swaps[pair_key] = astar_swaps[pair_key]

        for pair_key, count in greedy_swaps.items():
            if pair_key not in early_pairs:
                combined_swaps[pair_key] = count

        return combined_swaps, astar_total + greedy_total

    def simulate_routing_hybrid_bidir(m, rm, max_layers=20):
        astar_swaps, astar_total = astar_routing_early(m, rm)
        fwd_swaps, fwd_total, _ = simulate_routing_greedy(m, rm, max_layers=max_layers)
        bwd_swaps, bwd_total = simulate_routing_backward(m, rm, max_layers=max_layers)

        combined_swaps = defaultdict(float)
        early_pairs = set()
        for g in early_layer_gates:
            gq1, gq2 = gates_2q[g]
            early_pairs.add((min(gq1, gq2), max(gq1, gq2)))

        for pair_key in early_pairs:
            if pair_key in astar_swaps:
                combined_swaps[pair_key] = astar_swaps[pair_key]

        all_late_keys = (set(fwd_swaps.keys()) | set(bwd_swaps.keys())) - early_pairs
        for pair_key in all_late_keys:
            combined_swaps[pair_key] = 0.6 * fwd_swaps.get(pair_key, 0.0) + 0.4 * bwd_swaps.get(pair_key, 0.0)

        return combined_swaps, astar_total + (fwd_total + bwd_total) // 2

    # ---------------------------------------------------------------
    # Step 9: Seed generation
    # ---------------------------------------------------------------
    sorted_by_degree = sorted(interacting_logical, key=lambda q: logical_degree[q], reverse=True)
    seed_lqs = sorted_by_degree[:min(3, len(sorted_by_degree))]
    phys_by_centrality = sorted(physical_qubits, key=lambda pq: phys_centrality[pq])
    seed_pqs = phys_by_centrality[:min(3, len(phys_by_centrality))]

    logical_degree_ranked = sorted(interacting_logical, key=lambda q: logical_degree[q], reverse=True)
    logical_degree_rank = {q: i for i, q in enumerate(logical_degree_ranked)}
    max_logical_rank = max(len(logical_degree_ranked) - 1, 1)
    phys_degree_ranked = sorted(physical_qubits, key=lambda pq: phys_degree[pq], reverse=True)
    phys_degree_rank = {pq: i for i, pq in enumerate(phys_degree_ranked)}
    max_phys_rank = max(len(phys_degree_ranked) - 1, 1)

    static_nbrs, static_deg = build_neighbors(static_weight)
    max_iw = max(static_weight.values()) if static_weight else 1.0

    # ---------------------------------------------------------------
    # MIS seed
    # ---------------------------------------------------------------
    def conflict_graph_seed(start_pq, nbrs, deg, weights, routing_pressure=None):
        if len(interacting_logical) < 2:
            return None, None

        cur_max_iw = max(weights.values()) if weights else 1.0

        top_partners = {}
        for lq in interacting_logical:
            nbr_list = sorted(nbrs.get(lq, {}).items(), key=lambda x: x[1], reverse=True)
            top_partners[lq] = set(p for p, _ in nbr_list[:3])

        conflict_adj = defaultdict(set)
        il = interacting_logical

        qubit_pressure = defaultdict(float)
        if routing_pressure:
            for (q1, q2), cnt in routing_pressure.items():
                qubit_pressure[q1] += cnt
                qubit_pressure[q2] += cnt

        for i in range(len(il)):
            for j in range(i + 1, len(il)):
                l1, l2 = il[i], il[j]
                s1 = top_partners.get(l1, set())
                s2 = top_partners.get(l2, set())
                if not s1 and not s2:
                    continue
                intersection = len(s1 & s2)
                union = len(s1 | s2)
                if union > 0:
                    jaccard = intersection / union
                    threshold = 0.5
                    if routing_pressure and qubit_pressure[l1] > 0 and qubit_pressure[l2] > 0:
                        max_pressure = max(qubit_pressure.values()) if qubit_pressure else 1.0
                        pressure_factor = min(1.0, (qubit_pressure[l1] + qubit_pressure[l2]) /
                                              (max_pressure * 2 + 1e-10))
                        threshold = max(0.25, 0.5 - 0.25 * pressure_factor)
                    if jaccard > threshold:
                        conflict_adj[l1].add(l2)
                        conflict_adj[l2].add(l1)

        sorted_by_deg_local = sorted(interacting_logical,
                                     key=lambda q: (deg.get(q, 0), qubit_pressure.get(q, 0)),
                                     reverse=True)
        mis = set()
        excluded = set()
        for lq in sorted_by_deg_local:
            if lq not in excluded:
                mis.add(lq)
                for neighbor in conflict_adj.get(lq, set()):
                    excluded.add(neighbor)

        non_mis = [lq for lq in sorted_by_deg_local if lq not in mis]
        mis_ordered = sorted(mis, key=lambda q: (deg.get(q, 0), qubit_pressure.get(q, 0)),
                             reverse=True)

        m = [-1] * num_q
        rm = [-1] * num_q
        used_phys = set()

        if mis_ordered:
            first_lq = mis_ordered[0]
            m[first_lq] = start_pq
            rm[start_pq] = first_lq
            used_phys.add(start_pq)

            for lq in mis_ordered[1:]:
                nbrs_placed = {}
                for plq in mis:
                    if m[plq] >= 0 and plq in nbrs.get(lq, {}):
                        nbrs_placed[plq] = nbrs[lq][plq]

                if nbrs_placed:
                    best_pq = None
                    best_score = float('inf')
                    for pq in physical_qubits:
                        if pq in used_phys:
                            continue
                        score = 0.0
                        for plq, iw in nbrs_placed.items():
                            d = dist[pq][m[plq]]
                            cost = iw * d
                            if m[plq] in hw_adj[pq]:
                                cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                            score += cost
                        if score < best_score:
                            best_score = score
                            best_pq = pq
                else:
                    best_pq = None
                    best_score = float('inf')
                    for pq in physical_qubits:
                        if pq not in used_phys:
                            if phys_centrality[pq] < best_score:
                                best_score = phys_centrality[pq]
                                best_pq = pq

                if best_pq is not None:
                    m[lq] = best_pq
                    rm[best_pq] = lq
                    used_phys.add(best_pq)

        placed_set = set(lq for lq in interacting_logical if m[lq] >= 0)

        for lq in non_mis:
            nbrs_placed = {}
            for plq in placed_set:
                w = nbrs.get(lq, {}).get(plq, 0.0)
                if w > 0:
                    nbrs_placed[plq] = w

            if nbrs_placed:
                near_ties = []
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq in used_phys:
                        continue
                    score = 0.0
                    for plq, iw in nbrs_placed.items():
                        d = dist[pq][m[plq]]
                        cost = iw * d
                        if m[plq] in hw_adj[pq]:
                            cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                        score += cost
                    near_ties.append((score, pq))
                    if score < best_score:
                        best_score = score

                if near_ties and best_score > 0:
                    threshold = best_score * 1.05
                    candidates_list = [(s, pq) for s, pq in near_ties if s <= threshold]
                    if len(candidates_list) > 1 and lq in logical_degree_rank:
                        lq_rn = logical_degree_rank[lq] / max_logical_rank
                        best_pq = min(candidates_list, key=lambda x: (
                            abs(phys_degree_rank[x[1]] / max_phys_rank - lq_rn), x[0]))[1]
                    else:
                        best_pq = min(candidates_list, key=lambda x: x[0])[1]
                elif near_ties:
                    best_pq = min(near_ties, key=lambda x: x[0])[1]
                else:
                    best_pq = None
            else:
                best_pq = None
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq not in used_phys:
                        if phys_centrality[pq] < best_score:
                            best_score = phys_centrality[pq]
                            best_pq = pq

            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                used_phys.add(best_pq)
                placed_set.add(lq)

        remaining_lqs = [lq for lq in logical_qubits if m[lq] == -1]
        for lq in remaining_lqs:
            best_pq = None
            best_score = float('inf')
            for pq in physical_qubits:
                if pq not in used_phys:
                    if phys_centrality[pq] < best_score:
                        best_score = phys_centrality[pq]
                        best_pq = pq
            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                used_phys.add(best_pq)

        return m, rm

    # ---------------------------------------------------------------
    # Spectral seed
    # ---------------------------------------------------------------
    def spectral_seed():
        if len(interacting_logical) < 3:
            return None, None

        idx_map = {q: i for i, q in enumerate(interacting_logical)}
        n = len(interacting_logical)

        L = [[0.0] * n for _ in range(n)]
        for (q1, q2), w in static_weight.items():
            if q1 in idx_map and q2 in idx_map:
                i, j = idx_map[q1], idx_map[q2]
                L[i][j] -= w
                L[j][i] -= w
                L[i][i] += w
                L[j][j] += w

        def power_iter(mat, n_iter=200):
            v = [random.gauss(0, 1) for _ in range(n)]
            for _ in range(n_iter):
                new_v = [0.0] * n
                for i in range(n):
                    for j in range(n):
                        new_v[i] += mat[i][j] * v[j]
                norm = math.sqrt(sum(x * x for x in new_v)) or 1e-12
                v = [x / norm for x in new_v]
            return v

        max_diag = max(L[i][i] for i in range(n)) + 1.0
        shifted = [[0.0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                shifted[i][j] = -L[i][j]
            shifted[i][i] += max_diag

        v1 = power_iter(shifted, 150)

        dot_v1 = sum(x * x for x in v1) or 1e-12
        lam1_shifted = sum(v1[i] * sum(shifted[i][j] * v1[j] for j in range(n)) for i in range(n)) / dot_v1
        shifted2 = [row[:] for row in shifted]
        for i in range(n):
            for j in range(n):
                shifted2[i][j] -= lam1_shifted * v1[i] * v1[j] / dot_v1

        fiedler = power_iter(shifted2, 200)

        fiedler_order = sorted(range(n), key=lambda i: fiedler[i])
        sorted_logical = [interacting_logical[i] for i in fiedler_order]

        phys_sorted = sorted(physical_qubits, key=lambda pq: phys_centrality[pq])
        start_pq = phys_sorted[0]
        visited_bfs = set()
        bfs_order = []
        bfs_q = deque([start_pq])
        visited_bfs.add(start_pq)
        while bfs_q:
            pq = bfs_q.popleft()
            bfs_order.append(pq)
            for nb in sorted(hw_adj[pq]):
                if nb not in visited_bfs:
                    visited_bfs.add(nb)
                    bfs_q.append(nb)
        for pq in physical_qubits:
            if pq not in visited_bfs:
                bfs_order.append(pq)
                visited_bfs.add(pq)

        m = [-1] * num_q
        rm = [-1] * num_q
        n_interact = len(sorted_logical)
        n_phys = len(bfs_order)
        offset = max(0, (n_phys - n_interact) // 2)
        for i, lq in enumerate(sorted_logical):
            pq = bfs_order[min(offset + i, n_phys - 1)]
            if rm[pq] != -1:
                best_pq = None
                best_d = float('inf')
                for cpq in physical_qubits:
                    if rm[cpq] == -1:
                        d = dist[pq][cpq]
                        if d < best_d:
                            best_d = d
                            best_pq = cpq
                pq = best_pq
            m[lq] = pq
            rm[pq] = lq

        return m, rm

    # ---------------------------------------------------------------
    # Greedy placement
    # ---------------------------------------------------------------
    def run_greedy_placement(start_lq, start_pq, nbrs, deg, weights=None):
        cur_max_iw = max(weights.values()) if weights else max_iw
        used_phys = {start_pq}
        m = [-1] * num_q
        rm = [-1] * num_q
        m[start_lq] = start_pq
        rm[start_pq] = start_lq
        placed = {start_lq}
        remaining = set(logical_qubits) - placed

        while remaining:
            best_lq, best_w = None, -1.0
            for lq in remaining:
                w = sum(nbrs.get(lq, {}).get(plq, 0.0) for plq in placed)
                if w > best_w:
                    best_w = w
                    best_lq = lq

            nbrs_placed = {plq: nbrs.get(best_lq, {}).get(plq, 0.0)
                           for plq in placed if plq in nbrs.get(best_lq, {})}

            if nbrs_placed:
                near_ties = []
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq in used_phys:
                        continue
                    score = 0.0
                    for plq, iw in nbrs_placed.items():
                        d = dist[pq][m[plq]]
                        cost = iw * d
                        if m[plq] in hw_adj[pq]:
                            cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                        score += cost
                    near_ties.append((score, pq))
                    if score < best_score:
                        best_score = score

                if near_ties and best_score > 0:
                    threshold = best_score * 1.05
                    candidates_list = [(s, pq) for s, pq in near_ties if s <= threshold]
                    if len(candidates_list) > 1 and best_lq in logical_degree_rank:
                        lq_rn = logical_degree_rank[best_lq] / max_logical_rank
                        best_pq = min(candidates_list, key=lambda x: (
                            abs(phys_degree_rank[x[1]] / max_phys_rank - lq_rn), x[0]))[1]
                    else:
                        best_pq = min(candidates_list, key=lambda x: x[0])[1]
                elif near_ties:
                    best_pq = min(near_ties, key=lambda x: x[0])[1]
                else:
                    best_pq = None
            else:
                best_pq = None
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq not in used_phys:
                        score = phys_centrality[pq]
                        if score < best_score:
                            best_score = score
                            best_pq = pq

            m[best_lq] = best_pq
            rm[best_pq] = best_lq
            used_phys.add(best_pq)
            placed.add(best_lq)
            remaining.discard(best_lq)
        return m, rm

    def fill_unmapped(m, rm):
        unmapped = [q for q in range(num_q) if m[q] == -1]
        free = [pq for pq in range(num_q) if rm[pq] == -1]
        for lq, pq in zip(unmapped, free):
            m[lq] = pq
            rm[pq] = lq

    # ---------------------------------------------------------------
    # Local search
    # ---------------------------------------------------------------
    def local_search(m, rm, nbrs, weights, alpha_exp, max_rounds=5):
        if len(interacting_logical) <= 1:
            return compute_cost_nonlinear(m, weights, alpha_exp)
        for _ in range(max_rounds):
            improved = False
            best_d, best_pair = 0.0, None
            active_phys = [m[q] for q in interacting_logical]
            for pq1 in active_phys:
                for pq2 in hw_adj.get(pq1, set()):
                    d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                    if d < best_d:
                        best_d = d
                        best_pair = (pq1, pq2)
            n_random = min(150, len(interacting_logical) * 3)
            for _ in range(n_random):
                i, j = random.sample(range(len(interacting_logical)), 2)
                pq1, pq2 = m[interacting_logical[i]], m[interacting_logical[j]]
                d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                if d < best_d:
                    best_d = d
                    best_pair = (pq1, pq2)
            if best_pair and best_d < -1e-12:
                do_swap(m, rm, *best_pair)
                improved = True
            if not improved:
                for i in range(len(interacting_logical)):
                    for j in range(i + 1, len(interacting_logical)):
                        pq1, pq2 = m[interacting_logical[i]], m[interacting_logical[j]]
                        d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                        if d < best_d:
                            best_d = d
                            best_pair = (pq1, pq2)
                if best_pair and best_d < -1e-12:
                    do_swap(m, rm, *best_pair)
                else:
                    break
        return compute_cost_nonlinear(m, weights, alpha_exp)

    # ---------------------------------------------------------------
    # Perturbation modes with bandit selection
    # ---------------------------------------------------------------
    rsdiwr_iter_ref = [0]
    accumulated_routing_pressure_ref = [defaultdict(float)]

    def perturb_random(m, rm, **kw):
        if len(interacting_logical) >= 2:
            lqs = random.sample(interacting_logical, 2)
            do_swap(m, rm, m[lqs[0]], m[lqs[1]])

    def perturb_segment_shuffle(m, rm, **kw):
        k = min(random.randint(3, 5), len(interacting_logical))
        if k < 2:
            perturb_random(m, rm)
            return
        lqs = random.sample(interacting_logical, k)
        phys_positions = [m[lq] for lq in lqs]
        random.shuffle(phys_positions)
        for lq in lqs:
            rm[m[lq]] = -1
        for lq, pq in zip(lqs, phys_positions):
            m[lq] = pq
            rm[pq] = lq

    def perturb_worst_pair(m, rm, weights=None, alpha_exp=1.5, **kw):
        if weights is None:
            perturb_random(m, rm)
            return
        pair_costs = []
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                d = dist[m[q1]][m[q2]]
                c = w * (d ** alpha_exp)
                pair_costs.append((c, q1, q2))
        if not pair_costs:
            return
        pair_costs.sort(reverse=True)
        top_n = min(3, len(pair_costs))
        _, tq1, tq2 = pair_costs[random.randint(0, top_n - 1)]
        pq1, pq2 = m[tq1], m[tq2]
        adj_of_pq2 = list(hw_adj.get(pq2, set()))
        if adj_of_pq2:
            target = random.choice(adj_of_pq2)
            if target != pq1:
                do_swap(m, rm, pq1, target)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    def perturb_edge_targeted(m, rm, weights=None, alpha_exp=1.5, **kw):
        if weights is None:
            perturb_random(m, rm)
            return
        edge_costs = []
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                c = w * (dist[m[q1]][m[q2]] ** alpha_exp)
                edge_costs.append((c, q1, q2))
        if not edge_costs:
            return
        edge_costs.sort(reverse=True)
        top_n = min(5, len(edge_costs))
        _, eq1, eq2 = edge_costs[random.randint(0, top_n - 1)]
        pq1, pq2 = m[eq1], m[eq2]
        neighbors_of_pq2 = list(hw_adj.get(pq2, set()))
        if neighbors_of_pq2:
            target = random.choice(neighbors_of_pq2)
            if target != pq1:
                do_swap(m, rm, pq1, target)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    def perturb_lns(m, rm, nbrs=None, alpha_exp=1.5, **kw):
        if nbrs is None or len(interacting_logical) < 3:
            perturb_random(m, rm)
            return
        base_lo = 3 + rsdiwr_iter_ref[0]
        base_hi = 8 + rsdiwr_iter_ref[0] * 2
        k = min(random.randint(base_lo, base_hi), len(interacting_logical))

        acc_pressure = accumulated_routing_pressure_ref[0]
        qubit_acc_pressure = defaultdict(float)
        for (q1, q2), cnt in acc_pressure.items():
            qubit_acc_pressure[q1] += cnt
            qubit_acc_pressure[q2] += cnt
        max_acc = max(qubit_acc_pressure.values()) if qubit_acc_pressure else 1.0

        qcost = {}
        for lq in interacting_logical:
            c = 0.0
            for partner, w in nbrs.get(lq, {}).items():
                if m[partner] >= 0 and m[lq] >= 0:
                    c += w * (dist[m[lq]][m[partner]] ** alpha_exp)
            pressure_bonus = qubit_acc_pressure.get(lq, 0.0) / (max_acc + 1e-10)
            qcost[lq] = c * (1.0 + 0.5 * pressure_bonus)

        sorted_qs = sorted(qcost, key=lambda q: qcost[q], reverse=True)
        top_half = sorted_qs[:max(k, len(sorted_qs) // 2)]
        subset = random.sample(top_half, min(k, len(top_half)))

        freed_phys = []
        for lq in subset:
            freed_phys.append(m[lq])
            rm[m[lq]] = -1
            m[lq] = -1

        placed_set = set(lq for lq in interacting_logical if m[lq] >= 0)
        for lq in sorted(subset, key=lambda q: qcost[q], reverse=True):
            best_pq, best_sc = None, float('inf')
            for pq in freed_phys:
                if rm[pq] != -1:
                    continue
                sc = 0.0
                for partner, w in nbrs.get(lq, {}).items():
                    if partner in placed_set and m[partner] >= 0:
                        sc += w * (dist[pq][m[partner]] ** alpha_exp)
                if sc < best_sc:
                    best_sc = sc
                    best_pq = pq
            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                placed_set.add(lq)
            else:
                for pq in freed_phys:
                    if rm[pq] == -1:
                        m[lq] = pq
                        rm[pq] = lq
                        placed_set.add(lq)
                        break

    perturbation_modes = [perturb_random, perturb_segment_shuffle,
                          perturb_worst_pair, perturb_edge_targeted, perturb_lns]
    K = len(perturbation_modes)

    WINDOW_SIZE = 100
    EPSILON = 0.1
    window = []
    mode_successes = [0] * K
    mode_attempts = [0] * K

    def select_perturbation_mode():
        if random.random() < EPSILON or sum(mode_attempts) < K * 2:
            return random.randint(0, K - 1)
        rates = []
        for k in range(K):
            if mode_attempts[k] > 0:
                rates.append(mode_successes[k] / mode_attempts[k])
            else:
                rates.append(1.0)
        total = sum(rates)
        if total < 1e-12:
            return random.randint(0, K - 1)
        r = random.random() * total
        cumul = 0.0
        for k in range(K):
            cumul += rates[k]
            if r <= cumul:
                return k
        return K - 1

    def update_window(mode_idx, success):
        window.append((mode_idx, success))
        mode_attempts[mode_idx] += 1
        if success:
            mode_successes[mode_idx] += 1
        if len(window) > WINDOW_SIZE:
            old_mode, old_success = window.pop(0)
            mode_attempts[old_mode] -= 1
            if old_success:
                mode_successes[old_mode] -= 1

    # ---------------------------------------------------------------
    # Step 10: Build initial mapping candidates
    # ---------------------------------------------------------------
    candidates = []

    for s_lq in seed_lqs:
        for s_pq in seed_pqs:
            m, rm = run_greedy_placement(s_lq, s_pq, static_nbrs, static_deg,
                                         weights=static_weight)
            fill_unmapped(m, rm)
            cost = compute_cost(m, static_weight)
            candidates.append((cost, m, rm))

    for s_pq in seed_pqs:
        cg_m, cg_rm = conflict_graph_seed(s_pq, static_nbrs, static_deg, static_weight)
        if cg_m is not None:
            fill_unmapped(cg_m, cg_rm)
            cost = compute_cost(cg_m, static_weight)
            candidates.append((cost, cg_m, cg_rm))

    spec_m, spec_rm = spectral_seed()
    if spec_m is not None:
        fill_unmapped(spec_m, spec_rm)
        spec_cost = compute_cost(spec_m, static_weight)
        candidates.append((spec_cost, spec_m, spec_rm))

    m_rand = [-1] * num_q
    rm_rand = [-1] * num_q
    shuffled_phys = list(physical_qubits)
    random.shuffle(shuffled_phys)
    for i, lq in enumerate(logical_qubits):
        m_rand[lq] = shuffled_phys[i]
        rm_rand[shuffled_phys[i]] = lq
    fill_unmapped(m_rand, rm_rand)
    c = compute_cost(m_rand, static_weight)
    candidates.append((c, m_rand, rm_rand))

    if not candidates:
        self.mapping_dict = list(range(num_q))
        self.reverse_mapping_dict = list(range(num_q))
        if self.use_isl:
            self.isl_mapping = dict_to_isl_map(self.mapping_dict)
        return

    candidates.sort(key=lambda x: x[0])

    _, best_m, best_rm = candidates[0]
    best_m, best_rm = list(best_m), list(best_rm)
    local_search(best_m, best_rm, static_nbrs, static_weight, alpha_exp=2.0, max_rounds=6)
    best_cost = compute_cost(best_m, static_weight)

    for idx in range(1, min(5, len(candidates))):
        _, m_c, rm_c = candidates[idx]
        m_c, rm_c = list(m_c), list(rm_c)
        local_search(m_c, rm_c, static_nbrs, static_weight, alpha_exp=2.0, max_rounds=4)
        c = compute_cost(m_c, static_weight)
        if c < best_cost:
            best_cost = c
            best_m = list(m_c)
            best_rm = list(rm_c)

    # ---------------------------------------------------------------
    # Step 11: RSDIWR + ILS with Commutativity-Aware DAG Relinearization
    # ---------------------------------------------------------------
    time_budget = 25.0
    t_start = _time()
    n_rsdiwr = 4

    cur_m = list(best_m)
    cur_rm = list(best_rm)
    swap_counts = defaultdict(float)
    accumulated_routing_pressure = defaultdict(float)
    accumulated_routing_pressure_ref[0] = accumulated_routing_pressure

    for rsdiwr_iter in range(n_rsdiwr):
        rsdiwr_iter_ref[0] = rsdiwr_iter
        elapsed = _time() - t_start
        if elapsed > time_budget:
            break

        remaining_time = time_budget - elapsed
        remaining_iters = n_rsdiwr - rsdiwr_iter
        time_for_this_iter = remaining_time / max(remaining_iters, 1)
        n_ils = max(55, int(num_q * time_for_this_iter / 0.5)) if time_for_this_iter > 1.0 else max(30, num_q // 3)

        # Pressure-adaptive blending
        if rsdiwr_iter == 0 or not swap_counts:
            eff_weights = dict(static_weight)
        else:
            max_sw = max(swap_counts.values()) if swap_counts else 1.0
            scale = max(static_weight.values()) / max(max_sw, 1e-10)

            total_pressure = sum(accumulated_routing_pressure.values())
            n_pairs = len(accumulated_routing_pressure)
            avg_pressure = total_pressure / max(n_pairs, 1)
            pressure_adapt = min(0.15, 0.05 * avg_pressure / max(max_sw, 1e-10))
            alpha_blend = max(0.25, 1.0 - 0.3 * rsdiwr_iter - pressure_adapt)

            eff_weights = defaultdict(float)
            all_keys = set(static_weight.keys()) | set(swap_counts.keys())
            for key in all_keys:
                w_s = static_weight.get(key, 0.0)
                w_r = swap_counts.get(key, 0.0) * scale
                eff_weights[key] = alpha_blend * w_s + (1.0 - alpha_blend) * w_r

        eff_nbrs, eff_deg = build_neighbors(eff_weights)

        # Re-seed with routing-informed weights + routing-pressure MIS
        if rsdiwr_iter > 0 and swap_counts and (_time() - t_start) < time_budget * 0.7:
            eff_sorted = sorted(interacting_logical,
                                key=lambda q: eff_deg.get(q, 0), reverse=True)
            reseed_lqs = eff_sorted[:min(2, len(eff_sorted))]
            reseed_pqs = seed_pqs[:min(2, len(seed_pqs))]

            for s_lq in reseed_lqs:
                for s_pq in reseed_pqs:
                    rm_new, rmm_new = run_greedy_placement(
                        s_lq, s_pq, eff_nbrs, eff_deg, weights=eff_weights)
                    fill_unmapped(rm_new, rmm_new)
                    local_search(rm_new, rmm_new, eff_nbrs, eff_weights,
                                 alpha_exp=2.0, max_rounds=3)
                    sc = compute_cost(rm_new, static_weight)
                    if sc < best_cost:
                        best_cost = sc
                        best_m = list(rm_new)
                        best_rm = list(rmm_new)
                        cur_m = list(rm_new)
                        cur_rm = list(rmm_new)

            for s_pq in reseed_pqs:
                cg_m, cg_rm = conflict_graph_seed(
                    s_pq, eff_nbrs, eff_deg, eff_weights,
                    routing_pressure=accumulated_routing_pressure)
                if cg_m is not None:
                    fill_unmapped(cg_m, cg_rm)
                    local_search(cg_m, cg_rm, eff_nbrs, eff_weights,
                                 alpha_exp=2.0, max_rounds=3)
                    sc = compute_cost(cg_m, static_weight)
                    if sc < best_cost:
                        best_cost = sc
                        best_m = list(cg_m)
                        best_rm = list(cg_rm)
                        cur_m = list(cg_m)
                        cur_rm = list(cg_rm)

        alpha_start = 2.0
        alpha_end = 1.0

        ls_rounds = 6 if rsdiwr_iter == 0 else 4
        cur_cost_nl = local_search(cur_m, cur_rm, eff_nbrs, eff_weights,
                                   alpha_exp=alpha_start, max_rounds=ls_rounds)

        static_cost = compute_cost(cur_m, static_weight)
        if static_cost < best_cost:
            best_cost = static_cost
            best_m = list(cur_m)
            best_rm = list(cur_rm)

        # Reset bandit window
        window.clear()
        for k in range(K):
            mode_successes[k] = 0
            mode_attempts[k] = 0

        T = max(cur_cost_nl * 0.05, 1.0)
        T_init = T
        alpha_sa = 0.94
        reheat_interval = max(n_ils // 4, 8)

        for ils_iter in range(n_ils):
            if _time() - t_start > time_budget:
                break

            progress = ils_iter / max(n_ils - 1, 1)
            alpha_exp = alpha_start + (alpha_end - alpha_start) * progress

            saved_m = list(cur_m)
            saved_rm = list(cur_rm)
            saved_cost = cur_cost_nl

            mode = select_perturbation_mode()
            perturbation_modes[mode](cur_m, cur_rm,
                                    nbrs=eff_nbrs, weights=eff_weights,
                                    alpha_exp=alpha_exp)

            new_cost_nl = local_search(cur_m, cur_rm, eff_nbrs, eff_weights,
                                       alpha_exp=alpha_exp, max_rounds=3)

            success = new_cost_nl < saved_cost - 1e-12

            improvement = saved_cost - new_cost_nl
            if improvement > 0:
                cur_cost_nl = new_cost_nl
                sc = compute_cost(cur_m, static_weight)
                if sc < best_cost:
                    best_cost = sc
                    best_m = list(cur_m)
                    best_rm = list(cur_rm)
            elif random.random() < math.exp(min(0, improvement / max(T, 1e-10))):
                cur_cost_nl = new_cost_nl
            else:
                cur_m[:] = saved_m
                cur_rm[:] = saved_rm
                cur_cost_nl = saved_cost

            update_window(mode, success)

            T *= alpha_sa
            if (ils_iter + 1) % reheat_interval == 0:
                T = max(T, T_init * 0.35)

        # Routing simulation for RSDIWR feedback WITH bottleneck tracking
        if rsdiwr_iter < n_rsdiwr - 1:
            sim_depth = 14 + rsdiwr_iter * 7

            if rsdiwr_iter == 0 and early_layer_gates:
                swap_counts, _ = simulate_routing_hybrid(best_m, best_rm, max_layers=sim_depth)
                # Also run forward routing with bottleneck tracking for relinearization
                _, _, gate_bottlenecks = simulate_routing_greedy(best_m, best_rm, max_layers=sim_depth, track_bottlenecks=True)
            elif rsdiwr_iter == 1 and early_layer_gates:
                swap_counts, _ = simulate_routing_hybrid_bidir(best_m, best_rm, max_layers=sim_depth)
                _, _, gate_bottlenecks = simulate_routing_greedy(best_m, best_rm, max_layers=sim_depth, track_bottlenecks=True)
            else:
                swap_counts_bidir, _, gate_bottlenecks = simulate_routing_asymmetric_bidir(best_m, best_rm, max_layers=sim_depth, track_bottlenecks=True)
                swap_counts = swap_counts_bidir

            # Accumulate routing pressure
            for pair_key, cnt in swap_counts.items():
                accumulated_routing_pressure[pair_key] += cnt

            # === KEY NOVELTY: Commutativity-Aware DAG Relinearization ===
            # After routing simulation, reorder commuting adjacent gates
            # to reduce bottleneck SWAP counts
            if gate_bottlenecks and (_time() - t_start) < time_budget * 0.85:
                max_relinearize_swaps = min(20, max(5, len(gates_2q) // 10))
                dag_changed = relinearize_dag(gate_bottlenecks, best_m, best_rm,
                                              max_swaps=max_relinearize_swaps)

                if dag_changed:
                    # Recompute interaction weights with reordered DAG
                    # The gate_layer and critical_path are still valid since
                    # we only swapped commuting gates; but dep_count changed
                    # Update effective weights using new dep structure
                    pass  # dep_count already updated by recompute_topo_and_deps()

        cur_m = list(best_m)
        cur_rm = list(best_rm)
        cur_cost_nl = compute_cost_nonlinear(cur_m, eff_weights, alpha_end)

    # ---------------------------------------------------------------
    # Final: Set mapping
    # ---------------------------------------------------------------
    self.mapping_dict = best_m
    self.reverse_mapping_dict = best_rm

    if self.use_isl:
        self.isl_mapping = dict_to_isl_map(self.mapping_dict)

def init_mapping(self):
    import numpy as np
    from collections import defaultdict
    import random as rng

    N = self.num_qubits
    dist = self.distance_matrix
    backend = self.backend

    # ── Extract 2-qubit gates and logical qubits ──
    two_q_gates = []
    logical_qubits = set()
    for gid in sorted(self.access.keys()):
        qs = self.access[gid]
        for q in qs:
            logical_qubits.add(q)
        if len(qs) == 2:
            two_q_gates.append((gid, qs[0], qs[1]))

    # Trivial case: no 2-qubit gates
    if not two_q_gates:
        self.mapping_dict = {i: i for i in range(N)}
        self.reverse_mapping_dict = {i: i for i in range(N)}
        return

    logical_list = sorted(logical_qubits)
    n_log = len(logical_list)
    log2idx = {q: i for i, q in enumerate(logical_list)}

    # ── Build DAG layers for depth scheduling ──
    qubit_last_layer = {}
    gate_layer = []
    for gid, q1, q2 in two_q_gates:
        l = max(qubit_last_layer.get(q1, -1), qubit_last_layer.get(q2, -1)) + 1
        gate_layer.append(l)
        qubit_last_layer[q1] = l
        qubit_last_layer[q2] = l

    full_depth = max(gate_layer) + 1

    layer_gates = defaultdict(list)
    for idx, (gid, q1, q2) in enumerate(two_q_gates):
        layer_gates[gate_layer[idx]].append((q1, q2))

    # ── Static interaction weights (sparse) ──
    w_static = {}
    for gid, q1, q2 in two_q_gates:
        i, j = log2idx[q1], log2idx[q2]
        key = (min(i, j), max(i, j))
        w_static[key] = w_static.get(key, 0.0) + 1.0

    # Interaction adjacency for fast delta computation
    interact_adj = defaultdict(set)
    for (i, j) in w_static:
        interact_adj[i].add(j)
        interact_adj[j].add(i)

    interact_pairs = list(w_static.keys())

    # ── Helper: complete a partial mapping to full 1-to-1 ──
    def complete_mapping(partial):
        full = dict(partial)
        used = set(full.values())
        remaining_p = [p for p in range(N) if p not in used]
        remaining_l = [q for q in range(N) if q not in full]
        rng.shuffle(remaining_p)
        for lq, pq in zip(remaining_l, remaining_p):
            full[lq] = pq
        return full

    # ── Cost function ──
    def mapping_cost(m, weights):
        c = 0.0
        for (i, j), w in weights.items():
            c += w * dist[m[logical_list[i]]][m[logical_list[j]]]
        return c

    # ── Routing simulation (truncated to max_layers) ──
    def simulate_routing(mapping, max_layers):
        sim_m = dict(mapping)
        sim_r = {v: k for k, v in sim_m.items()}
        feedback = defaultdict(float)
        swaps = 0

        for layer_idx in range(min(max_layers, full_depth)):
            for q1, q2 in layer_gates.get(layer_idx, []):
                # Greedy routing: move q1 toward q2
                steps = 0
                max_steps = 2 * N  # safety bound
                while dist[sim_m[q1]][sim_m[q2]] > 1 and steps < max_steps:
                    p1 = sim_m[q1]
                    p2 = sim_m[q2]
                    # Also consider moving q2 toward q1 (bidirectional)
                    best_nb, best_d = None, dist[p1][p2]
                    for nb in backend.get(p1, []):
                        d = dist[nb][p2]
                        if d < best_d:
                            best_d = d
                            best_nb = nb
                    # Check reverse direction too
                    best_nb2, best_d2 = None, dist[p1][p2]
                    for nb in backend.get(p2, []):
                        d = dist[p1][nb]
                        if d < best_d2:
                            best_d2 = d
                            best_nb2 = nb

                    if best_nb is not None and (best_nb2 is None or best_d <= best_d2):
                        target_p, swap_p = p1, best_nb
                    elif best_nb2 is not None:
                        target_p, swap_p = p2, best_nb2
                    else:
                        break

                    lq1 = sim_r[target_p]
                    lq2 = sim_r[swap_p]
                    sim_m[lq1], sim_m[lq2] = swap_p, target_p
                    sim_r[target_p], sim_r[swap_p] = lq2, lq1
                    swaps += 1
                    steps += 1

                    if lq1 in log2idx and lq2 in log2idx:
                        i1, i2 = log2idx[lq1], log2idx[lq2]
                        key = (min(i1, i2), max(i1, i2))
                        feedback[key] += 1.0

        return feedback, swaps

    # ── Seed generators ──

    def greedy_seed():
        log_deg = [0.0] * n_log
        for (i, j), w in w_static.items():
            log_deg[i] += w
            log_deg[j] += w

        phys_deg = {p: len(backend.get(p, [])) for p in range(N)}
        sorted_log = sorted(range(n_log), key=lambda i: log_deg[i], reverse=True)
        sorted_phys = sorted(range(N), key=lambda p: phys_deg[p], reverse=True)

        partial = {}
        used = set()

        for li in sorted_log:
            lq = logical_list[li]
            candidates = [p for p in sorted_phys if p not in used][:max(20, n_log)]
            if not partial:
                best_p = candidates[0] if candidates else 0
            else:
                best_p, best_c = candidates[0], float('inf')
                for p in candidates:
                    c = 0.0
                    for i2 in range(n_log):
                        if logical_list[i2] in partial:
                            key = (min(li, i2), max(li, i2))
                            c += w_static.get(key, 0) * dist[p][partial[logical_list[i2]]]
                    if c < best_c:
                        best_c = c
                        best_p = p
            partial[lq] = best_p
            used.add(best_p)

        return complete_mapping(partial)

    def spectral_seed():
        try:
            L_log = np.zeros((n_log, n_log))
            for (i, j), w in w_static.items():
                L_log[i][j] -= w
                L_log[j][i] -= w
                L_log[i][i] += w
                L_log[j][j] += w

            L_hw = np.zeros((N, N))
            for p in range(N):
                nbs = backend.get(p, [])
                for nb in nbs:
                    L_hw[p][nb] = -1
                L_hw[p][p] = len(nbs)

            _, vecs_log = np.linalg.eigh(L_log)
            _, vecs_hw = np.linalg.eigh(L_hw)

            fiedler_log = vecs_log[:, min(1, n_log - 1)]
            fiedler_hw = vecs_hw[:, min(1, N - 1)]

            sorted_log = sorted(range(n_log), key=lambda i: fiedler_log[i])
            sorted_hw = sorted(range(N), key=lambda p: fiedler_hw[p])

            partial = {logical_list[sorted_log[r]]: sorted_hw[r] for r in range(n_log)}
            return complete_mapping(partial)
        except Exception:
            return random_seed()

    def mis_seed():
        adj = defaultdict(set)
        for (i, j) in w_static:
            adj[i].add(j)
            adj[j].add(i)

        sorted_verts = sorted(range(n_log), key=lambda i: len(adj[i]))
        independent = set()
        excluded = set()
        for v in sorted_verts:
            if v not in excluded:
                independent.add(v)
                excluded.update(adj[v])

        phys_deg = {p: len(backend.get(p, [])) for p in range(N)}
        sorted_phys = sorted(range(N), key=lambda p: phys_deg[p], reverse=True)

        # Place independent set on high-degree physical qubits spread apart
        partial = {}
        used = set()
        ind_sorted = sorted(independent, key=lambda i: sum(
            w_static.get((min(i, j), max(i, j)), 0) for j in interact_adj.get(i, set())
        ), reverse=True)

        for li in ind_sorted:
            lq = logical_list[li]
            best_p = None
            for p in sorted_phys:
                if p not in used:
                    best_p = p
                    break
            if best_p is not None:
                partial[lq] = best_p
                used.add(best_p)

        # Fill remaining by greedy interaction cost
        remaining = [i for i in range(n_log) if i not in independent]
        remaining.sort(key=lambda i: sum(
            w_static.get((min(i, j), max(i, j)), 0) for j in interact_adj.get(i, set())
        ), reverse=True)

        for li in remaining:
            lq = logical_list[li]
            best_p, best_c = None, float('inf')
            for p in range(N):
                if p in used:
                    continue
                c = 0.0
                for lq2, p2 in partial.items():
                    if lq2 in log2idx:
                        i2 = log2idx[lq2]
                        key = (min(li, i2), max(li, i2))
                        c += w_static.get(key, 0) * dist[p][p2]
                if c < best_c:
                    best_c = c
                    best_p = p
            if best_p is None:
                for p in range(N):
                    if p not in used:
                        best_p = p
                        break
            partial[lq] = best_p
            used.add(best_p)

        return complete_mapping(partial)

    def random_seed():
        phys = list(range(N))
        rng.shuffle(phys)
        return {i: phys[i] for i in range(N)}

    # ── Local search (first-improvement, delta-based) ──
    def local_search(mapping, weights, max_no_improve=None):
        if max_no_improve is None:
            max_no_improve = max(100, n_log * 3)
        reverse = {v: k for k, v in mapping.items()}
        best_cost = mapping_cost(mapping, weights)
        no_improve = 0

        if not interact_pairs:
            return mapping, best_cost

        all_keys = list(range(N))

        while no_improve < max_no_improve:
            # 80% interacting pair swap, 20% random swap
            if rng.random() < 0.8:
                i, j = rng.choice(interact_pairs)
                l1, l2 = logical_list[i], logical_list[j]
            else:
                l1, l2 = rng.sample(all_keys, 2)

            p1, p2 = mapping[l1], mapping[l2]
            l1_in = log2idx.get(l1)
            l2_in = log2idx.get(l2)

            delta = 0.0

            if l1_in is not None:
                for nb_idx in interact_adj.get(l1_in, set()):
                    lnb = logical_list[nb_idx]
                    if lnb == l2:
                        continue
                    key = (min(l1_in, nb_idx), max(l1_in, nb_idx))
                    w = weights.get(key, 0)
                    if w > 0:
                        pnb = mapping[lnb]
                        delta += w * (dist[p2][pnb] - dist[p1][pnb])

            if l2_in is not None:
                for nb_idx in interact_adj.get(l2_in, set()):
                    lnb = logical_list[nb_idx]
                    if lnb == l1:
                        continue
                    key = (min(l2_in, nb_idx), max(l2_in, nb_idx))
                    w = weights.get(key, 0)
                    if w > 0:
                        pnb = mapping[lnb]
                        delta += w * (dist[p1][pnb] - dist[p2][pnb])

            if delta < -1e-10:
                mapping[l1], mapping[l2] = p2, p1
                reverse[p1], reverse[p2] = l2, l1
                best_cost += delta
                no_improve = 0
            else:
                no_improve += 1

        return mapping, best_cost

    # ── Perturbation (bandit-adaptive strength) ──
    def perturb(mapping, strength):
        m = dict(mapping)
        keys = list(m.keys())
        for _ in range(strength):
            i, j = rng.sample(range(len(keys)), 2)
            m[keys[i]], m[keys[j]] = m[keys[j]], m[keys[i]]
        return m

    # ── ILS ──
    def ils(weights, seed, budget):
        m = dict(seed)
        m, cost = local_search(m, weights)
        best_m, best_cost = dict(m), cost

        # Adaptive perturbation strength
        base_strength = max(2, n_log // 8)

        for it in range(budget):
            # Bandit-adaptive: start with large perturbation, narrow down
            strength = max(2, base_strength - it * base_strength // max(budget, 1))
            pm = perturb(best_m, strength)
            pm, pc = local_search(pm, weights)
            if pc < best_cost:
                best_cost = pc
                best_m = dict(pm)

        return best_m, best_cost

    # ══════════════════════════════════════════════════════════
    # ══  RSDIWR with Iterative-Deepening Simulation Horizon ══
    # ══════════════════════════════════════════════════════════

    B_total = max(10, min(50, n_log))
    D_0 = 10

    # Depth schedule: D_k = min(full_depth, 10 * 2^k)
    depth_schedule = []
    k = 0
    while True:
        d_k = min(full_depth, D_0 * (2 ** k))
        depth_schedule.append(d_k)
        if d_k >= full_depth:
            break
        k += 1

    # Seeds: MIS + greedy + spectral + random
    seeds = [greedy_seed(), spectral_seed(), mis_seed()]
    seeds.extend([random_seed() for _ in range(2)])

    weights = dict(w_static)
    overall_best = None
    overall_best_swaps = float('inf')

    for k_idx, d_k in enumerate(depth_schedule):
        # Budget inversely proportional to depth
        b_k = max(2, int(B_total * D_0 / d_k))

        # β_k increases with depth (deeper = more trustworthy feedback)
        beta_k = min(0.9, 0.3 + 0.6 * (d_k / max(full_depth, 1)))

        # Nonlinear distance annealing: alpha decreases over iterations
        # (early iterations penalize large distances more strongly)
        alpha = max(1.0, 2.0 - k_idx * 0.3)
        annealed_weights = {}
        for key, w in weights.items():
            annealed_weights[key] = w ** alpha if alpha != 1.0 else w

        for seed in seeds:
            m, cost = ils(annealed_weights, seed, b_k)
            _, swaps = simulate_routing(m, d_k)
            if swaps < overall_best_swaps:
                overall_best_swaps = swaps
                overall_best = dict(m)

        # Update weights with routing feedback from best mapping
        if overall_best is not None:
            fb, _ = simulate_routing(overall_best, d_k)
            fb_max = max(fb.values()) if fb else 0
            w_s_max = max(w_static.values()) if w_static else 1.0

            new_weights = {}
            all_keys = set(list(w_static.keys()) + list(fb.keys()))
            for key in all_keys:
                ws = w_static.get(key, 0)
                wr = (fb.get(key, 0) / fb_max * w_s_max) if fb_max > 0 else 0
                new_weights[key] = (1 - beta_k) * ws + beta_k * wr
            weights = new_weights

            # Update interact structures for new weight keys
            for (i, j) in fb:
                if (i, j) not in interact_adj or j not in interact_adj[i]:
                    interact_adj[i].add(j)
                    interact_adj[j].add(i)

        # Seeds for next iteration: best + random diversity
        if overall_best is not None:
            seeds = [dict(overall_best)]
        seeds.extend([random_seed() for _ in range(2)])

    # ── Set final mapping ──
    if overall_best is None:
        overall_best = {i: i for i in range(N)}

    self.mapping_dict = overall_best
    self.reverse_mapping_dict = {v: k for k, v in self.mapping_dict.items()}

def init_mapping(self):
    import math
    import random
    from collections import defaultdict, deque
    from time import time as _time

    num_q = self.num_qubits
    physical_qubits = sorted(self.backend.keys())
    dist = self.distance_matrix

    # ---------------------------------------------------------------
    # Step 1: Build DAG and topological layers
    # ---------------------------------------------------------------
    all_gates = sorted(self.access.keys())
    two_qubit_gates = [g for g in all_gates if len(self.access[g]) == 2]

    last_gate_on_qubit = {}
    successors_dag = defaultdict(set)
    predecessors_dag = defaultdict(set)
    for g in all_gates:
        for q in self.access[g]:
            if q in last_gate_on_qubit:
                pred = last_gate_on_qubit[q]
                successors_dag[pred].add(g)
                predecessors_dag[g].add(pred)
            last_gate_on_qubit[q] = g

    in_degree = {g: len(predecessors_dag[g]) for g in all_gates}
    gate_layer = {g: 0 for g in all_gates}
    queue = deque(g for g in all_gates if in_degree[g] == 0)
    temp_in = dict(in_degree)
    topo_order = []
    while queue:
        g = queue.popleft()
        topo_order.append(g)
        for s in successors_dag[g]:
            gate_layer[s] = max(gate_layer[s], gate_layer[g] + 1)
            temp_in[s] -= 1
            if temp_in[s] == 0:
                queue.append(s)

    critical_path = {g: 0 for g in all_gates}
    for g in reversed(topo_order):
        for s in successors_dag[g]:
            if critical_path[s] + 1 > critical_path[g]:
                critical_path[g] = critical_path[s] + 1

    # 2q DAG for routing simulation
    gates_2q = {}
    dag2q_succ = defaultdict(set)
    dag2q_pred = defaultdict(set)
    last_2q_on_qubit = {}
    logical_qubits_set = set()

    for gate in all_gates:
        qubits = self.access[gate]
        if len(qubits) == 2:
            q1, q2 = qubits
            gates_2q[gate] = (q1, q2)
            logical_qubits_set.add(q1)
            logical_qubits_set.add(q2)
            for q in [q1, q2]:
                if q in last_2q_on_qubit:
                    prev = last_2q_on_qubit[q]
                    if prev != gate:
                        dag2q_succ[prev].add(gate)
                        dag2q_pred[gate].add(prev)
                last_2q_on_qubit[q] = gate
        elif len(qubits) == 1:
            logical_qubits_set.add(qubits[0])

    logical_qubits = sorted(logical_qubits_set)

    if not gates_2q:
        self.mapping_dict = list(range(num_q))
        self.reverse_mapping_dict = list(range(num_q))
        if self.use_isl:
            self.isl_mapping = dict_to_isl_map(self.mapping_dict)
        return

    # Topological order for 2q DAG
    topo_2q = []
    in_deg_2q = {g: len(dag2q_pred[g]) for g in gates_2q}
    q2 = deque(sorted(g for g in gates_2q if in_deg_2q[g] == 0))
    while q2:
        g = q2.popleft()
        topo_2q.append(g)
        for s in dag2q_succ[g]:
            in_deg_2q[s] -= 1
            if in_deg_2q[s] == 0:
                q2.append(s)

    dep_count = defaultdict(int)
    for g in reversed(topo_2q):
        for s in dag2q_succ[g]:
            dep_count[g] = max(dep_count[g], dep_count[s] + 1)

    # Reversed 2q DAG for backward routing
    dag2q_succ_rev = defaultdict(set)
    dag2q_pred_rev = defaultdict(set)
    for g in gates_2q:
        for s in dag2q_succ[g]:
            dag2q_succ_rev[s].add(g)
            dag2q_pred_rev[g].add(s)

    dep_count_rev = defaultdict(int)
    topo_2q_rev = list(reversed(topo_2q))
    for g in reversed(topo_2q_rev):
        for s in dag2q_succ_rev[g]:
            dep_count_rev[g] = max(dep_count_rev[g], dep_count_rev[s] + 1)

    # ---------------------------------------------------------------
    # Step 2: Interaction weights
    # ---------------------------------------------------------------
    max_layer = max((gate_layer[g] for g in two_qubit_gates), default=1)

    static_weight = defaultdict(float)
    logical_degree = defaultdict(float)

    for g in two_qubit_gates:
        q1, q2 = self.access[g]
        cp = critical_path[g] + 1
        layer = gate_layer[g]
        w = cp * (max_layer - layer + 1)
        key = (min(q1, q2), max(q1, q2))
        static_weight[key] += w
        logical_degree[q1] += w
        logical_degree[q2] += w

    interacting_logical = [q for q in logical_qubits if logical_degree.get(q, 0) > 0]

    # ---------------------------------------------------------------
    # Step 3: Physical graph properties
    # ---------------------------------------------------------------
    hw_adj = defaultdict(set)
    for pq in physical_qubits:
        for pq2 in self.backend.get(pq, []):
            hw_adj[pq].add(pq2)

    phys_degree = {pq: len(hw_adj[pq]) for pq in physical_qubits}
    phys_centrality = {}
    for pq in physical_qubits:
        phys_centrality[pq] = sum(dist[pq][pq2] for pq2 in physical_qubits)

    # ---------------------------------------------------------------
    # Step 4: Helper functions
    # ---------------------------------------------------------------
    def build_neighbors(weights):
        nbrs = defaultdict(dict)
        deg = defaultdict(float)
        for (q1, q2), w in weights.items():
            nbrs[q1][q2] = w
            nbrs[q2][q1] = w
            deg[q1] += w
            deg[q2] += w
        return nbrs, deg

    def compute_cost_nonlinear(m, weights, alpha_exp):
        cost = 0.0
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                d = dist[m[q1]][m[q2]]
                cost += w * (d ** alpha_exp)
        return cost

    def compute_cost(m, weights):
        cost = 0.0
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                cost += w * dist[m[q1]][m[q2]]
        return cost

    def delta_swap_cost_nonlinear(m, rm, pq_a, pq_b, nbrs, alpha_exp):
        lq_a, lq_b = rm[pq_a], rm[pq_b]
        delta = 0.0
        affected = set()
        if lq_a in nbrs:
            affected.update(nbrs[lq_a].keys())
        if lq_b in nbrs:
            affected.update(nbrs[lq_b].keys())
        for q in affected:
            if q == lq_a or q == lq_b:
                continue
            pq_q = m[q]
            w_a = nbrs.get(lq_a, {}).get(q, 0.0)
            if w_a > 0:
                old_d = dist[pq_a][pq_q] ** alpha_exp
                new_d = dist[pq_b][pq_q] ** alpha_exp
                delta += w_a * (new_d - old_d)
            w_b = nbrs.get(lq_b, {}).get(q, 0.0)
            if w_b > 0:
                old_d = dist[pq_b][pq_q] ** alpha_exp
                new_d = dist[pq_a][pq_q] ** alpha_exp
                delta += w_b * (new_d - old_d)
        return delta

    def do_swap(m, rm, pq_a, pq_b):
        lq_a, lq_b = rm[pq_a], rm[pq_b]
        m[lq_a], m[lq_b] = pq_b, pq_a
        rm[pq_a], rm[pq_b] = lq_b, lq_a

    # ---------------------------------------------------------------
    # Step 5: Seed generation — MIS + Greedy + Spectral
    # ---------------------------------------------------------------
    # MIS (Maximum Independent Set) seed on interaction graph
    def mis_seed():
        if len(interacting_logical) < 2:
            return None, None
        # Build conflict graph: two logical qubits conflict if they interact
        conflict_nbrs = defaultdict(set)
        for (q1, q2) in static_weight:
            conflict_nbrs[q1].add(q2)
            conflict_nbrs[q2].add(q1)

        # Greedy MIS: pick highest-degree-first exclusion
        remaining = set(interacting_logical)
        mis_set = []
        while remaining:
            # Pick qubit with fewest conflicts among remaining (easiest to place independently)
            best_q = min(remaining, key=lambda q: len(conflict_nbrs[q] & remaining))
            mis_set.append(best_q)
            # Remove best_q and its neighbors
            to_remove = {best_q} | (conflict_nbrs[best_q] & remaining)
            remaining -= to_remove

        if len(mis_set) < 1:
            return None, None

        # Place MIS qubits first at most central physical qubits spread apart
        phys_sorted = sorted(physical_qubits, key=lambda pq: phys_centrality[pq])
        m = [-1] * num_q
        rm = [-1] * num_q

        # For MIS qubits, place them spread out on hardware
        used_phys = set()
        for i, lq in enumerate(mis_set):
            best_pq = None
            best_score = float('inf')
            for pq in phys_sorted:
                if pq in used_phys:
                    continue
                # Maximize minimum distance to already placed MIS qubits
                if used_phys:
                    min_dist_to_placed = min(dist[pq][pp] for pp in used_phys)
                    # We want spread: use negative min_dist + centrality tiebreak
                    score = -min_dist_to_placed + 0.01 * phys_centrality[pq]
                else:
                    score = phys_centrality[pq]
                if score < best_score:
                    best_score = score
                    best_pq = pq
            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                used_phys.add(best_pq)

        # Now greedily place remaining interacting qubits near their partners
        placed = set(mis_set)
        remaining_lq = [q for q in interacting_logical if q not in placed]
        remaining_lq.sort(key=lambda q: logical_degree[q], reverse=True)

        for lq in remaining_lq:
            best_pq = None
            best_score = float('inf')
            partners_placed = {p: static_weight.get((min(lq, p), max(lq, p)), 0.0)
                              for p in conflict_nbrs.get(lq, set()) if p in placed}
            for pq in physical_qubits:
                if rm[pq] != -1:
                    continue
                if partners_placed:
                    score = sum(w * dist[pq][m[p]] for p, w in partners_placed.items())
                    if pq in hw_adj.get(m[next(iter(partners_placed))], set()):
                        score *= 0.9
                else:
                    score = phys_centrality[pq]
                if score < best_score:
                    best_score = score
                    best_pq = pq
            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                placed.add(lq)

        return m, rm

    def spectral_seed():
        if len(interacting_logical) < 3:
            return None, None

        idx_map = {q: i for i, q in enumerate(interacting_logical)}
        n = len(interacting_logical)

        L = [[0.0] * n for _ in range(n)]
        for (q1, q2), w in static_weight.items():
            if q1 in idx_map and q2 in idx_map:
                i, j = idx_map[q1], idx_map[q2]
                L[i][j] -= w
                L[j][i] -= w
                L[i][i] += w
                L[j][j] += w

        def power_iter(mat, n_iter=200):
            v = [random.gauss(0, 1) for _ in range(n)]
            for _ in range(n_iter):
                new_v = [0.0] * n
                for i in range(n):
                    for j in range(n):
                        new_v[i] += mat[i][j] * v[j]
                norm = math.sqrt(sum(x * x for x in new_v)) or 1e-12
                v = [x / norm for x in new_v]
            return v

        max_diag = max(L[i][i] for i in range(n)) + 1.0
        shifted = [[0.0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                shifted[i][j] = -L[i][j]
            shifted[i][i] += max_diag

        v1 = power_iter(shifted, 150)

        dot_v1 = sum(x * x for x in v1) or 1e-12
        lam1_shifted = sum(v1[i] * sum(shifted[i][j] * v1[j] for j in range(n)) for i in range(n)) / dot_v1
        shifted2 = [row[:] for row in shifted]
        for i in range(n):
            for j in range(n):
                shifted2[i][j] -= lam1_shifted * v1[i] * v1[j] / dot_v1

        fiedler = power_iter(shifted2, 200)

        fiedler_order = sorted(range(n), key=lambda i: fiedler[i])
        sorted_logical = [interacting_logical[i] for i in fiedler_order]

        phys_sorted = sorted(physical_qubits, key=lambda pq: phys_centrality[pq])
        start_pq = phys_sorted[0]
        visited = set()
        bfs_order = []
        bfs_q = deque([start_pq])
        visited.add(start_pq)
        while bfs_q:
            pq = bfs_q.popleft()
            bfs_order.append(pq)
            for nb in sorted(hw_adj[pq]):
                if nb not in visited:
                    visited.add(nb)
                    bfs_q.append(nb)
        for pq in physical_qubits:
            if pq not in visited:
                bfs_order.append(pq)
                visited.add(pq)

        m = [-1] * num_q
        rm = [-1] * num_q
        n_interact = len(sorted_logical)
        n_phys_bfs = len(bfs_order)
        offset = max(0, (n_phys_bfs - n_interact) // 2)
        for i, lq in enumerate(sorted_logical):
            pq = bfs_order[min(offset + i, n_phys_bfs - 1)]
            if rm[pq] != -1:
                best_pq = None
                best_d = float('inf')
                for cpq in physical_qubits:
                    if rm[cpq] == -1:
                        d = dist[pq][cpq]
                        if d < best_d:
                            best_d = d
                            best_pq = cpq
                pq = best_pq
            m[lq] = pq
            rm[pq] = lq

        return m, rm

    # ---------------------------------------------------------------
    # Step 6: Greedy placement
    # ---------------------------------------------------------------
    sorted_by_degree = sorted(interacting_logical, key=lambda q: logical_degree[q], reverse=True)
    seed_lqs = sorted_by_degree[:min(3, len(sorted_by_degree))]
    phys_by_centrality = sorted(physical_qubits, key=lambda pq: phys_centrality[pq])
    seed_pqs = phys_by_centrality[:min(3, len(phys_by_centrality))]

    logical_degree_ranked = sorted(interacting_logical, key=lambda q: logical_degree[q], reverse=True)
    logical_degree_rank = {q: i for i, q in enumerate(logical_degree_ranked)}
    max_logical_rank = max(len(logical_degree_ranked) - 1, 1)
    phys_degree_ranked = sorted(physical_qubits, key=lambda pq: phys_degree[pq], reverse=True)
    phys_degree_rank = {pq: i for i, pq in enumerate(phys_degree_ranked)}
    max_phys_rank = max(len(phys_degree_ranked) - 1, 1)

    max_iw = max(static_weight.values()) if static_weight else 1.0

    def run_greedy_placement(start_lq, start_pq, nbrs, deg):
        used_phys = {start_pq}
        m = [-1] * num_q
        rm = [-1] * num_q
        m[start_lq] = start_pq
        rm[start_pq] = start_lq
        placed = {start_lq}
        remaining = set(logical_qubits) - placed

        while remaining:
            best_lq, best_w = None, -1.0
            for lq in remaining:
                w = sum(nbrs.get(lq, {}).get(plq, 0.0) for plq in placed)
                if w > best_w:
                    best_w = w
                    best_lq = lq

            nbrs_placed = {plq: nbrs.get(best_lq, {}).get(plq, 0.0)
                          for plq in placed if plq in nbrs.get(best_lq, {})}

            if nbrs_placed:
                near_ties = []
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq in used_phys:
                        continue
                    score = 0.0
                    for plq, iw in nbrs_placed.items():
                        d = dist[pq][m[plq]]
                        cost = iw * d
                        if m[plq] in hw_adj[pq]:
                            cost *= 0.90 - 0.10 * (iw / max_iw)
                        score += cost
                    near_ties.append((score, pq))
                    if score < best_score:
                        best_score = score

                if near_ties and best_score > 0:
                    threshold = best_score * 1.05
                    candidates_list = [(s, pq) for s, pq in near_ties if s <= threshold]
                    if len(candidates_list) > 1 and best_lq in logical_degree_rank:
                        lq_rn = logical_degree_rank[best_lq] / max_logical_rank
                        best_pq = min(candidates_list, key=lambda x: (
                            abs(phys_degree_rank[x[1]] / max_phys_rank - lq_rn), x[0]))[1]
                    else:
                        best_pq = min(candidates_list, key=lambda x: x[0])[1]
                elif near_ties:
                    best_pq = min(near_ties, key=lambda x: x[0])[1]
                else:
                    best_pq = None
            else:
                best_pq = None
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq not in used_phys:
                        score = phys_centrality[pq]
                        if score < best_score:
                            best_score = score
                            best_pq = pq

            m[best_lq] = best_pq
            rm[best_pq] = best_lq
            used_phys.add(best_pq)
            placed.add(best_lq)
            remaining.discard(best_lq)
        return m, rm

    def fill_unmapped(m, rm):
        unmapped = [q for q in range(num_q) if m[q] == -1]
        free = [pq for pq in range(num_q) if rm[pq] == -1]
        for lq, pq in zip(unmapped, free):
            m[lq] = pq
            rm[pq] = lq

    # ---------------------------------------------------------------
    # Step 7: Local search with nonlinear distance penalty
    # ---------------------------------------------------------------
    def local_search(m, rm, nbrs, weights, alpha_exp, max_rounds=5):
        if len(interacting_logical) <= 1:
            return compute_cost_nonlinear(m, weights, alpha_exp)
        for _ in range(max_rounds):
            improved = False
            best_d, best_pair = 0.0, None
            active_phys = [m[q] for q in interacting_logical]
            for pq1 in active_phys:
                for pq2 in hw_adj.get(pq1, set()):
                    d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                    if d < best_d:
                        best_d = d
                        best_pair = (pq1, pq2)
            n_random = min(150, len(interacting_logical) * 3)
            for _ in range(n_random):
                i, j = random.sample(range(len(interacting_logical)), 2)
                pq1, pq2 = m[interacting_logical[i]], m[interacting_logical[j]]
                d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                if d < best_d:
                    best_d = d
                    best_pair = (pq1, pq2)
            if best_pair and best_d < -1e-12:
                do_swap(m, rm, *best_pair)
                improved = True
            if not improved:
                for i in range(len(interacting_logical)):
                    for j in range(i + 1, len(interacting_logical)):
                        pq1, pq2 = m[interacting_logical[i]], m[interacting_logical[j]]
                        d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                        if d < best_d:
                            best_d = d
                            best_pair = (pq1, pq2)
                if best_pair and best_d < -1e-12:
                    do_swap(m, rm, *best_pair)
                else:
                    break
        return compute_cost_nonlinear(m, weights, alpha_exp)

    # ---------------------------------------------------------------
    # Step 8: Asymmetric bidirectional routing with A*-guided early layers
    # and congestion-cascading
    # ---------------------------------------------------------------
    def simulate_routing_directed(m, rm, dag_succ, dag_pred, g2q, dc, max_layers=20, use_astar_early=False, congestion_map=None):
        """Routing simulation with optional A*-guided early layers and congestion."""
        sim_m = list(m)
        sim_rm = list(rm)
        swap_counts = defaultdict(float)
        total_swaps = 0

        if not g2q:
            return swap_counts, total_swaps

        pred_remaining = {g: len(dag_pred[g]) for g in g2q}
        front = set(g for g in g2q if pred_remaining[g] == 0)
        layers_done = 0
        astar_layers = 3 if use_astar_early else 0

        while front and layers_done < max_layers:
            executable = []
            for g in front:
                gq1, gq2 = g2q[g]
                p1, p2 = sim_m[gq1], sim_m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    executable.append(g)

            if executable:
                for g in executable:
                    front.discard(g)
                    for s in dag_succ[g]:
                        pred_remaining[s] -= 1
                        if pred_remaining[s] == 0:
                            front.add(s)
                layers_done += 1
                continue

            active_phys = set()
            for g in front:
                gq1, gq2 = g2q[g]
                active_phys.add(sim_m[gq1])
                active_phys.add(sim_m[gq2])

            candidates_sw = set()
            for pq in active_phys:
                for nb in self.backend.get(pq, []):
                    candidates_sw.add((min(pq, nb), max(pq, nb)))

            best_swap, best_score = None, float('inf')
            for (s1, s2) in candidates_sw:
                l1, l2 = sim_rm[s1], sim_rm[s2]
                score = 0.0
                for g in front:
                    gq1, gq2 = g2q[g]
                    p1, p2 = sim_m[gq1], sim_m[gq2]
                    if gq1 == l1: p1 = s2
                    elif gq1 == l2: p1 = s1
                    if gq2 == l1: p2 = s2
                    elif gq2 == l2: p2 = s1
                    deps = dc.get(g, 0) + 1
                    d = dist[p1][p2]
                    # A*-guided: for early layers, add lookahead penalty
                    if layers_done < astar_layers and d <= 1:
                        # Check if this swap enables execution of next-layer gates
                        lookahead_bonus = 0
                        for ns in dag_succ.get(g, set()):
                            if ns in g2q:
                                nq1, nq2 = g2q[ns]
                                np1 = sim_m[nq1] if nq1 != l1 and nq1 != l2 else (s2 if nq1 == l1 else s1)
                                np2 = sim_m[nq2] if nq2 != l1 and nq2 != l2 else (s2 if nq2 == l1 else s1)
                                lookahead_bonus += dist[np1][np2] * 0.5
                        score += deps * d + lookahead_bonus
                    else:
                        score += deps * d
                    # Congestion penalty
                    if congestion_map:
                        cong_penalty = congestion_map.get(s1, 0) + congestion_map.get(s2, 0)
                        score += 0.1 * cong_penalty

                if score < best_score:
                    best_score = score
                    best_swap = (s1, s2)

            if best_swap is None:
                break

            s1, s2 = best_swap
            l1, l2 = sim_rm[s1], sim_rm[s2]
            sim_m[l1], sim_m[l2] = s2, s1
            sim_rm[s1], sim_rm[s2] = l2, l1
            total_swaps += 1

            # Update congestion map
            if congestion_map is not None:
                congestion_map[s1] = congestion_map.get(s1, 0) + 1
                congestion_map[s2] = congestion_map.get(s2, 0) + 1

            for g in front:
                gq1, gq2 = g2q[g]
                pair_key = (min(gq1, gq2), max(gq1, gq2))
                swap_counts[pair_key] += 1.0

        return swap_counts, total_swaps

    def simulate_routing_bidirectional(m, rm, max_layers=20, use_astar=True, congestion_map=None):
        """Asymmetric bidirectional routing: forward-heavy with backward correction."""
        fwd_counts, fwd_swaps = simulate_routing_directed(
            m, rm, dag2q_succ, dag2q_pred, gates_2q, dep_count,
            max_layers=max_layers, use_astar_early=use_astar, congestion_map=congestion_map)

        bwd_counts, bwd_swaps = simulate_routing_directed(
            m, rm, dag2q_succ_rev, dag2q_pred_rev, gates_2q, dep_count_rev,
            max_layers=max(max_layers // 2, 8), use_astar_early=False, congestion_map=None)

        # Asymmetric fusion: forward-biased (0.7 forward, 0.3 backward)
        fused = defaultdict(float)
        all_keys = set(fwd_counts.keys()) | set(bwd_counts.keys())
        for k in all_keys:
            fused[k] = 0.7 * fwd_counts.get(k, 0.0) + 0.3 * bwd_counts.get(k, 0.0)

        total = 0.7 * fwd_swaps + 0.3 * bwd_swaps
        return fused, total

    # ---------------------------------------------------------------
    # Step 9: Online Ridge Regression Surrogate with cross-term features
    # ---------------------------------------------------------------
    pair_keys = sorted(static_weight.keys())
    n_pairs = len(pair_keys)
    pair_to_idx = {pk: i for i, pk in enumerate(pair_keys)}
    SURROGATE_ALPHA = 1.5

    # Cap base features to avoid huge feature vectors
    MAX_BASE_FEATURES = min(n_pairs, 60)
    if n_pairs > MAX_BASE_FEATURES:
        top_pair_indices = sorted(range(n_pairs), key=lambda i: static_weight[pair_keys[i]], reverse=True)[:MAX_BASE_FEATURES]
        base_pair_keys = [pair_keys[i] for i in top_pair_indices]
    else:
        top_pair_indices = list(range(n_pairs))
        base_pair_keys = list(pair_keys)

    n_base = len(base_pair_keys)
    MAX_CROSS_TERMS = min(20, n_base * (n_base - 1) // 2)

    def extract_features(m):
        """Feature vector: per-pair w*dist^α + top cross-terms."""
        base_feats = []
        for (q1, q2) in base_pair_keys:
            w = static_weight[(q1, q2)]
            d = dist[m[q1]][m[q2]]
            base_feats.append(w * (d ** SURROGATE_ALPHA))
        return base_feats

    # Cross-term indices will be identified after first batch of training data
    cross_term_indices = []  # list of (i, j) pairs into base_feats

    def extract_features_with_cross(m):
        """Features + cross-term interactions."""
        base = extract_features(m)
        if not base:
            return base
        feats = list(base)
        for (i, j) in cross_term_indices:
            feats.append(base[i] * base[j])
        # Aggregate features
        mean_c = sum(base) / len(base) if base else 0
        max_c = max(base) if base else 0
        feats.extend([mean_c, max_c])
        return feats

    def identify_cross_terms(training_data):
        """Identify top-20 most correlated feature pairs from training data."""
        if len(training_data) < 10 or n_base < 2:
            return []
        n_samp = len(training_data)
        # Compute correlation between feature pairs and target
        # Use covariance of feature products with target as proxy
        targets = [td[1] for td in training_data]
        t_mean = sum(targets) / n_samp

        # Compute mean of each base feature
        f_means = [0.0] * n_base
        for feat, _ in training_data:
            for i in range(min(n_base, len(feat))):
                f_means[i] += feat[i]
        for i in range(n_base):
            f_means[i] /= n_samp

        # Score each pair by |cov(f_i * f_j, target)|
        pair_scores = []
        # Only check a subset for efficiency
        check_pairs = min(n_base * (n_base - 1) // 2, 200)
        candidate_pairs = []
        for i in range(n_base):
            for j in range(i + 1, n_base):
                candidate_pairs.append((i, j))
                if len(candidate_pairs) >= check_pairs:
                    break
            if len(candidate_pairs) >= check_pairs:
                break

        for (i, j) in candidate_pairs:
            cov = 0.0
            for feat, t in training_data:
                if i < len(feat) and j < len(feat):
                    cov += (feat[i] * feat[j]) * (t - t_mean)
            pair_scores.append((abs(cov / n_samp), i, j))

        pair_scores.sort(reverse=True)
        return [(i, j) for _, i, j in pair_scores[:MAX_CROSS_TERMS]]

    class OnlineRidgeSurrogate:
        """Online ridge regression with incremental updates."""
        def __init__(self, n_features, ridge_lambda=1.0):
            self.n = n_features
            self.lam = ridge_lambda
            # XtX + lambda*I
            self.XtX = [[ridge_lambda if i == j else 0.0 for j in range(n_features + 1)]
                        for i in range(n_features + 1)]
            self.XtX[n_features][n_features] = ridge_lambda
            self.Xty = [0.0] * (n_features + 1)
            self.theta = None
            self.n_samples = 0
            self.ss_tot = 0.0
            self.ss_res = 0.0
            self.y_sum = 0.0
            self.y_sq_sum = 0.0

        def add_sample(self, features, target):
            """Add a single training sample incrementally."""
            x = list(features) + [1.0]  # bias
            n_col = len(x)
            if n_col != self.n + 1:
                return  # dimension mismatch, skip
            for i in range(n_col):
                self.Xty[i] += x[i] * target
                for j in range(i, n_col):
                    self.XtX[i][j] += x[i] * x[j]
                    if i != j:
                        self.XtX[j][i] = self.XtX[i][j]
            self.n_samples += 1
            self.y_sum += target
            self.y_sq_sum += target * target
            self.theta = None  # invalidate cached solution

        def solve(self):
            """Solve for theta via Gaussian elimination."""
            if self.n_samples < 3:
                self.theta = None
                return False
            n_col = self.n + 1
            aug = [self.XtX[i][:] + [self.Xty[i]] for i in range(n_col)]

            for col in range(n_col):
                max_row = col
                max_val = abs(aug[col][col])
                for row in range(col + 1, n_col):
                    if abs(aug[row][col]) > max_val:
                        max_val = abs(aug[row][col])
                        max_row = row
                if max_val < 1e-15:
                    self.theta = None
                    return False
                aug[col], aug[max_row] = aug[max_row], aug[col]
                pivot = aug[col][col]
                for row in range(col + 1, n_col):
                    factor = aug[row][col] / pivot
                    for k in range(col, n_col + 1):
                        aug[row][k] -= factor * aug[col][k]

            w = [0.0] * n_col
            for i in range(n_col - 1, -1, -1):
                s = aug[i][n_col]
                for j in range(i + 1, n_col):
                    s -= aug[i][j] * w[j]
                w[i] = s / aug[i][i]

            self.theta = w
            return True

        def predict(self, features):
            """Predict cost from features."""
            if self.theta is None:
                return None
            x = list(features) + [1.0]
            return sum(self.theta[i] * x[i] for i in range(len(x)))

        def r_squared(self):
            """Approximate R² from accumulated statistics."""
            if self.n_samples < 3 or self.theta is None:
                return 0.0
            y_mean = self.y_sum / self.n_samples
            ss_tot = self.y_sq_sum - self.n_samples * y_mean * y_mean
            if ss_tot < 1e-12:
                return 0.0
            # Compute ss_res from theta and XtX, Xty
            # ss_res = y^Ty - 2*theta^T*Xty + theta^T*XtX*theta
            # But we only need approximate, so we just track it isn't great
            # Use the simpler: recompute from recent predictions if needed
            return 0.5  # placeholder; we use fit quality heuristically

    # ---------------------------------------------------------------
    # Step 10: Perturbation modes with bandit selection
    # ---------------------------------------------------------------
    def perturb_random(m, rm, **kw):
        if len(interacting_logical) >= 2:
            lqs = random.sample(interacting_logical, 2)
            do_swap(m, rm, m[lqs[0]], m[lqs[1]])

    def perturb_segment_shuffle(m, rm, **kw):
        k = min(random.randint(3, 5), len(interacting_logical))
        if k < 2:
            perturb_random(m, rm)
            return
        lqs = random.sample(interacting_logical, k)
        phys_positions = [m[lq] for lq in lqs]
        random.shuffle(phys_positions)
        for lq in lqs:
            rm[m[lq]] = -1
        for lq, pq in zip(lqs, phys_positions):
            m[lq] = pq
            rm[pq] = lq

    def perturb_worst_pair(m, rm, weights=None, alpha_exp=1.5, **kw):
        if weights is None:
            perturb_random(m, rm)
            return
        pair_costs = []
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                d = dist[m[q1]][m[q2]]
                c = w * (d ** alpha_exp)
                pair_costs.append((c, q1, q2))
        if not pair_costs:
            return
        pair_costs.sort(reverse=True)
        top_n = min(3, len(pair_costs))
        _, tq1, tq2 = pair_costs[random.randint(0, top_n - 1)]
        pq1, pq2 = m[tq1], m[tq2]
        adj_of_pq2 = list(hw_adj.get(pq2, set()))
        if adj_of_pq2:
            target = random.choice(adj_of_pq2)
            if target != pq1:
                do_swap(m, rm, pq1, target)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    def perturb_edge_targeted(m, rm, weights=None, alpha_exp=1.5, **kw):
        if weights is None:
            perturb_random(m, rm)
            return
        edge_costs = []
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                c = w * (dist[m[q1]][m[q2]] ** alpha_exp)
                edge_costs.append((c, q1, q2))
        if not edge_costs:
            return
        edge_costs.sort(reverse=True)
        top_n = min(5, len(edge_costs))
        _, eq1, eq2 = edge_costs[random.randint(0, top_n - 1)]
        pq1, pq2 = m[eq1], m[eq2]
        neighbors_of_pq2 = list(hw_adj.get(pq2, set()))
        if neighbors_of_pq2:
            target = random.choice(neighbors_of_pq2)
            if target != pq1:
                do_swap(m, rm, pq1, target)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    def perturb_lns(m, rm, nbrs=None, alpha_exp=1.5, **kw):
        if nbrs is None or len(interacting_logical) < 3:
            perturb_random(m, rm)
            return
        k = min(random.randint(3, 8), len(interacting_logical))
        qcost = {}
        for lq in interacting_logical:
            c = 0.0
            for partner, w in nbrs.get(lq, {}).items():
                if m[partner] >= 0 and m[lq] >= 0:
                    c += w * (dist[m[lq]][m[partner]] ** alpha_exp)
            qcost[lq] = c
        sorted_qs = sorted(qcost, key=lambda q: qcost[q], reverse=True)
        top_half = sorted_qs[:max(k, len(sorted_qs) // 2)]
        subset = random.sample(top_half, min(k, len(top_half)))

        freed_phys = []
        for lq in subset:
            freed_phys.append(m[lq])
            rm[m[lq]] = -1
            m[lq] = -1

        placed_set = set(lq for lq in interacting_logical if m[lq] >= 0)
        for lq in sorted(subset, key=lambda q: qcost[q], reverse=True):
            best_pq, best_sc = None, float('inf')
            for pq in freed_phys:
                if rm[pq] != -1:
                    continue
                sc = 0.0
                for partner, w in nbrs.get(lq, {}).items():
                    if partner in placed_set and m[partner] >= 0:
                        sc += w * (dist[pq][m[partner]] ** alpha_exp)
                if sc < best_sc:
                    best_sc = sc
                    best_pq = pq
            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                placed_set.add(lq)
            else:
                for pq in freed_phys:
                    if rm[pq] == -1:
                        m[lq] = pq
                        rm[pq] = lq
                        placed_set.add(lq)
                        break

    perturbation_modes = [perturb_random, perturb_segment_shuffle,
                          perturb_worst_pair, perturb_edge_targeted, perturb_lns]
    K = len(perturbation_modes)

    WINDOW_SIZE = 100
    EPSILON = 0.1
    window = []
    mode_successes = [0] * K
    mode_attempts = [0] * K

    def select_perturbation_mode():
        if random.random() < EPSILON or sum(mode_attempts) < K * 2:
            return random.randint(0, K - 1)
        rates = []
        for k in range(K):
            if mode_attempts[k] > 0:
                rates.append(mode_successes[k] / mode_attempts[k])
            else:
                rates.append(1.0)
        total = sum(rates)
        if total < 1e-12:
            return random.randint(0, K - 1)
        r = random.random() * total
        cumul = 0.0
        for k in range(K):
            cumul += rates[k]
            if r <= cumul:
                return k
        return K - 1

    def update_window(mode_idx, success):
        window.append((mode_idx, success))
        mode_attempts[mode_idx] += 1
        if success:
            mode_successes[mode_idx] += 1
        if len(window) > WINDOW_SIZE:
            old_mode, old_success = window.pop(0)
            mode_attempts[old_mode] -= 1
            if old_success:
                mode_successes[old_mode] -= 1

    # ---------------------------------------------------------------
    # Step 11: Build initial mapping candidates (MIS + greedy + spectral)
    # ---------------------------------------------------------------
    static_nbrs, static_deg = build_neighbors(static_weight)

    candidates = []

    # Greedy seeds
    for s_lq in seed_lqs:
        for s_pq in seed_pqs:
            m, rm = run_greedy_placement(s_lq, s_pq, static_nbrs, static_deg)
            fill_unmapped(m, rm)
            cost = compute_cost(m, static_weight)
            candidates.append((cost, m, rm))

    # Spectral seed
    spec_m, spec_rm = spectral_seed()
    if spec_m is not None:
        fill_unmapped(spec_m, spec_rm)
        spec_cost = compute_cost(spec_m, static_weight)
        candidates.append((spec_cost, spec_m, spec_rm))

    # MIS seed
    mis_m, mis_rm = mis_seed()
    if mis_m is not None:
        fill_unmapped(mis_m, mis_rm)
        mis_cost = compute_cost(mis_m, static_weight)
        candidates.append((mis_cost, mis_m, mis_rm))

    # Random seed
    m_rand = [-1] * num_q
    rm_rand = [-1] * num_q
    shuffled_phys = list(physical_qubits)
    random.shuffle(shuffled_phys)
    for i, lq in enumerate(logical_qubits):
        m_rand[lq] = shuffled_phys[i]
        rm_rand[shuffled_phys[i]] = lq
    fill_unmapped(m_rand, rm_rand)
    c = compute_cost(m_rand, static_weight)
    candidates.append((c, m_rand, rm_rand))

    if not candidates:
        self.mapping_dict = list(range(num_q))
        self.reverse_mapping_dict = list(range(num_q))
        if self.use_isl:
            self.isl_mapping = dict_to_isl_map(self.mapping_dict)
        return

    candidates.sort(key=lambda x: x[0])

    _, best_m, best_rm = candidates[0]
    best_m, best_rm = list(best_m), list(best_rm)
    local_search(best_m, best_rm, static_nbrs, static_weight, alpha_exp=2.0, max_rounds=6)
    best_cost = compute_cost(best_m, static_weight)

    for idx in range(1, min(6, len(candidates))):
        _, m_c, rm_c = candidates[idx]
        m_c, rm_c = list(m_c), list(rm_c)
        local_search(m_c, rm_c, static_nbrs, static_weight, alpha_exp=2.0, max_rounds=4)
        c = compute_cost(m_c, static_weight)
        if c < best_cost:
            best_cost = c
            best_m = list(m_c)
            best_rm = list(rm_c)

    # ---------------------------------------------------------------
    # Step 12: Surrogate-Accelerated ILS with RSDIWR
    # ---------------------------------------------------------------
    time_budget = 25.0
    t_start = _time()
    n_rsdiwr = 4

    cur_m = list(best_m)
    cur_rm = list(best_rm)
    swap_counts = defaultdict(float)

    # Congestion map accumulates across RSDIWR iterations
    congestion_map = defaultdict(float)

    # Online ridge surrogate — initialized lazily after we know feature dim
    surrogate = None
    n_true_evals = 0
    SURROGATE_REFIT_INTERVAL = 50
    SURROGATE_BATCH_SIZE = 50
    SURROGATE_TOP_K = 5
    SURROGATE_MIN_SAMPLES = 8
    MIN_R2_FOR_USE = 0.3  # lower threshold since online model improves over time

    # Collect initial training data from seed candidates
    initial_training_features = []
    for ci in range(min(4, len(candidates))):
        _, cm, crm = candidates[ci]
        cm, crm = list(cm), list(crm)
        sim_cong = dict(congestion_map)
        _, csw = simulate_routing_bidirectional(cm, crm, max_layers=12, use_astar=True, congestion_map=sim_cong)
        feat = extract_features_with_cross(cm)
        if feat:
            initial_training_features.append((feat, csw))
        n_true_evals += 1

    # Add perturbed versions for diversity
    for _ in range(min(6, max(3, num_q // 10))):
        pm = list(best_m)
        prm = list(best_rm)
        for _ in range(random.randint(1, 3)):
            if len(interacting_logical) >= 2:
                lqs = random.sample(interacting_logical, 2)
                do_swap(pm, prm, pm[lqs[0]], pm[lqs[1]])
        sim_cong = dict(congestion_map)
        _, psw = simulate_routing_bidirectional(pm, prm, max_layers=12, use_astar=True, congestion_map=sim_cong)
        feat = extract_features_with_cross(pm)
        if feat:
            initial_training_features.append((feat, psw))
        n_true_evals += 1

    # Initialize surrogate with initial data
    if initial_training_features and len(initial_training_features[0][0]) > 0:
        feat_dim = len(initial_training_features[0][0])
        surrogate = OnlineRidgeSurrogate(feat_dim, ridge_lambda=1.0)
        for feat, target in initial_training_features:
            if len(feat) == feat_dim:
                surrogate.add_sample(feat, target)
        surrogate.solve()

    for rsdiwr_iter in range(n_rsdiwr):
        elapsed = _time() - t_start
        if elapsed > time_budget:
            break

        # Time-adaptive ILS iterations
        remaining_time = time_budget - elapsed
        remaining_iters = n_rsdiwr - rsdiwr_iter
        time_for_this_iter = remaining_time / max(remaining_iters, 1)
        n_ils = max(55, int(num_q * time_for_this_iter / 0.5)) if time_for_this_iter > 1.0 else max(30, num_q // 3)

        # Blend static weights with routing feedback
        if rsdiwr_iter == 0 or not swap_counts:
            eff_weights = dict(static_weight)
        else:
            max_sw = max(swap_counts.values()) if swap_counts else 1.0
            scale = max(static_weight.values()) / max(max_sw, 1e-10)
            alpha_blend = max(0.3, 1.0 - 0.3 * rsdiwr_iter)
            eff_weights = defaultdict(float)
            all_keys = set(static_weight.keys()) | set(swap_counts.keys())
            for key in all_keys:
                w_s = static_weight.get(key, 0.0)
                w_r = swap_counts.get(key, 0.0) * scale
                eff_weights[key] = alpha_blend * w_s + (1.0 - alpha_blend) * w_r

        eff_nbrs, eff_deg = build_neighbors(eff_weights)

        alpha_start = 2.0
        alpha_end = 1.0

        ls_rounds = 6 if rsdiwr_iter == 0 else 4
        cur_cost_nl = local_search(cur_m, cur_rm, eff_nbrs, eff_weights,
                                   alpha_exp=alpha_start, max_rounds=ls_rounds)

        static_cost = compute_cost(cur_m, static_weight)
        if static_cost < best_cost:
            best_cost = static_cost
            best_m = list(cur_m)
            best_rm = list(cur_rm)

        # Reset bandit window
        window.clear()
        for k in range(K):
            mode_successes[k] = 0
            mode_attempts[k] = 0

        # Determine if surrogate is usable
        use_surrogate = (surrogate is not None and surrogate.theta is not None
                         and surrogate.n_samples >= SURROGATE_MIN_SAMPLES
                         and rsdiwr_iter >= 1 and n_pairs > 0)

        T = max(cur_cost_nl * 0.05, 1.0)
        T_init = T
        alpha_sa = 0.94
        reheat_interval = max(n_ils // 4, 8)

        ils_since_refit = 0

        for ils_iter in range(n_ils):
            if _time() - t_start > time_budget:
                break

            progress = ils_iter / max(n_ils - 1, 1)
            # Nonlinear annealing of distance exponent
            alpha_exp = alpha_start + (alpha_end - alpha_start) * (progress ** 0.7)

            # ---------------------------------------------------------------
            # Surrogate-accelerated candidate screening
            # ---------------------------------------------------------------
            if use_surrogate and surrogate.theta is not None:
                # Generate SURROGATE_BATCH_SIZE candidates, score with surrogate
                candidate_mappings = []
                for _ in range(SURROGATE_BATCH_SIZE):
                    cand_m = list(cur_m)
                    cand_rm = list(cur_rm)
                    mode = select_perturbation_mode()
                    perturbation_modes[mode](cand_m, cand_rm,
                                            nbrs=eff_nbrs, weights=eff_weights,
                                            alpha_exp=alpha_exp)
                    feat = extract_features_with_cross(cand_m)
                    surrogate_score = surrogate.predict(feat)
                    if surrogate_score is None:
                        surrogate_score = compute_cost_nonlinear(cand_m, eff_weights, alpha_exp)
                    candidate_mappings.append((surrogate_score, cand_m, cand_rm, mode))

                # Sort by surrogate prediction, take top-K
                candidate_mappings.sort(key=lambda x: x[0])
                top_candidates = candidate_mappings[:SURROGATE_TOP_K]

                # Validate top candidates with local search
                best_cand_cost = float('inf')
                best_cand_m = None
                best_cand_rm = None
                best_cand_mode = 0

                saved_m = list(cur_m)
                saved_rm = list(cur_rm)
                saved_cost = cur_cost_nl

                for _, cand_m, cand_rm, cand_mode in top_candidates:
                    test_m = list(cand_m)
                    test_rm = list(cand_rm)
                    test_cost = local_search(test_m, test_rm, eff_nbrs, eff_weights,
                                            alpha_exp=alpha_exp, max_rounds=3)
                    if test_cost < best_cand_cost:
                        best_cand_cost = test_cost
                        best_cand_m = test_m
                        best_cand_rm = test_rm
                        best_cand_mode = cand_mode

                if best_cand_m is not None:
                    new_cost_nl = best_cand_cost
                    success = new_cost_nl < saved_cost - 1e-12
                    improvement = saved_cost - new_cost_nl

                    if improvement > 0:
                        cur_m[:] = best_cand_m
                        cur_rm[:] = best_cand_rm
                        cur_cost_nl = new_cost_nl
                        sc = compute_cost(cur_m, static_weight)
                        if sc < best_cost:
                            best_cost = sc
                            best_m = list(cur_m)
                            best_rm = list(cur_rm)
                    elif random.random() < math.exp(min(0, improvement / max(T, 1e-10))):
                        cur_m[:] = best_cand_m
                        cur_rm[:] = best_cand_rm
                        cur_cost_nl = new_cost_nl

                    update_window(best_cand_mode, success)

                # Periodically refit surrogate
                ils_since_refit += 1
                if ils_since_refit >= SURROGATE_REFIT_INTERVAL:
                    surrogate.solve()
                    ils_since_refit = 0

            else:
                # Standard ILS iteration (no surrogate)
                saved_m = list(cur_m)
                saved_rm = list(cur_rm)
                saved_cost = cur_cost_nl

                mode = select_perturbation_mode()
                perturbation_modes[mode](cur_m, cur_rm,
                                        nbrs=eff_nbrs, weights=eff_weights,
                                        alpha_exp=alpha_exp)

                new_cost_nl = local_search(cur_m, cur_rm, eff_nbrs, eff_weights,
                                          alpha_exp=alpha_exp, max_rounds=3)

                success = new_cost_nl < saved_cost - 1e-12
                improvement = saved_cost - new_cost_nl
                if improvement > 0:
                    cur_cost_nl = new_cost_nl
                    sc = compute_cost(cur_m, static_weight)
                    if sc < best_cost:
                        best_cost = sc
                        best_m = list(cur_m)
                        best_rm = list(cur_rm)
                elif random.random() < math.exp(min(0, improvement / max(T, 1e-10))):
                    cur_cost_nl = new_cost_nl
                else:
                    cur_m[:] = saved_m
                    cur_rm[:] = saved_rm
                    cur_cost_nl = saved_cost

                update_window(mode, success)

            T *= alpha_sa
            if (ils_iter + 1) % reheat_interval == 0:
                T = max(T, T_init * 0.35)

        # Routing simulation with asymmetric bidirectional + A*-guided + congestion
        if rsdiwr_iter < n_rsdiwr - 1:
            sim_depth = 12 + rsdiwr_iter * 6
            sim_cong = dict(congestion_map)
            swap_counts, total_sim_swaps = simulate_routing_bidirectional(
                best_m, best_rm, max_layers=sim_depth, use_astar=True,
                congestion_map=sim_cong)

            # Update global congestion map (cascading)
            for pq, cnt in sim_cong.items():
                congestion_map[pq] = congestion_map.get(pq, 0) * 0.5 + cnt * 0.5

            # Collect training data for surrogate
            feat = extract_features_with_cross(best_m)
            if feat and surrogate is not None and len(feat) == surrogate.n:
                surrogate.add_sample(feat, total_sim_swaps)
                n_true_evals += 1

            # Identify cross-terms after first RSDIWR round
            if rsdiwr_iter == 0 and surrogate is not None and n_base >= 2:
                # Collect base features from training data for correlation analysis
                base_data = []
                for ci in range(min(len(candidates), 4)):
                    _, cm, crm = candidates[ci]
                    base_feat = extract_features(cm)
                    sim_c2 = dict(congestion_map)
                    _, csw2 = simulate_routing_bidirectional(list(cm), list(crm),
                                                             max_layers=sim_depth,
                                                             use_astar=True,
                                                             congestion_map=sim_c2)
                    if base_feat:
                        base_data.append((base_feat, csw2))
                    n_true_evals += 1

                if len(base_data) >= 4:
                    cross_term_indices[:] = identify_cross_terms(base_data)

                # Rebuild surrogate with new feature dimension (cross-terms added)
                if cross_term_indices:
                    new_feat_dim = n_base + len(cross_term_indices) + 2  # +2 for mean, max
                    surrogate = OnlineRidgeSurrogate(new_feat_dim, ridge_lambda=1.0)
                    # Re-add all previous training data with cross-term features
                    for ci in range(min(len(candidates), 4)):
                        _, cm, crm = candidates[ci]
                        f = extract_features_with_cross(cm)
                        if f and len(f) == new_feat_dim:
                            # Use previously computed swap counts approximately
                            sim_c3 = {}
                            _, sw3 = simulate_routing_bidirectional(list(cm), list(crm),
                                                                     max_layers=sim_depth,
                                                                     use_astar=False,
                                                                     congestion_map=sim_c3)
                            surrogate.add_sample(f, sw3)
                            n_true_evals += 1
                    # Add diverse perturbed mappings
                    for _ in range(min(6, max(3, num_q // 10))):
                        pm = list(best_m)
                        prm = list(best_rm)
                        for _ in range(random.randint(1, 3)):
                            if len(interacting_logical) >= 2:
                                lqs = random.sample(interacting_logical, 2)
                                do_swap(pm, prm, pm[lqs[0]], pm[lqs[1]])
                        sim_c4 = {}
                        _, psw2 = simulate_routing_bidirectional(pm, prm,
                                                                  max_layers=sim_depth,
                                                                  use_astar=False,
                                                                  congestion_map=sim_c4)
                        f = extract_features_with_cross(pm)
                        if f and len(f) == new_feat_dim:
                            surrogate.add_sample(f, psw2)
                        n_true_evals += 1
                    surrogate.solve()

            # Also collect diverse data for surrogate training
            if rsdiwr_iter >= 1 and surrogate is not None:
                for _ in range(min(4, max(2, num_q // 15))):
                    pm = list(best_m)
                    prm = list(best_rm)
                    for _ in range(random.randint(1, 3)):
                        if len(interacting_logical) >= 2:
                            lqs = random.sample(interacting_logical, 2)
                            do_swap(pm, prm, pm[lqs[0]], pm[lqs[1]])
                    sim_c5 = {}
                    _, psw3 = simulate_routing_bidirectional(pm, prm,
                                                              max_layers=sim_depth,
                                                              use_astar=False,
                                                              congestion_map=sim_c5)
                    feat = extract_features_with_cross(pm)
                    if feat and len(feat) == surrogate.n:
                        surrogate.add_sample(feat, psw3)
                    n_true_evals += 1
                surrogate.solve()

        cur_m = list(best_m)
        cur_rm = list(best_rm)
        cur_cost_nl = compute_cost_nonlinear(cur_m, eff_weights, alpha_end)

    # ---------------------------------------------------------------
    # Step 13: Set final mapping
    # ---------------------------------------------------------------
    self.mapping_dict = best_m
    self.reverse_mapping_dict = best_rm

    if self.use_isl:
        self.isl_mapping = dict_to_isl_map(self.mapping_dict)

def init_mapping(self):
    import math
    import random
    import heapq
    from collections import defaultdict, deque
    from time import time as _time

    num_q = self.num_qubits
    physical_qubits = sorted(self.backend.keys())
    dist = self.distance_matrix

    # ---------------------------------------------------------------
    # Step 1: Build DAG and topological layers
    # ---------------------------------------------------------------
    all_gates = sorted(self.access.keys())
    two_qubit_gates = [g for g in all_gates if len(self.access[g]) == 2]

    last_gate_on_qubit = {}
    successors_dag = defaultdict(set)
    predecessors_dag = defaultdict(set)
    for g in all_gates:
        for q in self.access[g]:
            if q in last_gate_on_qubit:
                pred = last_gate_on_qubit[q]
                successors_dag[pred].add(g)
                predecessors_dag[g].add(pred)
            last_gate_on_qubit[q] = g

    in_degree = {g: len(predecessors_dag[g]) for g in all_gates}
    gate_layer = {g: 0 for g in all_gates}
    temp_in = dict(in_degree)
    queue = deque(g for g in all_gates if in_degree[g] == 0)
    topo_order = []
    while queue:
        g = queue.popleft()
        topo_order.append(g)
        for s in successors_dag[g]:
            gate_layer[s] = max(gate_layer[s], gate_layer[g] + 1)
            temp_in[s] -= 1
            if temp_in[s] == 0:
                queue.append(s)

    critical_path = {g: 0 for g in all_gates}
    for g in reversed(topo_order):
        for s in successors_dag[g]:
            if critical_path[s] + 1 > critical_path[g]:
                critical_path[g] = critical_path[s] + 1

    # 2q DAG for routing simulation
    gates_2q = {}
    dag2q_succ = defaultdict(set)
    dag2q_pred = defaultdict(set)
    last_2q_on_qubit = {}
    logical_qubits_set = set()

    for gate in all_gates:
        qubits = self.access[gate]
        if len(qubits) == 2:
            q1, q2 = qubits
            gates_2q[gate] = (q1, q2)
            logical_qubits_set.add(q1)
            logical_qubits_set.add(q2)
            for q in [q1, q2]:
                if q in last_2q_on_qubit:
                    prev = last_2q_on_qubit[q]
                    if prev != gate:
                        dag2q_succ[prev].add(gate)
                        dag2q_pred[gate].add(prev)
                last_2q_on_qubit[q] = gate
        elif len(qubits) == 1:
            logical_qubits_set.add(qubits[0])

    logical_qubits = sorted(logical_qubits_set)

    if not gates_2q:
        self.mapping_dict = list(range(num_q))
        self.reverse_mapping_dict = list(range(num_q))
        if self.use_isl:
            self.isl_mapping = dict_to_isl_map(self.mapping_dict)
        return

    # Topological order for 2q DAG
    topo_2q = []
    in_deg_2q = {g: len(dag2q_pred[g]) for g in gates_2q}
    q2 = deque(sorted(g for g in gates_2q if in_deg_2q[g] == 0))
    while q2:
        g = q2.popleft()
        topo_2q.append(g)
        for s in dag2q_succ[g]:
            in_deg_2q[s] -= 1
            if in_deg_2q[s] == 0:
                q2.append(s)

    dep_count = defaultdict(int)
    for g in reversed(topo_2q):
        for s in dag2q_succ[g]:
            dep_count[g] = max(dep_count[g], dep_count[s] + 1)

    bwd_dep = defaultdict(int)
    for g in topo_2q:
        for p in dag2q_pred[g]:
            if p in gates_2q:
                bwd_dep[g] = max(bwd_dep[g], bwd_dep[p] + 1)

    # ---------------------------------------------------------------
    # Step 2: Interaction weights
    # ---------------------------------------------------------------
    max_layer = max((gate_layer[g] for g in two_qubit_gates), default=1)

    static_weight = defaultdict(float)
    logical_degree = defaultdict(float)

    for g in two_qubit_gates:
        q1, q2 = self.access[g]
        cp = critical_path[g] + 1
        layer = gate_layer[g]
        w = cp * (max_layer - layer + 1)
        key = (min(q1, q2), max(q1, q2))
        static_weight[key] += w
        logical_degree[q1] += w
        logical_degree[q2] += w

    interacting_logical = [q for q in logical_qubits if logical_degree.get(q, 0) > 0]

    # ---------------------------------------------------------------
    # Step 3: Physical graph properties
    # ---------------------------------------------------------------
    hw_adj = defaultdict(set)
    for pq in physical_qubits:
        for pq2 in self.backend.get(pq, []):
            hw_adj[pq].add(pq2)

    phys_degree = {pq: len(hw_adj[pq]) for pq in physical_qubits}
    phys_centrality = {}
    for pq in physical_qubits:
        phys_centrality[pq] = sum(dist[pq][pq2] for pq2 in physical_qubits)

    # ---------------------------------------------------------------
    # Step 4: Core helper functions
    # ---------------------------------------------------------------
    def build_neighbors(weights):
        nbrs = defaultdict(dict)
        deg = defaultdict(float)
        for (q1, q2), w in weights.items():
            nbrs[q1][q2] = w
            nbrs[q2][q1] = w
            deg[q1] += w
            deg[q2] += w
        return nbrs, deg

    def compute_cost_nonlinear(m, weights, alpha_exp):
        cost = 0.0
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                d = dist[m[q1]][m[q2]]
                cost += w * (d ** alpha_exp)
        return cost

    def compute_cost(m, weights):
        cost = 0.0
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                cost += w * dist[m[q1]][m[q2]]
        return cost

    def delta_swap_cost_nonlinear(m, rm, pq_a, pq_b, nbrs, alpha_exp):
        lq_a, lq_b = rm[pq_a], rm[pq_b]
        delta = 0.0
        affected = set()
        if lq_a in nbrs:
            affected.update(nbrs[lq_a].keys())
        if lq_b in nbrs:
            affected.update(nbrs[lq_b].keys())
        for q in affected:
            if q == lq_a or q == lq_b:
                continue
            pq_q = m[q]
            w_a = nbrs.get(lq_a, {}).get(q, 0.0)
            if w_a > 0:
                old_d = dist[pq_a][pq_q] ** alpha_exp
                new_d = dist[pq_b][pq_q] ** alpha_exp
                delta += w_a * (new_d - old_d)
            w_b = nbrs.get(lq_b, {}).get(q, 0.0)
            if w_b > 0:
                old_d = dist[pq_b][pq_q] ** alpha_exp
                new_d = dist[pq_a][pq_q] ** alpha_exp
                delta += w_b * (new_d - old_d)
        return delta

    def do_swap(m, rm, pq_a, pq_b):
        lq_a, lq_b = rm[pq_a], rm[pq_b]
        m[lq_a], m[lq_b] = pq_b, pq_a
        rm[pq_a], rm[pq_b] = lq_b, lq_a

    def fill_unmapped(m, rm):
        unmapped = [q for q in range(num_q) if m[q] == -1]
        free = [pq for pq in range(num_q) if rm[pq] == -1]
        for lq, pq in zip(unmapped, free):
            m[lq] = pq
            rm[pq] = lq

    # ---------------------------------------------------------------
    # Step 5: Maximum-weight matching on interaction graph
    # ---------------------------------------------------------------
    def greedy_max_weight_matching(weights, nodes):
        """Greedy approximation of maximum-weight matching.
        Returns list of disjoint pairs (q1, q2)."""
        edges = []
        for (q1, q2), w in weights.items():
            if q1 in nodes and q2 in nodes:
                edges.append((w, q1, q2))
        edges.sort(reverse=True)
        matched = set()
        pairs = []
        for w, q1, q2 in edges:
            if q1 not in matched and q2 not in matched:
                pairs.append((q1, q2))
                matched.add(q1)
                matched.add(q2)
        return pairs

    def greedy_max_weight_matching_hw(hw_adj_local, phys_nodes):
        """Greedy matching on hardware graph by combined degree."""
        edges = []
        seen = set()
        for pq in phys_nodes:
            for nb in hw_adj_local.get(pq, set()):
                if nb in phys_nodes:
                    edge = (min(pq, nb), max(pq, nb))
                    if edge not in seen:
                        seen.add(edge)
                        combined_deg = len(hw_adj_local.get(pq, set())) + len(hw_adj_local.get(nb, set()))
                        edges.append((combined_deg, pq, nb))
        edges.sort(reverse=True)
        matched = set()
        pairs = []
        for _, p1, p2 in edges:
            if p1 not in matched and p2 not in matched:
                pairs.append((p1, p2))
                matched.add(p1)
                matched.add(p2)
        return pairs

    # ---------------------------------------------------------------
    # Step 6: Graph contraction functions
    # ---------------------------------------------------------------
    def contract_interaction_graph(weights, logical_pairs, interacting_set):
        """Contract the interaction graph by merging logical pairs into super-qubits.
        Returns: contracted_weights, super_to_pair mapping, pair_to_super mapping."""
        # Map each qubit to its super-qubit ID
        qubit_to_super = {}
        super_to_pair = {}  # super_id -> (q1, q2)
        next_super_id = 0

        for (q1, q2) in logical_pairs:
            qubit_to_super[q1] = next_super_id
            qubit_to_super[q2] = next_super_id
            super_to_pair[next_super_id] = (q1, q2)
            next_super_id += 1

        # Singleton qubits (not in any pair)
        for q in interacting_set:
            if q not in qubit_to_super:
                qubit_to_super[q] = next_super_id
                super_to_pair[next_super_id] = (q,)
                next_super_id += 1

        # Build contracted weights
        contracted_weights = defaultdict(float)
        for (q1, q2), w in weights.items():
            s1 = qubit_to_super.get(q1)
            s2 = qubit_to_super.get(q2)
            if s1 is not None and s2 is not None and s1 != s2:
                key = (min(s1, s2), max(s1, s2))
                contracted_weights[key] += w

        return contracted_weights, super_to_pair, qubit_to_super

    def contract_hardware_graph(hw_pairs, all_phys):
        """Contract hardware graph by merging physical pairs into super-positions.
        Returns: contracted_dist, super_to_phys_pair, phys_to_super, contracted_hw_adj."""
        phys_to_super = {}
        super_to_phys = {}
        next_id = 0

        for (p1, p2) in hw_pairs:
            phys_to_super[p1] = next_id
            phys_to_super[p2] = next_id
            super_to_phys[next_id] = (p1, p2)
            next_id += 1

        for p in all_phys:
            if p not in phys_to_super:
                phys_to_super[p] = next_id
                super_to_phys[next_id] = (p,)
                next_id += 1

        n_super = next_id
        # Contracted distance: min distance between members
        contracted_dist = [[0] * n_super for _ in range(n_super)]
        for i in range(n_super):
            for j in range(n_super):
                if i == j:
                    contracted_dist[i][j] = 0
                else:
                    min_d = float('inf')
                    for pi in super_to_phys[i]:
                        for pj in super_to_phys[j]:
                            d = dist[pi][pj]
                            if d < min_d:
                                min_d = d
                    contracted_dist[i][j] = min_d

        # Contracted adjacency
        contracted_hw_adj = defaultdict(set)
        for i in range(n_super):
            for j in range(n_super):
                if i != j and contracted_dist[i][j] <= 1:
                    contracted_hw_adj[i].add(j)

        return contracted_dist, super_to_phys, phys_to_super, contracted_hw_adj, n_super

    # ---------------------------------------------------------------
    # Step 7: Routing simulation (works on any resolution)
    # ---------------------------------------------------------------
    def simulate_routing_greedy(m, rm, max_layers=20):
        sim_m = list(m)
        sim_rm = list(rm)
        swap_counts = defaultdict(float)
        total_swaps = 0

        if not gates_2q:
            return swap_counts, total_swaps

        pred_remaining = {g: len(dag2q_pred[g]) for g in gates_2q}
        front = set(g for g in gates_2q if pred_remaining[g] == 0)
        layers_done = 0

        while front and layers_done < max_layers:
            executable = []
            for g in front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = sim_m[gq1], sim_m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    executable.append(g)

            if executable:
                for g in executable:
                    front.discard(g)
                    for s in dag2q_succ[g]:
                        pred_remaining[s] -= 1
                        if pred_remaining[s] == 0:
                            front.add(s)
                layers_done += 1
                continue

            active_phys = set()
            for g in front:
                gq1, gq2 = gates_2q[g]
                active_phys.add(sim_m[gq1])
                active_phys.add(sim_m[gq2])

            candidates_sw = set()
            for pq in active_phys:
                for nb in self.backend.get(pq, []):
                    candidates_sw.add((min(pq, nb), max(pq, nb)))

            best_swap, best_score = None, float('inf')
            for (s1, s2) in candidates_sw:
                l1, l2 = sim_rm[s1], sim_rm[s2]
                score = 0.0
                for g in front:
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = sim_m[gq1], sim_m[gq2]
                    if gq1 == l1: p1 = s2
                    elif gq1 == l2: p1 = s1
                    if gq2 == l1: p2 = s2
                    elif gq2 == l2: p2 = s1
                    deps = dep_count.get(g, 0) + 1
                    score += deps * dist[p1][p2]
                if score < best_score:
                    best_score = score
                    best_swap = (s1, s2)

            if best_swap is None:
                break

            s1, s2 = best_swap
            l1, l2 = sim_rm[s1], sim_rm[s2]
            sim_m[l1], sim_m[l2] = s2, s1
            sim_rm[s1], sim_rm[s2] = l2, l1
            total_swaps += 1

            for g in front:
                gq1, gq2 = gates_2q[g]
                pair_key = (min(gq1, gq2), max(gq1, gq2))
                swap_counts[pair_key] += 1.0

        return swap_counts, total_swaps

    def simulate_routing_backward(m, rm, max_layers=20):
        sim_m = list(m)
        sim_rm = list(rm)
        swap_counts = defaultdict(float)
        total_swaps = 0

        if not gates_2q:
            return swap_counts, total_swaps

        succ_remaining = {g: len(dag2q_succ[g] & set(gates_2q.keys())) for g in gates_2q}
        front = set(g for g in gates_2q if succ_remaining[g] == 0)
        layers_done = 0

        while front and layers_done < max_layers:
            executable = []
            for g in front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = sim_m[gq1], sim_m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    executable.append(g)

            if executable:
                for g in executable:
                    front.discard(g)
                    for p in dag2q_pred[g]:
                        if p in gates_2q:
                            succ_remaining[p] -= 1
                            if succ_remaining[p] == 0:
                                front.add(p)
                layers_done += 1
                continue

            active_phys = set()
            for g in front:
                gq1, gq2 = gates_2q[g]
                active_phys.add(sim_m[gq1])
                active_phys.add(sim_m[gq2])

            candidates_sw = set()
            for pq in active_phys:
                for nb in self.backend.get(pq, []):
                    candidates_sw.add((min(pq, nb), max(pq, nb)))

            best_swap, best_score = None, float('inf')
            for (s1, s2) in candidates_sw:
                l1, l2 = sim_rm[s1], sim_rm[s2]
                score = 0.0
                for g in front:
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = sim_m[gq1], sim_m[gq2]
                    if gq1 == l1: p1 = s2
                    elif gq1 == l2: p1 = s1
                    if gq2 == l1: p2 = s2
                    elif gq2 == l2: p2 = s1
                    deps = bwd_dep.get(g, 0) + 1
                    score += deps * dist[p1][p2]
                if score < best_score:
                    best_score = score
                    best_swap = (s1, s2)

            if best_swap is None:
                break

            s1, s2 = best_swap
            l1, l2 = sim_rm[s1], sim_rm[s2]
            sim_m[l1], sim_m[l2] = s2, s1
            sim_rm[s1], sim_rm[s2] = l2, l1
            total_swaps += 1

            for g in front:
                gq1, gq2 = gates_2q[g]
                pair_key = (min(gq1, gq2), max(gq1, gq2))
                swap_counts[pair_key] += 1.0

        return swap_counts, total_swaps

    def simulate_routing_bidir(m, rm, max_layers=20):
        fwd_swaps, fwd_total = simulate_routing_greedy(m, rm, max_layers=max_layers)
        bwd_swaps, bwd_total = simulate_routing_backward(m, rm, max_layers=max_layers)
        combined = defaultdict(float)
        all_keys = set(fwd_swaps.keys()) | set(bwd_swaps.keys())
        for key in all_keys:
            combined[key] = 0.6 * fwd_swaps.get(key, 0.0) + 0.4 * bwd_swaps.get(key, 0.0)
        return combined, (fwd_total + bwd_total) // 2

    # ---------------------------------------------------------------
    # Step 8: Seed generation
    # ---------------------------------------------------------------
    sorted_by_degree = sorted(interacting_logical, key=lambda q: logical_degree[q], reverse=True)
    seed_lqs = sorted_by_degree[:min(3, len(sorted_by_degree))]
    phys_by_centrality = sorted(physical_qubits, key=lambda pq: phys_centrality[pq])
    seed_pqs = phys_by_centrality[:min(3, len(phys_by_centrality))]

    logical_degree_ranked = sorted(interacting_logical, key=lambda q: logical_degree[q], reverse=True)
    logical_degree_rank = {q: i for i, q in enumerate(logical_degree_ranked)}
    max_logical_rank = max(len(logical_degree_ranked) - 1, 1)
    phys_degree_ranked = sorted(physical_qubits, key=lambda pq: phys_degree[pq], reverse=True)
    phys_degree_rank = {pq: i for i, pq in enumerate(phys_degree_ranked)}
    max_phys_rank = max(len(phys_degree_ranked) - 1, 1)

    static_nbrs, static_deg = build_neighbors(static_weight)
    max_iw = max(static_weight.values()) if static_weight else 1.0

    # ---------------------------------------------------------------
    # Step 9: Greedy placement
    # ---------------------------------------------------------------
    def run_greedy_placement(start_lq, start_pq, nbrs, deg, weights=None):
        cur_max_iw = max(weights.values()) if weights else max_iw
        used_phys = {start_pq}
        m = [-1] * num_q
        rm = [-1] * num_q
        m[start_lq] = start_pq
        rm[start_pq] = start_lq
        placed = {start_lq}
        remaining = set(logical_qubits) - placed

        while remaining:
            best_lq, best_w = None, -1.0
            for lq in remaining:
                w = sum(nbrs.get(lq, {}).get(plq, 0.0) for plq in placed)
                if w > best_w:
                    best_w = w
                    best_lq = lq

            nbrs_placed = {plq: nbrs.get(best_lq, {}).get(plq, 0.0)
                           for plq in placed if plq in nbrs.get(best_lq, {})}

            if nbrs_placed:
                near_ties = []
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq in used_phys:
                        continue
                    score = 0.0
                    for plq, iw in nbrs_placed.items():
                        d = dist[pq][m[plq]]
                        cost = iw * d
                        if m[plq] in hw_adj[pq]:
                            cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                        score += cost
                    near_ties.append((score, pq))
                    if score < best_score:
                        best_score = score

                if near_ties and best_score > 0:
                    threshold = best_score * 1.05
                    candidates_list = [(s, pq) for s, pq in near_ties if s <= threshold]
                    if len(candidates_list) > 1 and best_lq in logical_degree_rank:
                        lq_rn = logical_degree_rank[best_lq] / max_logical_rank
                        best_pq = min(candidates_list, key=lambda x: (
                            abs(phys_degree_rank[x[1]] / max_phys_rank - lq_rn), x[0]))[1]
                    else:
                        best_pq = min(candidates_list, key=lambda x: x[0])[1]
                elif near_ties:
                    best_pq = min(near_ties, key=lambda x: x[0])[1]
                else:
                    best_pq = None
            else:
                best_pq = None
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq not in used_phys:
                        score = phys_centrality[pq]
                        if score < best_score:
                            best_score = score
                            best_pq = pq

            m[best_lq] = best_pq
            rm[best_pq] = best_lq
            used_phys.add(best_pq)
            placed.add(best_lq)
            remaining.discard(best_lq)
        return m, rm

    # ---------------------------------------------------------------
    # Step 10: Spectral seed
    # ---------------------------------------------------------------
    def spectral_seed():
        if len(interacting_logical) < 3:
            return None, None

        idx_map = {q: i for i, q in enumerate(interacting_logical)}
        n = len(interacting_logical)

        L = [[0.0] * n for _ in range(n)]
        for (q1, q2), w in static_weight.items():
            if q1 in idx_map and q2 in idx_map:
                i, j = idx_map[q1], idx_map[q2]
                L[i][j] -= w
                L[j][i] -= w
                L[i][i] += w
                L[j][j] += w

        def power_iter(mat, n_iter=200):
            v = [random.gauss(0, 1) for _ in range(n)]
            for _ in range(n_iter):
                new_v = [0.0] * n
                for i in range(n):
                    for j in range(n):
                        new_v[i] += mat[i][j] * v[j]
                norm = math.sqrt(sum(x * x for x in new_v)) or 1e-12
                v = [x / norm for x in new_v]
            return v

        max_diag = max(L[i][i] for i in range(n)) + 1.0
        shifted = [[0.0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                shifted[i][j] = -L[i][j]
            shifted[i][i] += max_diag

        v1 = power_iter(shifted, 150)
        dot_v1 = sum(x * x for x in v1) or 1e-12
        lam1_shifted = sum(v1[i] * sum(shifted[i][j] * v1[j] for j in range(n)) for i in range(n)) / dot_v1
        shifted2 = [row[:] for row in shifted]
        for i in range(n):
            for j in range(n):
                shifted2[i][j] -= lam1_shifted * v1[i] * v1[j] / dot_v1

        fiedler = power_iter(shifted2, 200)
        fiedler_order = sorted(range(n), key=lambda i: fiedler[i])
        sorted_logical = [interacting_logical[i] for i in fiedler_order]

        phys_sorted = sorted(physical_qubits, key=lambda pq: phys_centrality[pq])
        start_pq = phys_sorted[0]
        visited_bfs = set()
        bfs_order = []
        bfs_q = deque([start_pq])
        visited_bfs.add(start_pq)
        while bfs_q:
            pq = bfs_q.popleft()
            bfs_order.append(pq)
            for nb in sorted(hw_adj[pq]):
                if nb not in visited_bfs:
                    visited_bfs.add(nb)
                    bfs_q.append(nb)
        for pq in physical_qubits:
            if pq not in visited_bfs:
                bfs_order.append(pq)
                visited_bfs.add(pq)

        m = [-1] * num_q
        rm = [-1] * num_q
        n_interact = len(sorted_logical)
        n_phys = len(bfs_order)
        offset = max(0, (n_phys - n_interact) // 2)
        for i, lq in enumerate(sorted_logical):
            pq = bfs_order[min(offset + i, n_phys - 1)]
            if rm[pq] != -1:
                best_pq = None
                best_d = float('inf')
                for cpq in physical_qubits:
                    if rm[cpq] == -1:
                        d = dist[pq][cpq]
                        if d < best_d:
                            best_d = d
                            best_pq = cpq
                pq = best_pq
            m[lq] = pq
            rm[pq] = lq

        return m, rm

    # ---------------------------------------------------------------
    # Step 11: MIS seed
    # ---------------------------------------------------------------
    def conflict_graph_seed(start_pq, nbrs, deg, weights, routing_pressure=None):
        if len(interacting_logical) < 2:
            return None, None

        cur_max_iw = max(weights.values()) if weights else 1.0

        top_partners = {}
        for lq in interacting_logical:
            nbr_list = sorted(nbrs.get(lq, {}).items(), key=lambda x: x[1], reverse=True)
            top_partners[lq] = set(p for p, _ in nbr_list[:3])

        conflict_adj = defaultdict(set)
        il = interacting_logical

        qubit_pressure = defaultdict(float)
        if routing_pressure:
            for (q1, q2), cnt in routing_pressure.items():
                qubit_pressure[q1] += cnt
                qubit_pressure[q2] += cnt

        for i in range(len(il)):
            for j in range(i + 1, len(il)):
                l1, l2 = il[i], il[j]
                s1 = top_partners.get(l1, set())
                s2 = top_partners.get(l2, set())
                if not s1 and not s2:
                    continue
                intersection = len(s1 & s2)
                union = len(s1 | s2)
                if union > 0:
                    jaccard = intersection / union
                    threshold = 0.5
                    if routing_pressure and qubit_pressure[l1] > 0 and qubit_pressure[l2] > 0:
                        max_pressure = max(qubit_pressure.values()) if qubit_pressure else 1.0
                        pressure_factor = min(1.0, (qubit_pressure[l1] + qubit_pressure[l2]) /
                                              (max_pressure * 2 + 1e-10))
                        threshold = max(0.25, 0.5 - 0.25 * pressure_factor)
                    if jaccard > threshold:
                        conflict_adj[l1].add(l2)
                        conflict_adj[l2].add(l1)

        sorted_by_deg_local = sorted(interacting_logical,
                                     key=lambda q: (deg.get(q, 0), qubit_pressure.get(q, 0)),
                                     reverse=True)
        mis = set()
        excluded = set()
        for lq in sorted_by_deg_local:
            if lq not in excluded:
                mis.add(lq)
                for neighbor in conflict_adj.get(lq, set()):
                    excluded.add(neighbor)

        non_mis = [lq for lq in sorted_by_deg_local if lq not in mis]
        mis_ordered = sorted(mis, key=lambda q: (deg.get(q, 0), qubit_pressure.get(q, 0)),
                             reverse=True)

        m = [-1] * num_q
        rm = [-1] * num_q
        used_phys = set()

        if mis_ordered:
            first_lq = mis_ordered[0]
            m[first_lq] = start_pq
            rm[start_pq] = first_lq
            used_phys.add(start_pq)

            for lq in mis_ordered[1:]:
                nbrs_placed = {}
                for plq in mis:
                    if m[plq] >= 0 and plq in nbrs.get(lq, {}):
                        nbrs_placed[plq] = nbrs[lq][plq]

                if nbrs_placed:
                    best_pq = None
                    best_score = float('inf')
                    for pq in physical_qubits:
                        if pq in used_phys:
                            continue
                        score = 0.0
                        for plq, iw in nbrs_placed.items():
                            d = dist[pq][m[plq]]
                            cost = iw * d
                            if m[plq] in hw_adj[pq]:
                                cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                            score += cost
                        if score < best_score:
                            best_score = score
                            best_pq = pq
                else:
                    best_pq = None
                    best_score = float('inf')
                    for pq in physical_qubits:
                        if pq not in used_phys:
                            if phys_centrality[pq] < best_score:
                                best_score = phys_centrality[pq]
                                best_pq = pq

                if best_pq is not None:
                    m[lq] = best_pq
                    rm[best_pq] = lq
                    used_phys.add(best_pq)

        placed_set = set(lq for lq in interacting_logical if m[lq] >= 0)

        for lq in non_mis:
            nbrs_placed = {}
            for plq in placed_set:
                w = nbrs.get(lq, {}).get(plq, 0.0)
                if w > 0:
                    nbrs_placed[plq] = w

            if nbrs_placed:
                best_pq = None
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq in used_phys:
                        continue
                    score = 0.0
                    for plq, iw in nbrs_placed.items():
                        d = dist[pq][m[plq]]
                        cost = iw * d
                        if m[plq] in hw_adj[pq]:
                            cost *= 0.90 - 0.10 * (iw / cur_max_iw)
                        score += cost
                    if score < best_score:
                        best_score = score
                        best_pq = pq
            else:
                best_pq = None
                best_score = float('inf')
                for pq in physical_qubits:
                    if pq not in used_phys:
                        if phys_centrality[pq] < best_score:
                            best_score = phys_centrality[pq]
                            best_pq = pq

            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                used_phys.add(best_pq)
                placed_set.add(lq)

        remaining_lqs = [lq for lq in logical_qubits if m[lq] == -1]
        for lq in remaining_lqs:
            best_pq = None
            best_score = float('inf')
            for pq in physical_qubits:
                if pq not in used_phys:
                    if phys_centrality[pq] < best_score:
                        best_score = phys_centrality[pq]
                        best_pq = pq
            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                used_phys.add(best_pq)

        return m, rm

    # ---------------------------------------------------------------
    # Step 12: Local search
    # ---------------------------------------------------------------
    def local_search(m, rm, nbrs, weights, alpha_exp, max_rounds=5):
        if len(interacting_logical) <= 1:
            return compute_cost_nonlinear(m, weights, alpha_exp)
        for _ in range(max_rounds):
            improved = False
            best_d, best_pair = 0.0, None
            active_phys = [m[q] for q in interacting_logical]
            for pq1 in active_phys:
                for pq2 in hw_adj.get(pq1, set()):
                    d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                    if d < best_d:
                        best_d = d
                        best_pair = (pq1, pq2)
            n_random = min(150, len(interacting_logical) * 3)
            for _ in range(n_random):
                i, j = random.sample(range(len(interacting_logical)), 2)
                pq1, pq2 = m[interacting_logical[i]], m[interacting_logical[j]]
                d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                if d < best_d:
                    best_d = d
                    best_pair = (pq1, pq2)
            if best_pair and best_d < -1e-12:
                do_swap(m, rm, *best_pair)
                improved = True
            if not improved:
                for i in range(len(interacting_logical)):
                    for j in range(i + 1, len(interacting_logical)):
                        pq1, pq2 = m[interacting_logical[i]], m[interacting_logical[j]]
                        d = delta_swap_cost_nonlinear(m, rm, pq1, pq2, nbrs, alpha_exp)
                        if d < best_d:
                            best_d = d
                            best_pair = (pq1, pq2)
                if best_pair and best_d < -1e-12:
                    do_swap(m, rm, *best_pair)
                else:
                    break
        return compute_cost_nonlinear(m, weights, alpha_exp)

    # ---------------------------------------------------------------
    # Step 13: Perturbation modes with bandit selection
    # ---------------------------------------------------------------
    rsdiwr_iter_ref = [0]
    accumulated_routing_pressure_ref = [defaultdict(float)]

    def perturb_random(m, rm, **kw):
        if len(interacting_logical) >= 2:
            lqs = random.sample(interacting_logical, 2)
            do_swap(m, rm, m[lqs[0]], m[lqs[1]])

    def perturb_segment_shuffle(m, rm, **kw):
        k = min(random.randint(3, 5), len(interacting_logical))
        if k < 2:
            perturb_random(m, rm)
            return
        lqs = random.sample(interacting_logical, k)
        phys_positions = [m[lq] for lq in lqs]
        random.shuffle(phys_positions)
        for lq in lqs:
            rm[m[lq]] = -1
        for lq, pq in zip(lqs, phys_positions):
            m[lq] = pq
            rm[pq] = lq

    def perturb_worst_pair(m, rm, weights=None, alpha_exp=1.5, **kw):
        if weights is None:
            perturb_random(m, rm)
            return
        pair_costs = []
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                d = dist[m[q1]][m[q2]]
                c = w * (d ** alpha_exp)
                pair_costs.append((c, q1, q2))
        if not pair_costs:
            return
        pair_costs.sort(reverse=True)
        top_n = min(3, len(pair_costs))
        _, tq1, tq2 = pair_costs[random.randint(0, top_n - 1)]
        pq1, pq2 = m[tq1], m[tq2]
        adj_of_pq2 = list(hw_adj.get(pq2, set()))
        if adj_of_pq2:
            target = random.choice(adj_of_pq2)
            if target != pq1:
                do_swap(m, rm, pq1, target)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    def perturb_edge_targeted(m, rm, weights=None, alpha_exp=1.5, **kw):
        if weights is None:
            perturb_random(m, rm)
            return
        edge_costs = []
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                c = w * (dist[m[q1]][m[q2]] ** alpha_exp)
                edge_costs.append((c, q1, q2))
        if not edge_costs:
            return
        edge_costs.sort(reverse=True)
        top_n = min(5, len(edge_costs))
        _, eq1, eq2 = edge_costs[random.randint(0, top_n - 1)]
        pq1, pq2 = m[eq1], m[eq2]
        neighbors_of_pq2 = list(hw_adj.get(pq2, set()))
        if neighbors_of_pq2:
            target = random.choice(neighbors_of_pq2)
            if target != pq1:
                do_swap(m, rm, pq1, target)
            else:
                do_swap(m, rm, pq1, pq2)
        else:
            do_swap(m, rm, pq1, pq2)

    def perturb_lns(m, rm, nbrs=None, alpha_exp=1.5, **kw):
        if nbrs is None or len(interacting_logical) < 3:
            perturb_random(m, rm)
            return
        base_lo = 3 + rsdiwr_iter_ref[0]
        base_hi = 8 + rsdiwr_iter_ref[0] * 2
        k = min(random.randint(base_lo, base_hi), len(interacting_logical))

        acc_pressure = accumulated_routing_pressure_ref[0]
        qubit_acc_pressure = defaultdict(float)
        for (q1, q2), cnt in acc_pressure.items():
            qubit_acc_pressure[q1] += cnt
            qubit_acc_pressure[q2] += cnt
        max_acc = max(qubit_acc_pressure.values()) if qubit_acc_pressure else 1.0

        qcost = {}
        for lq in interacting_logical:
            c = 0.0
            for partner, w in nbrs.get(lq, {}).items():
                if m[partner] >= 0 and m[lq] >= 0:
                    c += w * (dist[m[lq]][m[partner]] ** alpha_exp)
            pressure_bonus = qubit_acc_pressure.get(lq, 0.0) / (max_acc + 1e-10)
            qcost[lq] = c * (1.0 + 0.5 * pressure_bonus)

        sorted_qs = sorted(qcost, key=lambda q: qcost[q], reverse=True)
        top_half = sorted_qs[:max(k, len(sorted_qs) // 2)]
        subset = random.sample(top_half, min(k, len(top_half)))

        freed_phys = []
        for lq in subset:
            freed_phys.append(m[lq])
            rm[m[lq]] = -1
            m[lq] = -1

        placed_set = set(lq for lq in interacting_logical if m[lq] >= 0)
        for lq in sorted(subset, key=lambda q: qcost[q], reverse=True):
            best_pq, best_sc = None, float('inf')
            for pq in freed_phys:
                if rm[pq] != -1:
                    continue
                sc = 0.0
                for partner, w in nbrs.get(lq, {}).items():
                    if partner in placed_set and m[partner] >= 0:
                        sc += w * (dist[pq][m[partner]] ** alpha_exp)
                if sc < best_sc:
                    best_sc = sc
                    best_pq = pq
            if best_pq is not None:
                m[lq] = best_pq
                rm[best_pq] = lq
                placed_set.add(lq)
            else:
                for pq in freed_phys:
                    if rm[pq] == -1:
                        m[lq] = pq
                        rm[pq] = lq
                        placed_set.add(lq)
                        break

    perturbation_modes = [perturb_random, perturb_segment_shuffle,
                          perturb_worst_pair, perturb_edge_targeted, perturb_lns]
    K = len(perturbation_modes)

    WINDOW_SIZE = 100
    EPSILON = 0.1
    window = []
    mode_successes = [0] * K
    mode_attempts = [0] * K

    def select_perturbation_mode():
        if random.random() < EPSILON or sum(mode_attempts) < K * 2:
            return random.randint(0, K - 1)
        rates = []
        for k in range(K):
            if mode_attempts[k] > 0:
                rates.append(mode_successes[k] / mode_attempts[k])
            else:
                rates.append(1.0)
        total = sum(rates)
        if total < 1e-12:
            return random.randint(0, K - 1)
        r = random.random() * total
        cumul = 0.0
        for k in range(K):
            cumul += rates[k]
            if r <= cumul:
                return k
        return K - 1

    def update_window(mode_idx, success):
        window.append((mode_idx, success))
        mode_attempts[mode_idx] += 1
        if success:
            mode_successes[mode_idx] += 1
        if len(window) > WINDOW_SIZE:
            old_mode, old_success = window.pop(0)
            mode_attempts[old_mode] -= 1
            if old_success:
                mode_successes[old_mode] -= 1

    # ---------------------------------------------------------------
    # Step 14: RSDIWR+ILS engine (reusable at any resolution)
    # ---------------------------------------------------------------
    def run_rsdiwr_ils(init_m, init_rm, n_rsdiwr_iters, time_budget_sec, t_start_ref):
        """Run RSDIWR+ILS from given initial mapping. Returns best_m, best_rm, best_cost."""
        cur_m = list(init_m)
        cur_rm = list(init_rm)
        best_m = list(init_m)
        best_rm = list(init_rm)
        best_cost = compute_cost(init_m, static_weight)
        swap_counts = defaultdict(float)
        accumulated_routing_pressure = defaultdict(float)
        accumulated_routing_pressure_ref[0] = accumulated_routing_pressure

        for rsdiwr_iter in range(n_rsdiwr_iters):
            rsdiwr_iter_ref[0] = rsdiwr_iter
            elapsed = _time() - t_start_ref
            if elapsed > time_budget_sec:
                break

            remaining_time = time_budget_sec - elapsed
            remaining_iters = n_rsdiwr_iters - rsdiwr_iter
            time_for_this_iter = remaining_time / max(remaining_iters, 1)
            n_ils = max(55, int(num_q * time_for_this_iter / 0.5)) if time_for_this_iter > 1.0 else max(30, num_q // 3)

            if rsdiwr_iter == 0 or not swap_counts:
                eff_weights = dict(static_weight)
            else:
                max_sw = max(swap_counts.values()) if swap_counts else 1.0
                scale = max(static_weight.values()) / max(max_sw, 1e-10)
                total_pressure = sum(accumulated_routing_pressure.values())
                n_pairs = len(accumulated_routing_pressure)
                avg_pressure = total_pressure / max(n_pairs, 1)
                pressure_adapt = min(0.15, 0.05 * avg_pressure / max(max_sw, 1e-10))
                alpha_blend = max(0.25, 1.0 - 0.3 * rsdiwr_iter - pressure_adapt)

                eff_weights = defaultdict(float)
                all_keys = set(static_weight.keys()) | set(swap_counts.keys())
                for key in all_keys:
                    w_s = static_weight.get(key, 0.0)
                    w_r = swap_counts.get(key, 0.0) * scale
                    eff_weights[key] = alpha_blend * w_s + (1.0 - alpha_blend) * w_r

            eff_nbrs, eff_deg = build_neighbors(eff_weights)

            # Re-seed with routing-informed weights
            if rsdiwr_iter > 0 and swap_counts and (_time() - t_start_ref) < time_budget_sec * 0.7:
                eff_sorted = sorted(interacting_logical,
                                    key=lambda q: eff_deg.get(q, 0), reverse=True)
                reseed_lqs = eff_sorted[:min(2, len(eff_sorted))]
                reseed_pqs = seed_pqs[:min(2, len(seed_pqs))]

                for s_lq in reseed_lqs:
                    for s_pq in reseed_pqs:
                        rm_new, rmm_new = run_greedy_placement(
                            s_lq, s_pq, eff_nbrs, eff_deg, weights=eff_weights)
                        fill_unmapped(rm_new, rmm_new)
                        local_search(rm_new, rmm_new, eff_nbrs, eff_weights,
                                     alpha_exp=2.0, max_rounds=3)
                        sc = compute_cost(rm_new, static_weight)
                        if sc < best_cost:
                            best_cost = sc
                            best_m = list(rm_new)
                            best_rm = list(rmm_new)
                            cur_m = list(rm_new)
                            cur_rm = list(rmm_new)

                for s_pq in reseed_pqs:
                    cg_m, cg_rm = conflict_graph_seed(
                        s_pq, eff_nbrs, eff_deg, eff_weights,
                        routing_pressure=accumulated_routing_pressure)
                    if cg_m is not None:
                        fill_unmapped(cg_m, cg_rm)
                        local_search(cg_m, cg_rm, eff_nbrs, eff_weights,
                                     alpha_exp=2.0, max_rounds=3)
                        sc = compute_cost(cg_m, static_weight)
                        if sc < best_cost:
                            best_cost = sc
                            best_m = list(cg_m)
                            best_rm = list(cg_rm)
                            cur_m = list(cg_m)
                            cur_rm = list(cg_rm)

            alpha_start = 2.0
            alpha_end = 1.0

            ls_rounds = 6 if rsdiwr_iter == 0 else 4
            cur_cost_nl = local_search(cur_m, cur_rm, eff_nbrs, eff_weights,
                                       alpha_exp=alpha_start, max_rounds=ls_rounds)

            static_cost = compute_cost(cur_m, static_weight)
            if static_cost < best_cost:
                best_cost = static_cost
                best_m = list(cur_m)
                best_rm = list(cur_rm)

            # Reset bandit window
            window.clear()
            for k in range(K):
                mode_successes[k] = 0
                mode_attempts[k] = 0

            T = max(cur_cost_nl * 0.05, 1.0)
            T_init = T
            alpha_sa = 0.94
            reheat_interval = max(n_ils // 4, 8)

            for ils_iter in range(n_ils):
                if _time() - t_start_ref > time_budget_sec:
                    break

                progress = ils_iter / max(n_ils - 1, 1)
                alpha_exp = alpha_start + (alpha_end - alpha_start) * progress

                saved_m = list(cur_m)
                saved_rm = list(cur_rm)
                saved_cost = cur_cost_nl

                mode = select_perturbation_mode()
                perturbation_modes[mode](cur_m, cur_rm,
                                        nbrs=eff_nbrs, weights=eff_weights,
                                        alpha_exp=alpha_exp)

                new_cost_nl = local_search(cur_m, cur_rm, eff_nbrs, eff_weights,
                                           alpha_exp=alpha_exp, max_rounds=3)

                success = new_cost_nl < saved_cost - 1e-12

                improvement = saved_cost - new_cost_nl
                if improvement > 0:
                    cur_cost_nl = new_cost_nl
                    sc = compute_cost(cur_m, static_weight)
                    if sc < best_cost:
                        best_cost = sc
                        best_m = list(cur_m)
                        best_rm = list(cur_rm)
                elif random.random() < math.exp(min(0, improvement / max(T, 1e-10))):
                    cur_cost_nl = new_cost_nl
                else:
                    cur_m[:] = saved_m
                    cur_rm[:] = saved_rm
                    cur_cost_nl = saved_cost

                update_window(mode, success)

                T *= alpha_sa
                if (ils_iter + 1) % reheat_interval == 0:
                    T = max(T, T_init * 0.35)

            # Routing simulation for RSDIWR feedback
            if rsdiwr_iter < n_rsdiwr_iters - 1:
                sim_depth = 14 + rsdiwr_iter * 7
                swap_counts, _ = simulate_routing_bidir(best_m, best_rm, max_layers=sim_depth)

                for pair_key, cnt in swap_counts.items():
                    accumulated_routing_pressure[pair_key] += cnt

            cur_m = list(best_m)
            cur_rm = list(best_rm)
            cur_cost_nl = compute_cost_nonlinear(cur_m, eff_weights, alpha_end)

        return best_m, best_rm, best_cost

    # ===============================================================
    # PHASE 1: COARSE-LEVEL CONTRACTION AND RSDIWR
    # ===============================================================
    t_global_start = _time()
    TOTAL_TIME_BUDGET = 25.0

    # Determine contraction pairs using maximum-weight matching
    # on edges above 90th percentile
    interacting_set = set(interacting_logical)

    if len(interacting_logical) >= 6 and len(static_weight) >= 3:
        # Compute 90th percentile threshold for contraction
        weight_vals = sorted(static_weight.values())
        p90_idx = int(len(weight_vals) * 0.90)
        p90_threshold = weight_vals[min(p90_idx, len(weight_vals) - 1)]

        # Filter to high-weight edges for contraction matching
        high_weight_edges = {k: v for k, v in static_weight.items() if v >= p90_threshold}

        # Maximum-weight matching on interaction graph (greedy)
        logical_pairs = greedy_max_weight_matching(high_weight_edges, interacting_set)

        # Contract interaction graph
        contracted_weights, super_to_pair, qubit_to_super = contract_interaction_graph(
            static_weight, logical_pairs, interacting_set)

        # Contract hardware graph: match adjacent physical pairs with highest combined degree
        hw_pairs = greedy_max_weight_matching_hw(hw_adj, set(physical_qubits))

        contracted_dist, super_to_phys, phys_to_super, contracted_hw_adj, n_super_phys = contract_hardware_graph(
            hw_pairs, physical_qubits)

        # Number of super-qubits (logical) and super-positions (physical)
        n_super_logical = len(super_to_pair)

        # Only proceed with coarse phase if we actually contracted significantly
        if n_super_logical < len(interacting_logical) * 0.85 and n_super_phys < len(physical_qubits) * 0.85:

            # Build coarse-level greedy placement
            # Map super-qubit IDs to their total interaction degree
            super_degree = defaultdict(float)
            for (s1, s2), w in contracted_weights.items():
                super_degree[s1] += w
                super_degree[s2] += w

            super_nodes = sorted(super_to_pair.keys())
            super_phys_nodes = sorted(super_to_phys.keys())

            # Coarse centrality
            coarse_centrality = {}
            for sp in super_phys_nodes:
                coarse_centrality[sp] = sum(contracted_dist[sp][sp2] for sp2 in super_phys_nodes)

            # Greedy placement at coarse level
            def coarse_greedy_placement(start_super_lq, start_super_pq):
                cm = [-1] * max(max(super_nodes) + 1, n_super_phys)
                crm = [-1] * max(max(super_nodes) + 1, n_super_phys)
                # Extend arrays if needed
                while len(cm) <= max(max(super_nodes, default=0), max(super_phys_nodes, default=0)):
                    cm.append(-1)
                    crm.append(-1)
                sz = max(len(cm), len(crm), max(super_nodes, default=0) + 1, max(super_phys_nodes, default=0) + 1)
                cm = [-1] * sz
                crm = [-1] * sz

                cm[start_super_lq] = start_super_pq
                crm[start_super_pq] = start_super_lq
                placed = {start_super_lq}
                used = {start_super_pq}
                remaining = set(super_nodes) - placed

                coarse_nbrs = defaultdict(dict)
                for (s1, s2), w in contracted_weights.items():
                    coarse_nbrs[s1][s2] = w
                    coarse_nbrs[s2][s1] = w

                while remaining:
                    best_sq, best_w = None, -1.0
                    for sq in remaining:
                        w = sum(coarse_nbrs.get(sq, {}).get(psq, 0.0) for psq in placed)
                        if w > best_w:
                            best_w = w
                            best_sq = sq

                    # Find best physical super-position
                    best_sp, best_score = None, float('inf')
                    for sp in super_phys_nodes:
                        if sp in used:
                            continue
                        score = 0.0
                        for psq in placed:
                            iw = coarse_nbrs.get(best_sq, {}).get(psq, 0.0)
                            if iw > 0:
                                score += iw * contracted_dist[sp][cm[psq]]
                        if score < best_score:
                            best_score = score
                            best_sp = sp

                    if best_sp is None:
                        # Use any free position
                        for sp in super_phys_nodes:
                            if sp not in used:
                                best_sp = sp
                                break

                    if best_sp is not None:
                        cm[best_sq] = best_sp
                        crm[best_sp] = best_sq
                        placed.add(best_sq)
                        used.add(best_sp)
                    remaining.discard(best_sq)

                return cm, crm

            # Generate a few coarse seeds
            sorted_super_by_deg = sorted(super_nodes, key=lambda s: super_degree.get(s, 0), reverse=True)
            sorted_super_phys_by_cent = sorted(super_phys_nodes, key=lambda s: coarse_centrality.get(s, 0))

            best_coarse_cost = float('inf')
            best_coarse_cm = None

            for s_lq in sorted_super_by_deg[:min(2, len(sorted_super_by_deg))]:
                for s_pq in sorted_super_phys_by_cent[:min(2, len(sorted_super_phys_by_cent))]:
                    cm, crm = coarse_greedy_placement(s_lq, s_pq)
                    cost = 0.0
                    for (s1, s2), w in contracted_weights.items():
                        if cm[s1] >= 0 and cm[s2] >= 0:
                            cost += w * contracted_dist[cm[s1]][cm[s2]]
                    if cost < best_coarse_cost:
                        best_coarse_cost = cost
                        best_coarse_cm = (list(cm), list(crm))

            # ===============================================================
            # PHASE 2: EXPAND COARSE SOLUTION TO FULL RESOLUTION
            # ===============================================================
            if best_coarse_cm is not None:
                coarse_m, coarse_rm = best_coarse_cm

                # Build full-resolution mapping from coarse solution
                expanded_m = [-1] * num_q
                expanded_rm = [-1] * num_q
                used_phys_expanded = set()

                for super_lq in super_nodes:
                    super_pq = coarse_m[super_lq]
                    if super_pq < 0:
                        continue

                    logical_members = super_to_pair[super_lq]
                    physical_members = super_to_phys.get(super_pq, ())

                    if len(logical_members) == 1:
                        # Singleton: assign to first available physical member
                        lq = logical_members[0]
                        for pq in physical_members:
                            if pq not in used_phys_expanded:
                                expanded_m[lq] = pq
                                expanded_rm[pq] = lq
                                used_phys_expanded.add(pq)
                                break
                    elif len(logical_members) == 2:
                        lq1, lq2 = logical_members
                        # Assign higher-interaction qubit to physical qubit with more free neighbors
                        d1 = logical_degree.get(lq1, 0)
                        d2 = logical_degree.get(lq2, 0)
                        if d1 < d2:
                            lq1, lq2 = lq2, lq1  # lq1 has higher interaction

                        if len(physical_members) >= 2:
                            p1, p2 = physical_members[0], physical_members[1]
                            # Count free neighbors for each physical position
                            free_nb_p1 = sum(1 for nb in hw_adj.get(p1, set()) if nb not in used_phys_expanded)
                            free_nb_p2 = sum(1 for nb in hw_adj.get(p2, set()) if nb not in used_phys_expanded)

                            if free_nb_p1 >= free_nb_p2:
                                if p1 not in used_phys_expanded:
                                    expanded_m[lq1] = p1
                                    expanded_rm[p1] = lq1
                                    used_phys_expanded.add(p1)
                                if p2 not in used_phys_expanded:
                                    expanded_m[lq2] = p2
                                    expanded_rm[p2] = lq2
                                    used_phys_expanded.add(p2)
                            else:
                                if p2 not in used_phys_expanded:
                                    expanded_m[lq1] = p2
                                    expanded_rm[p2] = lq1
                                    used_phys_expanded.add(p2)
                                if p1 not in used_phys_expanded:
                                    expanded_m[lq2] = p1
                                    expanded_rm[p1] = lq2
                                    used_phys_expanded.add(p1)
                        elif len(physical_members) == 1:
                            pq = physical_members[0]
                            if pq not in used_phys_expanded:
                                expanded_m[lq1] = pq
                                expanded_rm[pq] = lq1
                                used_phys_expanded.add(pq)

                # Place any still-unplaced logical qubits (could happen if expansion incomplete)
                unplaced = [lq for lq in logical_qubits if expanded_m[lq] == -1]
                for lq in sorted(unplaced, key=lambda q: logical_degree.get(q, 0), reverse=True):
                    # Find closest free physical qubit to qubits it interacts with
                    best_pq, best_score = None, float('inf')
                    nbrs_placed = {}
                    for partner, w in static_nbrs.get(lq, {}).items():
                        if expanded_m[partner] >= 0:
                            nbrs_placed[partner] = w

                    if nbrs_placed:
                        for pq in physical_qubits:
                            if pq in used_phys_expanded:
                                continue
                            score = 0.0
                            for partner, iw in nbrs_placed.items():
                                score += iw * dist[pq][expanded_m[partner]]
                            if score < best_score:
                                best_score = score
                                best_pq = pq
                    else:
                        for pq in physical_qubits:
                            if pq not in used_phys_expanded:
                                if phys_centrality[pq] < best_score:
                                    best_score = phys_centrality[pq]
                                    best_pq = pq

                    if best_pq is not None:
                        expanded_m[lq] = best_pq
                        expanded_rm[best_pq] = lq
                        used_phys_expanded.add(best_pq)

                fill_unmapped(expanded_m, expanded_rm)

                coarse_expanded_seed = (expanded_m, expanded_rm)
            else:
                coarse_expanded_seed = None
        else:
            coarse_expanded_seed = None
    else:
        coarse_expanded_seed = None

    # ===============================================================
    # PHASE 3: FINE-RESOLUTION RSDIWR+ILS
    # ===============================================================
    # Build initial candidates from multiple seeds
    candidates = []

    # Seed from coarse expansion
    if coarse_expanded_seed is not None:
        cm, crm = coarse_expanded_seed
        cost = compute_cost(cm, static_weight)
        candidates.append((cost, list(cm), list(crm)))

    # Standard greedy seeds
    for s_lq in seed_lqs:
        for s_pq in seed_pqs:
            m, rm = run_greedy_placement(s_lq, s_pq, static_nbrs, static_deg,
                                         weights=static_weight)
            fill_unmapped(m, rm)
            cost = compute_cost(m, static_weight)
            candidates.append((cost, m, rm))

    # MIS seeds
    for s_pq in seed_pqs:
        cg_m, cg_rm = conflict_graph_seed(s_pq, static_nbrs, static_deg, static_weight)
        if cg_m is not None:
            fill_unmapped(cg_m, cg_rm)
            cost = compute_cost(cg_m, static_weight)
            candidates.append((cost, cg_m, cg_rm))

    # Spectral seed
    spec_m, spec_rm = spectral_seed()
    if spec_m is not None:
        fill_unmapped(spec_m, spec_rm)
        spec_cost = compute_cost(spec_m, static_weight)
        candidates.append((spec_cost, spec_m, spec_rm))

    # Random seed
    m_rand = [-1] * num_q
    rm_rand = [-1] * num_q
    shuffled_phys = list(physical_qubits)
    random.shuffle(shuffled_phys)
    for i, lq in enumerate(logical_qubits):
        m_rand[lq] = shuffled_phys[i]
        rm_rand[shuffled_phys[i]] = lq
    fill_unmapped(m_rand, rm_rand)
    c = compute_cost(m_rand, static_weight)
    candidates.append((c, m_rand, rm_rand))

    if not candidates:
        self.mapping_dict = list(range(num_q))
        self.reverse_mapping_dict = list(range(num_q))
        if self.use_isl:
            self.isl_mapping = dict_to_isl_map(self.mapping_dict)
        return

    candidates.sort(key=lambda x: x[0])

    # Local search on top candidates
    _, best_m, best_rm = candidates[0]
    best_m, best_rm = list(best_m), list(best_rm)
    local_search(best_m, best_rm, static_nbrs, static_weight, alpha_exp=2.0, max_rounds=6)
    best_cost = compute_cost(best_m, static_weight)

    for idx in range(1, min(6, len(candidates))):
        _, m_c, rm_c = candidates[idx]
        m_c, rm_c = list(m_c), list(rm_c)
        local_search(m_c, rm_c, static_nbrs, static_weight, alpha_exp=2.0, max_rounds=4)
        c = compute_cost(m_c, static_weight)
        if c < best_cost:
            best_cost = c
            best_m = list(m_c)
            best_rm = list(rm_c)

    # Run RSDIWR+ILS from best seed
    elapsed_so_far = _time() - t_global_start
    remaining_budget = TOTAL_TIME_BUDGET - elapsed_so_far

    if remaining_budget > 1.0:
        best_m, best_rm, best_cost = run_rsdiwr_ils(
            best_m, best_rm, n_rsdiwr_iters=4,
            time_budget_sec=TOTAL_TIME_BUDGET,
            t_start_ref=t_global_start)

    # ---------------------------------------------------------------
    # Final: Set mapping
    # ---------------------------------------------------------------
    self.mapping_dict = best_m
    self.reverse_mapping_dict = best_rm

    if self.use_isl:
        self.isl_mapping = dict_to_isl_map(self.mapping_dict)

def init_mapping(self):
    import math
    import random
    import heapq
    from collections import defaultdict, deque
    from time import time as _time

    num_q = self.num_qubits
    physical_qubits = sorted(self.backend.keys())
    dist = self.distance_matrix

    # ---------------------------------------------------------------
    # Step 1: Build DAG and topological layers
    # ---------------------------------------------------------------
    all_gates = sorted(self.access.keys())
    two_qubit_gates = [g for g in all_gates if len(self.access[g]) == 2]

    last_gate_on_qubit = {}
    successors_dag = defaultdict(set)
    predecessors_dag = defaultdict(set)
    for g in all_gates:
        for q in self.access[g]:
            if q in last_gate_on_qubit:
                pred = last_gate_on_qubit[q]
                successors_dag[pred].add(g)
                predecessors_dag[g].add(pred)
            last_gate_on_qubit[q] = g

    in_degree = {g: len(predecessors_dag[g]) for g in all_gates}
    gate_layer = {g: 0 for g in all_gates}
    temp_in = dict(in_degree)
    queue = deque(g for g in all_gates if in_degree[g] == 0)
    topo_order = []
    while queue:
        g = queue.popleft()
        topo_order.append(g)
        for s in successors_dag[g]:
            gate_layer[s] = max(gate_layer[s], gate_layer[g] + 1)
            temp_in[s] -= 1
            if temp_in[s] == 0:
                queue.append(s)

    critical_path = {g: 0 for g in all_gates}
    for g in reversed(topo_order):
        for s in successors_dag[g]:
            if critical_path[s] + 1 > critical_path[g]:
                critical_path[g] = critical_path[s] + 1

    # 2q DAG for routing simulation
    gates_2q = {}
    dag2q_succ = defaultdict(set)
    dag2q_pred = defaultdict(set)
    last_2q_on_qubit = {}
    logical_qubits_set = set()

    for gate in all_gates:
        qubits = self.access[gate]
        if len(qubits) == 2:
            q1, q2 = qubits
            gates_2q[gate] = (q1, q2)
            logical_qubits_set.add(q1)
            logical_qubits_set.add(q2)
            for q in [q1, q2]:
                if q in last_2q_on_qubit:
                    prev = last_2q_on_qubit[q]
                    if prev != gate:
                        dag2q_succ[prev].add(gate)
                        dag2q_pred[gate].add(prev)
                last_2q_on_qubit[q] = gate
        elif len(qubits) == 1:
            logical_qubits_set.add(qubits[0])

    logical_qubits = sorted(logical_qubits_set)

    if not gates_2q:
        self.mapping_dict = list(range(num_q))
        self.reverse_mapping_dict = list(range(num_q))
        if self.use_isl:
            self.isl_mapping = dict_to_isl_map(self.mapping_dict)
        return

    # Topological order for 2q DAG
    topo_2q = []
    in_deg_2q = {g: len(dag2q_pred[g]) for g in gates_2q}
    q2 = deque(sorted(g for g in gates_2q if in_deg_2q[g] == 0))
    while q2:
        g = q2.popleft()
        topo_2q.append(g)
        for s in dag2q_succ[g]:
            in_deg_2q[s] -= 1
            if in_deg_2q[s] == 0:
                q2.append(s)

    dep_count = defaultdict(int)
    for g in reversed(topo_2q):
        for s in dag2q_succ[g]:
            dep_count[g] = max(dep_count[g], dep_count[s] + 1)

    # Backward dep count for backward routing
    bwd_dep = defaultdict(int)
    for g in topo_2q:
        for p in dag2q_pred[g]:
            if p in gates_2q:
                bwd_dep[g] = max(bwd_dep[g], bwd_dep[p] + 1)

    # ---------------------------------------------------------------
    # Step 2: Interaction weights — critical-path weighting
    # ---------------------------------------------------------------
    max_layer = max((gate_layer[g] for g in two_qubit_gates), default=1)

    static_weight = defaultdict(float)
    logical_degree = defaultdict(float)

    for g in two_qubit_gates:
        q1, q2 = self.access[g]
        cp = critical_path[g] + 1
        layer = gate_layer[g]
        w = cp * (max_layer - layer + 1)
        key = (min(q1, q2), max(q1, q2))
        static_weight[key] += w
        logical_degree[q1] += w
        logical_degree[q2] += w

    interacting_logical = [q for q in logical_qubits if logical_degree.get(q, 0) > 0]

    # ---------------------------------------------------------------
    # Step 3: Physical graph properties
    # ---------------------------------------------------------------
    hw_adj = defaultdict(set)
    for pq in physical_qubits:
        for pq2 in self.backend.get(pq, []):
            hw_adj[pq].add(pq2)

    phys_degree = {pq: len(hw_adj[pq]) for pq in physical_qubits}
    phys_centrality = {}
    for pq in physical_qubits:
        phys_centrality[pq] = sum(dist[pq][pq2] for pq2 in physical_qubits)

    # ---------------------------------------------------------------
    # Step 4: Helper functions
    # ---------------------------------------------------------------
    def build_neighbors(weights):
        nbrs = defaultdict(dict)
        deg = defaultdict(float)
        for (q1, q2), w in weights.items():
            nbrs[q1][q2] = w
            nbrs[q2][q1] = w
            deg[q1] += w
            deg[q2] += w
        return nbrs, deg

    def compute_cost_nonlinear(m, weights, alpha_exp):
        cost = 0.0
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                d = dist[m[q1]][m[q2]]
                cost += w * (d ** alpha_exp)
        return cost

    def compute_cost(m, weights):
        cost = 0.0
        for (q1, q2), w in weights.items():
            if m[q1] >= 0 and m[q2] >= 0:
                cost += w * dist[m[q1]][m[q2]]
        return cost

    def delta_swap_cost_nonlinear(m, rm, pq_a, pq_b, nbrs, alpha_exp):
        lq_a, lq_b = rm[pq_a], rm[pq_b]
        delta = 0.0
        affected = set()
        if lq_a in nbrs:
            affected.update(nbrs[lq_a].keys())
        if lq_b in nbrs:
            affected.update(nbrs[lq_b].keys())
        for q in affected:
            if q == lq_a or q == lq_b:
                continue
            pq_q = m[q]
            w_a = nbrs.get(lq_a, {}).get(q, 0.0)
            if w_a > 0:
                old_d = dist[pq_a][pq_q] ** alpha_exp
                new_d = dist[pq_b][pq_q] ** alpha_exp
                delta += w_a * (new_d - old_d)
            w_b = nbrs.get(lq_b, {}).get(q, 0.0)
            if w_b > 0:
                old_d = dist[pq_b][pq_q] ** alpha_exp
                new_d = dist[pq_a][pq_q] ** alpha_exp
                delta += w_b * (new_d - old_d)
        return delta

    def do_swap(m, rm, pq_a, pq_b):
        lq_a, lq_b = rm[pq_a], rm[pq_b]
        m[lq_a], m[lq_b] = pq_b, pq_a
        rm[pq_a], rm[pq_b] = lq_b, lq_a

    # ---------------------------------------------------------------
    # Step 5: A* early-layer routing with adaptive node limit
    # ---------------------------------------------------------------
    ASTAR_LAYERS = 5
    n_2q = len(gates_2q)
    if n_2q < 50:
        ASTAR_NODE_LIMIT = 8000
    elif n_2q < 200:
        ASTAR_NODE_LIMIT = 5000
    else:
        ASTAR_NODE_LIMIT = 3000

    pred_rem_layer = {g: len(dag2q_pred[g]) for g in gates_2q}
    front_layer_calc = set(g for g in gates_2q if pred_rem_layer[g] == 0)
    current_layer = 0
    early_layer_gates = set()

    temp_front = set(front_layer_calc)
    while temp_front:
        for g in temp_front:
            if current_layer < ASTAR_LAYERS:
                early_layer_gates.add(g)
        next_front = set()
        for g in temp_front:
            for s in dag2q_succ[g]:
                pred_rem_layer[s] -= 1
                if pred_rem_layer[s] == 0:
                    next_front.add(s)
        current_layer += 1
        temp_front = next_front

    # ---------------------------------------------------------------
    # Step 6: A*-guided routing for early layers
    # ---------------------------------------------------------------
    def astar_routing_early(m, rm):
        if not early_layer_gates:
            return defaultdict(float), 0

        early_pred = {}
        for g in early_layer_gates:
            early_pred[g] = len(dag2q_pred[g] & early_layer_gates)

        initial_front = frozenset(g for g in early_layer_gates if early_pred[g] == 0)

        init_executed = set()
        cur_front = set(initial_front)
        changed = True
        while changed:
            changed = False
            newly_exec = set()
            for g in cur_front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = m[gq1], m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    newly_exec.add(g)
            if newly_exec:
                changed = True
                init_executed |= newly_exec
                cur_front -= newly_exec
                for g in newly_exec:
                    for s in dag2q_succ[g]:
                        if s in early_layer_gates and s not in init_executed:
                            all_pred_done = True
                            for p in dag2q_pred[s]:
                                if p in early_layer_gates and p not in init_executed:
                                    all_pred_done = False
                                    break
                            if all_pred_done:
                                cur_front.add(s)

        remaining_early = early_layer_gates - init_executed
        if not remaining_early:
            return defaultdict(float), 0

        def compute_front(executed):
            front = set()
            for g in early_layer_gates:
                if g in executed:
                    continue
                all_pred = True
                for p in dag2q_pred[g]:
                    if p in early_layer_gates and p not in executed:
                        all_pred = False
                        break
                if all_pred:
                    front.add(g)
            return frozenset(front)

        init_exec_frozen = frozenset(init_executed)
        init_front_astar = compute_front(init_executed)

        active_logical = set()
        for g in remaining_early:
            gq1, gq2 = gates_2q[g]
            active_logical.add(gq1)
            active_logical.add(gq2)

        def h_func(mapping, front_gates):
            h = 0
            for g in front_gates:
                gq1, gq2 = gates_2q[g]
                h += dist[mapping[gq1]][mapping[gq2]]
            return h

        active_logical_list = sorted(active_logical)

        def mapping_key(mapping):
            return tuple(mapping[lq] for lq in active_logical_list)

        init_m = list(m)
        init_h = h_func(init_m, init_front_astar)

        counter = [0]
        start_state = (init_h, 0, 0, init_m, init_exec_frozen, init_front_astar)
        open_heap = [start_state]
        visited = {}
        best_known_total = float('inf')
        best_result = None

        swap_history = {}
        init_key = (mapping_key(init_m), init_exec_frozen)
        swap_history[init_key] = defaultdict(float)

        expansions = 0

        while open_heap and expansions < ASTAR_NODE_LIMIT:
            f, _, g_cost, cur_m_list, executed, front = heapq.heappop(open_heap)

            mk = mapping_key(cur_m_list)
            state_key = (mk, executed)

            if state_key in visited and visited[state_key] <= g_cost:
                continue
            visited[state_key] = g_cost

            if best_known_total < float('inf') and f > best_known_total * 1.2:
                continue

            new_executed = set(executed)
            new_front = set(front)
            progress = True
            while progress:
                progress = False
                newly_exec = set()
                for g in list(new_front):
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = cur_m_list[gq1], cur_m_list[gq2]
                    if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                        newly_exec.add(g)
                if newly_exec:
                    progress = True
                    new_executed |= newly_exec
                    new_front -= newly_exec
                    for g in newly_exec:
                        for s in dag2q_succ[g]:
                            if s in early_layer_gates and s not in new_executed:
                                all_pred = True
                                for p in dag2q_pred[s]:
                                    if p in early_layer_gates and p not in new_executed:
                                        all_pred = False
                                        break
                                if all_pred:
                                    new_front.add(s)

            new_exec_frozen = frozenset(new_executed)
            new_front_frozen = frozenset(new_front)

            if not (early_layer_gates - new_executed):
                if g_cost < best_known_total:
                    best_known_total = g_cost
                    parent_key = (mk, executed)
                    pair_swaps = dict(swap_history.get(parent_key, {}))
                    best_result = (g_cost, pair_swaps)
                continue

            if not new_front_frozen:
                continue

            active_phys = set()
            for g in new_front_frozen:
                gq1, gq2 = gates_2q[g]
                active_phys.add(cur_m_list[gq1])
                active_phys.add(cur_m_list[gq2])
            ext_gates = set()
            for g in new_front_frozen:
                for s in dag2q_succ[g]:
                    if s in early_layer_gates and s not in new_executed:
                        ext_gates.add(s)
            for g in ext_gates:
                gq1, gq2 = gates_2q[g]
                active_phys.add(cur_m_list[gq1])
                active_phys.add(cur_m_list[gq2])

            swaps = set()
            for pq in active_phys:
                for nb in hw_adj.get(pq, set()):
                    swaps.add((min(pq, nb), max(pq, nb)))

            expansions += 1
            parent_pair_swaps = swap_history.get((mk, executed), defaultdict(float))

            for (s1, s2) in swaps:
                new_m = list(cur_m_list)
                lq_at_s1 = -1
                lq_at_s2 = -1
                for lq in range(num_q):
                    if new_m[lq] == s1:
                        lq_at_s1 = lq
                    if new_m[lq] == s2:
                        lq_at_s2 = lq

                if lq_at_s1 >= 0:
                    new_m[lq_at_s1] = s2
                if lq_at_s2 >= 0:
                    new_m[lq_at_s2] = s1

                new_g = g_cost + 1
                new_mk = mapping_key(new_m)
                child_key = (new_mk, new_exec_frozen)

                if child_key in visited and visited[child_key] <= new_g:
                    continue

                new_h = h_func(new_m, new_front_frozen)
                new_f = new_g + new_h

                if best_known_total < float('inf') and new_f > best_known_total * 1.2:
                    continue

                counter[0] += 1

                child_pair_swaps = defaultdict(float, parent_pair_swaps)
                for g in new_front_frozen:
                    gq1, gq2 = gates_2q[g]
                    pair_key = (min(gq1, gq2), max(gq1, gq2))
                    child_pair_swaps[pair_key] += 1.0

                swap_history[child_key] = child_pair_swaps

                heapq.heappush(open_heap, (new_f, counter[0], new_g, new_m, new_exec_frozen, new_front_frozen))

        if best_result is not None:
            return defaultdict(float, best_result[1]), best_result[0]
        else:
            return defaultdict(float), 0

    # ---------------------------------------------------------------
    # Step 7: Forward greedy routing simulation with congestion-cascading
    # ---------------------------------------------------------------
    def simulate_routing_greedy(m, rm, max_layers=20, pair_pressure=None):
        sim_m = list(m)
        sim_rm = list(rm)
        swap_counts = defaultdict(float)
        total_swaps = 0

        if not gates_2q:
            return swap_counts, total_swaps

        pp = pair_pressure if pair_pressure else {}
        max_pp = max(pp.values()) if pp else 1.0

        pred_remaining = {g: len(dag2q_pred[g]) for g in gates_2q}
        front = set(g for g in gates_2q if pred_remaining[g] == 0)
        layers_done = 0

        while front and layers_done < max_layers:
            executable = []
            for g in front:
                gq1, gq2 = gates_2q[g]
                p1, p2 = sim_m[gq1], sim_m[gq2]
                if (p1, p2) in self.backend_connections or (p2, p1) in self.backend_connections:
                    executable.append(g)

            if executable:
                for g in executable:
                    front.discard(g)
                    for s in dag2q_succ[g]:
                        pred_remaining[s] -= 1
                        if pred_remaining[s] == 0:
                            front.add(s)
                layers_done += 1
                continue

            active_phys = set()
            for g in front:
                gq1, gq2 = gates_2q[g]
                active_phys.add(sim_m[gq1])
                active_phys.add(sim_m[gq2])

            candidates_sw = set()
            for pq in active_phys:
                for nb in self.backend.get(pq, []):
                    candidates_sw.add((min(pq, nb), max(pq, nb)))

            best_swap, best_score = None, float('inf')
            for (s1, s2) in candidates_sw:
                l1, l2 = sim_rm[s1], sim_rm[s2]
                score = 0.0
                for g in front:
                    gq1, gq2 = gates_2q[g]
                    p1, p2 = sim_m[gq1], sim_m[gq2]
                    if gq1 == l1: p1 = s2
                    elif gq1 == l2: p1 = s1
                    if gq2 == l1: p2 = s2
                    elif gq2 == l2: p2 = s1
                    deps = dep_count.get(g, 0) + 1
                    d = dist[p1][p2]
                    if pp:
                        pair_key = (min(gq1, gq2), max(gq1, gq2))
                        pressure_mult = 1.0 + 0.3 * pp.get(pair_key, 0.0) / (max_pp + 1e-10)
                        score += deps * d * pressure_mult
                    else:
                        score += deps * d
                if score < best_score:
                    best_score = score
                    best_swap = (s1, s2)

            if best_swap is None:
                break

            s1, s2 = best_swap
            l1, l2 = sim_rm[s1], sim_rm[s2]
            sim_m[l1], sim_m[l2] = s2, s1
            sim_rm[s1], sim_rm[s2] = l2, l1
            total_swaps += 1

            for g in front:
                gq1, gq2 = gates_2q[g]
                pair_key = (min(gq1, gq2), max(gq1, gq2))
                swap_counts[pair_key] += 1.0

        return swap_counts, total_swaps

    # ---------------------------------------------------------------
    # Step 7b: Backward greedy routing simulation with congestion-cascading
    # ---------------------------------------------------------------
    def simulate_routing_backward(m, rm, max_layers=20, pair_pressure=None):
        sim_m = list(m)
